import React, { useRef, useState, useCallback, useEffect } from 'react';
import useWavesurfer from './useWavesurfer';
import { formatSecondsToMMSS } from 'libs/utiles';
import Button from 'components/elements/Button';

// 음파 라이브러리
const WaveSurferPlayer = (props) => {
  const containerRef = useRef();
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0); // 전체 시간
  const wavesurfer = useWavesurfer(containerRef, props);

  // On play button click
  const onPlayClick = useCallback(() => {
    wavesurfer.isPlaying() ? wavesurfer.pause() : wavesurfer.play();
    if (props.onPlayCallback && !wavesurfer.isPlaying()) {
      props.onPlayCallback();
    }
  }, [wavesurfer]);

  // On stop play button click
  const onStopPlayClick = useCallback(() => {
    wavesurfer.setTime(0);
    wavesurfer.pause();
  }, [wavesurfer]);

  // On Move back button click
  const onMoveBackClick = useCallback(() => {
    wavesurfer.setTime(wavesurfer.getCurrentTime() - 10);
  }, [wavesurfer]);

  // On Move front button click
  const onMoveFrontClick = useCallback(() => {
    wavesurfer.setTime(wavesurfer.getCurrentTime() + 10);
  }, [wavesurfer]);

  // Initialize wavesurfer when the container mounts
  // or any of the props change
  useEffect(() => {
    if (!wavesurfer) return;

    setCurrentTime(0);
    setIsPlaying(false);

    const subscriptions = [
      wavesurfer.on('play', () => {
        // if (props.onPlayCallback) {
        //   props.onPlayCallback();
        // }
        // setIsPlaying(true);
      }),
      wavesurfer.on('pause', () => setIsPlaying(false)),
      wavesurfer.on('ready', () => setDuration(Math.floor(wavesurfer.getDuration()))),
      wavesurfer.on('timeupdate', (currentTime) => setCurrentTime(Math.floor(currentTime))),
    ];

    return () => {
      subscriptions.forEach((unsub) => unsub());
    };
  }, [wavesurfer]);

  useEffect(() => {
    if (!containerRef.current) return;
    containerRef.current.childNodes[0].shadowRoot.lastElementChild.controlsList.value =
      'nodownload';
  }, [containerRef]);

  return (
    <>
      <div ref={containerRef} />
      {props.url && props.isShowButton ? (
        <div className="speech-control">
          <Button
            label={isPlaying ? '일시정지' : '플레이'}
            className={isPlaying ? 'secondary audio-pause round' : 'secondary audio-play round'}
            btnType="icon"
            onClick={onPlayClick}
          />
          <>
            <Button
              label="정지"
              className="secondary audio-stop round"
              btnType="icon"
              onClick={onStopPlayClick}
            />

            <Button
              label="이전"
              className="secondary audio-prev-new round"
              btnType="icon"
              onClick={onMoveBackClick}
            />

            <Button
              label="다음"
              className="secondary audio-next-new round"
              btnType="icon"
              onClick={onMoveFrontClick}
              style={{ margin: '1em' }}
            />
          </>

          {duration ? (
            <div className="play-time">
              <strong>{formatSecondsToMMSS(currentTime)}</strong>/ {formatSecondsToMMSS(duration)}
            </div>
          ) : null}
        </div>
      ) : null}
    </>
  );
};

export default React.memo(WaveSurferPlayer);
