import React, { useRef } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { GraphLabelWrap, GraphLayout, GraphTitleItem, GraphWrapBox } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const TwoBarChart = ({ labels, colors, datas, width, height, legends, title, legendPadding }) => {
  
  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const data = {
    labels,
    datasets: [
      {
        label: legends[0],
        data: datas[0],
        backgroundColor: colors[0],
        borderWidth: 3,
        borderColor: 'transparent', //그래프 간격 조정 위함
        barThickness:22,
      },
      {
        label: legends[1],
        data: datas[1],
        backgroundColor: colors[1],
        borderWidth: 3,
        borderColor: 'transparent', //그래프 간격 조정 위함
        barThickness: 22,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      title: { display: false },
      datalabels: { display: false },
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: {
          font: { size: 11 },
          color: '#B3B3C5',
          maxRotation: 0,
          minRotation: 0,
          align: 'center',
        },
        barPercentage: 10,
        categoryPercentage: 50,
      },
      y: {
        border: { display: false },
        ticks: {
          stepSize: 50,
          align: 'start',
          padding: 5,
          font: { size: 12 },
          color: '#B3B3C5',
        },
      },
    },
  };

  return (
    <GraphLayout>
      <div className="left-wrap">
        <GraphTitleItem>{title}</GraphTitleItem>
        <CustomLegend legends={legends} colors={colors} paddingL={legendPadding} />
      </div>
      <GraphWrapBox width={width} height={height}>
        <Bar red={chartRef} data={data} options={options} />
      </GraphWrapBox>
    </GraphLayout>
  );
};

export default TwoBarChart;

const CustomLegend = ({ legends, colors, paddingL }) => (
  <GraphLabelWrap paddingL={paddingL}>
    {legends.map((item, index) => (
      <p key={index}>
        <span style={{ backgroundColor: colors[index] }} />
        {item}
      </p>
    ))}
  </GraphLabelWrap>
);