import { useState } from "react";
import Title from "components/common/Title";
import Filter from "components/common/Filter";
import Select from "components/elements/Select";
import Button from 'components/elements/Button';
import { TagBtnsWraps, TagBtns } from "style/AutoQAStyle";
import Table from "components/common/Table";
import ButtonList from "components/common/ButtonList";
import Pagination from 'components/common/Pagination';
import LayerPopup from "components/common/LayerPopup";
import UserDetailPopup from "./popups/UserDetailPopup";
import UserSearchPopup from "./popups/UserSearchPopup";
import Radio from "components/elements/Radio";
import TextField from "components/elements/TextField";
import NoData from "components/common/NoData";

const UserManagementPage = () => {
  const [openPopup, setPopupOpen] = useState(false); // 사용자명 검색 팝업
  const [openDetail, setOpenDetail] = useState(false); //사용자 상세 팝압
  const [selectedRadio, setSelectedRadio] = useState(0); //라디오버튼 임시값

  const _RadioBtnList = [
    { label: '전체', cnt: 400 },
    { label: 'AIKMS 사용자', cnt: 10 },
    { label: 'AUTOQA 사용자', cnt: 5 },
    { label: 'AUTOQA QAA', cnt: 30 },
    { label: 'AICCPORTAL 관리자', cnt: 355 },
    { label: 'AUTOQA 관리자', cnt: 400 },
    { label: 'AUTOQA 운영자', cnt: 10 },
    { label: '관리자', cnt: 5 },
    { label: 'AIKMS 운영자', cnt: 30 },
    { label: 'AICCPORTAL 운영자', cnt: 355 },
    { label: 'AICCPORTAL 사용자', cnt: 20 }
  ];

  return (
    <>
      {openPopup && // 사용자 등록 팝업   
        <LayerPopup
          title={`신규 사용자 등록`}
          customWidth={1000}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <UserSearchPopup />
        </LayerPopup>
      }

      {openDetail && // 사용자 상세 팝업   
        <LayerPopup
          title={`사용자 상세`}
          customWidth={800}
          open={openDetail}
          onClose={() => setOpenDetail(false)}
        >
          <UserDetailPopup />
        </LayerPopup>
      }

      <Title title="사용자 관리" icon="settings" />
      <Filter>
        <Select
          option={[]}
          label="검색 조건 선택"
          value={null}
          disabled={false}
          title={'사용자명'}
          onChange={() => { console.log('select!') }}
        />
        <TextField
          placeholder="사용자 명을 입력하세요"
          label="검색 값 입력"
          multi
          onChange={(e) => { }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>
      <TagBtnsWraps>
        <TagBtns>
          {_RadioBtnList.map((item, index) => {
            return (
              <Radio
                key={index}
                type="button"
                name="tRdaio"
                checked={selectedRadio === index}
                onChange={() => setSelectedRadio(index)}
              >
                {item.label} {item.cnt}
              </Radio>
            );
          })}
        </TagBtns>
        <ButtonList buttonList={[
          { label: '신규 사용자 등록', className: 'primary left-plus', onClick: () => { setPopupOpen(true) } },
        ]} />
      </TagBtnsWraps>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="220px" />
            <col width="220px" />
            <col width="260px" />
            <col width="340px" />
            <col width="220px" />
            <col width="320px" />
          </colgroup>
          <thead>
            <tr>
              <th>아이디</th>
              <th>사용자명</th>
              <th>사번</th>
              <th className="t-left left-padding">이메일</th>
              <th>시스템 권한</th>
              <th>조직</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={6}><NoData txt={'데이터가 없습니다'}/></td></tr> 
            */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index} onClick={() => { setOpenDetail(true) }}>
                <td>2000456</td>
                <td>김상담</td>
                <td>2000456</td>
                <td className="t-left left-padding">test@test.com</td>
                <td>QAA</td>
                <td>고객상담1실​</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}

export default UserManagementPage;