import * as S from '../../style/ElementsStyle';

const LnbToggleButton = ({ className, btnClick }) => {
  return (
    <S.LnbToggleButton type="button" className={className} onClick={btnClick && btnClick}>
      <span>메뉴영역 축소/확대</span>
    </S.LnbToggleButton>
  );
};

export default LnbToggleButton;
