import { useState } from "react";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import Button from "components/elements/Button";
import { LayerInButtonWrap, FormFileList } from "style/AutoQAStyle";
import Select from "components/elements/Select";
import TextField from "components/elements/TextField";
import ButtonList from 'components/common/ButtonList';
import FileUpload from 'components/pages/Test/FileUpload';
import LayerPopup from "components/common/LayerPopup";
import CategoryPopup from "./CategoryPopup";

const fileList = Array.from({ length: 3 }); // 테스트 데이터

const DocumentsManagementAddPopup = () => {
  const [openPopup, setOpenPopup] = useState(false);

  return (
    <>
     {openPopup &&  //카테고리 선택 팝업
        <LayerPopup
          size="large"
          title='카테고리 선택'
          customWidth={900}
          open={openPopup}
          onClose={() => setOpenPopup(false)}
        >
          <CategoryPopup onClose={() => setOpenPopup(false)}/>
        </LayerPopup> 
      }
      <GrayBox direction={"column"}>
        <FormItem label={'카테고리'} marginB={8}>
          <div style={{ display: 'flex', gap: 8 }}>
            <TextField width={508} />
            <Button label="선택" className="secondary" onClick={() => {setOpenPopup(true)}} />
          </div>
        </FormItem>
        <FormItem label={'상태'} marginB={8}>
          <Select
            option={[]}
            type={'simple'}
            title={'사용'}
            onChange={() => { }}
          />
        </FormItem>
        <FormItem label={'파일'} marginB={8}>
          <>
            <FormFileList height={fileList.length === 1 ? '40px' : '64px'}>
              {fileList.map((_, index) => (
                <li key={index}>선택약정 할인 제도_{index}.pdf<button /></li>
              ))}
            </FormFileList>
            <div style={{ marginTop: '8px', width: '575px' }}>
              <FileUpload />
            </div>
          </>
        </FormItem>
        <FormItem label={'작성자'}>
          <TextField width={260} disabled={true} value={'관리자'}/>
        </FormItem>
      </GrayBox>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '저장', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  )
};

export default DocumentsManagementAddPopup;