import { useEffect, useState } from "react";
import { Document, Page, pdfjs } from "react-pdf";
import "react-pdf/dist/esm/Page/AnnotationLayer.css";
import "react-pdf/dist/esm/Page/TextLayer.css";
import { PDFPopupContainer, PDFPopup, PDFPopupHeader,PDFViewer} from "style/AutoQAStyle";

// PDF.js 워커 설정
pdfjs.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;

const PdfViewerWithPopup = ({ selectedPdfUrl, closePdfViewer }) => {
  const [pdfData, setPdfData] = useState(null);
  const [numPages, setNumPages] = useState(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [scale, setScale] = useState(1.0); // 확대/축소 비율

  useEffect(() => {
    const fetchPdf = async () => {
      try {
        const response = await fetch('https://sktaicc.aikms.com/v1/documents/75f5a08b-07ba-48ed-abf9-8061e2641a19/download');
        const blob = await response.blob();
        setPdfData(URL.createObjectURL(blob));
      } catch (error) {
        console.error("PDF 로드 실패:", error);
      }
    };

    fetchPdf();
  }, [selectedPdfUrl]);

  const onDocumentLoadSuccess = ({ numPages }) => {
    setNumPages(numPages);
  };

  const goToNextPage = () => {
    if (pageNumber < numPages) {
      setPageNumber(pageNumber + 1);
    }
  };

  const goToPrevPage = () => {
    if (pageNumber > 1) {
      setPageNumber(pageNumber - 1);
    }
  };

  const increaseScale = () => {
    setScale((prevScale) => Math.min(prevScale + 0.1, 2)); // 최대 200% 확대
  };

  const decreaseScale = () => {
    setScale((prevScale) => Math.max(prevScale - 0.1, 0.5)); // 최소 50% 축소
  };

  return (
    <PDFPopupContainer>
      <PDFPopup>
        <PDFPopupHeader>
          <p className="title">나라 사랑 군인 보험</p>

          <div className="center-contents">
            <div className="page-wrap">
              <button onClick={goToPrevPage} disabled={pageNumber <= 1} className="prev-btn page-btn" />
              <div className="page-num">
                <span className="now-page">{pageNumber}</span>/
                <span className="total-page">{numPages}</span>
              </div>
              <button onClick={goToNextPage} disabled={pageNumber >= numPages} className="next-btn page-btn" />
            </div>

            <div className="scale-wrap">
              <button onClick={decreaseScale} disabled={scale <= 0.5} className="minus-btn page-btn" />
              <span className="scale-view">{(scale * 100).toFixed(0)}%</span>
              <button onClick={increaseScale} disabled={scale >= 2} className="plus-btn page-btn" />
            </div>

            <button className="download-btn"/>
          </div>
          <button onClick={closePdfViewer} className="close-btn" />
        </PDFPopupHeader>
        <PDFViewer>
          {pdfData ? (
            <Document file={pdfData} onLoadSuccess={onDocumentLoadSuccess}>
              <Page pageNumber={pageNumber} scale={scale} />
            </Document>
          ) : (
            <p className="loading">PDF 로드 중...</p>
          )}
        </PDFViewer>
      </PDFPopup>
    </PDFPopupContainer >
  );
};

export default PdfViewerWithPopup;
