import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import * as S from '../../style/ChartStyle';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ChartDataLabels);
{
  /*231027 maxnum 삭제, option 수정*/
}
const MultipleBarChart = ({ isDataLabels = false, title, num, labels, colors, datas = [], dataGap = 500, dataFullSize = 7000, isPer = false }) => { // 231205 dataGap 추가, 231206 dataFullSize 추가
  const max = Math.max.apply(Math, datas);
  const options = {
    responsive: true,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      x: {
        grid: {
          display: false,
        },
        ticks: {
          color: '#7E8B99',
          fontSize: 12,
        },
      },
      y: {
        min: 0,
        //max: datas.length ? (isDataLabels ? max + dataGap : max) : 1, // 231205 dataGap 추가 //max 기준으로 하면 위에 label값 안보여서 label 노출하는경우 상단에 간격 더 줌
        max: isPer ? 100 : datas.length ? (isDataLabels ? max + dataGap : max) : 1,
        setpSize: 1000,
        ticks: {
          color: '#7E8B99',
          fontSize: 12,
        },
      },
    },
    maintainAspectRatio: false,
  };

  const data = {
    labels: labels,
    datasets: [
      {
        label: '',
        maxBarThickness: 20,
        data: datas,
        backgroundColor: colors,
        hoverBackgroundColor: colors,
        borderRadius: 2,
        datalabels: {
          color: function(ctx) { // 231205 최대값, 최저값만 표기
            if (ctx.dataset.data[ctx.dataIndex] === max && isDataLabels) { 
              return '#C53434';
            } else if (ctx.dataset.data[ctx.dataIndex] === Math.min(...ctx.dataset.data)) {
              return '#000';
            } else {
              return 'transparent';
            }
          },
          font: {
            // size: datas.length < 6 ? '15px' : '12px',
            size: '12px', // 231205 font size 고정
            weight: '500',
          },
          anchor: 'end',
          align: 'top',
          offset: function(ctx) { // 231206 offset 추가
            return ctx.dataset.data[ctx.dataIndex] === dataFullSize ? -40 : 4;
          },
          backgroundColor: function(ctx) { // 231206 backgroundColor 추가
            return ctx.dataset.data[ctx.dataIndex] === dataFullSize ? 'rgba(255, 255, 255, 0.7)' : 'transparent';
          },
          padding: { // 231206 padding 추가
            top: 2,
            right: 0,
            bottom: 0,
            left: 0
          },
          formatter: function (value) {
            if (!isDataLabels) { 
              return '';
            } else { 
              // return ((value/dataFullSize) * 100).toFixed(2) + '%';
              return (Math.round((value/dataFullSize) * 100)) + '%';  // 231205 dataFullSize 추가
            }
          },
        },
      },
    ],
  };

  return (
    <S.MultipleBar>
      {title && (
        <div className="chart-title">
          <strong className="title">{title}</strong>
          {num && <span className="num">{num}</span>}
        </div>
      )}
      <div className="inner">
        <Bar options={options} data={data} />
      </div>
    </S.MultipleBar>
  );
};

export default MultipleBarChart;
