import { useNavigate } from "react-router-dom";
import Table from "components/common/Table";
import { WideLayerGrid, DetailPageContainer, BackBtnWrap } from "style/AutoQAStyle";
import IconTab from "components/common/IconTab";
import Title from 'components/common/Title';
import Button from "components/elements/Button";
import AutoCheckTab from "../tabs/AutoCheckTab";
import ManualCheckTab from "../tabs/ManualCheckTab";
import ChatElementWrap from "components/common/ChatElementWrap";

const tabList = [
  {
    icon: 'noteIcon',
    title: '자동 평가',
    tabContent: <AutoCheckTab />
  },
  {
    icon: 'writeIcon',
    title: '수동 평가',
    tabContent: <ManualCheckTab commentIs={false}/>
  }
];

const EvaluationDetailPage = () => {
  const navigate = useNavigate();

  return (
    <DetailPageContainer>
      <Title title="평가 현황 상세" icon="counsel" />

      <Table round={false} interval={false}>
        <table>
          <colgroup>
            <col width="208px" />
            <col width="208px" />
            <col width="208px" />
            <col width="278px" />
            <col width="162px" />
            <col width="208px" />
          </colgroup>
          <thead>
            <tr>
              <th>상담유형1</th>
              <th>상담유형2</th>
              <th>상담유형3</th>
              <th >상담 일시</th>
              <th >평가 방식</th>
              <th >평가자</th>
            </tr>
          </thead>
          <tbody>
            <tr style={{height:'64px'}}>
              <td >상담유형1</td>
              <td >상담유형2</td>
              <td >상담유형3</td>
              <td>2024-01-05 13:15:45</td>
              <td>자동/수동</td>
              <td>김박사</td>
            </tr>
          </tbody>
        </table>
      </Table>

      <WideLayerGrid>
        <div style={{ width: '853px' }}>
          <h5 className="icon-title">
            <img src={process.env.PUBLIC_URL+'/images/ico-tab-title.svg'} alt='icon' />
            평가 결과
          </h5>
          <div className="content-wrap">
            <IconTab tabList={tabList} />
          </div>
        </div>

        <div style={{ width: '691px' }}>
          <h5 className="icon-title">
            <img src={process.env.PUBLIC_URL+'/images/ico-tab-title2.svg'} alt='icon' />
            상담 내역
          </h5>
          <div className="content-wrap">
            <ChatElementWrap waveIs={true} waveH={0} iconType="search"/>
          </div>
        </div>
      </WideLayerGrid>

      <BackBtnWrap>
        <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
      </BackBtnWrap>
    </DetailPageContainer>
  );
}

export default EvaluationDetailPage;