import { SubContentsWrap, SubTableTitle, CountingTitle, TextFieldWithBtn } from "style/AutoQAStyle";
import Button from "components/elements/Button";
import FormItem from "components/common/FormItem";
import FormGrid from "components/common/FormGrid";
import TextField from "components/elements/TextField";
import FileUpload from 'components/pages/Test/FileUpload';
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import Checkbox from 'components/elements/Checkbox';

const TestSet = () => {
  return (
    <SubContentsWrap>
      <div className='titles'>
        <h5>테스트셋 등록</h5>
        <Button label="샘플 다운로드" className="secondary download" onClick={() => { }} />
      </div>

      <div className="file-upload-wrap">
        <FormGrid gap={8}>
          <FormItem label="테스트셋 명​">
            <TextField width={480} count={10} maxLength={10} />
          </FormItem>
          <FormItem label="테스트셋 파일​" vertical={'start'}>
            <TextFieldWithBtn>
              {'선택 약정 할인제도.pdf'}
              <button onClick={() => { }} />
            </TextFieldWithBtn>
            <FileUpload />
          </FormItem>
        </FormGrid>
      </div>
      <div className="bottom-btn-wrap">
        <Button label="저장" className="primary wide" onClick={() => { }} />
      </div>


      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <Button label="선택 삭제" className="secondary del2" onClick={() => { }} />
      </SubTableTitle>

      <Table className="active" fixedHeader={true} height="572" hover={false} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="64px" />
            <col width="520px" />
            <col width="640px" />
            <col width="360px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th>테스트셋 명</th>
              <th>등록 일시</th>
              <th>다운로드</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={4}><NoData txt={'데이터가 없습니다'}/></td></tr> 
               */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index}>
                <td className='checkType'>
                  <Checkbox />
                </td>
                <td>테스트셋 명​</td>
                <td>2024-10-31 09:13:24​</td>
                <td className='center'>
                  <Button label="" className="secondary download" btnType={'icon'} onClick={() => { }} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </SubContentsWrap>
  );
};

export default TestSet; 