export const IconWithTab = styled.div`
  width:${(props) => props.width !== '' ? props.width + 'px' : '853px'};
  height:auto;
  border-radius: 0px 0px 8px 8px;
  .icon-tab{
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .icon-tab-cont{
    background: #fff;
    height:${(props) => props.height ? props.height + 'px' : '725px'};
    border-radius: 0 0 8px 8px;
  }

  .tabButton{
    border-top: 1px solid #DADEE4;
    border-right: 1px solid #dadee4;
    border-radius: 8px 8px 0px 0px;
    background: #E9ECEF;
    width: calc(100% / ${(props) => props.length !== '' ? props.length : 2});
    height: 52px;
    color: #4A545E;
    font-size: 15px;
    font-weight: 500;
    display: flex;
    align-items: center;
    justify-content: center;
    
    
    &.no-border-right {
      border-right: none;
    }

    .icon{
      margin-right:16px;
      width:20px;
      height:20px;
        
      &.noteIcon{
        background:  ${_mx.svg(_svg.noteIcon('555F6D'))} center center no-repeat;
        &.active,&:hover { background: ${_mx.svg(_svg.noteIcon('4E47D6'))} center center no-repeat; }
      }
      &.writeIcon{
        background:  ${_mx.svg(_svg.writeIcon('555F6D'))} center center no-repeat;
        &.active,&:hover { background: ${_mx.svg(_svg.writeIcon('4E47D6'))} center center no-repeat; }
      }
      &.objectionIcon{
        background:  ${_mx.svg(_svg.objectionIcon('555F6D'))} center center no-repeat;
        &.active,&:hover { background: ${_mx.svg(_svg.objectionIcon('4E47D6'))} center center no-repeat; }
      }
    }

    &.active{
      background: #FFF;
      /* filter: drop-shadow(0px 1px -1px rgba(27, 36, 44, 0.12)); */
      color: #4E47D6;
      font-size: 18px;
      font-weight: 600;
    }
  }
`;

