import React, { useEffect, useState } from "react";
import styled from "@emotion/styled";

const Container = styled.div`
  display: flex;
  gap: 4px;
`;

const HiddenRadio = styled.input`
  display: none;
`;

const Label = styled.label`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  box-shadow: 0px 1px 2px 0px rgba(27, 36, 44, 0.12);

  &:hover {
    opacity: 0.5;
  }
  &.like{
    background: url(${process.env.PUBLIC_URL + '/images/thumbsUp-default.svg'}) no-repeat center center;
  }

  &.dislike{
    background: url(${process.env.PUBLIC_URL + '/images/thumbsDown-default.svg'}) no-repeat center center;
  }

  &.like.active {
    background: url(${process.env.PUBLIC_URL + '/images/thumbsUp-active.svg'}) no-repeat center center;
  }

  &.dislike.active {
    background: url(${process.env.PUBLIC_URL + '/images/thumbsDown-active.svg'}) no-repeat center center;
  }
`;

const LikeDislikeRadio = ({ name }) => {
  const [selected, setSelected] = useState(null);

  return (
    <Container>
      <HiddenRadio
        id={`${name}-like`}
        type="radio"
        value="like"
        name={name}
        checked={selected === "like"}
        onChange={() => setSelected("like")}
      />
      <Label htmlFor={`${name}-like`} className={`like ${selected === "like" ? "active" : ""}`} />

      <HiddenRadio
        id={`${name}-dislike`}
        value="dislike"
        type="radio"
        name={name}
        checked={selected === "dislike"}
        onChange={() => setSelected("dislike")}
      />
      <Label htmlFor={`${name}-dislike`} className={`dislike ${selected === "dislike" ? "active" : ""}`} />
    </Container>
  );
};

export default LikeDislikeRadio;
