import * as PS from '../../style/Statistics'; /* 231031 파일명 statistics > Statistics 으로 수정 */
import Button from 'components/elements/Button';

{
  /* 231027 row 추가 */
}
const ItemGraph = ({ title, graph, oneGraph, row, isCallingInfo, onClick, direction,gapIs=true}) => {
  return (
    <PS.ItemGraph row={row} direction={direction} gap={gapIs}>
      {/* 231027 row 추가 */}
      <div className="item-title">
        {title && (
          <>
            {title.name && <strong>{title.name}</strong>}
            {title.number && (
              <>
                <br />
                <strong className='number'>{title.number}</strong>
              </>
            )}
          </>
        )}


        {isCallingInfo ? (
          <Button
            label="대화 이력"
            className="calling secondary small chevron-right-calling-small"
            onClick={onClick}
            spanName={"calling"}
          />
        ) : null}
      </div>
      <div className="item-cont">
        {graph && (
          <ul className="list">
            {graph.map((el, index) => {
              return (
                <li key={el + index}>
                  <div className="graph-cont">{el.graph}</div>
                </li>
              );
            })}
          </ul>
        )}

        {oneGraph && <div className="graph-cont">{oneGraph}</div>}
      </div>
    </PS.ItemGraph>
  );
};

export default ItemGraph;
