import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Filter from "components/common/Filter";
import Button from "components/elements/Button";
import dayjs from 'dayjs';
import DateRange from 'components/common/DateRange';
import { SubTableTitle, CountingTitle } from 'style/AutoQAStyle';
import ButtonList from 'components/common/ButtonList';
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import Checkbox from 'components/elements/Checkbox';
import NoData from 'components/common/NoData';
import LayerPopup from 'components/common/LayerPopup';
import EvaluationListPopup from '../popups/EvaluationListPopup';

const EvaluationList = () => {
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [openPopup, setPopupOpen] = useState(false); // 상담사, 평가자 검색 팝업

  return (
    <>
     {openPopup &&
        <LayerPopup
          size=""
          title={'Agent 성능 평가 등록​'}
          customWidth={800}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <EvaluationListPopup/>
        </LayerPopup>
      }
      <Filter>
        <DateRange
          rangeCal
          utilMenu
          label="조회 기간"
          monthsShown={2}
          selectsRange
          format="YYYY-MM-DD"
          startDate={dayjs(startDate).toDate()}
          endDate={dayjs(endDate).toDate()}
          selected={dayjs(startDate).toDate()}
          disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
          disableNum={3}
          maxDate={dayjs().toDate()}
          onChange={(value) => {
            setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
            setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
          }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>
      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          { label: '선택 삭제', className: 'secondary del2', onClick: () => { } },
          { label: '', className: 'secondary repeat', onClick: () => { }, btnType: 'icon' },
          { label: '평가', className: 'primary left-plus', onClick: () => {setPopupOpen(true)} },
        ]} />
      </SubTableTitle>

      <Table className="active" fixedHeader={true} height="572" hover={false} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="64px" />
            <col width="140px" />
            <col width="144px" />
            <col width="150px" />
            <col width="170px"  />
            <col width="170px" />
            <col width="170px" />
            <col width="170px" />
            <col width="200px" />
            <col width="100px" />
            <col width="100px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th>에이전트명</th>
              <th>평가 항목</th>
              <th>데이터셋</th>
              <th>Context<br />Precision</th>
              <th>Context<br />Recall</th>
              <th>Faithfulness​</th>
              <th>Answer<br />Relevancy</th>
              <th>테스트 일시​</th>
              <th>평가상태​</th>
              <th>평가 결과​</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={11}><NoData txt={'데이터가 없습니다'}/></td></tr> 
               */}
            {Array.from({ length: 10 }).map((_, index) => (
               <tr key={index}>
                <td className='checkType'>
                  <Checkbox />
                </td>
                <td>I/B​</td>
                <td>-</td>
                <td>-</td>
                <td>0.000</td>
                <td>0.000</td>
                <td>0.000</td>
                <td>0.000</td>
                <td>2024-10-31 09:13:24​</td>
                {/* 아래 td 두개 조건 변경 필요(기획 수정 요청 사항 임시 적용) */}
                <td>{index % 2 === 0 ? '미완료' : '완료'}</td> 
                <td className='center'>
                  {index % 2 !== 0 && <Button label="" className="secondary download" btnType={'icon'} onClick={() => { }} />}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
};

export default EvaluationList;