import { useState } from "react";
import NavStep from "./NavSteps";
import { ScoreTableContainer, CommentBox } from "style/AutoQAStyle";
import TextField from "components/elements/TextField";

const InputTable = ({ tableInfo, modifyIs = true, commentStr, tableList, commentIs = true }) => {

  const [totalScore, setScoreIs] = useState(0);
  const isLongText = commentStr.length > 62;

  return (
    <>
      <NavStep listInfo={tableInfo} />
      <ScoreTableContainer>
        <table>
          <colgroup>
            <col width='662px'/>
            <col width="45px" />
            <col width="45px" />
            <col width={modifyIs ? "45px" : '0'} />
          </colgroup>
          <thead>
            <tr>
              <th className="left">평가 항목</th>
              <th>배점</th>
              <th>점수</th>
              {modifyIs && <th>수정</th>}
            </tr>
          </thead>
          <tbody>
            {tableList.map((row, index) => (
              <tr key={index}>
                <td className={`left ${row.isSubItem ? "flag" : ""} ${row.isSubItem &&'small-txt'}`}>
                  {row.isSubItem && <span>세부항목</span>}
                  {row.description}
                </td>
                <td>{row.maxScore}</td>
                <td>{row.score}</td>
                {modifyIs && (
                  <td className="center">
                    {row.isEditable ? (
                      <TextField
                        width={40}
                        size="small"
                        defaultValue={row.score}
                        disabled={commentIs}
                        center="center"
                        readOnly={!row.isEditable}
                      />
                    ) : (
                      row.score
                    )}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
        <CommentBox modifyIs={modifyIs} commentIs={commentIs}>
          <p>Comment</p>
          <textarea
            type="text"
            {...(commentIs ? { value: commentStr } : {})}
            {...(!commentIs ? { placeholder: '코멘트를 입력하세요.' } : { placeholder: '' })}
            readOnly={commentIs}
            className={isLongText ? "long-text" : ""}
            style={{paddingLeft:commentIs ? '0' : '10px'}}
          />
        </CommentBox>
      </ScoreTableContainer>
    </>
  );
};

export default InputTable;