import FileUpload from 'components/pages/Test/FileUpload';
import Button from 'components/elements/Button';
import ButtonList from 'components/common/ButtonList';
import { FileUploadLayer } from 'style/AutoQAStyle';

const EvaluationSheetExcelPopup = () => {
  return (
    <FileUploadLayer>
      <Button className={'secondary download'} label={'양식 다운로드'} />
      <div className='file-container'>
        <FileUpload />
      </div>
      <ButtonList buttonList={[
        { label: '취소', className: 'secondary', onClick: () => { } },
        { label: '확인', className: 'primary', onClick: () => { } },
      ]} />
    </FileUploadLayer>
  );
};

export default EvaluationSheetExcelPopup;
