import styled from '@emotion/styled';
import _mx from './Style';
import _svg from './SvgList';
import { _color } from './Variable';

export const DashboardLayout = styled.div`
  display: flex; justify-content: space-between; background: ${_color.gray7}; min-width: 1888px;
`;

export const DashbordAside = styled.aside`
  min-height: 100vh; background: ${_color.white}; position: relative; 
  &.expand {
    width: 240px;
    min-width:240px;
  }
  &.collapse {
    width:72px; min-width: 72px; border-right: solid 1px ${_color.gray7};
  }
`
export const DashbordInner = styled.div`
  position: sticky;
  top: 0;
  overflow:hidden;
  width: 256px;
  height: 100vh;
  .collapse & {
    width:88px;
  }
`
export const DashbordScroll = styled.div`
  &::-webkit-scrollbar-button:vertical:start:decrement,
  &::-webkit-scrollbar-button:vertical:start:increment {
    display: block;
    height: 0;
  }
  &::-webkit-scrollbar {
    width: 8px;
  }
  &::-webkit-scrollbar-thumb {
    background-color: #e9ecef;
    border-radius: 8px;
  }
  display:flex;
  flex-direction:column;
  overflow-y: auto;
  width:240px;
  height:100%;
  background:${_color.white};
  .collapse & {
    width:72px;
  }
`
export const Contents = styled.div`
  flex-grow: 1; 
  min-width: calc(1888px - 240px);
`

export const DashbordHeader = styled.header`
  height: 44px; background: ${_color.primary0}; display: flex; justify-content: flex-end;
`
export const UtilMenu = styled.ul`
  padding: 6px 40px 6px 22px; display: flex;
  li {
    button { padding: 0; }
    & + li { margin-left: 32px; }
  }
`
export const AsideMenu = styled.ul`
  padding: 12px 8px;
  > li { 
    > h3{
      line-height:40px;
      padding-left:18px;
      margin-bottom:8px;
    }
    > button, > a {
      position: relative;
      &::before { content: ''; position: absolute; width: 24px; height: 24px; }
    }
    button, a {
      display: block; width: 100%; min-height: 40px; background: none;
    }
    &:first-of-type {
      > button, > a {margin-top: 0 !important; }
    }
    &.dashboard {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.viewBoxes('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.viewBoxes('1f2937'))} center center no-repeat; }
        &:hover:before {background: ${_mx.svg(_svg.viewBoxes('372496'))} center center no-repeat;}
      }
    }
    &.test {
      > button, > a {
        &::before { background: url('/images/callbot.svg') center center no-repeat; }
        &.on::before { background: url('/images/callbot.svg') center center no-repeat; }
        &:hover::before { background: url('/images/callbot.svg') center center no-repeat; }
      }
    }
    &.chatTest {
      > button, > a {
        &::before { background: url('/images/chatbot.svg') center center no-repeat; }
        &.on::before { background: url('/images/chatbot.svg') center center no-repeat; }
        &:hover::before { background: url('/images/chatbot.svg') center center no-repeat; }
      }
    }
    &.statistics {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.chartBar('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.chartBar('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.chartBar('372496'))} center center no-repeat; }
      }
    }
    &.call-history {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.phoneCall('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.phoneCall('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.phoneCall('372496'))} center center no-repeat; }
      }
    }
    &.fallback {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.fallBack('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.fallBack('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.fallBack('372496'))} center center no-repeat; }
      }
    }
    &.callbot {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.callBotManage('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.callBotManage('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.callBotManage('372496'))} center center no-repeat; }
      }
    }
    &.chatbot {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.chatBotManage('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.chatBotManage('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.chatBotManage('372496'))} center center no-repeat; }
      }
    }
    &.system {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.settings('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.settings('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.settings('372496'))} center center no-repeat; }
      }
    }
    &.bot-builder {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.botBuilder('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.botBuilder('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.botBuilder('372496'))} center center no-repeat; }
      }
    }
    &.acp-admin {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.headphones('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.headphones('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.headphones('372496'))} center center no-repeat; }
      }
    }
    &.stt-tts {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.mic('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.mic('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.mic('372496'))} center center no-repeat; }
      }
    }
    &.template {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.filter('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.filter('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.filter('372496'))} center center no-repeat; }
      }
    }
    &.counsel {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.counsel('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.counsel('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.counsel('372496'))} center center no-repeat; }
      } 
    }
    &.evaluation {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.evaluation('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.evaluation('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.evaluation('372496'))} center center no-repeat; }
      } 
    }
    &.notice {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.notice('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.notice('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.notice('372496'))} center center no-repeat; }
      } 
    }
    &.graph {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.graph('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.graph('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.graph('372496'))} center center no-repeat; }
      } 
    }
    &.search {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.search('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.search('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.search('372496'))} center center no-repeat; }
      } 
    }
    &.folderEdit {
      > button, > a {
        &::before { background: ${_mx.svg(_svg.folderEdit('374151'))} center center no-repeat; }
        &.on::before { background: ${_mx.svg(_svg.folderEdit('1f2937'))} center center no-repeat; }
        &:hover::before { background: ${_mx.svg(_svg.folderEdit('372496'))} center center no-repeat; }
      } 
    }
  }


  &.expand {
    > li {
      > button, > a {
        margin-top: 8px;
        span {color: ${_color.black2};}
        &::before { left: 16px; top: 50%; transform: translateY(-50%); }
        &.on {
          background: rgba(16, 40, 72, 0.09); border-radius: 6px;
          span { color: ${_color.black2};}
        }
      }
      > button {
        &.on {
          background: rgba(16, 40, 72, 0.09); border-radius: 6px;
          span { color: ${_color.black2};}
        }
      }
      > a {
        &.on {
          background: #EAEFFF; border-radius: 6px;
          span {color: #372496;}
        }
      }
      button, a {
        padding: 10px 16px 10px 52px; color: #4A545E; text-align: left; display: flex; align-items: center;
        &:hover {
          background: #EAEFFF; border-radius: 6px;
          span {color: #372496;}
        }
        span { font-size: 15px; font-weight: 500;  color: #4A545E; line-height: 20px; }
      }
      &.bot-builder, &.acp-admin, &.stt-tts {
        > button, > a {
          &::after {
            content: ''; width: 20px; height: 20px; position: absolute; right: 16px; top: 50%; transform: translate(0, -50%);
            background: ${_mx.svg(_svg.openInNew('7E8B99'))} center center no-repeat;
          }
        }
      }
      > ul {
        > li {
          > button, > a { margin-top: 6px; }
        }
      }
    }
  }
  &.collapse {
    > li {
      > button, > a {
        &::before { left: 50%; top: 50%; transform: translate(-50%, -50%); }
        &:hover { background-color: ${_color.secondary3}; border-radius: 8px; }
        &.on {
          background-color: ${_color.secondary3}; border-radius: 6px;
        }
      }
      button, a {
        padding: 0; width: 100%; height: 40px; margin-top: 8px;
        span {
          ${_mx.blind};
        }
      }
      &.dashboard {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.viewBoxes('372496'))} center center no-repeat; }
        }
      }
      &.test {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.tree('372496'))} center center no-repeat; }
        }
      }
      &.statistics {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.chartBar('372496'))} center center no-repeat; }
        }
      }
      &.call-history {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.phoneCall('372496'))} center center no-repeat; }
        }
      }
      &.fallback {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.fallBack('372496'))} center center no-repeat; }
        }
      }
      &.callbot {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.callBotManage('372496'))} center center no-repeat; }
        }
      }
      &.chatbot {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.chatBotManage('372496'))} center center no-repeat; }
        }
      }
      &.system {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.settings('372496'))} center center no-repeat; }
        }
      }
      &.bot-builder {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.botBuilder('372496'))} center center no-repeat; }
        }
      }
      &.acp-admin {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.headphones('372496'))} center center no-repeat; }
        }
      }
      &.stt-tts {
        > button, > a {
          &.on::before { background: ${_mx.svg(_svg.mic('372496'))} center center no-repeat; }
        }
      }
      
      ul { display: none; }
    }
  }
`
export const SubMenu = styled.ul`
  ${(props) => (props.isView ? 'display: block' : 'display: none')};
  li {
    > button, > a { 
      &.on {
        background: #EAEFFF; border-radius: 6px;
        span {color: #372496 !important; }
      }
    }
  }
`
export const SubContents = styled.div`
  padding: 10px 36px 10px;
  background-color: ${_color.gray7};
  height: calc(100vh - 44px);
  overflow-y: auto;
`;

export const AsideFooter = styled.ul`
  margin-top: auto;
  padding: 12px 24px;
  > li {
    a {
      span {
        font-size: 14px;
        font-weight: 500;
        color: #7e8b99;
        line-height: 30px;
      }
    }
  }
`;
