import { DashboardGridBoxs, HorizontalGraphWrap ,GraphWraps, GraphBox ,GraphTitleWrap} from 'style/AutoQAStyle'
import Title from 'components/common/Title';
import * as S from "../../../../../style/ElementsStyle";
import HorizontalStackedBarChart from 'components/chart/HorizontalStackedBarChart';
import RatioDougnutChartBig from 'components/chart/RatioDougnutChartBig';
import Filter from 'components/common/Filter';
import AutoRefreshSet from 'components/common/AutoRefreshSet';

const QAAType = () => {

  return (
    <>
      <Filter>
        <div className="left-area">
          <Title
            type="sub"
            title="상담 평가 현황"
            leftArea={<S.TxtInfo>　</S.TxtInfo>}
          />
        </div>
        <div className="right-area">
          <AutoRefreshSet
            refrashData={15000}
            autoRefrashTimeOption={15000}
            setAutoRefrashTimeOption={15000}
            onSaveCallback={() => { }} />
        </div>
      </Filter>
      
      <DashboardGridBoxs width={1578}>
        <div className="left">
          <div className='container'>
            <div className="titles">
              <p>평가 진행 현황</p>
              <span className="date">최근 업데이트 시간 HH:MM:SS</span>
            </div>
            <ul>
              <li data-title="평가 배정 건수" className='bold'>0,000</li>
              <li data-title="평가 완료 건수">0,000</li>
              <li data-title="진행중 건수">0,000</li>
              <li data-title="진행률(%)">0,000</li>
            </ul>
          </div>
          <div className='container'>
            <div className="titles">
              <p>평가 결과 현황</p>
              <span className="date">최근 업데이트 시간 HH:MM:SS</span>
            </div>
            <ul>
              <li data-title="평균 점수" className='bold'>0,000</li>
              <li data-title="최고 점수">0,000</li>
              <li data-title="최저 점수">0,000</li>
            </ul>
            <HorizontalGraphWrap>
              <HorizontalStackedBarChart
                width={700}
                height={60}
                datas={[17, 38, 25, 14, 8]}
                colors={['#5C5FD6', '#9D9FE6', '#BEBFEF', '#F8AB9A', '#F47356']}
                labels={['90-100점', '80-90점', '70-79점', '60-69점', '60점미만']}
              />
            </HorizontalGraphWrap>
          </div>
        </div>
      </DashboardGridBoxs>

      <GraphWraps>
        <GraphBox width={1578} height={260} padding={'30px 32px'} flexDirectionIs={'row'} horizontalFlexIs={'start'}>
          <GraphTitleWrap>
            <h5>상담 유형별 평가 현황</h5>
            <p>최근 업데이트 시간 HH:MM:SS</p>
          </GraphTitleWrap>
          <div className='two-custom-wraps' style={{width:'1121px',paddingLeft:'100px',gap:'100px'}}>
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={'신청/변경 요청'}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={''}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={'자동납부 신청 / 변경'}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={'혜택 상담'}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={'해지 상담'}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
            <RatioDougnutChartBig
              labels={['콜 건수', '이싱징후 건수']}
              datas={['50', '30']}
              colors={['#5C5FD6', '#F47356']}
              rate={'00.00%'}
              title={'기타 상담'}
              width={'100px'}
              height={'100px'}
              legendShowIs= {false}
            />
          </div>
        </GraphBox>
        </GraphWraps>
    </>
  );
}

export default QAAType;