import styled from "@emotion/styled/macro";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";

import * as S from "./ElementsStyle";
import * as CS from "./ChartStyle";
import * as PS from "./Statistics";

export const Dashboard = styled.div` 
	${S.Tab} {
		margin-top: 24px;
		.tab-cont { margin-top: 16px; }
	}
 
	.statistics {
		display: flex;
		background-color: #fff;
		.title {
			padding: 32px 100px 32px 32px;
			position: relative;
			width: 40%;
			strong { 
				font-size: 20px;
				color: #272E35;
				font-weight: 600;
			}
			p {
				margin-top: 10px;
				color: #555F6D;
				font-size: 14px;
				font-weight: 500;
			}
			${S.Button} {
				position: absolute;
				top: 50%;
				right: 40px;
				transform:translateY(-50%);
			}
		}
		.status {
			position: relative;
			width: 30%;
			display: flex;
			justify-content: space-between;
			
			padding: 32px 40px;
			> div {
				dt {
					color: #555F6D;
					font-size: 15px;
					font-weight: 600;
				}

				dd {
					margin-top: 12px;
					color: #272E35;
					font-size: 20px;
					font-weight: 600;
				}
				&.status-title {
					dt {
						color: #272E35;
						font-size: 16px;
						font-weight: 600;
					}

					dd {
						margin-top: 8px;
						color: #272E35;
						font-size: 24px;
						font-weight: 500;
					}
				}
			}

			&::after {
				content: '';
				position: absolute;
				top: 50%;
				left: 0;
				width: 2px;
				height: 60px;
				background-color: rgba(158, 168, 179, 0.50);
				transform: translate(0, -50%);
			}
		}
	}
`

export const DashboardBot = styled.div` 
	.reference-date {
		display: flex;

		dt,
		dd {
			color: #555F6D;
			font-size: 15px;
			font-weight: 500;
		}

		dt {
			padding-left: 26px;
			background: ${_mx.svg(_svg.timeClockNew)} left center no-repeat;
		 }
		dd { margin-left: 3px; }
	}

	.split-area {
		display: flex;
		gap: 32px;
		.split {
			flex: 1;
		}
	}
	.in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 52px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}
	}
`

export const SituationService = styled.div` 
	.box-multi-chart {
		width:100%;
		height:260px;
		background:#fff;
	}
	${PS.GridItem} {
		&:last-of-type {
			height:260px;
			.boxes1 {
				height:260px;
			}
		}
	}
`

export const SituationBotUse = styled.div` 
	.rank-list-wrap {
		display: flex;
		gap: 16px;
		margin-bottom: 40px;

		.box { 
			background-color: ${_color.white};
			box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
			border-radius: 8px;
			padding: 20px;

			&:nth-of-type(1) { width: 26%;}
			&:nth-of-type(2) { width: 37%;}
			&:nth-of-type(3) { width: 37%;}
		}

		.title {
			display: flex;
			align-items: center;
			justify-content: space-between;
			height: 40px;
			& + .sub-title {margin-top: 12px}
		}
		.sub-title {
			& + ${S.Table} { margin-top: 10px; }
			color: #5C5FD6;
			font-size: 16px;
			font-weight: 600;
		}

		.rank-graph {
			width:320px;
			height: 200px;
			margin: 18px auto 20px;
		}
	}

	${S.Table} {
		border-bottom:0;
		table {
			border-collapse: separate;
			border-spacing: 0;
			thead {
				th {
					border-bottom:0;
				}
			}
			tbody {
				border-top: 8px solid transparent;
			}
			td {
				border-top:1px solid transparent;
				border-bottom:1px solid transparent;
			}
			td:first-of-type {
				border-top-left-radius:10px;
				border-bottom-left-radius:10px;
			}
			td:last-of-type {
				border-top-right-radius:10px;
				border-bottom-right-radius:10px;
			}
			
			tr.checked {
				td {
					border-top:1px solid #C9CDF9;
					border-bottom:1px solid #C9CDF9;
				}
				td:first-of-type {
					border-left:1px solid #C9CDF9;
				}
				td:last-of-type {
					border-right:1px solid #C9CDF9
				}
			}
			th, 
			td {
				border-top: 0 none;
			}
			th {
				background-color: #F0F3F5;
				padding: 14px 0 14px;
				color: #555F6D;
				font-size: 14px;
				font-weight: 500;
			}
			td {
				height: 40px;
				padding: 6px 0;
				color: #272E35;
				font-size: 14px;
				font-weight: 400;
				${S.Button} {
					min-width: 28px;
					height: 28px;
					padding: 0 !important;
				}
			}
		}
	}
	${CS.HorizontalBarChart} {
		.inner {
			.chart {
    		margin-top: -15px;
			}
		}
	}
	
`

export const AutoRefreshSet = styled.div`
  display: flex;
  align-items: center;
  gap: 0 16px;
	position:relative;
	.refresh-item {
		display:flex;
		align-items:center;
		gap:0 12px;
		position:relative;
		&::before {
			content: '';
			display:none;
			position: absolute;
			top: 50%;
			left: 0;
			width: 1px;
			height: 28px;
			transform: translate(0, -50%);
			background-color: #9EA8B3;
		}
		& + .refresh-item {
			padding-left:16px;
			&::before {
				display:block;
			}
		}
	}
  .auto-title {
    font-size: 14px;
    font-weight: 400;
    padding: 4px 0 4px 26px;
    background: ${_mx.svg(_svg.settings)} left center no-repeat;
  }
  ${S.Button} { 
    position: relative;
    min-width: 40px;
		&.down-small {
    	justify-content: space-between;
			min-width:85px;
		}
  }
`
export const PopupAutoRefresh = styled.div`
	position:absolute;
	right:0;
	top:50px;
	width:500px;
	background:${_color.white};
	border-radius:8px;
	box-shadow: 0px 8px 16px -2px rgba(27, 36, 44, 0.12);
	z-index:100;
	.popup-inner {
		padding:20px 40px 24px;
	}
	${S.GrayBox} {
		flex-wrap:wrap;
		gap:30px 0;
		${S.Radio} {
			flex:1 1 30%;
			margin-left:0 !important;
		}	
	}
	.txt-guide {
		margin-top:8px;
		color: #555F6D;
		font-size: 14px;
		font-weight: 400;
		line-height: 22px;
	}
	.popup-btns {
		padding:24px 40px;
		border-top:1px solid #E9ECEF;
    justify-content: right;
		${S.Button} {
			width:120px;
		}
	}
`

export const DashboardRank = styled.div`
	${S.Title} {
		p {
			position:relative;
			padding-left:28px;
			color: #555F6D;
			font-size: 15px;
			font-weight: 500;
			line-height: 22px;
			&:before {
				content:'';
				display:block;
				position:absolute;
				left:0;
				top:50%;
				width:20px;
				height:20px;
				margin-top:-10px;
				background:${_mx.svg(_svg.timeClockNew)} left center no-repeat;
			}
		}
	}
	.grid-table {
		display:grid;
    grid-template-columns: repeat(2, 1fr);
		gap:0 32px;
		.grid-item {}
	}
`