import { useRef } from 'react'; // 231123
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import * as S from '../../style/ChartStyle';
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const HorizontalBarChart = ({ colors, legends, labels, datas = {}, percentage }) => {
  const data = {
    labels: labels,
    datasets: [
      {
        label: labels[1],
        data: datas.dataFirst,
        backgroundColor: colors,
        hoverBackgroundColor: colors,
        barThickness: 20,
        maxBarThickness: 20,
      },
      {
        label: labels[2],
        data: datas.dataSecond,
        backgroundColor: '#E9ECEF',
        hoverBackgroundColor: '#E9ECEF',
        barThickness: 20,
        maxBarThickness: 20,
      },
    ],
  };
  const options = {
    indexAxis: 'y',
    maintainAspectRatio: false,
    responsive: true,
    plugins: {
      legend: {
        display: false,
      },
      datalabels: {
        display: false,
      },
    },
    scales: {
      x: {
        // min: 1,
        max: datas.dataSecond !== undefined ? datas.dataSecond : 100,
        // setpSize: 1,
        border: {
          display: false,
        },
        grid: {
          drawBorder: false,
          display: false,
          lineWidth: 0,
        },
        ticks: {
          display: false,
          beginAtZero: true,
        },
      },
      y: {
        border: {
          display: false,
        },
        stacked: true,
        grid: {
          drawBorder: false,
          display: false,
          lineWidth: 0,
        },
        ticks: {
          display: false,
          beginAtZero: true,
        },
      },
    },
  };

  const legendContainer = useRef(); // 231123 ref 추가

  // 231123 htmlLegendPlugin 추가
  const htmlLegendPlugin = {
    id: 'htmlLegend',
    afterUpdate(chart) {
      const items = chart.options.plugins.legend.labels.generateLabels(chart);
      const legendBtn = legendContainer.current;
      legendBtn &&
        (legendBtn.onclick = (e) => {
          const li = e.target.closest('li') !== null ? e.target.closest('li') : e.target;
          li.classList.contains('disabled')
            ? li.classList.remove('disabled')
            : li.classList.add('disabled');
          chart.toggleDataVisibility(items[0].datasetIndex);
          chart.update();
        });
    },
  };

  return (
    <S.HorizontalBarChart>
      {legends && (
        <div className="chart-title">
          <div className="legend">
            <ul>
              <S.Legend color={colors} ref={legendContainer}>
                {' '}
                {/* 231123 ref 추가 */}
                <span></span>
                <p>{legends}</p>
              </S.Legend>
            </ul>
          </div>
        </div>
      )}
      <div className="inner">
        <div className="chart">
          <Bar options={options} data={data} plugins={[htmlLegendPlugin]} />{' '}
          {/* 231123 plugins 추가 */}
        </div>
        {percentage && <span className="percentage">{percentage}%</span>}
      </div>
    </S.HorizontalBarChart>
  );
};

export default HorizontalBarChart;
