import React, { Fragment, useEffect, useRef, useState } from 'react';
import classnames from 'classnames';

import Button from '../elements/Button';
import fp from 'lodash/fp';

import ChatElement from '../elements/ChatElement';
import * as S from '../../style/ElementsStyle';
import WaveSurferPlayer from 'components/wavePlayer/WaveSurferPlayer';

/**
 * isDate : 날짜노출 여부
 * isChatInput : input 노출 여부
 * isSimulate : 채팅 정렬 구분용
 * list : 케이스확인 샘플용
 * iconType : 검색용 아이콘 적용 추가
 */
const ChatElementWrap = ({
  isDate = true,
  isChatInput = true,
  isSimulate = false,
  list = [],
  focusId,
  iconType = '',
  setPlay = () => { },
  pcmPlayList = [],
  waveIs = false,
  waveH = 30
}) => {
  /* input 높이 계산용 */
  const [val, setVal] = useState('');
  const textAreaRef = useRef(null);
  const focusedItemRef = useRef({});

  const resizeTextArea = () => {
    if (isChatInput && textAreaRef.current.scrollHeight < 67) {
      textAreaRef.current.style.height = 'auto';
      textAreaRef.current.style.height = textAreaRef.current.scrollHeight + 'px';
    }
  };

  const scrollToId = (focusId) => {
    const ref = focusedItemRef.current[focusId];
    if (ref && ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const onChange = (e) => {
    setVal(e.target.value);
  };

  const botConversation = () => {
    console.log('봇 대화 클릭');
  };

  useEffect(resizeTextArea, [val]);

  useEffect(() => {
    if (focusId) {
      scrollToId(focusId);
    }
  }, [focusId]);
  return (
    <>
      <S.ChatElementWrap className={classnames({ 'simulate-type': isSimulate })}>
        {isDate && (
          <S.ChatDate>
            <strong className="title">
              {isDate.title} 상담 시간: {isDate.date}
            </strong>{''}
            {/* 231027 텍스트를 변수로 변경 */}
            {iconType === 'forbidden' && <p className='forbidden'><span> </span>금칙어</p>}

          </S.ChatDate>

        )}
        {waveIs &&
          <div style={{ width: '100%', height: 'auto', padding: '16px 20px' }}>
            <WaveSurferPlayer
              height={waveH}
              cursorWidth={10}
              waveColor={'#4e47d6'}
              progressColor={'#ddd5e9'}
              url={``}
              mediaControls={true}
              isShowButton={false}
            />
          </div>
        }
        <S.ChatElementList>
          {list.length > 0 ? (
            <>
              <div>
                <ul>
                  {list.map((item, index) => (
                    <li
                      key={`chat-${index}`}
                      ref={(el) => {
                        if (!focusedItemRef.current[item.id]) {
                          focusedItemRef.current[item.id] = React.createRef();
                        }
                        focusedItemRef.current[item.id].current = el;
                      }}
                    >
                      <ChatElement
                        item={{
                          ...item,
                          focus: focusId === item.id
                        }}
                        botClick={botConversation}
                        setPlay={setPlay}
                        isPlay={fp.some((pcm) => pcm.id == item.statDialogId && pcm.isPlay)(
                          pcmPlayList
                        )}
                      />
                    </li>
                  ))}{' '}
                  {/* 231103 봇 대화 클릭 이벤트 추가 */}
                  {/* <li className="line-chat">
                    <div className="line-inner">
                      <span>봇 전이</span>
                    </div>
                  </li>
                  <li className="line-chat chat-end">
                    <div className="line-inner">
                      <span>테스트 종료</span>
                    </div>
                  </li> */}
                </ul>
              </div>
            </>
          ) : (
            <>
              <>
                <div className="placeholder">
                  <p>확인할 이력을 선택해주세요.</p>
                </div>
                {/* 231110 텍스트 변경 */}
                {/* <div className="chat-save-complete"><span>저장 완료</span></div> */}
                {/* 231110 삭제 */}
              </>
            </>
          )}
        </S.ChatElementList>
        {/* {list.length > 0 ? (
          <S.ChatSaveBtn>
            <Button className="secondary btn-chat-save" label="테스트 종료 및 내역 저장" />
          </S.ChatSaveBtn>
        ) : (
          <></>
        )}{' '} */}
        {/* 231103 버튼 위치 변경, 231106 코드 변경 */}
        {isChatInput && (
          <S.ChatInput>
            <textarea
              ref={textAreaRef}
              value={val}
              onChange={onChange}
              rows={1}
              placeholder="검색어를 입력해주세요."
            ></textarea>
            <button
              type="button"
              className={classnames(
                iconType === 'search' || iconType === 'forbidden' ? 'btn-search-word' : 'btn-message-send',
                { active: val.length > 0 }
              )}
            >
              <span className="hidden">전송</span>
            </button>

          </S.ChatInput>
        )}
      </S.ChatElementWrap>
    </>
  );
};

export default ChatElementWrap;
