import styled from "@emotion/styled/macro";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";
import * as S from "./ElementsStyle";



export const SelectButton = styled.div`
	.btn-call-select {
		position: relative;
		display: flex;
		flex-direction: column;
		justify-content: center;
		padding: 8px 12px 8px 16px;
		/* width: 100%; */
		height: 60px;
		background-color: #fff;
		border-radius: 6px;
		border: 1px solid #CFD6DD;
		text-align: left;
		box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);

		${({ isFlow }) => isFlow && `
			&::after {
				content: '';
				position: absolute;
				left: -24px;
				top: 50%;
				width: 24px;
				height: 32px;
				margin-top: -16px;
				background: ${_mx.svg(_svg.chevron("272e35"))} center no-repeat;
				transform: rotate(180deg)
			}
		`}

		.label,
		.name { font-size: 14px; }
		.label {& + .name {margin-top: 4px;}}

	}

	&.active {
		.btn-call-select {
			border: 1px solid #cfd6dd;
			font-weight: 500;
			${({ isFlow }) => isFlow && `
				&::after {
					transform: rotate(-90deg)
				}
			`}
		}
	}

	${({ isFlow }) => isFlow && `
		& + .area-flow-tree {
			height: 0;
			overflow: hidden;
		}

		&.active + .area-flow-tree {
			height: 100%;
			overflow: visible;
		}
	`}

`

export const CallElementWrap = styled.div`
	${S.ScrollDefaultStyle} 
	height: 100%;
	overflow-x: hidden;
	overflow-y: auto;
	display: flex;
	flex-direction: column;
	gap: 18px;
	padding-right: 10px;;

	${SelectButton} {
		button {
			width: 140px;
		}
	}

	.call-list-wrap {
		display: flex;

		.area-bot {
			width: 140px;
			flex-shrink: 0;
			text-align: center;
			${SelectButton} + .flag-label { margin-top: 10px }
			.flag-label + .flag-label { margin-top: 6px }
		}

		.area-flow {
			flex: 1;
			display: flex;
			flex-direction: column;
			gap: 16px;
			padding-left: 24px;
			${SelectButton} {
				&.active + .area-flow-tree {
					.flag-label {
						position: static;
					}
				}
			}
			.flow-inner {
				position: relative;

				.area-flow-tree {
					margin-top: 12px;
					display: flex;
					flex-direction: column;
					gap: 12px;

					> div {
						display: flex;
						align-items: center;
					}

					.flag-label {
						position: absolute;
						top: 16px;
						left: 140px;
						margin-left: 8px;
						min-width: auto;
						padding: 0 14px;
					}
				
				}
			}
		}

		.btn-call-tree-select {
			width: 140px;
			flex-shrink: 0;
			height: 32px;
			background-color: #f5f7f9;
			border: 1px solid #cfd6dd;
			border-radius: 6px;
			font-size: 14px;
			font-weight: 400;
			text-align: left;
			padding: 0 14px;
			cursor: default;
			.label {
				font-weight: 400;
			}
			&.active {
				border: 2px solid #4E47D6;
				color: #4E47D6;
				background-color: #fff;
				.label {
					font-weight: 500;
				}

			}

			/* & + .flag-label {
				margin-left: 12px;
			} */
		}
	}
	
	.line-chat {
    display:flex;
    position:relative;
    &:before {
      content:'';
      display:block;
      position:absolute;
      top:50%;
      left: -12px;
      right: 0;
      width: calc(100% + 14px);
      height:1px;
      background-color: rgba(92, 95, 214, 0.20);
    }
    .line-inner {
      position:relative;
      padding:0 8px;
      background:#fff;
      margin:0 auto;
      span {
        display:block;
        min-width:88px;
        height:28px;
        padding:0 10px;
        border-radius:14px;
        color: ${_color.secondary0};
        font-size: 14px;
        font-weight: 400;
        line-height: 28px;
        background-color:#dbdff7;
        text-align:center;
      }
    }
    &.chat-end {
      margin-top:8px;
    }
  }

	.flag-label {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		padding: 0 15px;
		min-width: 80px;
		height: 28px;
		color: #372496;
		font-size: 13px;
		background: #EAEFFF;
		border-radius: 4px;
		border: 1px solid rgba(117, 117, 224, 0.50);
		/* padding: 0 16px; */
	}

	.icon-transfer {
		flex-shrink: 0;
		display: inline-flex;
		vertical-align: top;
		margin-left: 8px;
		width: 32px;
		height: 32px;
		border: 1px #CFD6DD solid;
		box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
		background: ${_mx.svg(_svg.transfer("555F6D"))} center no-repeat;
		border-radius: 100%;

		&:hover,
		&:focus {
			border: 1px #9EA8B3 solid;
		}

		&.active {
			border: 2px solid #4E47D6;
		}

	}
`

export const CallHistory = styled.div`
	.table-hover-wrap {
		position: relative;
		&::after {
			content: '';
			position: absolute;
			bottom: 0;
			left: 0;
			width: 100%;
			height: 50px;
			background-color: #f3f4f6;
		}
		& + ${S.Pagination} {
			margin-top: -20px;
		}
	}

	${S.Table} {
		border-bottom: 0;

		table {
			position: relative;
			padding-bottom: 50px;
			background-color: #f3f4f6;
			border-bottom: 0;
			&::after {
				/* content: ''; */
				position: absolute;
				bottom: 50px;
				left: 0;
				width: 100%;
				height: 1px;
				background-color: #d7d9f3;
			}

			tbody {
				tr:last-child {
					td {
						/* border-bottom: 50px solid transparent; */
					}
				}
			}
		}

	}
	.in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 52px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}

	}
	.sub-list-info {
		display: flex;
		margin: 0 4px;
		gap: 0 16px;
		> div {
			display: flex;
			gap: 0 8px;
		}

		dt,
		dd {
			font-size: 14px;
			font-weight: 500;
			line-height: 20px;
		}

		dt {
			color: #7E8B99;
		}
		dd {
			color: #555F6D;
		}
	}
`;

export const PopupCallHistory = styled.div`
	${S.Table} {
    /* overflow: hidden; */
		border:1px solid #D7D9F3;
		border-radius:8px;

		table {
			
			&.active {
				display: table;
			}
			td {
				background-color: transparent;
			}
		}
	}
	.top-info {
		display: flex;
		gap: 0 20px;
		padding: 13px 20px;
		.inner {
			display: flex;
			align-items: center;
			gap: 0 16px;
			width:20%;
			
			&:first-of-type {
				width: 40%;
			}
			&:nth-of-type(3) {
				width:15%;
			}
			&:last-of-type {
				width: 26%;
				${S.Button} {
					width: 28px;
					min-width: 28px;
					transform: rotate(90deg);

					&.active {
						transform: rotate(-90deg);
					}
				}
			}
			dt {
				display: flex;
				align-items: center;
				justify-content: center;
				height: 36px;
				color: #555F6D;
				font-size: 15px;
				font-weight: 500;
				border-radius: 6px;
				background-color: #f5f7f9;
				padding: 0 42px;
				flex-shrink: 0;
			}
			dd {
				display: flex;
				align-items: center;
				gap: 8px;
				flex: 1;
				color: #272E35;
				font-size: 15px;
				font-weight: 500;
			}
		}


	}

	.box-call-inquiry {
		display: flex;
		gap: 25px;
		margin-top: 14px;
		.inner:nth-of-type(1) {
			width: calc(100% - 460px - 25px);
		}
		.inner:nth-of-type(2) {
			width: 460px;
			min-width:460px;
		}
		.callingInner:nth-of-type(1) {
			width: 50%;
		}
		.callingInner:nth-of-type(2) {
			width: 50%;
		}

		.simulate-inner {
			/* height: 800px; */
			border-radius: 6px;
    	border:1px solid #D7D9F3;
			overflow: hidden;
			
			${S.ChatElementWrap} {
				border-radius:0 0 7px 7px;
    		border: 0 none;
				border-top: 1px solid #D7D9F3;
			}

			.area-equalizer {
				height: 155px;
				padding: 22px 23px 16px;
				background-color: #fff;
				.title-content-wrap {
					flex-wrap: wrap;
					height: calc(100% - 18px);
					.a-title,
					.a-content {
						width: 100%;
					}
				}
			}

			.area-section-choice {
				padding: 20px 23px;
				background-color: #e9edfb;
				.swiper-area {
					.swiper {
						margin: 0 48px;
						.swiper-slide {
							text-align: center;
							width: auto;

							&::before {
								content: '';
								position: absolute;
								top: 0;
								left: -32px;
								width: 32px;
								height: 100%;
								background: ${_mx.svg(_svg.chevron("272e35"))} center no-repeat;
								transform: rotate(-180deg);
							}
						}
					}

					.swiper-button-prev,
					.swiper-button-next {
						z-index: 10;
						position: absolute;
						top: 50%;
						transform: translate(0, -50%);
						width: 36px;
						height: 36px;
						border-radius: 6px;
						border: 1px solid #CFD6DD;
						background-color: #fff;
						box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
					}

					.swiper-button-prev {
						left: 0;
					}
					.swiper-button-next {
						right: 0;
					}

					.swiper-button-prev::after,
					.swiper-button-next::after {
						content: '';
						position: absolute;
						top: 0;
						left: 0;
						background-position: center;
						background-repeat: no-repeat;
						width: 100%;
						height: 100%;
						background-image: ${_mx.svg(_svg.chevron("272e35"))};
					}

					.swiper-button-next::after {
						transform: rotate(-180deg);
					}

					.swiper-button-prev:hover::before,
					.swiper-button-next:hover::before,
					.swiper-button-prev:focus::before,
					.swiper-button-next:focus::before {
						content: '';
						z-index: 20;
						position: absolute;
						top: -4px;
						left: -4px;
						border-radius: 8px;
						width: calc(100% + 4px);
						height: calc(100% + 4px);
						border: 2px solid #4e47d6;
					}

					.swiper-button-prev:disabled,
					.swiper-button-next:disabled {
						border-color: #dce2ec;
						background-color: #f4f6fd;
						cursor: inherit;
						&::before {
							content: none;
						}
						&::after {
							background-image: ${_mx.svg(_svg.chevron("9aa1ad"))};
						}
					}
				}
			}
			.area-chat {
				height: 640px;
			}

			.title-content-wrap {
				position: relative;
				display:flex;
				align-items:center;
				height: 100%;
				.a-title {
					display: flex;
					align-items: center;
					width: 92px;
					min-width:92px;
					color: ${_color.black2};
					font-size: 15px;
					font-weight: 500;
					padding-left: 34px;
					&[class^="icon-"] {
						background-repeat: no-repeat;
						background-position: left center;
					}
					&.icon-slider {
						background-image: ${_mx.svg(_svg.slider("4e47d6"))};
					}
					&.icon-play {
						background-image: ${_mx.svg(_svg.play("4e47d6"))};
					}
				}
				.a-content {
					width:calc(100% - 92px);
					height: 100%;

					.audio-listen {
						display: flex;
						flex-direction: column;
						height: 100%;
						gap: 5px;
						margin-top: 5px;

						.wave-audio {
							overflow: hidden;
							flex-shrink: 0;
							canvas {
								height: 53px !important;
							}
						}

						.control-audio {
							height: 54px;
							audio { 
								width: 100%;
								height: 100%;
							 }
						}
					}
				}
			}
		}

		.call-inquiry-inner {
			border: 1px solid #d7d9f3;
			height: 892px;
			border-radius: 8px;
			padding: 27px 0 27px 24px;
			background-color: #fff;

			${SelectButton} {
				.name {
					display: block;
					overflow: hidden;
					white-space: nowrap;
					text-overflow: ellipsis;
				}
			}
		}
	} 

	${S.Flag} {
		.error-message {
			right: auto;
			left: 0;
			&::before {
				right: auto;
				left: 37px;
			}
		}
	}

`;


export const CallElement = styled.div`

`