import { useState } from "react";
import { AddCategoryContainer } from "style/AutoQAStyle";
import FormGrid from "components/common/FormGrid";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Button from "components/elements/Button";

const CategoryDetails = ({ viewType }) => {
  const tempTitle = 'Category 0'; //임시 선택 값
  const [categorys, setCategory] = useState([]); //카테고리 추가 임시 값

  const onAddCategory = () => {
    setCategory([...categorys, ""]);
  };

  const removeCategory = (index) => {
    setCategory(categorys.filter((_, i) => i !== index));
  };

  const onChangeCategory = (index, value) => {
    const newcategorys = [...categorys];
    newcategorys[index] = value;
    setCategory(newcategorys);
  };

  return (
    <>
      <AddCategoryContainer>
        <FormGrid gap={8}>
          {viewType === 'edit' &&
            <FormItem label={'카테고리명'} gap={8}>
              <div style={{ display: 'flex', gap: 8 }}>
                <TextField
                  width={377}
                  defaultValue={tempTitle}
                  // count={10}
                  // maxLength={10}
                //disabled={true} // 하위depth일 경우
                />
              </div>
            </FormItem>
          }
          {viewType === 'add' &&
            <>
              {categorys.map((category, index) => (
                <FormItem label={`카테고리명`} key={index}>
                  <div style={{ display: "flex", gap: 8 }}>
                    <TextField
                      placeholder={"카테고리명을 입력하세요."}
                      width={377}
                      count={10}
                      maxLength={10}
                      value={category}
                      onChange={(e) => onChangeCategory(index, e.target.value)}
                    />
                    <Button
                      className="secondary minus"
                      btnType="icon"
                      onClick={() => removeCategory(index)}
                    />
                  </div>
                </FormItem>
              ))}
              <FormItem label={`카테고리명`}>
                <div style={{ display: 'flex', gap: 8 }}>
                  <TextField
                    placeholder={"카테고리명을 입력하세요."}
                    width={377}
                    count={10}
                    maxLength={10}
                  />
                  <Button className="primary left-plus" btnType='icon' onClick={onAddCategory} />
                  {categorys.length > 0 && <Button className="secondary minus" btnType="icon" onClick={() => removeCategory(categorys.length - 1)} />}
                </div>
              </FormItem>
            </>
          }
        </FormGrid>
      </AddCategoryContainer>
    </>
  );
};

export default CategoryDetails;