import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

import Title from 'components/common/Title';
import Select from 'components/elements/Select';
import Table from 'components/common/Table';
import Button from 'components/elements/Button';
import Filter from 'components/common/Filter';
import Pagination from 'components/common/Pagination';
import LayerPopup from 'components/common/LayerPopup';
import Checkbox from 'components/elements/Checkbox';
import { TableInTxtBtn, SubTableTitle, CountingTitle } from 'style/AutoQAStyle';
import TextField from 'components/elements/TextField';
import ButtonList from 'components/common/ButtonList';
import EvaluationSheetPopup from './popups/EvaluationSheetExcelPopup';
import Alert from 'components/common/Alert';

const _personList = [
  {
    name: '통합평가',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  },
  {
    name: '첫인사',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  },
  {
    name: '요금안내1',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  },
  {
    name: '통합평가2',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '통합평가3',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '요금안내2',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '요금안내3',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '요금안내14',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '요금안내5',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }, {
    name: '요금안내6',
    type1: '상담유형1',
    type2: '상담유형2',
    type3: '상담유형3',
  }
];

const EvaluationSheetPage = () => {
  const navigate = useNavigate();
  const [openDetail, setDetailOpen] = useState(false); // 엑셀 업로드 팝업
  const [deletePopup, setDeletePopup] = useState(false); // 삭제 클릭 팝업
  const _btnListIs = [
    {
      label : '취소',
      type:'secondary',
      evt : () => {console.log('1')}
    },
    {
      label : '확인',
      type:'primary',
      evt : () => {console.log('2')}
    },
  ];

  return (
    <>
      {openDetail && // 엑셀 업로드 팝업
        <LayerPopup
          size="large"
          title="평가표 엑셀 업로드"
          customWidth={800}
          open={openDetail}
          onClose={() => setDetailOpen(false)}
        >
          <EvaluationSheetPopup />
        </LayerPopup>
      }
      {deletePopup && // 선택삭제 팝업
        <Alert onClose={() => setDeletePopup(false)} text={'삭제가 완료되었습니다.'} />  // **** 기본 텍스트 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'<div class="icon"></div><span class="red">현재 진행 중</span>인 평가 계획은 삭제가 불가합니다.'}/>  // **** 아이콘 + 경고(빨간 텍스트) 포함 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'선택하신 평가 계획을 삭제 하시겠습니까?​'} btnList={_btnListIs}/>  // **** 기본 텍스트 타입
      }
      <Title title="평가표 조회" icon="evaluation"/>
      <Filter>
        <TextField
          placeholder="평가표명를 입력해주세요"
          label="평가표 입력"
          multi
          onChange={(e) => { }}
        />
        <Select
          option={[]}
          label="상담 유형 1 선택"
          value={null}
          title={'상담유형 1'}
          disabled={false}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="상담 유형 2 선택"
          value={null}
          disabled={false}
          title={'상담유형 2'}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="상담 유형 3 선택"
          value={null}
          disabled={false}
          title={'상담유형 3'}
          onChange={() => { console.log('select!') }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>
      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          { label: '선택 삭제', className: 'secondary del2', onClick: () => setDeletePopup(true) },
          { label: '엑셀 업로드', className: 'secondary upload', onClick: () => { setDetailOpen(true) } },
          { label: '생성', className: 'primary left-plus', onClick: () => navigate('/evaluationSheet/detail')},
        ]} />
      </SubTableTitle>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <caption>평가표 조회</caption>
          <colgroup>
            <col width="64px" />
            <col width="194px" />
            <col width="240px" />
            <col width="240px" />
            <col width="240px" />
            <col width="200px" />
            <col width="200px" />
            <col width="200px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th className="t-left left-padding">평가표명</th>
              <th className="t-left left-padding">상담유형1</th>
              <th className="t-left left-padding">상담유형2</th>
              <th className="t-left left-padding">상담유형3</th>
              <th>항목 수</th>
              <th>상세 항목 수</th>
              <th>복사</th>
            </tr>
          </thead>
          <tbody>
            {_personList.map((item, index) => {
              return <tr key={index} onClick={(e) => {
                // 클릭한 요소가 체크박스가 포함된 td일 경우 행 클릭 이벤트 무시
                const excludedTd = e.currentTarget.querySelector('td.checkType');
                if (excludedTd && excludedTd.contains(e.target)) {
                  return;
                }
                navigate('/evaluationSheet/detail');
              }}>
                <td className='checkType'><Checkbox /></td>
                <td className="t-left left-padding" height={52}>{item.name}</td>
                <td className="t-left left-padding">{item.type1}</td>
                <td className="t-left left-padding">{item.type2}</td>
                <td className="t-left left-padding">{item.type3}</td>
                <td>2</td>
                <td>2</td>
                <td className='center'>
                  <TableInTxtBtn onClick={() => { }}>복사</TableInTxtBtn>
                </td>
              </tr>
            })}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  )
};

export default EvaluationSheetPage;