import React, { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Button from 'components/elements/Button';
import dayjs from 'dayjs';
import Filter from 'components/common/Filter';
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import SortingButton from 'components/elements/SortingButton';
import TwoBarChart from 'components/chart/TwoBarChart';
import NoData from 'components/common/NoData';
import { StatisticsDashboardContainer, StatisticsDashboardTitle, GraphWraps, GraphBox } from 'style/AutoQAStyle';
import DateRange from 'components/common/DateRange';
import Select from 'components/elements/Select';

const AbnolmalCallConsultationTypeTab = () => {
  const [date, setDate] = useState('2023-01-20 ~ 2023-01-22'); //기간
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜

  return (
    <>
      <StatisticsDashboardContainer>
        <Filter>
          <Select title={'금칙어 선택'} label={'금칙어 선택'} option={[]} />
          {/* <Select title={'상담 유형 선택'} label={'상담 유형 선택'} option={[]} /> */}
          <DateRange
            rangeCal
            utilMenu
            label="상담 일시"
            monthsShown={2}
            selectsRange
            format="YYYY-MM-DD"
            startDate={dayjs(startDate).toDate()}
            endDate={dayjs(endDate).toDate()}
            selected={dayjs(startDate).toDate()}
            disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
            disableNum={3}
            maxDate={dayjs().toDate()}
            onChange={(value) => {
              setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
              setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
            }}
          />
          <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
        </Filter>
        <StatisticsDashboardTitle>
          <div>
            <h5 className="title">상담 유형별 이상 징후</h5>
            <span className="date">{date}</span>
          </div>
          <Button label="다운로드" className="secondary download down-small" onClick={() => { alert('조회중') }} />
        </StatisticsDashboardTitle>

        {/* 대시보드 */}
        <GraphWraps>
          <GraphBox width={1576} height={248} padding={'48px 60px'}>
            <TwoBarChart
              legendPadding={60}
              title={'금칙어 발생 건수'}
              legends={['이상 징후 발생 건수', '금칙어 사용 횟수']}
              colors={['#5C5FD6', '#F47356']}
              labels={["상담>상담>상담", '상담>상담>상담', "상담>상담>상담", '상담>상담>상담', "상담>상담>상담", '상담>상담>상담', "상담>상담>상담", '상담>상담>상담', "상담>상담>상담", '상담>상담>상담']}
              width={1134}
              height={173}
              datas={[[92, 91, 93, 94, 92, 95, 94, 93, 91, 92], [80, 85, 90, 85, 80, 85, 90, 85, 80, 85],]}
            />
          </GraphBox>
        </GraphWraps>
      </StatisticsDashboardContainer>

      <Table className="active" fixedHeader={true} height="532" hover={true} interval={true} round={false} xScroll={true}>
        <table>
          <colgroup>
            <col width="180px" />
            <col width="160px" />
            <col width="206px" />
            <col width="206px" />
            <col width="206px" />
            <col width="206px" />
            <col width="206px" />
            <col width="206px" />
            <col width="206px" />
          </colgroup>
          <thead>
            <tr>
              <th><SortingButton text={'금칙어'} /></th>
              <th><SortingButton text={'총 사용 횟수'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
              <th><SortingButton text={'상담>상담>상담'} /></th>
            </tr>
          </thead>
          <tbody>
            <tr><td colSpan={8}><NoData txt={'데이터가 없습니다'}/></td></tr>
            {/***********************
                  데이터 없는 경우
              *********************** 
            <tr><td colSpan={8}><NoData txt={'데이터가 없습니다'}/></td></tr> 
            */}
            {/* {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index}>
                <td>{'상담>상담>상담'}</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
              </tr>
            ))} */}
          </tbody>
        </table>
      </Table>

      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}

export default AbnolmalCallConsultationTypeTab;