import React, { forwardRef } from "react";
import classNames from "classnames";
import { TreeWrapper, TreeListArrow, ActionButton } from "style/AutoQAStyle";


// Action 컴포넌트
export const Action = ({ className, cursor, ...props }) => {
  return <ActionButton className={classNames(className)} cursor={cursor} {...props} />;
};

// Handle 컴포넌트
export const Handle = (props) => {
  return <Action className="dragCursor" cursor="move" data-cypress="draggable-handle" {...props} />;
};

// TreeItem 컴포넌트
export const TreeItem = forwardRef(
  (
    {
      depth,
      ghost,
      indicator,
      collapsed,
      onCollapse,
      onSelect,
      selectedId,
      id,
      value,
      handleProps,
      wrapperRef,
      ...props
    },
    ref
  ) => {
    return (
      <TreeWrapper className={classNames(ghost && "ghost", indicator && "indicator")} ref={wrapperRef} {...props}>
        <div className={classNames("one-depth", !collapsed ? "active" : "", selectedId === id ? "select" : "")}
          ref={ref}
          style={{background: depth > 0 && '#fff' }}
        >
          {/* 드래그 핸들 */}
          <Handle {...handleProps} />

          {/* 카테고리 명 + 클릭 이벤트 */}
          <p onClick={() => onSelect(id === selectedId ? null : id)}>
            {depth > 0 && <TreeListArrow depth={depth} />}
            {value}
          </p>

          {/* 하위 카테고리 여닫는 버튼 */}
          {onCollapse && (
            <Action
              onClick={(e) => {
                e.stopPropagation(); // 이벤트 버블링 방지
                onCollapse();
              }}
              className={classNames("btn-toggle-triangle", collapsed ? "collapsed" : "open")}
            />
          )}
        </div>
      </TreeWrapper>
    );
  }
);
