import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';

const Checkbox = ({
  type,
  value,
  id,
  checkError,
  defaultChecked,
  checked,
  disabled,
  indeterminate = false,
  callback,
  children,
  hiddenLabel = false,
  alert,
  helper,
}) => {
  return (
    <S.Checkbox
      className={classnames('box-checkbox', { error: checkError })}
      type={type}
      disabled={disabled}
    >
      <label>
        <input
          type="checkbox"
          value={value}
          data-id={id}
          defaultChecked={defaultChecked}
          checked={checked}
          disabled={disabled}
          onChange={(e) => {
            callback && callback(e);
          }}
        />
        <span className="txt-label">
          <i className={classnames('icon', { icon__indeterminate: indeterminate })}></i>
          <em className={classnames('label', { hidden: hiddenLabel })}>{children}</em>
        </span>
      </label>

      {helper && <div className="alert-text">{alert}</div>}
    </S.Checkbox>
  );
};

export default Checkbox;
