import { useState } from "react";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import React from "react";
import Button from "components/elements/Button";
import TextField from "components/elements/TextField";
import { PopupSubTitle, TableInTxtBtn } from "style/AutoQAStyle";
import Table from "components/common/Table";

const MAX_NUM = 5;

const EvaluationSheetAddColum = () => {

  const [sections, setSections] = useState([
    {
      title: "",
      description: "",
      score: "",
      rows: [{ detail: "", score: "" }],
    },
  ]);

  const handleAddSection = () => {
    setSections([
      ...sections,
      {
        title: "",
        description: "",
        score: "",
        rows: [{ detail: "", score: "" }],
      },
    ]);
  };

  const handleAddRow = (sectionIndex) => {
    setSections((prevSections) => {
      const updatedSections = [...prevSections];
      const section = updatedSections[sectionIndex];
      if (section.rows.length < MAX_NUM) {
        section.rows.push({ detail: "", score: "" });
      }
      return updatedSections;
    });
  };

  const handleDeleteRow = (sectionIndex, rowIndex) => {
    setSections((prevSections) => {
      const updatedSections = [...prevSections];
      const section = updatedSections[sectionIndex];
      if (section.rows.length > 1) {
        section.rows = section.rows.filter((_, i) => i !== rowIndex);
      }
      return updatedSections;
    });
  };

  const handleSectionChange = (index, field, value) => {
    setSections((prevSections) => {
      const updatedSections = [...prevSections];
      updatedSections[index][field] = value;
      return updatedSections;
    });
  };

  const handleRowChange = (sectionIndex, rowIndex, field, value) => {
    setSections((prevSections) => {
      const updatedSections = [...prevSections];
      const section = updatedSections[sectionIndex];
      section.rows[rowIndex][field] = value;
      return updatedSections;
    });
  };


  return (
    <>
      {sections.map((section, sectionIndex) => (
        <div key={sectionIndex} style={{ marginBottom: "24px" }}>
          <PopupSubTitle>평가 항목 정보 <strong> *</strong> </PopupSubTitle>
          <GrayBox direction={"column"}>
            <FormItem label={"평가 항목 명"} marginB={8}>
              <TextField
                width={561}
                maxLength={30}
                count
                value={section.title}
                onChange={(e) => handleSectionChange(sectionIndex, "title", e.target.value)}
              />
            </FormItem>
            <FormItem label={"평가 항목 설명"} marginB={8}>
              <TextField
                width={561}
                maxLength={30}
                count
                value={section.description}
                onChange={(e) => handleSectionChange(sectionIndex, "description", e.target.value)}
              />
            </FormItem>
            <FormItem label={"항목 배점"}>
              <TextField
                width={223}
                placeholder={"숫자만 입력하세요."}
                value={section.score}
                onChange={(e) => handleSectionChange(sectionIndex, "score", e.target.value)}
              />
            </FormItem>
          </GrayBox>

          <PopupSubTitle marginT={24}>평가 세부 항목 정보</PopupSubTitle>

          <div style={{ borderBottom: '1px solid #d7d9f3' }}>
            <Table className="active" fixedHeader={true} height="260" hover={false} round={false} borderBottom={false}>
              <table>
                <caption>평가 세부 항목 정보</caption>
                <colgroup>
                  <col width="760px" />
                  <col width="176px" />
                  <col width="160px" />
                </colgroup>
                <thead>
                  <tr>
                    <th className="t-left left-padding">세부 항목</th>
                    <th className="t-left left-padding">세부 항목별 점수</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {section.rows.map((row, rowIndex) => (
                    <tr key={rowIndex} height='54px'>
                      <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                        <TextField
                          width={744}
                          maxLength={30}
                          count
                          value={row.detail}
                          placeholder={"평가 세부 항목을 입력하세요."}
                          onChange={(e) =>
                            handleRowChange(sectionIndex, rowIndex, "detail", e.target.value)
                          }
                        />
                      </td>
                      <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                        <TextField
                          width={160}
                          value={row.score}
                          placeholder={"숫자만 입력하세요."}
                          onChange={(e) =>
                            handleRowChange(sectionIndex, rowIndex, "score", e.target.value)
                          }
                        />
                      </td>
                      <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                        <div
                          style={{
                            display: "flex",
                            width: "136px",
                            justifyContent: "space-between",
                          }}
                        >
                          <TableInTxtBtn
                            onClick={() => handleAddRow(sectionIndex)}
                            disabled={section.rows.length >= MAX_NUM}
                          >
                            추가
                          </TableInTxtBtn>
                          <TableInTxtBtn
                            className={`red ${rowIndex === 0 && 'disabledIs'}`}
                            onClick={() => handleDeleteRow(sectionIndex, rowIndex)}
                            disabled={section.rows.length === 1}
                          >
                            삭제
                          </TableInTxtBtn>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </Table>
          </div>

        </div>
      ))}

      <div style={{ marginTop: "24px", display: "flex", justifyContent: "end" }}>
        <Button
          label="평가 항목 추가"
          className={"primary left-plus"}
          onClick={handleAddSection}
          disabled={sections.length >= MAX_NUM}
        />
      </div>
    </>
  );
};

export default EvaluationSheetAddColum;
