import { useNavigate } from "react-router-dom";
import { useState } from "react";
import { SubContentsWrap , BackBtnWrap ,SubTableTitleWrap} from "style/AutoQAStyle";
import Button from "components/elements/Button";
import FormItem from "components/common/FormItem";
import FormGrid from "components/common/FormGrid";
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import Title from "components/common/Title";
import Checkbox from "components/elements/Checkbox";
import LayerPopup from "components/common/LayerPopup";
import ChunkManagementPopup from "../popups/ChunkManagementPopup";

const ChunkManagementDetail = () => {
  const navigate = useNavigate();
  const [openPopup, setOpenPopup] = useState(false);

  return (
    <>
    	{openPopup &&
				<LayerPopup
					title={'청크 상세'}
					customWidth={900}
					open={openPopup}
					onClose={() => setOpenPopup(false)}
					// customClass={'padding-custom'}
				>
          <ChunkManagementPopup/>
				</LayerPopup>
			}
      <Title title="청크 관리" icon="settings" />
      <SubContentsWrap>
        <div className="file-upload-wrap">
          <FormGrid gap={8}>
            <FormItem label="문서 명">
              <p>선택 약정 할인 제도</p>
            </FormItem>
          </FormGrid>
        </div>

        <SubTableTitleWrap>청크 목록</SubTableTitleWrap>
        <Table className="active" fixedHeader={true} height="572" hover={true} interval={true} round={false}>
          <table>
            <colgroup>
              <col width="160px" />
              <col width="220px" />
              <col width="368px" />
              <col width="200px" />
              <col width="200px" />
              <col width="200px" />
              <col width="120px" />
              <col width="120px" />
            </colgroup>
            <thead>
              <tr>
                <th>Chunk ID​</th>
                <th>등록 일시</th>
                <th>컨텍스트​</th>
                <th>메타데이터1​</th>
                <th>메타데이터2​</th>
                <th>메타데이터3​</th>
                <th>상태</th>
                <th>사용여부</th>
              </tr>
            </thead>
            <tbody>
              {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={8}><NoData txt={'데이터가 없습니다'}/></td></tr> 
               */}
              {Array.from({ length: 10 }).map((_, index) => (
                <tr key={index} onClick={(e) => {
                  const excludedTds = e.currentTarget.querySelectorAll("td.checkType");
                  // 클릭한 요소가 excludedTds에 포함된 경우 행 클릭 이벤트를 무시
                  const isExcluded = Array.from(excludedTds).some((td) => td.contains(e.target));
                  if (isExcluded) {
                    return;
                  }
                  setOpenPopup(true);
                }}>
                  <td>UIID​</td>
                  <td>2024-10-31 09:13:24​</td>
                  <td>\n \n1 \n \n가입가능 요금상품 \n가입 가능한 요금상...​</td>
                  <td>3G 요금상품...​</td>
                  <td>지원금 수혜 ...​</td>
                  <td>지원금 수혜 ...​</td>
                  <td>완료​</td>
                  <td className="checkType"><Checkbox type="switch"/></td>
                </tr>
              ))}
            </tbody>
          </table>
        </Table>
        <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
      </SubContentsWrap>
      <BackBtnWrap style={{width:'1576px'}}>
        <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
      </BackBtnWrap>
    </>
  );
};

export default ChunkManagementDetail;