import axios from 'axios';
import { useCallback, useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { clearService, setService } from '../redux/service';
import { login, logout } from '../redux/user';
import { AICC_PORTAL_API_URL } from './Constants';
import {
  getTokenFromLocalStorage,
  logoutFunction, setAuthToken,
  setAuthTokenFromResponseHeader,
} from './authUtil';

let refreshingFunc = undefined;

axios.interceptors.response.use(
    (response) => {
      if (response && response.config && response.config.headers) {
        setAuthTokenFromResponseHeader(response);
      }
      return response;
    },
    async (error) => {
      const originalConfig = error.config;
      const token = getTokenFromLocalStorage();

      if ((!token || !isUnauthorizedError(error))) {
        if(error.response?.status === 403) {
          // logoutFunction()
          // window.location.href = '/login';
        }
        return Promise.reject(error);
      }

      try {
        if (!refreshingFunc) {
          refreshingFunc = reIssueToken();
        }

        const newToken = await refreshingFunc;

        setAuthToken(newToken)

        originalConfig.headers.Authorization = `Bearer ${newToken}`

        try {
          return axios.request(originalConfig)
        } catch (error) {
          if (isUnauthorizedError(error)) {
            // logoutFunction()
            // window.location.href = '/login';
          }
        }
      } catch (err) {
        // logoutFunction()
        // window.location.href = '/login';
      } finally {
        refreshingFunc = undefined;
      }
    }
);

export async function reIssueToken() {
  const originalToken = getTokenFromLocalStorage();

  if (!originalToken) throw new Error('access token does not exist');

  const reIssuePayload = {
    "token" : originalToken
  }

  const response = await axios.patch(`${AICC_PORTAL_API_URL}/api/v1/auth`, reIssuePayload)

  return response.data.data;
}

function isUnauthorizedError(error) {
  const {
    response: { status },
  } = error;
  return status === 401;
}

axios.interceptors.request.use(
  (request) => {
    const token = getTokenFromLocalStorage();
			if (request.headers && token) request.headers.Authorization = `Bearer ${token}`;
    return request;
  },
  (error) => {
    return Promise.reject(error.response);
  }
);

export function useUserInfo() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  
  useEffect(() => {
    axios({
      url: AICC_PORTAL_API_URL + '/api/v1/user-info',
      method: 'GET',
    })
      .then((res) => {
          if (res.data.data) {
              dispatch(
                  login({
                      id: res.data.data.userId,
                      lastName: res.data.data.userLastName,
                      firstName: res.data.data.userFirstName,
                      email: res.data.data.email,
                      employeeId: res.data.data.employeeId,
                      role: res.data.data.role,
                      menuRoleId: res.data.data.menuRoleId,
                      fileDownloadYn: res.data.data.fileDownloadYn,
                      serviceId: res.data.data.serviceId,
                      serviceName: res.data.data.serviceName
                  })
              );
          }
      })
      .catch((e) => {
        console.log(e);
        // dispatch(clearService());
        // dispatch(logout());
        // navigate('/login');
      });
  }, []);
}

