import styled from "@emotion/styled/macro";
import { _color } from "./Variable";

const chartDefaultStyle = `
  display:flex;
  gap : 0 20px;
  .chart-title {
    display:flex;
    flex-direction: column;
    justify-content: top;
    min-width:100px;
    .title {
      color: ${_color.black2};
      font-size: 16px;
      font-weight: 600;
      line-height: 24px;
    }
    .num {
      display:block;
      margin-top:4px;
      color: ${_color.black2};
      font-size: 20px;
      font-weight: 600;
      line-height: 32px;
    }
  }
`;

export const legendDefaultStyle = `
  & > ul {
    & > li {width:100px;
      margin-top: 8px; display: flex; align-items: center;
      > span { display: inline-block; width: 12px; height: 12px; border-radius: 50%; }
      > p { 
        margin: 0 0 0 4px; padding: 0; color: #555F6D; font-size: 14px; font-weight: 400; line-height: 20px; min-width: 68px; max-width: 84px; word-break:break-all; 
        &:hover { color: #333 !important; font-weight: 700 !important; }
      }
      cursor: pointer;
    }
  }
`
export const RatioDoughnut = styled.div`
  width:181px;
  height:100%;
  white-space: pre-wrap;
  
  .chart-title {
    width:100px;
    margin-bottom:16px;
    text-align:center;
    .title {
      color: #555F6D;
      font-size: 15px;
      font-weight: 500;
      line-height: 22px;
    }
  }

  .inner{
    display: flex; 
    position:relative;
    width:100%;
    height:auto;
    align-items: center;
  }
  .rate {
    position:absolute;
    left: 22px;
    width: 56px;
    top: 50%;
    transform:translateY(-50%);
    color: ${_color.black2};
    font-size: 15px;
    font-weight: 600;
    line-height: 32px;
    text-align:center;
    z-index:3;
  }
  .legend { 
    ${legendDefaultStyle}
    margin-left: 18px; 
  }
`;

export const RatioDoughnutCanvas = styled.div`
  position: relative;
  width: ${({width}) => width ? `${width}` : '100px'};
  height: ${({height}) => height ? `${height}` : '100px'}; 
  /* &::before { content: ''; display: block; width: 100%; height: 100%; background: ${_color.chartBg}; border-radius: 50%; position: absolute; top: 0; left: 0; z-index: 1; }
  &::after { content: ''; display: block; width: 60%; height: 60%; background: #fff; border-radius: 50%; position: absolute; top: 20%; left: 20%; z-index: 2; } */
  canvas { position: relative; z-index: 3; }
`;

export const DecimalSingleBar = styled.div`
  ${chartDefaultStyle};
  justify-content:center;
  .inner {
    width:100%;
    height:100%;
    width: 116px; height: 178px;
  }
  // canvas { width: 116px !important; height: 178px !important; }
  
 
  .legend { 
    &.big_ver{
      li{
        margin-top: 4px !important;
        border:1px solid red;
      }
    }
    ${legendDefaultStyle}
    margin-top: auto;
    span {
      background-color:#9D9FE6;
    }
    li:last-of-type {
      span {
        background-color:#5C5FD6
      }
    }
    li {
      &.disabled {
        p { text-decoration: line-through; }
      }
    }
  }
`;

export const MultipleBar = styled.div`
  width:463px;
  border:1px solid red;
  ${chartDefaultStyle};
  height:248px;
  .inner {
    width:100%;
    height:100%;
  }
  canvas {
    width:100% !important;
    height:100% !important;
  }
`;

export const MultipleLineChart = styled.div`
  display:flex;
  gap:0 24px;
  align-items: end;
  width:${(props) => props.width ? props.width + 'px' : '100%'};
  height:${(props) => props.height ? props.height + 'px' : '100%'};
  /* height:100%; */
  .legend {
    min-width:175px;
    li {
      &:hover {
        cursor: pointer;
        color: #333;
        font-weight: 700;
      }
      &.disabled {
        text-decoration: line-through;
      }
    }
  }
  .inner {
    width:100%;
    height:100%;
  }
  canvas {
    width:100% !important;
    height:100% !important;
  }
`
export const Legend = styled.li`
  display:flex;
  align-items:center;
  gap:0 4px;
  color: #555F6D;
  font-size: 14px;
  font-weight: 400;
  line-height: 24px;
  &:before {
    content:'';
    display:block;
    width:12px;
    height:12px;
    border-radius:50%;
    background:${({color}) => color && color};
  }
`
export const HorizontalBarChart = styled.div`
  .chart-title {
    margin-bottom:18px;
  }
  .inner {
    display:flex;
    align-items: start;
    gap:0 4px;
    height:20px;
    justify-content: space-between;
    .chart {
      width:89%;
      height:60px;
      margin-left: -7px;
      canvas {
        /* width:100% !important; */
      }
    }
    .percentage {
      min-width:40px;
      text-align:right;
      color:${_color.black};
      font-size: 15px;
    }
  }
  .legend {
    li {
      &:hover {
        cursor: pointer;
        color: #333;
        font-weight: 700;
      }
      &.disabled {
        p { text-decoration: line-through; }
      }
    }
  }
`