import { useRef } from 'react';

import { Navigation } from 'swiper/modules';
import { Swiper } from 'swiper/react';
import 'swiper/css';

import * as S from '../../style/ElementsStyle';

const Swipers = ({ options, isNavigation = true, children }) => {
  const swiperRef = useRef();
  const prevRef = useRef(null);
  const nextRef = useRef(null);
  const defaultOptions = {
    modules: [Navigation],
    slidesPerView: 1,
    centeredSlides: false,
    spaceBetween: 0,
    initialSlide: 0,
    loop: false,
    autoplay: false,
    navigation: {
      nextEl: '.swiper-button-next',
      prevEl: '.swiper-button-prev',
      enabled: true,
    },
  };

  const mergeOpt = {
    ...defaultOptions,
    ...options,
  };
  return (
    <S.Swiper>
      <Swiper {...mergeOpt} ref={swiperRef}>
        {/* <SwiperSlide>1</SwiperSlide> */}
        {children}
      </Swiper>
      {isNavigation && (
        <>
          <button type="button" className="swiper-button-prev" ref={prevRef}>
            <span className="hidden">이전</span>
          </button>
          <button type="button" className="swiper-button-next" ref={nextRef}>
            <span className="hidden">다음</span>
          </button>
        </>
      )}
    </S.Swiper>
  );
};

export default Swipers;
