import styled from "@emotion/styled/macro";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";

import * as S from "./ElementsStyle";

export const LoginLayout = styled.div`
  display: flex;
  flex-direction: column;
  justify-content:center;
  position: relative;
  min-width: 1888px;
  min-height: 100vh;
  padding: 20px 0;
  background: url('/images/bg_login.png') no-repeat;
  background-size:cover; 
`;
export const LoginHeader = styled.div`
  padding-bottom:14px;
  ${({noLine}) => noLine ? 'border-bottom:0' : 'border-bottom:1px solid #E3E6E9' };
  .logo {
    display:flex;
    align-items:center;
    gap: 0 4px;
    ${({ join }) => join && 'justify-content:center'};
    height:42px;
    font-size: 25px;
    line-height:30px;
    font-weight: 600;
    box-sizing:border-box;
    & + .sub-title {
      margin-top:40px;
    }
    &:before {
      content:'';
      display:block;
      width:30px;
      height:30px;
      background:${_mx.svg(_svg.tLogo)} center center no-repeat;
      background-size:contain;
    }
  }
  .main-logo {
    width:350px;
    height:40px;
    margin:0 auto;
    background:url('/images/login_logo_img.svg') no-repeat center center;

  }
  h2 {
    padding-top:37px;
    font-size: 20px;
    font-weight: 600;
    color:${_color.black2};
  }
  .sub-title {
    display:flex;
    align-items:center;
    gap:0 12px;
    color:${_color.black2};
    font-size: 20px;
    font-weight: 600;
    strong {
      display:block;
      position:relative;
      padding-left:18px;
      font-size: 18px;
      &:before {
        content:'';
        display:block;
        position:absolute;
        left:0;
        top:2px;
        width:2px;
        height:18px;
        background:${_color.black2};
      }
    }
  }
  & + p {
    margin:16px 0 0;
    color: ${_color.black2};
    font-size: 14px;
    font-weight: 400;
  }
`
export const Login = styled.div`
  width:${({join}) => join ? '900' : '600'}px;
  margin: 0 auto;
  padding:${({join}) => join ? '46px 70px' : '165px 75px'};
  border-radius: 10px; 
  border: 1px solid #EAEAEA;
  background-color:${_color.white};
  box-shadow: 0px 10px 40px rgba(174.25, 174.25, 174.25, 0.30); 
  ${LoginHeader} {
    padding:0;
    border:0;
  }
  ${S.FormGrid} {
    margin-top:88px;
    ${S.TextField} {
      .text-area {
        height:60px;
        border-radius:10px;
        input {
          font-size: 15px;
          font-weight: 450;
          background:rgba(232.96, 236, 239.04, 0.58);
        }
      }
    }
    & + ${S.Button} {
      display:block;
      width: 450px;
      margin:40px auto 0;
    }
  }
  ${S.Checkbox} {
    margin-top:18px;
    .label {
      font-size: 15px;
    }
  }
  
  ${S.FormItem} {
    .form-label {
      min-width:84px;
      width:84px;
      color: ${_color.black2};
      font-size: 15px;
      font-weight: 400;
      background:none;
      text-align:left;
    }
    .form-cont {
      gap:0 15px;
    }
    ${S.Button} {
      width:150px;
      min-width:150px;
      height:60px;
      margin:0;
    }
  }
  ${S.Button} {
    width:100%;
    height:60px;
    margin-top:28px;
    border-radius: 10px;
    font-size: 15px;
  }
  .box-login-links {
    display:flex;
    align-items : center;
    justify-content:space-between;
    margin-top:24px;
    button {
      color: #555F6D;
      font-size: 15px;
      font-weight: 500;

      &:hover,
      &:focus {
        font-weight: 700;
      }
    }
  }

  .error-massage {
    margin: 12px 0 0 24px;
    color: #C53434;
    font-size: 14px;
    font-weight: 400;
    line-height: 24px;
  }
`

export const LoginDefaultStyle = styled.div`
  width:540px;
  margin: 0 auto;
  padding:40px 45px;
  border-radius: 10px; 
  border: 1px solid #EAEAEA;
  background-color:${_color.white};
  box-shadow: 0px 10px 40px rgba(174.25, 174.25, 174.25, 0.30); 
  
  ${S.FormGrid} {
    margin-top: 24px;
  }
  ${LoginHeader} {
    & + ${S.GrayBox} {
      margin-top:25px;
    }
    & + p + ${S.GrayBox} {
      margin-top:35px;
    }
  }
  ${S.GrayBox} {
    ${({ join }) => join && 'height:250px'};
    strong {
      padding-bottom:20px;
      color: ${_color.black2};
      font-size: 16px;
      font-weight:500;
      em {
        color:${_color.primary0}
      }
    }
    p {
      color: #7E8B99;
      font-size: 14px;
      font-weight: 400;
      line-height: 24px;
    }
    ul {
      margin-top:8px;
      text-align:left;
      color: #7E8B99;
      font-size: 14px;
      font-weight: 400;
      line-height: 24px;
      span {color:${_color.black2}}
    }
    & + ${S.ButtonList} {
      ${S.Button} {
        // width:100%;
      }
    }
  }
  ${S.Tab} {
    .tab-cont {
      margin-top:24px;
    }
  }

  .btn-area {
    margin-top:40px;
    ${S.Button} {
      width:120px;
    }
  }

  .txt-caution {
    white-space: nowrap;
  }

`
export const PopupLogin = styled.section`
  ${S.Button} {
    width:100%;
    margin-top:40px;
    font-size: 15px;
  }
  ${LoginHeader} {
    & + ${S.GrayBox} {
      margin-top:45px;
    }
  }
  ${S.GrayBox} {
    ${({ join }) => join && 'height:250px'};
    strong {
      padding-bottom:20px;
      color: ${_color.black2};
      font-size: 16px;
      font-weight:500;
      em {
        color:${_color.primary0}
      }
    }
    p {
      color: #7E8B99;
      font-size: 14px;
      font-weight: 400;
      line-height: 24px;
    }
    ul {
      margin-top:30px;
      text-align:left;
      color: #7E8B99;
      font-size: 14px;
      font-weight: 400;
      line-height: 24px;
      span {color:${_color.black2}}
    }
  }
`

export const PopupUserInfo = styled.div`
  .user-info{
    margin-bottom:12px;
    color:${_color.black2};
    font-size: 20px;
    font-weight: 500;
    line-height: 32px;
    p {
      color: #555F6D;
      font-size: 15px;
    }
  }
`

export const PopupFindInfo = styled.div`
  ${S.Tab} {
    .tab-menu {border-bottom:0;}
    .tab-cont {margin-top:40px;}
  }
`
export const PopupLogout = styled.div`
  ${S.GrayBox} {
    height:120px;
  }
`