import { useCallback, useEffect, useState } from 'react';
import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { getBotGroupsApi } from 'pages/fallbackUtterance/apis';
import { getDashboardFlowApi, getDashboardIntentApi } from '../apis';
import { customSort } from 'libs/utiles';
import {useServiceList} from "../../../libs/DataHook";
import {useSelector} from "react-redux";

const DEFAULT_PARAMS = {
  searchStartDate: dayjs().format('YYYY-MM-DD'),
  searchEndDate: dayjs().format('YYYY-MM-DD'),
};

const DEFAULT_INTENT_PARAMS = { pageNo: 0, pageSize: 10 };
const DEFAULT_FLOW_PARAMS = { pageNo: 0, pageSize: 10 };

const useRank = () => {
  const [searchParams, setSearchParams] = useState(DEFAULT_PARAMS); // 인텐트 조회 조건
  const [latestSearchParams, setLatestSearchParams] = useState(null); // 최신 조회 조건
  const [intentSearchParams, setIntentSearchParams] = useState(DEFAULT_INTENT_PARAMS); // 인텐트 조회 조건
  const [flowSearchParams, setFlowSearchParams] = useState(DEFAULT_FLOW_PARAMS); // 플로우 조회 조건
  const [intentRankRes, setIntentRankRes] = useState({}); // 인텐트 목록 데이터
  const [flowRankRes, setFlowRankRes] = useState({}); // 플로우 목록 데이터
  const serviceList = useServiceList();
  const { serviceId, serviceName } = useSelector((state) => state.service.value);
  const [botGroupList, setBotGroupList] = useState(null);

  // 조회 조건 변경
  const changeSearchParams = (key, value) => {
    setSearchParams(fp.set(key, value));
  };

  // 인텐트 조회 조건 변경
  const changeIntentSearchParams = (key, value) => {
    setIntentSearchParams(fp.set(key, value));
  };

  // 플로우 조회 조건 변경
  const changeFlowSearchParams = (key, value) => {
    setFlowSearchParams(fp.set(key, value));
  };

  // 인텐트 목록 조회
  const getIntentRank = useCallback(
    async (searchParams, intentSearchParams) => {
      try {
        searchParams.serviceId = serviceId
        searchParams.serviceName = serviceName
        const res = await getDashboardIntentApi({ ...searchParams, ...intentSearchParams });

        if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
          throw new Error(fp.getOr('', 'data.header.resultMessage', res));
        setIntentRankRes(fp.getOr({}, 'data.data.botIntentRankList', res));

        const botGroupName = fp.pipe(
          fp.find((obj) => obj.botGroupId == searchParams.botGroupId),
          fp.getOr('', 'botGroupName')
        )(botGroupList);

        setLatestSearchParams({ ...searchParams, botGroupName });
      } catch (error) {
        console.log('error', error?.message);
        alert('인텐트 목록 조회에 실패했습니다.');
        setIntentRankRes({});
      }
    },
    [searchParams]
  );

  // 플로우 목록 조회
  const getFlowRank = useCallback(
    async (searchParams, flowSearchParams) => {
      try {
        searchParams.serviceId = serviceId
        searchParams.serviceName = serviceName
        const res = await getDashboardFlowApi({ ...searchParams, ...flowSearchParams });

        if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
          throw new Error(fp.getOr('', 'data.header.resultMessage', res));
        setFlowRankRes(fp.getOr({}, 'data.data.botIFlowRankList', res));
      } catch (error) {
        console.log('error', error?.message);
        alert('플로우 목록 조회에 실패했습니다.');
        setFlowRankRes({});
      }
    },
    [searchParams]
  );

  const getBotGroups = async (serviceId, botGroupId, jobType) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, jobType, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));

      setBotGroupList(sortBotGroups);
      const firstBotGroupId = botGroupId || fp.getOr('', '[0].botGroupId', sortBotGroups);
      const botGroupName = fp.pipe(
        fp.getOr([], 'data.data.content'),
        fp.find((obj) => obj.botGroupId == firstBotGroupId),
        fp.getOr('', 'botGroupName')
      )(res);

      changeSearchParams('botGroupId', firstBotGroupId);
      changeSearchParams('botGroupName', botGroupName);
    } catch (error) {
      console.log('error', error?.message);
      alert('서비스 목록 조회에 실패했습니다. 서비스 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupList([]);
    }
  };

  useEffect(() => {
    if (!serviceId) return;
    getBotGroups(serviceId);
  }, [serviceId]);

  return {
    searchParams,
    latestSearchParams,
    intentSearchParams,
    flowSearchParams,
    intentRankRes, // 인텐트 데이터
    flowRankRes, // 플로우 데이터
    serviceList,
    serviceId,
    serviceName,
    botGroupList,
    getBotGroups,
    changeSearchParams, // 조회 조건 변경
    changeIntentSearchParams,
    changeFlowSearchParams,
    getIntentRank,
    getFlowRank,
  };
};

export default useRank;
