import { useEffect, useState } from 'react';
import classnames from 'classnames';

import { IconWithTab } from 'style/AutoQAStyle';

const IconTab = ({ tabList, defaultIndex = 0, tabClickCallback ,height}) => {
  const [tabIndex, setTabIndex] = useState(defaultIndex);

  const tabActiveHandler = (index) => {
    setTabIndex(index);
    tabClickCallback && tabClickCallback(index);
  };

  useEffect(() => {
    const number = Number(defaultIndex) ? Number(defaultIndex) : 0;
    setTabIndex(number);
  }, [defaultIndex]);

  return (
    <IconWithTab length={2} height={height}>
      <div className="icon-tab">
        {tabList.map((tab, index) => {
          return (
            <button
              type="button"
              key={`icon-tab-${index}`}
              className={classnames(
                'tab-anchor',
                { active: index === tabIndex },
                'tabButton',
                { 'no-border-right': index === tabList.length - 1 } // 마지막 탭에 대한 클래스 추가
              )}
              onClick={() => tabActiveHandler(index)}
            >
              <div className={`icon ${tab.icon} ${index === tabIndex ? 'active' : ''}`}/>
              {tab.title}
            </button>
          );
        })}
      </div>
      <div className="icon-tab-cont">{tabList[tabIndex]?.tabContent}</div>
    </IconWithTab>
  );
};

export default IconTab;
