import { useState } from "react";
import Title from "components/common/Title";
import GrayBox from "components/common/GrayBox";
import FormGrid from "components/common/FormGrid";
import FormItem from "components/common/FormItem";
import { DetailContentsWrap, DetailTitles, DetailPageContainer, SubTableTitle, CountingTitle } from "style/AutoQAStyle";
import Table from "components/common/Table";
import ButtonList from "components/common/ButtonList";
import Checkbox from "components/elements/Checkbox";
import LayerPopup from "components/common/LayerPopup";
import ExcellentCallManagementPopup from "./popups/ExcellentCallManagementPopup";
import NoData from "components/common/NoData";
import Pagination from "components/common/Pagination";

const ExcellentCallManagementPage = () => {
	const [openPopup, setOpenPopup] = useState(false);

	return (
		<>
			{openPopup &&
				<LayerPopup
					size=""
					title={'　'}
					customWidth={1500}
					open={openPopup}
					onClose={() => setOpenPopup(false)}
					customClass={'padding-custom'}
				>
					<ExcellentCallManagementPopup />
				</LayerPopup>
			}
			<Title title="우수 콜 목록" icon="settings" />
			<DetailPageContainer>
				<DetailContentsWrap style={{ padding: '32px 50px', marginBottom: '60px' }}>
					<GrayBox direction={'column'}>
						<FormGrid gap={12}>
							<FormItem label={'통화 길이'}>
								<div style={{ display: 'flex', alignItems: 'center' }}>
									<p style={{ marginLeft: '16px' }}>10분 이상 콜</p>
								</div>
							</FormItem>
							<FormItem label={'AI 평가 점수'}>
								<div style={{ display: 'flex', alignItems: 'center' }}>
									<p style={{ marginLeft: '16px' }}>90점 이상</p>
								</div>
							</FormItem>
							<FormItem label={'QAA 평가 점수'}>
								<div style={{ display: 'flex', alignItems: 'center' }}>
									<p style={{ marginLeft: '16px' }}>90점 이상</p>
								</div>
							</FormItem>
						</FormGrid>
					</GrayBox>

					<div style={{paddingTop:'40px'}}>
						<Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
							<table>
								<colgroup>
									<col width="231px" />
									<col width="205px" />
									<col width="205px" />
									<col width="205px" />
									<col width="205px" />
									<col width="149px" />
									<col width="113px" />
									<col width="167px" />
								</colgroup>
								<thead>
									<tr>
										<th className="t-left left-padding">상담사명</th>
										<th className="t-left left-padding">상담유형 대</th>
										<th className="t-left left-padding">상담유형 증</th>
										<th className="t-left left-padding">상담유형 소</th>
										<th>상담 일시</th>
										<th>평가 방식</th>
										<th>평가자</th>
										<th>노출 여부</th>
									</tr>
								</thead>
								<tbody>
									{/***********************
											데이터 없는 경우
										***********************
										<tr>
											<td colSpan={9}><NoData txt={'데이터가 없습니다'}/></td>
										</tr> 
					 				*/}
									{Array.from({ length: 10 }).map((_, index) => (
										<tr key={index}  onClick={(e) => {
											const excludedTds = e.currentTarget.querySelectorAll("td.checkType");
											// 클릭한 요소가 excludedTds에 포함된 경우 행 클릭 이벤트를 무시
											const isExcluded = Array.from(excludedTds).some((td) => td.contains(e.target));
											if (isExcluded) {
												return;
											}
											setOpenPopup(true);
										}}
>
											<td className="t-left left-padding">김상담(202020)</td>
											<td className="t-left left-padding">상담유형 1</td>
											<td className="t-left left-padding">상담유형 2​</td>
											<td className="t-left left-padding">상담유형 3</td>
											<td>2024-11-28 12:00​</td>
											<td>자동 / 수동​</td>
											<td>-</td>
											<td className="checkType">
												<Checkbox type="switch"/>
											</td>
										</tr>
									))}
								</tbody>
							</table>
						</Table>
					</div>
					<Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
				</DetailContentsWrap>
			</DetailPageContainer>

		</>
	)
}

export default ExcellentCallManagementPage;