import Parser from 'html-react-parser';
import * as S from '../../style/ElementsStyle';
/**
 * type : h2 (default :font size 20px) | sub (font-size 18px)
 */
const Title = ({
  type = 'h2',
  title,
  subTitle,
  subNoLine = false,
  underLine = false,
  tooltip,
  leftArea,
  children,
  icon,
}) => {
  return (
    <S.Title underLine={underLine} subNoLine={subNoLine}>
      {icon && <i className={`icon-${icon}`}></i>}
      <div className="title-area">
        {title !== undefined ? (
          type === 'h2' ? (
            <h2 className="title">{title}</h2>
          ) : (
            <strong className="title">{title}</strong>
          )
        ) : null}

        {subTitle && <span className="sub-title">{Parser(subTitle)}</span>}
        {tooltip && tooltip}
        {leftArea && leftArea}
      </div>

      {children && <div className="right-area">{children}</div>}
    </S.Title>
  );
};

export default Title;
