import React, { useRef } from "react";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  LineElement,
  PointElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
} from "chart.js";
import { GraphLabelWrap, GraphLayout, GraphTitleItem, GraphWrapBox } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

// Chart.js 등록
ChartJS.register(LineElement, PointElement, CategoryScale, LinearScale, Tooltip, Legend);

const CustomLinesChart = ({ width, height, labels, datasets, title, legendPadding }) => {

  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const data = {
    labels,
    datasets: datasets.map(({ label, data, borderColor, backgroundColor, borderDash }) => ({
      label,
      data,
      borderColor,
      backgroundColor,
      borderDash: borderDash || [],
      borderWidth: 3,
      pointRadius: 0,
      fill: false,
      tension: 0,
      borderJoinStyle: "round",
      borderCapStyle: "round",
      pointHitRadius: 4,
      hoverRadius: 4,
    })),
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false }, // 범례 숨김
      datalabels: { display: false }, // 그래프 위 수치 표시 비활성화
      tooltips: {
        enabled: true,
          mode: 'nearest',  // 가장 가까운 데이터 포인트 툴팁 표시
          intersect: true  // 데이터 근처에서도 툴팁 표시 가능
      },
      hover: {
          mode: 'index',  // 같은 인덱스의 모든 데이터셋 툴팁 표시
          intersect: true  // 데이터 포인트 위에서만 반응
      }
    },
    scales: {
      x: {
        ticks: {
          color: "#B3B3C5",
          align: "center",
          font: { size: 11, weight: "500" },
        },
        grid: { display: false },
      },
      y: {
        min: 80,
        max: 100,
        grid: { display: true, color: "rgba(200, 200, 200, 0.3)" },
        border: { display: false },
        ticks: {
          stepSize: 10,
          padding: 5,
          color: "#B3B3C5",
          align: "end",
          font: { size: 12, weight: "500" },
        },
      },
    },
  };

  return (
    <GraphLayout>
      <div className="left-wrap">
        <GraphTitleItem>{title}</GraphTitleItem>
        <CustomLegend datasets={datasets} paddingL={legendPadding} />
      </div>
      <GraphWrapBox width={width} height={height}>
        <Line data={data} options={options} />
      </GraphWrapBox>
    </GraphLayout>
  );
};

export default CustomLinesChart;

const CustomLegend = ({ datasets,paddingL }) => (
  <GraphLabelWrap paddingL={paddingL}>
    {datasets.map(({ label, borderColor }, index) => (
      <p key={index}>
        <span style={{ backgroundColor: borderColor }} />
        {label}
      </p>
    ))}
  </GraphLabelWrap>
);
