import React, { useRef } from "react";
import {
  Chart as ChartJS,
  RadialLinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend,
} from 'chart.js';
import { Radar } from "react-chartjs-2";
import { GraphLabelWrap, GraphLayout, GraphTitleItem, GraphWrapBox } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(
  RadialLinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend
);


const RadarChart = ({ width, height, labels, legends, colors, datas, title,marginGap }) => {

  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const data = {
    labels,
    datasets: [
      {
        label: legends[1],
        data: datas[1], // 이상징후 데이터
        backgroundColor: "transparent", // 빨간색 투명 배경
        borderColor: colors[1], // 빨간색 테두리
        pointRadius: 0,
        borderWidth: 3,
        borderJoinStyle: "round", // 라인 끝을 둥글게
        borderCapStyle: "round", // 각 데이터 연결선을 둥글게

      },
      {
        label: legends[0],
        data: datas[0], // 콜 건수 데이터
        backgroundColor: 'transparent', // 파란색 투명 배경
        borderColor: colors[0], // 파란색 테두리
        pointRadius: 0,
        borderWidth: 3,
        borderJoinStyle: "round", // 라인 끝을 둥글게
        borderCapStyle: "round", // 각 데이터 연결선을 둥글게
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      datalabels: { display: false },
      tooltip: {
        enabled: true,
        mode: 'nearest',  // 가장 가까운 데이터 포인트 툴팁 표시
        intersect: false,  // 데이터 근처에서도 툴팁 표시 가능

       },
       hover: {
        mode: 'index',  // 같은 인덱스의 모든 데이터셋 툴팁 표시
        intersect: true  // 데이터 포인트 위에서만 반응
    }
    },
    scales: {
      r: {
        ticks: {
          beginAtZero: true,
          maxTicksLimit: 8,
          stepSize: 1, // 눈금 간격을 1로 설정 (총 10줄이 생기도록 조정)
          max: 10, // 최대 값 설정 (10까지 표시)
          // count: 10, // 눈금 개수를 10개로 강제
          display: false, // 눈금 숫자 숨기기
        },
        angleLines: {// 각도 라인 숨기기
          display: false,
        },
        grid: {
          color: "#DEDFF7", // 5각형 배경색 지정
          circular: false, // 선을 직선으로 설정
        },
        pointLabels: {
          font: {
            size: 11, // 라벨 사이즈 수정
            color: '#7E8B99'
          },
        },
      },
    },
  };

  return (
    <GraphLayout marginGap={marginGap}>
      <div className="left-wrap">
        <GraphTitleItem>{title}</GraphTitleItem>
        <CustomLegend legends={legends} colors={colors} />
      </div>
      <GraphWrapBox width={width} height={height}>
        <Radar ref={chartRef} data={data} options={options} />
      </GraphWrapBox>
    </GraphLayout>

  );
}

export default RadarChart;

const CustomLegend = ({ legends, colors }) => (
  <GraphLabelWrap>
    {legends.map((item, index) => (
      <p key={index}>
        <span style={{ backgroundColor: colors[index] }} />
        {item}
      </p>
    ))}
  </GraphLabelWrap>
);
