import ReactDOM from 'react-dom';
import classnames from 'classnames';
import { PopupBottomBtnWrap } from 'style/AutoQAStyle';
import Button from 'components/elements/Button';

import * as S from '../../style/ElementsStyle';

const Dimmed = ({ onClose }) => {
  return <S.Dimmed onClick={onClose} />;
};

/**
 * size : mid (default : 800px) | small (500px)
 */
const Modal = ({
  size = 'mid',
  open,
  onClose,
  title,
  titleHeight = false,
  subTitle,
  customWidth,
  customClass,
  children,
  btnText = '저장',
  btnEvent,
  contentsHeight,
  padding=true,
}) => {
  return (
    <S.LayerPopupWrap open={open}>
      <Dimmed onClose={onClose} />
      <S.LayerPopup customWidth={customWidth} titleHeight={titleHeight}>
        {/* 231107 titleHeight 추가 */}
        <div className="layer-wrap">

          <div className={`layer-popup ${size}`}>

            {title && (
              <div className="layer-header">
                <h2>{title}</h2>
                {subTitle && <span className="sub-title">{subTitle}</span>}
                <button onClick={onClose} />
              </div>
            )}

            <div className="layer-container" style={{ height: contentsHeight + 'px'}}>
              <div className={classnames('layer-inner', customClass)} style={{padding:padding ? '26px 52px 28px' : '0'}}>
                {children}
              </div>
            </div>

            <PopupBottomBtnWrap>
              <Button label={btnText} className={'primary wide'} onClick={btnEvent} />
            </PopupBottomBtnWrap>
          </div>
        </div>
      </S.LayerPopup>
    </S.LayerPopupWrap>
  );
};
const CustomLayerPopup = (props) => {
  return <>{ReactDOM.createPortal(<Modal {...props} />, document.getElementById('layer-root'))}</>;
};

export default CustomLayerPopup;
