import Title from "components/common/Title";
import Filter from "components/common/Filter";
import TextField from "components/elements/TextField";
import Button from 'components/elements/Button';
import { SubTableTitle, CountingTitle } from "style/AutoQAStyle";
import Table from "components/common/Table";
import ButtonList from "components/common/ButtonList";
import Checkbox from "components/elements/Checkbox";
import Pagination from 'components/common/Pagination';
import SearchBox from 'components/common/SearchBox';
import { useState } from "react";
import LayerPopup from "components/common/LayerPopup";
import SearchBoxPopupForGroup from "./popups/SearchBoxPopupForGroup";
import NoData from "components/common/NoData";

const GroupManagementPage = () => {
  const [openPopup, setPopupOpen] = useState(false); // 조직명 검색 팝업
  const [disabledIs, setDisbaledIs] = useState(false); // 검색 버튼 비활성화

  return (
    <>
      {openPopup && // 상담사 검색 팝업
        <LayerPopup
          title={'조직 상세'}
          customWidth={800}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <SearchBoxPopupForGroup onClose={() => setPopupOpen(false)} disabled={disabledIs} />
        </LayerPopup>
      }
      <Title title="조직 등록/목록" icon="settings" />
      <Filter>
        <div style={{ justifyContent: 'space-between', display: 'flex', width: '1584px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <TextField
              placeholder="조직명를 입력해주세요"
              label="조직명 등록"
              multi
              width={357}
              onChange={(e) => { }}
              maxLength={20}
              count={20}
            />
            <Button label="저장" className="primary wide" onClick={() => { }} />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <TextField
              placeholder="조직명 검색"
              label="조직명 검색"
              multi
              width={260}
              onChange={(e) => { }}
            />
            <Button label="검색" className="primary wide" onClick={() => { }} />
          </div>
        </div>
      </Filter>

      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          {
            label: '선택 삭제', className: 'secondary del2', onClick: () => {}
          },
        ]} />
      </SubTableTitle>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="64px" />
            <col width="597px" />
            <col width="320px" />
            <col width="320px" />
            <col width="285px" />
          </colgroup>
          <thead>
            <tr>
              <th><Checkbox /></th>
              <th className="t-left left-padding">조직명</th>
              <th>등록 일시</th>
              <th>수정 일시</th>
              <th>구성원 수</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={5}><NoData txt={'데이터가 없습니다'}/></td></tr> 
              */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index} onClick={(e) => {
                // 클릭한 요소가 체크박스가 포함된 td일 경우 행 클릭 이벤트 무시
                const excludedTd = e.currentTarget.querySelector('td.checkType');
                if (excludedTd && excludedTd.contains(e.target)) {
                  return;
                }
                setPopupOpen(true)
                setDisbaledIs(true)
              }}>
                <td className="checkType"><Checkbox /></td>
                <td className="t-left left-padding">고객상담1실</td>
                <td>2024-11-28 13:44</td>
                <td>2024-12-06 15:43</td>
                <td>20</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}

export default GroupManagementPage;