import styled from '@emotion/styled/macro';
import * as S from './ElementsStyle';
import * as C from './ChartStyle';

export const GridItem = styled.div`
  display: flex;
  flex-direction: column;
  gap: 8px;

  & + & {
    margin-top: 40px;
  }
  & + ${S.Table}, & + .in-table-bg {
    margin-top: 40px;
  }
`;

export const GridHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 70px;
  padding: 0 32px;
  background-color: #fff;
  box-shadow: 0px 2px 8px -1px rgba(27, 36, 44, 0.08);
  .title {
    font-size: 20px;
    font-weight: 600;
  }

  .title-side {
    display: flex;
    align-items: center;
    gap: 0 16px;

    .sub-info {
      display: flex;
      gap: 24px;
      > div {
        display: flex;
        align-items: center;
        font-size: 14px;
        font-weight: 500;
        gap: 8px;
      }

      dt {
        color: #7e8b99;
      }
      dd {
        color: #555f6d;
      }
    }
  }
`;

export const GridContent = styled.div``;

export const Box = styled.div`
  flex-grow: 1;
  padding: 35px 32px;
  background: white;
  box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
`;

export const BoxWrap = styled.div`
  display: flex;
  gap: 6px;

  &.boxes1 {
    ${Box} {
      &:nth-of-type(1) {
        width: 100%;
      }
    }
  }
  &.boxes2 {
    ${Box} {
      &:nth-of-type(1) {
        width: 24%;
      }
      &:nth-of-type(2) {
        width: 76%;
      }
    }
  }

  &.boxes3 {
    ${Box} {
      &:nth-of-type(1) {
        width: 44%;
      }
      &:nth-of-type(2) {
        width: 23%;
      }
      &:nth-of-type(3) {
        width: 33%;
      }
    }
  }
  &.boxes4 {
    ${Box} {
      &:nth-of-type(1) {
        width: 40%;
      }
      &:nth-of-type(2) {
        width: 18%;
      }
      &:nth-of-type(3) {
        width: 24%;
      }
      &:nth-of-type(4) {
        width: 18%;
      }
    }
  }
  &.boxes5 {
    ${Box} {
      &:nth-of-type(1) {
        width: 574px;
      }
      &:nth-of-type(2) {
        width: 656px;
      }
      &:nth-of-type(3) {
        width: 335px;
      }
    }
  }
`;

export const ItemGraph = styled.div`
  display: flex;
  /* gap: 17px; */
  gap:${(props) => props.gapIs ? '17px' : props.gapIs};
  flex-direction:${({ direction }) => direction === 'column' ? 'column' : 'none'};
  .item-title {
    width: auto;
    flex-shrink: 0;
    font-size: 15px;
    font-weight: 600;
    line-height: 24px;
    /* margin-bottom: 20px; */
    white-space: pre-wrap;

    .number {
      font-size: 20px;
      font-weight: 600;
      line-height: 32px;
    }
  }

  .item-cont {
    display: flex;
    flex: 1;
    .list {
      display: flex;
      gap: 24px;
      height:auto;
      ${({ row }) => row && `flex-wrap:wrap; gap:20px 0;`}
      > li {
        flex: 1;
        ${({ row }) => row && `flex: initial;width:100%;`}
        ${C.RatioDoughnut} {
          .legend li span {
            flex-shrink: 0;
          }
        }
      }
    }

    .graph-cont {
      margin-top: 10px;
      width: 100%;
      
    }
  }

  ${C.RatioDoughnut} {
    .legend {
      flex-shrink: 0;
    }
  }
`;

export const ItemInfoList = styled.div`
  display: flex;
  align-items: center;
  height: 100%;
  dl {
    display: flex;
    width: 100%;
    flex-direction: column;
    gap: 17px;
  }
`;

export const ItemInfo = styled.div`
  display: flex;
  justify-content: space-between;
  dt {
    color: #555f6d;
    font-size: 15px;
    font-weight: 500;
  }
  dd {
    color: #272e35;
    font-size: 18px;
    font-weight: 600;
  }

  ${({ strong }) =>
    strong &&
    `
		dt {
			font-size: 16px;
			font-weight: 600;
			color: #272E35;
		}
	`}
`;

export const AreaSplit = styled.div`
  display: flex;
  gap: 12%;
  height: 100%;
  justify-content: space-between;
  ${ItemInfoList} {
    width: 50%;
  }
  ${({ ratioGraphType }) =>
    ratioGraphType &&
    `
			gap: 30px;
			${C.RatioDoughnut}:nth-of-type(1) { width: 35% }
			${ItemInfoList}:nth-of-type(2) { width: 65% }

			${C.RatioDoughnut} {
				.inner {
					flex-direction: column;
					.legend {
						margin-top: 4px;
						margin-left: 0;
					}
				}
			}
	`}
`;
export const ServiceStatistics = styled.div`
  .service-status {
    .title {
      i {
        display: inline-block;
        width: auto;
      }
    }
    ${AreaSplit} {
      margin-top: 17px;
    }
  }
`;

export const BotGroupBotStatistics = styled.div``;

export const BotGroupPeriodStatistics = styled.div`
  ${S.Filter} {
    margin: 25px 0 32px;
  }
`;

export const statisticsTable = `
	.in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 60px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}
	}
`;

export const StatisticsInquiryDaily = styled.div`
  ${statisticsTable}
  .chart-wrap {
    height: 178px;
  }
`;
export const StatisticsInquiryWeekly = styled.div`
  ${statisticsTable}
  .chart-wrap {
    height: 178px;
  }
`;
export const StatisticsInquiryMonthly = styled.div`
  ${statisticsTable}
  .chart-wrap {
    height: 178px;
  }
`;
