import { useState } from "react";
import FormItem from "components/common/FormItem";
import GrayBox from "components/common/GrayBox";
import FormGrid from "components/common/FormGrid";
import Select from 'components/elements/Select';
import { LayerInButtonWrap, PopupInSmallTitle } from "style/AutoQAStyle";
import Button from "components/elements/Button";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import Alert from "components/common/Alert";
import NoData from "components/common/NoData";

const UserDetailPopup = () => {
  const [openPopup, setOpenPopup] = useState(false);

  return (
    <>
      {openPopup && // 선택삭제 팝업
        <Alert onClose={() => setOpenPopup(false)} text={'선택하신 계정을 비활성화 처리하시겠습니까?'} />
      }
      <div style={{ marginBottom: '40px' }}>
        <PopupInSmallTitle>
          사용자 기본정보
          <Button label="계정 비활성화" className="secondary" onClick={() => { setOpenPopup(true) }} />

        </PopupInSmallTitle>
        <GrayBox>
          <FormGrid>
            <FormItem label={'아이디'} >
              <p>2004552</p>
            </FormItem>
            <FormItem label={'사용자명'} >
              <p>김상담</p>
            </FormItem>
            <FormItem label={'사번'} >
              <p>00123</p>
            </FormItem>
            <FormItem label={'이메일'} >
              <p>test@test.com</p>
            </FormItem>
            <FormItem label={'가입 일시'} >
              <p>YYYY.MM.DD hh:mm:ss</p>
            </FormItem>
            <FormItem label={'계정 상태'} >
              <p>활성</p>
            </FormItem>
            <FormItem label={'최종 수정 일시'} >
              <p>YYYY.MM.DD hh:mm:ss</p>
            </FormItem>
            <FormItem label={'변경인'} >
              <p>admin5</p>
            </FormItem>
          </FormGrid>
        </GrayBox>
      </div>
      <PopupInSmallTitle>사용자 설정</PopupInSmallTitle>
      <Table >
        <table>
          <colgroup>
            <col width="232px" />
            <col width="232px" />
            <col width="232px" />
          </colgroup>
          <thead>
            <tr>
              <th>시스템 권한</th>
              <th>메뉴 접근 권한</th>
              <th>조직</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr className='thin'>
                  <td colSpan="3">
                    <NoData txt={`조회된 데이터가 없습니다.`} />
                  </td>
                </tr> */}
            <tr height="64px" >
              <td>
                <Select
                  option={[]}
                  label="역할을 선택하세요"
                  value={''}
                  type="simple"
                  width={200}
                />
              </td>
              <td>
                <Select
                  option={[]}
                  label="역할을 선택하세요"
                  value={''}
                  type="simple"
                  width={200}
                />
              </td>
              <td>
                <Select
                  option={[]}
                  label="조직을 선택하세요"
                  value={''}
                  type="simple"
                  width={200}
                />
              </td>
            </tr>
          </tbody>
        </table>
      </Table>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '저장', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  );
};

export default UserDetailPopup;