import { useNavigate } from "react-router-dom";
import { useState } from "react";
import Title from "components/common/Title";
import Button from "components/elements/Button";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Textarea from "components/elements/Textarea";
import { DetailPageContainer, DetailContentsWrap, DetailTitles, BackBtnWrap } from 'style/AutoQAStyle';
import Select from "components/elements/Select";
import Alert from "components/common/Alert";

const AIAgentDetail = () => {
  const navigate = useNavigate();
  const [detailIs, setDetailIs] = useState(false); // 생성페이지 또는 복사(상세)페이지 여부
  const [openPopup, setOpenPopup] = useState(false); // 팝업 샘플

  return (
    <>
      {openPopup && // 선택삭제 팝업
        <Alert onClose={() => setOpenPopup(false)} text={'<div class="icon"></div>이미 해당 AI Agent의 동일한 AI 버전이 있습니다.'} /> 
      }
      <Title title={`AI Agent ${detailIs ? '상세' : '생성'}`} icon="evaluation" />
      <DetailPageContainer>
        <DetailContentsWrap padding={true}>
          <DetailTitles>AI Agent 정보</DetailTitles>
          <GrayBox direction={'column'} height={390}>
            <FormItem label={'AI 모델명'} marginB={8}>
              <Select
                option={[]}
                value={null}
                title={'선택'}
                width={561}
                type="simple"
                onChange={() => {}}
                disabled={detailIs}
              />
            </FormItem>
            <FormItem label={'AI Agent'} marginB={8}>
              <TextField disabled={detailIs} width={561} placeholder={'AI Agent명을 입력하세요.'} count={20} maxLength={20} defaultValue={detailIs ? 'test' : ''} />
            </FormItem>
            <FormItem label={'AI 버전'} marginB={8}>
              <TextField disabled={detailIs} width={561} placeholder={'버전 정보를 입력하세요.'} count={20} maxLength={20} defaultValue={detailIs ? 'test' : ''} />
            </FormItem>
            <FormItem label={'프롬프트'}>
              <Textarea disabled={detailIs} width={900} height={192} placeholder={'프롬프트 입력 (영자/숫자 포함 최대 200자 까지 등록 가능합니다.)​'} count={10} maxLength={200} defaultValue={detailIs ? 'test' : ''} />
            </FormItem>
          </GrayBox>
          <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
            <Button label={detailIs ? '복사' : "저장"} className={'primary wide'} onClick={() => {setOpenPopup(true)}} />
          </div>
        </DetailContentsWrap>
        <BackBtnWrap>
          <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
        </BackBtnWrap>
      </DetailPageContainer>

    </>
  )
};

export default AIAgentDetail;