import { useState } from "react";
import React from "react";
import GrayBox from "components/common/GrayBox";
import Select from "components/elements/Select";
import TextField from "components/elements/TextField";
import Button from "components/elements/Button";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import { TransferListContainer, ModalInSubTitle, TransferTableContainer ,FormLabel} from "style/AutoQAStyle";
import Checkbox from "components/elements/Checkbox";
import NoData from "components/common/NoData";
import Alert from "components/common/Alert";
import Pagination from 'components/common/Pagination';

const data = [
  { id: 1, name: "이상담(202021)", department: "상담센터 부서1" },
  { id: 2, name: "김상담(202021)", department: "상담센터 부서1" },
  { id: 3, name: "박상담(202021)", department: "상담센터 부서1" },
  { id: 4, name: "안상담(202021)", department: "상담센터 부서1" },
  { id: 5, name: "이상담(202021)", department: "상담센터 부서1" },
];

const TransferListPopup = ({ type }) => {
  const tableHeader = ['checkbox', 'No.', '상담사명 (사번)', '소속'];
  const tableHeader2 = ['checkbox', 'No.', '상담사명 (사번)', '소속', '평가 비중'];
  const [showIs, setShowIs] = useState(false);

  return (
    <>
      {showIs && type === 'b' &&
        <Alert
          text={`<p>평가 비중의 총 합은 <span class='red'>100</span>이 되어야 합니다.</br>다시 입력해 주세요.</p>`}
          onClose={() => setShowIs(false)}
        />
      }

      <GrayBox vertical={true}>
        <div style={{ display: 'flex', flexDirection: 'column', marginRight: '12px' }}>
          <FormLabel>조직</FormLabel>
          <Select
            option={[]}
            type={'simple'}
            title={'조직 선택'}
            width={399}
            onChange={() => { console.log('select!') }}
          />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', marginRight: '12px' }}>
          <FormLabel>{type === 'a' ? `상담사명` : `평가자명`}</FormLabel>
          <TextField disabled={false} width={399} placeholder={`${type === 'a' ? '상담사명' : '평가자명'}을 입력하세요.`} />
        </div>
        <ButtonList marginT={30} buttonList={[
          { label: '초기화', className: 'secondary', onClick: () => { } },
          { label: '검색', className: 'primary', onClick: () => { } },
        ]} />
      </GrayBox>
      <TransferListContainer>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <TransferTable
            title="지정대상"
            headerList={tableHeader}
            bodyList={[]}
            subText="검색결과"
            lastStr="개"
          />
          <Pagination pagingTotal={27} displayed={5} />
        </div>
        <div className="changed-btn-wrap">
          <Button
            label="오른쪽으로 이동"
            className="arrow-right-button secondary"
            btnType="icon"
          />
          <Button
            label="왼쪽으로 이동"
            className="arrow-left-button secondary"
            btnType="icon"
          />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column' }}>

          <TransferTable
            title="지정결과"
            headerList={type === 'b' ? tableHeader2 : tableHeader}
            bodyList={data}
            subText="총"
            lastStr="명"
            type={type}
          />
          <Pagination pagingTotal={27} displayed={5} />
        </div>
      </TransferListContainer>
      <div style={{ marginTop: '26px', display: 'flex', justifyContent: 'end' }}>
        <Button label="저장" className={'primary wide'} onClick={() => { setShowIs(true) }} />
      </div>
    </>
  );
};

export default TransferListPopup;


const TransferTable = ({ title, headerList, bodyList, subText, lastStr, type }) => {
  const count = 0;
  return (
    <TransferTableContainer>
      <ModalInSubTitle>
        <h5>{title}</h5>
        <ul>
          <li className="subTitle">{subText}</li>
          <li className="point">{count}</li>
          <li>{lastStr}</li>
        </ul>
      </ModalInSubTitle>
      <Table height={313} fixedHeader scroll>
        <table className="small-line">
          <colgroup>
            <col width="50px" />
            <col width="40px" />
            <col width="90px" />
            {type === 'b' ? <col width="100px" /> : <col width="200px" />}
            {type === 'b' && <col width="100px" />}
          </colgroup>
          <thead>
            <tr>
              {headerList.map((item, index) => (
                <th
                  key={index}
                  className={`${index === headerList.length - 1 && type !== 'b' ? 't-left left-padding' : ''}`}
                >
                  {item === "checkbox" ? <Checkbox /> : item}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {bodyList.length === 0 ? (
              <tr >
                <td colSpan={type === 'b' ? 5 : 4}>
                  <NoData txt={"선택된 상담원이 없습니다"} height={260} />
                </td>
              </tr>
            ) : (
              bodyList.map((item, index) => {
                const isLastIndex = index === bodyList.length - 1;
                return (
                  <React.Fragment key={index}>
                    <tr key={index}>
                      <td><Checkbox /></td>
                      <td>{item.id}</td>
                      <td>{item.name}</td>
                      <td className="t-left left-padding">{item.department}</td>
                      {type === 'b' &&
                        <td className="center">
                          <TextField width={55} size={'small'} center={'center'} />　%
                        </td>
                      }
                    </tr>
                    {isLastIndex && type === 'b' && (
                      <tr>
                        <td colSpan={5} style={{ textAlign: "center" }}>
                          <p className="notice-text">평가 비중의 총합은 반드시 100이 되어야 합니다.</p>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })
            )}
          </tbody>
        </table>
      </Table>
    </TransferTableContainer>
  );
}