import React, { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Button from 'components/elements/Button';
import dayjs from 'dayjs';
import Filter from 'components/common/Filter';
import StackBarChart from 'components/chart/StackBarChart';
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import SortingButton from 'components/elements/SortingButton';
import NoData from 'components/common/NoData';
import { StatisticsDashboardContainer, StatisticsDashboardTitle, GraphWraps, GraphBox } from 'style/AutoQAStyle';
import DateRange from 'components/common/DateRange';
import Select from 'components/elements/Select';
import CustomLinesChart from 'components/chart/CustomLineChart';

const AImodelTypeTab = () => {
  const [date, setDate] = useState('2023-01-20 ~ 2023-01-22'); //기간
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜

  return (
    <>
      <StatisticsDashboardContainer>
        <Filter>
          <Select title={'선택'} label={'AI 모델 선택'} option={[]} />
          <DateRange
            rangeCal
            utilMenu
            label="상담 일시"
            monthsShown={2}
            selectsRange
            format="YYYY-MM-DD"
            startDate={dayjs(startDate).toDate()}
            endDate={dayjs(endDate).toDate()}
            selected={dayjs(startDate).toDate()}
            disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
            disableNum={3}
            maxDate={dayjs().toDate()}
            onChange={(value) => {
              setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
              setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
            }}
          />
          <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
        </Filter>
        <StatisticsDashboardTitle>
          <div>
            <h5 className="title">AI모델 평가</h5>
            <span className="date">{date}</span>
          </div>
          <Button label="다운로드" className="secondary download down-small" onClick={() => { alert('조회중') }} />
        </StatisticsDashboardTitle>

        {/* 대시보드 */}
        <GraphWraps>
          <GraphBox width={1576} height={248} padding={'48px 50px'}>
            <CustomLinesChart
              width="1134"
              height="163"
              title={'평가 평균 점수'}
              legendPadding={120}
              labels={['AI모델1', 'AI모델2', 'AI모델3', 'AI모델4', 'AI모델5', 'AI모델6', 'AI모델7', 'AI모델8', 'AI모델9', 'AI모델10']}
              datasets={[
                { label: 'AI 평균 점수', data: [92, 91, 93, 94, 92, 95, 94, 93, 91, 92], borderColor: '#5C5FD6', backgroundColor: '#5C5FD6' },
                { label: '기간 평균', data: [80, 85, 90, 85, 80, 85, 90, 85, 80, 85], borderColor: '#F47356', backgroundColor: '#F47356', borderDash: [6, 10] },
              ]}
            />
          </GraphBox>
        </GraphWraps>

        <GraphWraps>
          <GraphBox width={1576} height={260} padding={'48px 50px'}>
            <StackBarChart
              legendPadding={150}
              title={'기간 내 평가 비중'}
              legends={['평가 상', '평가 중', '평가 하']}
              colors={['#5C5FD6', '#A4A6EA', '#D3D5F4']}
              labels={["MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD"]}
              width={1134}
              height={173}
              datas={[[2000, 1000, 800, 600, 500, 700, 900, 1000, 3000, 2000], [200, 100, 80, 60, 50, 70, 90, 100, 300, 2000], [200, 100, 80, 60, 50, 70, 90, 100, 300, 0]]}
            />
          </GraphBox>
        </GraphWraps>
      </StatisticsDashboardContainer>

      <Table className="active" fixedHeader={true} height="532" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="453px" />
            <col width="240px" />
            <col width="240px" />
            <col width="240px" />
            <col width="202px" />
            <col width="202px" />
          </colgroup>
          <thead>
            <tr>
              <th><SortingButton text={'AI 모델'} /></th>
              <th><SortingButton text={'총 평가 건수'} /></th>
              <th><SortingButton text={'평가 완료 건수'} /></th>
              <th><SortingButton text={'평균 점수'} /></th>
              <th>토근 사용량</th>
              <th>평균 소요 시간</th>
            </tr>
          </thead>
          <tbody>
            <tr><td colSpan={8}><NoData txt={'데이터가 없습니다'}/></td></tr>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={8}><NoData txt={'데이터가 없습니다'}/></td></tr>
                */}
            {/* {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index}>
                <td>text-embedding-ada-002​</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
              </tr>
            ))} */}
          </tbody>
        </table>
      </Table>

      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}

export default AImodelTypeTab;