import { useState } from 'react';

import Radio from 'components/elements/Radio';
import Title from 'components/common/Title';
import GrayBox from 'components/common/GrayBox';
import ButtonList from 'components/common/ButtonList';

import * as PS from 'style/Dashboard';

const options = [
  { id: '0', title: '설정안함' },
  { id: '5000', title: '5초' },
  { id: '10000', title: '10초' },
  { id: '15000', title: '15초' },
  { id: '30000', title: '30초' },
  { id: '60000', title: '1분' },
  { id: '300000', title: '5분' },
];

const AutoRefreshSetPopup = ({
  autoRefrashTimeOption,
  setAutoRefrashTimeOption,
  setRefreshOpen,
  onSaveCallback,
}) => {
  const handleCancel = () => {
    setRefreshOpen(false);
  };

  const handleSave = () => {
    setRefreshOpen(false);
    onSaveCallback(autoRefrashTimeOption, refrashTime);
    setAutoRefrashTimeOption(refrashTime);
  };

  const [refrashTime, setRefrashTime] = useState(autoRefrashTimeOption);

  const popupBts = [
    { label: '취소', className: 'secondary', onClick: handleCancel },
    { label: '저장', className: 'primary', onClick: handleSave },
  ];

  const getRefrashText = (refrashTime) => {
    if (!refrashTime || refrashTime == '0') return '자동 새로고침을 중지합니다.';
    return `${options.find((obj) => obj.id === refrashTime)?.title} 마다 자동 새로고침 합니다.`;
  };

  return (
    <PS.PopupAutoRefresh>
      <div className="popup-inner">
        <Title title="자동 새로고침 설정 간격" type="sub">
          <div className="right-area">
            <Radio
              id={'0'}
              name="tRdaio"
              checked={refrashTime === '0'}
              onChange={(value) => setRefrashTime(value)}
            >
              설정안함
            </Radio>
          </div>
        </Title>

        <GrayBox>
          <Radio
            id={'5000'}
            name="tRdaio"
            checked={refrashTime === '5000'}
            onChange={(value) => setRefrashTime(value)}
          >
            5초
          </Radio>
          <Radio
            id={'10000'}
            name="tRdaio"
            checked={refrashTime === '10000'}
            onChange={(value) => setRefrashTime(value)}
          >
            10초
          </Radio>
          <Radio
            id={'15000'}
            name="tRdaio"
            checked={refrashTime === '15000'}
            onChange={(value) => setRefrashTime(value)}
          >
            15초
          </Radio>
          <Radio
            id={'30000'}
            name="tRdaio"
            checked={refrashTime === '30000'}
            onChange={(value) => {
              setRefrashTime(value);
            }}
          >
            30초
          </Radio>
          <Radio
            id={'60000'}
            name="tRdaio"
            checked={refrashTime === '60000'}
            onChange={(value) => setRefrashTime(value)}
          >
            1분
          </Radio>
          <Radio
            id={'300000'}
            name="tRdaio"
            checked={refrashTime === '300000'}
            onChange={(value) => setRefrashTime(value)}
          >
            5분
          </Radio>
        </GrayBox>

        <p className="txt-guide">{getRefrashText(refrashTime)}</p>
      </div>

      <ButtonList buttonList={popupBts} ulClass="popup-btns" />
    </PS.PopupAutoRefresh>
  );
};

export default AutoRefreshSetPopup;
