import React, { useRef } from "react";
import { Chart as ChartJS, BarElement, CategoryScale, LinearScale, LineElement, PointElement, Tooltip, Legend } from "chart.js";
import { Bar } from "react-chartjs-2";
import { GraphLabelWrap, GraphLayout, GraphTitleItem, GraphWrapBox } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  Tooltip,
  Legend
);

const MultiBarLineChart = ({ width, height, labels, legends, colors, datas, graphTypes = ['line', 'line', 'bar'], title, legendPadding, useRightYAxis = true }) => {

  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const datasets = datas.map((data, index) => ({
    type: graphTypes[index],
    label: legends[index],
    data: data,
    borderColor: graphTypes[index] === 'line' ? colors[index] : undefined,
    backgroundColor: colors[index],
    borderWidth: graphTypes[index] === 'line' ? 3 : undefined,
    tension: graphTypes[index] === 'line' ? 0 : undefined, // 곡선 형태
    yAxisID: graphTypes[index] === 'bar' ? 'y1' : 'y2', // 막대는 좌측, 라인은 우측 Y축
    pointRadius: graphTypes[index] === 'line' ? 0 : undefined,
    borderCapStyle: graphTypes[index] === 'line' ? "round" : undefined, // 각 데이터 연결선을 둥글게
    barThickness: graphTypes[index] === 'bar' ? 20 : undefined, // 막대 두께
    pointHitRadius: 4,
    hoverRadius: 4,
  }));

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        enabled: true,
        mode: 'nearest',  // 가장 가까운 데이터 포인트 툴팁 표시
        intersect: true  // 데이터 근처에서도 툴팁 표시 가능
      },
      hover: {
        mode: 'index',  // 같은 인덱스의 모든 데이터셋 툴팁 표시
        intersect: true  // 데이터 포인트 위에서만 반응
      },
      datalabels: { display: false },
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: {

          // callback: function (value) {
          //   const label = this.getLabelForValue(value);
          //   return label.split("\n"); // \n을 기준으로 줄 바꿈 처리
          // },

          color: '#B3B3C5',
          font: { size: 11, weight: "500" },
        },

      },
      y1: {
        type: 'linear',
        position: 'left',
        padding: 5,
        stepSize: 1000,
        border: { display: false },
        grid: { color: 'rgba(200, 200, 200, 0.3)' },
        ticks: {
          color: '#B3B3C5',
          font: { size: 11, weight: "500" },
        },
      },
      y2: {
        type: 'linear',
        position: 'right',
        padding: 5,
        stepSize: 1000,
        border: { display: false },
        grid: { drawOnChartArea: false },
        ticks: useRightYAxis ? {
          color: '#B3B3C5',
          font: { size: 11, weight: "500" },
        } : {
          display: false,
        },
      },
    },
  };

  return (
    <GraphLayout>
      <div className="left-wrap">
        <GraphTitleItem>{title}</GraphTitleItem>
        <CustomLegend legends={legends} colors={colors} paddingL={legendPadding} />
      </div>
      <GraphWrapBox width={width} height={height}>
        <Bar data={{ labels, datasets }} options={options} />
      </GraphWrapBox>
    </GraphLayout>
  );
};

export default MultiBarLineChart;

const CustomLegend = ({ legends, colors, paddingL }) => (
  <GraphLabelWrap paddingL={paddingL}>
    {legends.map((item, index) => (
      <p key={index}>
        <span style={{ backgroundColor: colors[index] }} />
        {item}
      </p>
    ))}
  </GraphLabelWrap>
);
