import { useEffect, useState } from 'react';
import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';

const Tab = ({ tabList, defaultIndex = 0, tabClickCallback }) => {
  const [tabIndex, setTabIndex] = useState(defaultIndex);

  const tabActiveHandler = (index) => {
    setTabIndex(index);
    tabClickCallback && tabClickCallback(index);
  };

  useEffect(() => {
    const number = Number(defaultIndex) ? Number(defaultIndex) : 0;
    setTabIndex(number);
  }, [defaultIndex]);

  return (
    <S.Tab>
      <div className="tab-menu">
        {tabList.map((tab, index) => {
          return (
            <button
              type="button"
              key={`tab-menu${index}`}
              className={classnames('tab-anchor', { active: index === tabIndex })}
              onClick={() => tabActiveHandler(index)}
            >
              {tab.title}
            </button>
          );
        })}
      </div>
      <div className="tab-cont">{tabList[tabIndex]?.tabContent}</div>
    </S.Tab>
  );
};

export default Tab;
