import { useState } from "react";
import GrayBox from "components/common/GrayBox";
import { LayerInButtonWrap ,CategoryListContainer} from "style/AutoQAStyle";
import ButtonList from 'components/common/ButtonList';

const tempCategoryList = [
  {
    name: "선택 약정 할인 제도 1-1",
    id: 0,
    children: [],
  },
  {
    name: "선택 약정 할인 제도 1-2",
    id: 1,
    children: [
      {
        name: "선택 약정 할인 제도 1-2-1",
        id: 2,
        children: [
          {
            name: "선택 약정 할인 제도 1-2-1-1", id: 3, children: [
              { name: "선택 약정 할인 제도 1-2-1-1-1", id: 4, children: [] },
              { name: "선택 약정 할인 제도 1-2-1-1-2", id: 5, children: [] }
            ]
          },
          {
            name: "선택 약정 할인 제도 1-2-1-2", id: 6, children: [
              {
                name: "선택 약정 할인 제도 ", id: 7, children: [
                  {
                    name: "선택 약정 할인 제도 ", id: 8, children: [
                      { name: "선택 약정 할인 제도 1-2-1-1-1", id: 9, children: [] },
                    ]
                  },
                ]
              },
            ]
          },
        ],
      },
      { name: "선택 약정 할인 제도 1-2-2", id: 10, children: [] },
      { name: "선택 약정 할인 제도 1-2-3", id: 11, children: [] },
    ],
  },
  {
    name: "선택 약정 할인 제도 1-3",
    id: 12,
    children: [],
  },
];

const CategoryPopup = ({onClose}) => {
  const [openCategory, setOpenCategory] = useState({});
  const [selectedCategory, setSelectedCategory] = useState(null);
  

  const onToggle = (categoryId) => {
    setOpenCategory((prev) => ({
      ...prev,
      [categoryId]: !prev[categoryId],
    }));
  };

  const onSelect = (categoryId) => {
    setSelectedCategory(categoryId);
  };


  const categoryList = (categories, depth = 1) => {
    return categories.map((category,index) => {
      const isOpen = openCategory[category.id]; //arrow 리스트 오픈
      const isSelected = selectedCategory === category.id; //카테고리 값 선택

      return (
        <div key={index}>
          <div
            className={`one-depth ${isOpen ? "active" : ""} ${isSelected ? "select" : ""}`}
            style={{ background: depth > 1 ? "#fff" : "" }}
            onClick={(e) => {onSelect(category.id);}}
          >
            <p>
              {depth > 1 && (
                <span style={{ marginLeft: depth > 2 ? `${(depth - 2) * 32}px` : "0px" }}>　</span>
              )}
              {category.name}
            </p>
            {category.children.length > 0 && (
              <div
                className="btn-toggle-triangle"
                onClick={(e) => {
                  e.stopPropagation(); // 이벤트 전파 방지
                  onToggle(category.id);
                }}
              />
            )}
          </div>
          {isOpen && category.children.length > 0 && (
            <div className="sub-category-list">
              {categoryList(category.children, depth + 1)}
            </div>
          )}
        </div>
      );
    });
  };

  return(
    <>
      <GrayBox direction={"column"}>
        <CategoryListContainer>
          {categoryList(tempCategoryList)}
        </CategoryListContainer>
      </GrayBox>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '선택', className: 'primary', onClick: () => {onClose()} },
        ]} />
      </LayerInButtonWrap>
    </>
  )
};

export default CategoryPopup; 