import { Dimmed } from "style/ElementsStyle";
import { AlertContainer, CenterContainer } from "style/AutoQAStyle";
import Button from "components/elements/Button";

const Alert = ({ text, btnText='확인', width, height, onClose, btnList = [] }) => {
  return (
    <>
      <Dimmed onClose={onClose}>
        <CenterContainer>
          <AlertContainer width={width}>
            <div className="header">
              <button onClick={onClose} />
            </div>
            <div className="center" dangerouslySetInnerHTML={{ __html: text }} />
            <div style={{ marginTop: '26px', display: 'flex', justifyContent: 'end' ,gap:'16px'}}>
              {btnList.length > 0 ?
                btnList.map((item, index) => {
                  return <Button key={index} label={item.label} className={`wide ${item.type}`} onClick={item.evt} />
                })
                 : 
                 <Button label={btnText} className={`wide primary`} onClick={onClose} />
              }
            </div>
          </AlertContainer>
        </CenterContainer>
      </Dimmed>
    </>
  )
};

export default Alert;
