import { useEffect, useState } from "react";
import React from "react";
import Title from "components/common/Title";
import Tooltip from "components/common/Tooltip";
import Button from "components/elements/Button";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Select from "components/elements/Select";
import Checkbox from 'components/elements/Checkbox';
import Table from 'components/common/Table';
import ButtonList from 'components/common/ButtonList';
import { useNavigate } from "react-router-dom";
import NoData from "components/common/NoData";
import { TableInTxtBtn, SubTableTitle, CountingTitle, TotalScore, DetailPageContainer, DetailContentsWrap, BackBtnWrap } from 'style/AutoQAStyle';
import EvaluationSheetPreview from "../popups/EvaluationSheetPreview";
import EvaluationSheetAddColum from "../popups/EvaluationSheetAddColum";
import CustomLayerPopup from "components/common/CustomLayerPopup";
import EvaluationSheetSimulation from "../popups/EvaluationSheetSimulation";
import Alert from "components/common/Alert";

const _tempList_ = [
  {
    name: 'CS 수동 > 기본 인사 > 요금안내',
    desc: '고객에게 정확한 요금을 했는가?',
    cnt: 40,
    details: ['상담사 이름 소개','요금제 별 가격 안내']
  },
  {
    name: 'CS 자동 > 기본인사 > 마무리 인사',
    desc: '고객에게 마무리 인사를 했는가?',
    cnt: 25,
    details: ['테스트1', '테스트2']
  },
  {
    name: 'CS 자동 > 상품안내 > 요금안내',
    desc: '고객에게 정확한 요금을 했는가?',
    cnt: 35,
    details: []
  }
];

const EvaluationSheetDetail = () => {
  const navigate = useNavigate();
  const [tooltipTxt, setTooltipTxt] = useState('');
  const [titleIs, setTitleIs] = useState('상세'); // 평가표 생성 : 툴팁 삭제  || 평가표 상세 : 툴팁 필요  || 평가표 복사 등록 : 툴팁 필요
  const [btnText, setBtnText] = useState(''); // 위의 타이틀 경우마다 버튼 내용 달라짐
  const [openPopup, setOpenPopup] = useState(false); // 평가표 미리보기 팝업
  const [openAddCol, setOpenAddCol] = useState(false); // 평가항목 추가 팝업
  const [title, setTitle] = useState(''); // 평가항목 팝업 타이틀
  const [openSimulation, setOpenSimulation] = useState(false); // 평가 항목 시뮬레이션 팝업
  const [expandedRows, setExpandedRows] = useState([]); // 상태로 확장된 행 관리
  const [arrowStates, setArrowStates] = useState([]);   // 화살표 상태
  // const UpArrow = '/images/up-arrow-round.png';
  const UpArrow = process.env.PUBLIC_URL+'/images/up-arrow-round.png';
  const DownArrow = process.env.PUBLIC_URL+'/images/down-arrow-round.png'

  const [alertOpen, setAlertOpen] = useState(false);  // 평가항목생성 > 저장 버튼 클릭 시 alert창
  const [alertMessage, setAlertMessage] = useState(''); // alert창 메시지

  const toggleRow = (index) => {
    const isExpanded = expandedRows.includes(index);

    // 행 확장,축소 상태 업데이트
    setExpandedRows(isExpanded
      ? expandedRows.filter(row => row !== index)
      : [...expandedRows, index]);

    // 화살표 상태 업데이트
    setArrowStates(prevState => ({
      ...prevState,
      [index]: !prevState[index]
    }));
  };

  const onChangedPopup = (type) => {
    setOpenAddCol(true)
    setTitle(type);
  }

  const handlePopupConfirm = () => {
    setAlertMessage('항목 배점은 평가 세부 항목별 점수의 합과 동일해야합니다.');
    setAlertOpen(true);
  };

  useEffect(() => {
    if (titleIs === '생성') {
      setTooltipTxt('');
      setBtnText('평가항목 생성');
    } else if (titleIs === '상세') {
      setTooltipTxt('현재 해당 평가표를 이용해 평가가 진행 중일​ 경우에는 수정이 불가합니다.​');
      setBtnText('추가');
    } else if (titleIs === '복사 등록') {
      setTooltipTxt('기존에 등록된 평가표를 수정하여 새로운 평가표로 등록할 수 있습니다. <br/>​저장 시, 반드시 평가표명을 수정해주시기 바랍니다.​')
      setBtnText('추가');
    }
  }, [titleIs]);

  return (
    <>
      {openSimulation && //평가 항목 시뮬레이션 팝업
        <CustomLayerPopup
          size="large"
          title="평가 항목 시뮬레이션"
          customWidth={1200}
          open={openSimulation}
          contentsHeight={500}
          padding={false}
          btnEvent={() => { }}
          btnText={'시뮬레이션'}
          onClose={() => setOpenSimulation(false)}
        >
          <EvaluationSheetSimulation />
        </CustomLayerPopup>
      }
      {openPopup && //평가표 미리보기 팝업 
        <CustomLayerPopup
          size="large"
          title="평가표 미리보기"
          customWidth={1200}
          open={openPopup}
          contentsHeight={500}
          btnText={'확인'}
          btnEvent={() => { }}
          onClose={() => setOpenPopup(false)}
        >
          <EvaluationSheetPreview text1={'통합평가'} text2={'상담유형 1 > 상담유형 2 > 상담유형 3'} />
        </CustomLayerPopup>
      }
      {openAddCol && // 평가항목 추가, 수정 팝업
        <CustomLayerPopup
          size="large"
          title={`평가 항목 ${title}`}
          customWidth={1200}
          open={openAddCol}
          contentsHeight={466}
          onClose={() => setOpenAddCol(false)}
          btnEvent={handlePopupConfirm}
        >
          <EvaluationSheetAddColum />
        </CustomLayerPopup>
      }

      {alertOpen && (
        <Alert onClose={() => setAlertOpen(false)} text={`<div class="icon"></div>${alertMessage}`}/> 
      )}

      {/* 평가표 생성 : 툴팁 삭제  || 평가표 상세 : 툴팁 필요  || 평가표 복사 등록 : 툴팁 필요 */}
      <Title title={`평가표 ${titleIs}`} icon="evaluation" tooltip={titleIs !== '생성' ? <Tooltip color={'white'}>{tooltipTxt}</Tooltip> : ''} />

      <DetailPageContainer>
        <DetailContentsWrap className="right-content">
          <Button label="평가표 미리 보기" className={'secondary file'} onClick={() => { setOpenPopup(true) }} />
          <div style={{ margin: '20px 0 28px' }}>
            <GrayBox direction={'column'}>
              <FormItem label={'평가표 명'} marginB={8}>
                <TextField disabled={titleIs === '상세' ? true : false} defaultValue={titleIs === '생성' ? '' : '통합평가'} width={776} />
              </FormItem>
              <FormItem label={'상담 유형'}>
                <div className="wrapping-item">
                  <Select
                    option={[]}
                    type={'simple'}
                    title={'상담유형 1'}
                    onChange={() => { console.log('select!') }}
                  />
                  <Select
                    option={[]}
                    type={'simple'}
                    title={'상담유형 2'}
                    onChange={() => { console.log('select!') }}
                  />
                  <Select
                    option={[]}
                    type={'simple'}
                    title={'상담유형 3'}
                    onChange={() => { console.log('select!') }}
                  />
                </div>
              </FormItem>
            </GrayBox>
          </div>
          <SubTableTitle>
            <CountingTitle>선택 <span>0</span>개</CountingTitle>
            <ButtonList buttonList={[
              { label: '선택 삭제', className: 'secondary del2', onClick: () => { } },
              { label: '평가표 시뮬레이션', className: 'primary play', onClick: () => setOpenSimulation(true) },
              { label: btnText, className: 'primary left-plus', onClick: () => onChangedPopup('생성') },
            ]} />
          </SubTableTitle>
          <Table className="active" scroll fixedHeader={true} height="692" hover={true} round={false}>
            <table className="hover">
              <caption>평가표 조회</caption>
              <colgroup>
                <col width="64px" />
                <col width="706px" />
                <col width="400px" />
                <col width="150px" />
                <col width="150px" />
              </colgroup>
              <thead>
                <tr>
                  <th>
                    <Checkbox />
                  </th>
                  <th className="t-left left-padding">평가 항목명</th>
                  <th className="t-left left-padding">평가 항목 설명</th>
                  <th>배점</th>
                  <th>수정</th>
                </tr>
              </thead>
              <tbody>
                {_tempList_.length > 0 ?
                  _tempList_.map((item, index) => {
                    const hasDetails = item.details.length > 0;
                    const rowClass = hasDetails ? 'gray' : '';
                    return (
                      <React.Fragment key={index}>
                        <tr
                          key={index}
                          onClick={() => toggleRow(index)}
                          className={`details-row`}
                        >
                          <td className={rowClass}><Checkbox /></td>
                          <td className={`${rowClass} t-left left-padding with-img`} height={52}>
                            {item.name}
                            {hasDetails && <img src={arrowStates[index] ? UpArrow : DownArrow} />}
                          </td>
                          <td className={`${rowClass} t-left left-padding`}>{item.desc}</td>
                          <td className={rowClass}>{item.cnt}</td>
                          <td className={`${rowClass} center`}>
                            <TableInTxtBtn 
                              onClick={(e) => {
                              e.stopPropagation();
                              onChangedPopup('수정');
                              }}
                            >수정</TableInTxtBtn>
                          </td>
                        </tr>
                        {expandedRows.includes(index) && hasDetails && (
                          <tr key={`${index}-details`} className="details-row">
                            <td colSpan={5}>
                              <ul>
                                {item.details.map((detail, i) => (
                                  <li key={`${index}-${i}`}>
                                    <div>
                                      <span className="detail-tag">세부 항목</span>{detail}
                                    </div>
                                    <p className="score">{item.cnt / 2}</p>
                                    <p>-</p>
                                  </li>
                                ))}
                              </ul>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    )
                  }) :
                  <tr><td colSpan={5}><NoData txt={'내용이 없습니다'} /></td></tr>
                }
              </tbody>
            </table>
          </Table>
          <TotalScore height={76} border={false} padding={false}>0</TotalScore>
          <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
            <Button 
              label="저장" 
              className={'primary wide'} 
              onClick={() => {
                setAlertMessage('기존에 등록된 동일한 이름의 평가표가 있습니다.');
                setAlertOpen(true);
              }} 
            />
          </div>
        </DetailContentsWrap>
        <BackBtnWrap>
          <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
        </BackBtnWrap>
      </DetailPageContainer>
    </>
  );
}

export default EvaluationSheetDetail;