import Title from "components/common/Title";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Button from "components/elements/Button";
import { DetailContentsWrap, DetailTitles, DetailPageContainer, SubTableTitle, CountingTitle, } from "style/AutoQAStyle";
import Table from "components/common/Table";
import ButtonList from "components/common/ButtonList";
import Checkbox from "components/elements/Checkbox";
import NoData from "components/common/NoData";

const RoleManagementPage = () => {
  return (
    <>
      <Title title="역할 생성/목록" icon="settings" />
      <DetailPageContainer>
        <DetailContentsWrap padding={true}>
          <DetailTitles>역할 생성</DetailTitles>
          <GrayBox direction={'column'}>
            <FormItem label={'역할명'} marginB={8}>
              <TextField disabled={false} width={223} placeholder={'역할명을 입력하세요.'} />
            </FormItem>
            <FormItem label={'역할 코드'} marginB={8}>
              <TextField disabled={false} width={223} placeholder={'코드를 입력하세요.'} />
            </FormItem>
            <FormItem label={'설명'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'설명을 입력하세요.'} count={40} maxLength={40} />
            </FormItem>
          </GrayBox>
          <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
            <Button label="저장" className={'primary wide'} onClick={() => { }} />
          </div>

          <div>
            <SubTableTitle width={1478}>
              <CountingTitle>선택 <span>0</span>개</CountingTitle>
              <ButtonList buttonList={[
                { label: '선택 삭제', className: 'secondary del2', onClick: () => { } },
              ]} />
            </SubTableTitle>
            <Table className="active" scroll fixedHeader={true} height="692" hover={true} interval={true} round={false}>
              <table>
                <colgroup>
                  <col width="64px" />
                  <col width="220px" />
                  <col width="220px" />
                  <col width="720px" />
                  <col width="256px" />
                </colgroup> 
                <thead>
                  <tr>
                    <th>
                      <Checkbox />
                    </th>
                    <th>역할 명</th>
                    <th>역할 코드</th>
                    <th className="t-left left-padding">설명</th>
                    <th>최종 수정 일시</th>
                  </tr>
                </thead>
                <tbody>
                  {/***********************
                        데이터 없는 경우
                    ***********************
                    <tr><td colSpan={5}><NoData txt={'데이터가 없습니다'}/></td></tr> 
                   */}
                  {Array.from({ length: 5 }).map((_, index) => (
                    <tr key={index} onClick={() => { }}>
                      <td><Checkbox /></td>
                      <td>QAA</td>
                      <td>admin</td>
                      <td className="t-left left-padding">시스템 운영을 위한 권한 보유​</td>
                      <td>2024-11-28 12:00​</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </Table>
          </div>
        </DetailContentsWrap>
      </DetailPageContainer>
    </>
  );
}

export default RoleManagementPage;