import { useState } from "react";
import { TabInLabelInputs, BottomButtonWrap } from "style/AutoQAStyle";
import TextField from "components/elements/TextField";
import Select from "components/elements/Select";
import ButtonList from "components/common/ButtonList";
import Button from "components/elements/Button";
import Alert from "components/common/Alert";


const MenuManagementPopup = ({ type }) => {
  const alertBtnList = [
    {
      label:'취소',
      type:'secondary',
      evt : () => {}
    },
    {
      label:'저장',
      type:'primary',
      evt : () => {}
    }
  ];
  const [openPopup,setOpenPopup] = useState(false);

  return (
    <>
    {openPopup && // 선택삭제 팝업
        // <Alert onClose={() => setOpenPopup(false)} text={'메뉴를 생성 하시겠습니까?​'} btnList={alertBtnList} />  // **** 기본 텍스트 타입
        <Alert onClose={() => setOpenPopup(false)} text={'<div class="icon"></div><span class="red">모든 항목</span>을 입력하셔야 메뉴 생성이 가능합니다.​'}/>  // **** 아이콘 + 경고(빨간 텍스트) 포함 타입
      }
      <TabInLabelInputs>
        <p>대분류 아이디</p>
        <Select width={500} option={[]} type="simple" title={'신규'} />
        {type === 'add' && 
          <> 
          <span className="subStr">* 신규를 선택하여 하위 입력 영역을 기재하면 대분류 메뉴가 생성됩니다.</span>
          <span className="subStr">* 기존에 등록된 대분류 아이디를 선택하면 하위 메뉴를 생성 할 수 있습니다.</span>
          </>
        }
      </TabInLabelInputs>
      {/* <TabInLabelInputs>
        <p>중분류 아이디</p>
        <Select width={500} option={[]} type="simple" title={'신규'} />
      </TabInLabelInputs> */}
      <TabInLabelInputs>
        <p>메뉴명</p>
        <TextField width={500} placeholder={'메뉴명을 입력하세요'} maxLength={20} count={20}/>
      </TabInLabelInputs>
      {/* <TabInLabelInputs>
        <p>메뉴 아이디</p>
        <TextField width={500} placeholder={'메뉴아이디를 입력하세요'} maxLength={10} count={10}/>
      </TabInLabelInputs> */}
      <TabInLabelInputs>
        <p>메뉴 순서</p>
        <Select
          option={[]}
          type="simple"
          width={500}
          title={'메뉴 순서를 선택하세요.'}
        />
      </TabInLabelInputs>
      <TabInLabelInputs>
        <p>메뉴 URL</p>
        <TextField width={500} placeholder={'메뉴 URL을 입력하세요'} />
      </TabInLabelInputs>
      <BottomButtonWrap flexSet={type === 'add' ? 'end' :'space-between'}>
        {type === 'detail' && 
        <div className="left-area">
          <Button label="삭제" className="primary wide" onClick={() => { alert('조회중') }} />
        </div>}
        <div className="right-area">
          <ButtonList buttonList={[
            { label: '취소', className: 'secondary', onClick: () => { } },
            { label: '저장', className: 'primary', onClick: () => {setOpenPopup(true) } },
          ]} />
        </div>
      </BottomButtonWrap>
      
    </>

  )
}

export default MenuManagementPopup;