import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { useEffect, useState } from 'react';
import {
  getFallbacksApi,
  getFallbacksExcelApi,
  getIntentsApi,
  getBotGroupsApi,
  getSentencesApi,
  putSentencesApi,
  updateFallbackStatusApi,
} from '../apis';

import {useDispatch, useSelector} from 'react-redux';
import { showToastNotice } from 'redux/toast';
import { customSort } from 'libs/utiles';
import {useServiceList} from "../../../libs/DataHook";

const DEFAULT_SEARCH_FALLBACK_NEW_PARAMS = {
  startDate: dayjs().subtract(6, 'day').format('YYYY-MM-DD'), // to do subtract 제거
  endDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 20,
};
const DEFAULT_SEARCH_FALLBACK_HISTORY_PARAMS = {
  startDate: dayjs().subtract(6, 'day').format('YYYY-MM-DD'),
  endDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 20,
};

const useFallback = () => {
  const [searchFallbackNewParams, setSearchFallbackNewParams] = useState(
    DEFAULT_SEARCH_FALLBACK_NEW_PARAMS
  );
  const [searchFallbackHistoryParams, setSearchFallbackHistoryParams] = useState(
    DEFAULT_SEARCH_FALLBACK_HISTORY_PARAMS
  );
  const [latestSearchFallbackNewParams, setLatestSearchFallbackNewParams] = useState(null);
  const [latestSearchFallbackHistoryParams, setLatestSearchFallbackHistoryParams] = useState({});

  const serviceList = useServiceList(); // 폴백신규 탭 서비스 목록
  const {serviceId, serviceName} = useSelector((state) => state.service.value);
  const [botGroupList, setBotGroupList] = useState([]); // 폴백신규 탭 봇 그룹 목록
  const [historyBotGroupList, setHistoryBotGroupList] = useState([]); // 처리 이력 탭 봇 그룹 목록
  const [fallbackNewRes, setFallbackNewRes] = useState({}); // 폴백 신규 이력 목록
  const [fallbackHistoryRes, setFallbackHistoryRes] = useState({}); // 폴백 처리이력 목록
  const [fallbackDetail, setFallbackDetail] = useState({}); // 폴백 디테일
  const [intents, setIntents] = useState([]); // 인텐트 리스트 (bot ID 기준)
  const [isfallbackHistoryPopupOpen, setIsFallbackHistoryPopupOpen] = useState(false);

  const dispatch = useDispatch();

  // 조회 조건 변경
  const chageSearchFallbackNewParams = (key, value) => {
    setSearchFallbackNewParams(fp.set(key, value));
    if (['serviceId', 'botGroupId'].includes(key)) {
      // 각각의 탭에서 서비스, 봇 그룹 동기화
      setSearchFallbackHistoryParams(fp.set(key, value));
    }
  };

  // 처리 이력 조회 조건 변경
  const chageSearchFallbackHistoryParams = (key, value) => {
    setSearchFallbackHistoryParams(fp.set(key, value));
    if (['serviceId', 'botGroupId'].includes(key)) {
      // 각각의 탭에서 서비스, 봇 그룹 동기화
      setSearchFallbackNewParams(fp.set(key, value));
    }
  };

  // 봇 그룹 목록 조회
  const getBotGroups = async (serviceId) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
      setBotGroupList(sortBotGroups);
      setHistoryBotGroupList(sortBotGroups);
      const firstbotGroupId = fp.getOr('', '[0].botGroupId', sortBotGroups);
      const botGroupName = fp.pipe(
        fp.getOr([], 'data.data.content'),
        fp.find((obj) => obj.botGroupId == firstbotGroupId),
        fp.getOr('', 'botGroupName')
      )(res);
      chageSearchFallbackNewParams('botGroupId', firstbotGroupId);
      chageSearchFallbackNewParams('botGroupName', botGroupName);
      chageSearchFallbackHistoryParams('botGroupId', firstbotGroupId);
      chageSearchFallbackHistoryParams('botGroupName', botGroupName);
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 목록 조회에 실패했습니다. 봇 그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupList([]);
      setHistoryBotGroupList([]);
    }
  };

  // 폴백 리스트 조회
  const getFallbacks = async (searchParams, type = 'new') => {
    try {
      searchParams.serviceId = serviceId
      searchParams.serviceName = serviceName
      const res = await getFallbacksApi(searchParams, type);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      if (type === 'new') {
        setFallbackNewRes(fp.getOr({}, 'data.data', res));
        console.log('content', fp.getOr({}, 'data.data.list.content', res));
        setLatestSearchFallbackNewParams(searchParams);
      } else {
        setFallbackHistoryRes(fp.getOr({}, 'data.data', res));
        setLatestSearchFallbackHistoryParams(searchParams);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('폴백발화 목록 조회에 실패했습니다.');
      if (type === 'new') {
        setFallbackNewRes({});
      } else {
        setFallbackHistoryRes({});
      }
    }
  };

  // 폴백 리스트 엑셀
  const getFallbacksExcel = async (searchParams, type = 'new') => {
    try {
      const res = await getFallbacksExcelApi({ ...searchParams, type });

      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_${
          type === 'new' ? '폴백신규' : '폴백처리이력'
        }_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Error downloading the file:', error);
    }
  };

  // 폴백 상세 조회
  const getFallbackDtail = async (statDialogId, fallbackStatus) => {
    try {
      const res = await getFallbacksApi({ statDialogId, fallbackStatus });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setFallbackDetail(fp.getOr({}, 'data.data.list.content[0]', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('폴백발화 상세 조회에 실패했습니다.');
      setFallbackDetail({});
    }
  };

  // 폴백 검토 상태 수정
  const updateFallbackStatus = async (payload, type = 'new', isPopup = false) => {
    try {
      const res = await updateFallbackStatusApi(payload);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));

      if (type === 'new') {
        getFallbacks(searchFallbackNewParams, type); // 폴백 목록 재 조회
      } else if (type === 'history') {
        // 폴백 상세 재 조회
        getFallbacks(searchFallbackHistoryParams, type);
      }

      if (isPopup) {
        setIsFallbackHistoryPopupOpen(false);
      }
      const cond = fp.cond([
        [
          fp.matches('IGNORE'),
          fp.constant({
            toastType: 'SUCCESS',
            toastMsg: '해당 폴백 발화가 무시 처리되었습니다.',
          }),
        ],
        [
          fp.matches('HOLD'),
          fp.constant({
            toastType: 'SUCCESS',
            toastMsg: '해당 폴백 발화가 보류 처리되었습니다.',
          }),
        ],
        [
          fp.matches('RELEARN'),
          fp.constant({ toastType: 'SUCCESS', toastMsg: '재학습 처리가 완료되었습니다.' }),
        ],
        [fp.T, fp.constant({ toastType: 'SUCCESS', toastMsg: '처리되었습니다.' })],
      ]);
      // alert(cond(payload.fallbackStatus));

      dispatch(
        showToastNotice({
          ...cond(payload.fallbackStatus),
          position: isPopup ? 'bottom-right' : 'bottom-center',
        })
      );
    } catch (error) {
      console.log('error', error?.message);
      // alert('오류가 발생했습니다. 다시 시도해주세요.');
      dispatch(
        showToastNotice({
          toastType: 'ERROR',
          toastMsg: '오류가 발생했습니다. 다시 시도해주세요.',
          position: isPopup ? 'bottom-right' : 'bottom-center',
        })
      );
    }
  };

  // 인텐트 목록 조회
  const getIntents = async (botId) => {
    try {
      const res = await getIntentsApi({ botId });

      if (fp.getOr(0, 'request.status', res) !== 200)
        throw new Error(fp.getOr('', 'request.statusText', res));

      const intents = fp.pipe(fp.getOr([], 'data.data.content'), fp.sortBy('botName'))(res); // 정렬

      setIntents(intents);
    } catch (error) {
      console.log('error', error?.message);
      // alert('인텐트 목록 조회에 실패했습니다.');
      setIntents([]);
    }
  };

  // 문장 학습
  const putSentences = async (
    botId,
    intentId,
    name,
    utterance,
    statDialogId,
    type = 'new',
    isPopup = false
  ) => {
    try {
      const sentenceRes = await getSentencesApi({ botId, intentId });

      if (fp.getOr(0, 'request.status', sentenceRes) !== 200)
        throw new Error(fp.getOr('', 'request.statusText', sentenceRes));
      const exSentences = fp.getOr([], 'data.data.sentences', sentenceRes);
      const res = await putSentencesApi({
        botId,
        intentId,
        name,
        sentences: [...exSentences, utterance],
      });

      if (fp.getOr(0, 'request.status', res) !== 200)
        throw new Error(fp.getOr('', 'request.statusText', res));
      updateFallbackStatus(
        {
          statDialogId,
          fallbackStatus: 'RELEARN',
          learnMappingIntentId: intentId,
          learnMappingIntentName: name,
          relearnUtterance: utterance,
        },
        type,
        isPopup
      );
      setIsFallbackHistoryPopupOpen(false);
    } catch (error) {
      console.log('error', error?.message);
      const openFeignResponse = JSON.parse(fp.getOr('{}', 'request.response', error));
      if (fp.includes('403', openFeignResponse?.errorMessage)) {
        dispatch(showToastNotice({ toastType: 'ERROR', toastMsg: '권한이 없습니다.' }));
        return;
      }

      dispatch(
        showToastNotice({
          toastType: 'ERROR',
          toastMsg: '오류가 발생했습니다. 다시 시도해주세요.',
        })
      );
    }
  };

  useEffect(() => {
    if (!serviceId) return;
    getBotGroups(serviceId);
    getBotGroups(serviceId, 'history');
  }, [serviceId]);

  useEffect(() => {
    const botGroupName = fp.pipe(
      fp.find((obj) => obj.botGroupId == searchFallbackNewParams.botGroupId),
      fp.getOr('', 'botGroupName')
    )(botGroupList);

    chageSearchFallbackNewParams('botGroupName', botGroupName);
  }, [searchFallbackNewParams.botGroupId]);

  useEffect(() => {
    const botGroupName = fp.pipe(
      fp.find((obj) => obj.botGroupId == searchFallbackHistoryParams.botGroupId),
      fp.getOr('', 'botGroupName')
    )(historyBotGroupList);

    chageSearchFallbackHistoryParams('botGroupName', botGroupName);
  }, [searchFallbackHistoryParams.botGroupId]);

  return {
    searchFallbackNewParams,
    searchFallbackHistoryParams,
    serviceList,
    serviceId,
    serviceName,
    botGroupList,
    historyBotGroupList,
    fallbackNewRes,
    fallbackHistoryRes,
    fallbackDetail,
    intents,
    isfallbackHistoryPopupOpen,
    latestSearchFallbackNewParams,
    latestSearchFallbackHistoryParams,
    chageSearchFallbackNewParams,
    chageSearchFallbackHistoryParams,
    getBotGroups,
    getFallbacks,
    getFallbacksExcel,
    updateFallbackStatus,
    getFallbackDtail,
    getIntents,
    putSentences,
    setIsFallbackHistoryPopupOpen,
  };
};

export default useFallback;
