import SortingButton from 'components/elements/SortingButton';
import Table from "components/common/Table";
import Button from 'components/elements/Button';

const data = [
  { id: 1, name: "이상담(202021)", department: "상담센터 부서1", cnt: 0, total: 100, high: 10, mid: 10, low: 10, sum: 10 },
  { id: 2, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 60, high: 5, mid: 5, low: 5, sum: 5 },
  { id: 3, name: "이상담(202021)", department: "상담센터 부서1", cnt: 0, total: 34, high: 7, mid: 7, low: 7, sum: 7 },
  { id: 4, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 52, high: 12, mid: 12, low: 12, sum: 12 },
  { id: 5, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 18, high: 4, mid: 4, low: 4, sum: 4 },
  { id: 6, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 53, high: 21, mid: 21, low: 21, sum: 21 },
  { id: 7, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 65, high: 2, mid: 2, low: 2, sum: 2 },
  { id: 8, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 15, high: 7, mid: 7, low: 7, sum: 7 },
  { id: 9, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 38, high: 8, mid: 8, low: 8, sum: 8 },
  { id: 10, name: "장상담(202022)", department: "상담센터 부서1", cnt: 0, total: 39, high: 3, mid: 3, low: 3, sum: 3 },
];

const ExtractPopup = ({ type }) => {
  return (
    <>
      <Table className="active" scroll fixedHeader={true} height="492" hover={true} interval={true} round={false}>
        <table className='small-line'>
          <colgroup>
            <col width="60px" />
            <col width="160px" />
            <col width={`${type === 'type1' ? '297px' : '160px'}`} />
            <col width="120px" />
            {type === 'type1' ?
              <col width="120px" colSpan={4} />
              : <>
                <col width="60px" />
                <col width="60px" />
                <col width="60px" />
                <col width="60px" />
              </>}
          </colgroup>
          <thead>
            <tr>
              <th rowSpan="2">No.</th>
              <th rowSpan="2" className="t-left left-padding">상담사명(사번)</th>
              <th rowSpan="2" className="t-left left-padding">소속</th>
              <th rowSpan="2" className="t-left left-padding">
                <SortingButton text={'대상 건수'} />
              </th>
              <th colSpan="4" className='no-line'>
                {type === 'type1' ? <SortingButton text={'추출 건수'} /> : '추출 건수'}
              </th>
            </tr>
            {type === 'type2' &&
              <tr>
                <th className='custom-title'><SortingButton text={'상위'} /></th>
                <th className='custom-title'><SortingButton text={'중위'} /></th>
                <th className='custom-title'><SortingButton text={'하위'} /></th>
                <th className='custom-title'><SortingButton text={'합계'} /></th>
              </tr>
            }
          </thead>
          <tbody>
            {data.map((row, index) => (
              <tr key={row.id}>
                <td>{index + 1}</td>
                <td className="t-left left-padding">{row.name}</td>
                <td className="t-left left-padding">{row.department}</td>
                <td>{row.total}</td>
                {type === 'type1' && <td colSpan={4}>{row.cnt}</td>}
                {type === 'type2' &&
                  <>
                    <td>{row.high}</td>
                    <td>{row.mid}</td>
                    <td>{row.low}</td>
                    <td>{row.sum}</td>
                  </>
                }
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
        <Button label="확인" className={'primary wide'} onClick={() => { }} />
      </div>
    </>
  );
};

export default ExtractPopup;