import styled from '@emotion/styled/macro';
import _mx from './Style';
import _svg from './SvgList';
import {_color} from './Variable';
import * as S from './ElementsStyle';

export const tableTheadBg = `
	.in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 42px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}
	}
`;

export const Service = styled.div`
  ${tableTheadBg}
  ${S.Table} {
    ${S.ButtonList} {
      justify-content: center;
    }
    ${S.Button} {
      min-width: 72px !important;
    }
  }
`;

export const PopupService = styled.div`
  .app-key-row {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 16px;
    span {
      &.error {
        color: ${_color.error};
      }
    }
  }
  .form-item__title {
    margin-top: 24px;

    .form-cont {
      align-self: flex-start;
      ${S.BulletList} {
        margin-top: 0px;
      }
    }
  }
`;

export const MenuAccess = styled.div`
${tableTheadBg}
`;

export const Permission = styled.div`
	${tableTheadBg}
`;
export const UserManagement = styled.div`
	${tableTheadBg}
`;

export const MenuManagement = styled.div`
	${tableTheadBg}
`;

export const CodeManagement = styled.div`
	${tableTheadBg}
`;

export const Template = styled.div`
  .reference-date {
    display: flex;

    dt,
    dd {
      color: #555f6d;
      font-size: 15px;
      font-weight: 500;
    }

    dt {
      padding-left: 26px;
      background: ${_mx.svg(_svg.timeClockNew)} left center no-repeat;
    }
    dd {
      margin-left: 3px;
    }
  }

  .split-area {
    display: flex;
    gap: 32px;
    .split {
      flex: 1;
    }
  }
  .in-table-bg {
    position: relative;
    width: calc(100% - 8px);
    &::before {
      display: block;
      content: '';
      width: 8px;
      height: 52px;
      background: #e9edfb;
      border-top: 1px solid #d7d9f3;
      border-bottom: 1px solid #d7d9f3;
      position: absolute;
      top: 0;
      right: -8px;
    }
  }
  .titH3 {
    font-size: 20px;
    height: initial;
    padding: 44px 0 14px 0;
    border-bottom: 1px solid #cfd6dd;
    margin-bottom: 20px;
    &.non-line {
      border: none;
    }
  }
  .template-wrap {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: relative;
    margin-top: 10px;
    border-radius: 8px;
    > h3 {
      font-size: 15px;
      font-weight: 500;
      color: #222;
      padding: 24px 0 10px 0;
    }
    .right-area {
      display: flex;
      justify-content: flex-end;
      padding-bottom: 10px;
    }
    .template-title {
      font-size: 17px;
      padding: 17px;
    }

    .template-contents {
      padding: 10px;
      height: 100%;
      border-radius: 8px;
      border: 1px solid #cfd6dd;
      background-color: #fff;
    }

    .template-textarea {
      padding: 5px;
    }

    .template-input {
      font-size: 17px;
      padding: 6px;
    }
  }
  .template-preview {
    width: 100%;
    height: 500px;
    padding: 10px;
    border: 1px solid #cfd6dd;
    border-radius: 8px;
    overflow-y: auto;
    &::-webkit-scrollbar-button:vertical:start:decrement,
    &::-webkit-scrollbar-button:vertical:start:increment {
      display: block;
      height: 0;
    }
    &::-webkit-scrollbar {
      width: 8px;
    }
    &::-webkit-scrollbar-thumb {
      background-color: #e9ecef;
      border-radius: 8px;
    }
  }
  .preview-section {
    display: flex;
    border: 1px solid #d7d9f3;
    border-radius: 14px;
    width: 350px;
  }
  .next-line {
    width: 100%;
    margin-bottom: 18px;
    display: flex;
    > label {
      min-width: 140px;
      height: 30px;
      font-size: 14px;
      line-height: 30px;
      border-radius: 4px;
      display: inline-block;
      text-align: center;
    }
    > a {
      cursor: pointer;
      padding-left: 20px;
      font-weight: 500;
      font-size: 15px;
      color: #66AAFE;
      text-decoration: underline;
    }
  }
  .input-box {
    width: 100%;
    margin-bottom: 18px;
    display: flex;
    &.textarea {
      align-items: flex-start;
    }
    > label {
      min-width: 140px;
      height: 30px;
      font-size: 14px;
      line-height: 30px;
      border-radius: 4px;
      background-color: #e9ecef;
      display: inline-block;
      text-align: center;
    }
    > p,
    > div {
      width: calc(100% - 110px);
      padding-left: 20px;
      font-weight: 500;
      font-size: 15px;
    }
    .upload {
      width: calc(100% - 110px);
      display: flex;
      position: relative;
      > div {
        & + button {
          margin-left: 6px;
        }
      }
      > button {
        & + button {
          margin-left: 6px;
        }
      }
      .color-prev {
        width: 40px;
        height: 40px;
        border-radius: 6px;
        overflow: hidden;
        margin-left: 6px;
        border: 1px solid #cfd6dd;
      }
    }
    // .text-area {
    //   background: none;
    //   border: none;
    //   border-radius: 0;
    //   > input,
    //   textarea {
    //     width: 100%;
    //     overflow: hidden;
    //     background: ${_color.white};
    //     border: 1px solid #cfd6dd;
    //     border-radius: 6px;
    //     &:read-only {
    //       border: none;
    //       background-color: #fff;
    //     }
    //   }
    //   .info {
    //     font-size: 12px;
    //     color: #7e8b99;
    //     padding-left: 16px;
    //   }
    // }
  }
  .templateDetail {
    width: 100%;
    background-color: #fff;
    border-radius: 8px;
    padding: 28px 52px;
    > .input-box{
      align-items: baseline;
    }
  }
  .mt-30 {
    margin-top: 30px;
  }
  .mt-40 {
    margin-top: 40px;
  }
  .channerUI {
    width: 100%;
    display: flex;
    .preview,
    .setting {
      h4 {
        width: 100%;
        line-height: 40px;
        font-size: 16px;
        color: #272e35;
        text-align: left;
        font-weight: bold;
        margin-bottom: 6px;
        display: flex;
        align-items: center;
        justify-content: space-between;
      }
      .cont-prev {
        display: flex;
        justify-content: center;
        align-items: center;
        width: 100%;
        min-height: 702px;
        background-color: #fff;
        border-radius: 8px;
        .chatting-prev {
          border: 0;
        }
      }
      .cont {
        width: 100%;
        min-height: 702px;
        background-color: #fff;
        border-radius: 8px;
        padding: 24px 52px;
      }
    }
    .preview {
      min-width: 510px;
    }
    .setting {
      width: calc(100% - 510px);
      height:100%;
      margin-left: 30px;
    }
    .favorites {
      display: inline-block;
      width: 22px;
      height: 22px;
      background-color: transparent;
      background: url('/images/ico_star_line.svg') 0 0 / 100% no-repeat;
      &.check {
        background: url('/images/ico_star.svg') 0 0 / 100% no-repeat;
      }
      &:hover {
        background: url('/images/ico_star.svg') 0 0 / 100% no-repeat;
      }
    }
  }
  .warning {
    font-size: 13px;
    position: relative;
    margin-top: 8px;
    color: #555f6d;
    margin-bottom: 10px;
    &.bot {
      font-size: 13px;
      color: #7e8b99;
      padding-left: 16px;
    }
  }
  .platform-setting {
    width: 100%;
    height: 100%;
    background-color: #fff;
    border-radius: 8px;
    padding: 24px 52px;
    .field-box {
      width: fit-content;
      display: flex;
      align-items: baseline;
      .time-unit {
        display: block;
        color: #7e8b99;
        font-size: 14px;
        margin-left: 12px;
      }
    }
    .item-box {
      > .input-box {
        align-items: center;
      }
    }
  }
  .chatbot-setting {
    width: 100%;
    position: relative;
    display: flex;
    justify-content: space-between;
    .setting-item {
      width: calc(100% - 490px);
      height: 722px;
      background-color: #fff;
      border-radius: 8px;
      padding: 24px 52px;
      &::-webkit-scrollbar-button:vertical:start:decrement,
      &::-webkit-scrollbar-button:vertical:start:increment {
        display: block;
        height: 0;
      }
      &::-webkit-scrollbar {
        width: 8px;
      }
      &::-webkit-scrollbar-thumb {
        background-color: #e9ecef;
        border-radius: 8px;
      }
      overflow: hidden;
      overflow-y: auto;
      > .input-box {
        align-items: baseline;
        > label {
          width: 200px;
        }
        > div {
          width: calc(100% - 220px);
        }
        .text-area {
          max-width: 550px;
        }
        .select {
          width: 558px;
          > div {
            width: 100%;
          }
        }
        > .bg-upload {
          width: 570px;
          display: flex;
          align-items: baseline;
          > .radio-box {
            width: 224px;
            padding-right: 20px;
            margin-right: 20px;
            position: relative;
            &:after {
              content: '';
              width: 1px;
              height: 20px;
              display: inline-block;
              background-color: #e9e9e9;
              position: absolute;
              top: 50%;
              transform: translateY(-50%);
              right: 0;
            }
          }
          > .upload {
            width: auto;
            flex: 1;
            > div {
              width: auto;
              flex: 1;
            }
            .text-area {
              width: auto;
            }
            .color-prev {
              width: 40px;
              height: 40px;
              border-radius: 6px;
              overflow: hidden;
              margin-left: 6px;

              border: 1px solid #cfd6dd;
            }
          }
          &.short {
            width: 320px;
          }
          .icon-wrap {
            width: auto;
            padding-left: 50px;
            position: relative;
            .chat-icon {
              width: 40px;
              height: 40px;
              border-radius: 50%;
              position: absolute;
              top: 50%;
              transform: translateY(-50%);
              left: 0;
            }
          }
        }
        > .upload {
          width: 330px;
          flex: auto;
          > div {
            width: 290px;
          }
        }
      }
    }
  }
  .chatting-prev {
    width: 460px;
    background-color: #fff;
    border-radius: 8px;
    padding: 24px 24px;
    display: flex;
    flex-direction: column;
    align-items: center;
    > .visible {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
    }
    > .invisible {
      display: flex;
      justify-content: center;
      align-items: center;
      height: 604px;
      text-align: center;
      font-size: 15px;
      flex-direction: column;
      color: #7e8b99;
      > .icon {
        width: 20px;
        height: 20px;
        margin-bottom: 15px;
        background: url('/images/ico_search.svg') center center / 100% no-repeat; 
      }
    }
    > h4 {
      width: 100%;
      font-size: 20px;
      color: #272e35;
      font-weight: 600;
      padding: 24px 0 10px 0;
    }
    .floating-btn {
      width: 400px;
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      .speech-bubble {
        text-align: center;
        width: calc(100% - 78px);
        padding: 15px;
        border-radius: 14px;
        margin-right: 14px;
        position: relative;
        .tail {
          width: 4px;
          height: 10px;
          display: inline-block;
          -webkit-mask: url('/images/ico_floating_bubble.svg') center center / 100% no-repeat;
          mask: url('/images/ico_floating_bubble.svg') center center / 100% no-repeat;
          position: absolute;
          top: 50%;
          right: -4px;
          transform: translateY(-50%);
        }
      }
      .btn-chatting {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        position: relative;
        &::after {
          content: '';
          width: 32px;
          height: 32px;
          display: inline-block;
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
        }
      }
    }
    .chat-box {
      width: 360px;
      height: 600px;
      border: 1px solid #d7d9f3;
      border-radius: 10px;
      overflow: hidden;
      display: flex;
      flex-wrap: wrap;
      flex-direction: column;
      .chat-head {
        width: 100%;
        min-height: 80px;
        padding: 12px 16px;
        position: relative;
        border-bottom: 1px solid #d7d9f3;
        background-color: #fff;
        display: flex;
        .chat-close {
          width: 20px;
          height: 20px;
          background: url('/images/ico_chat_close.svg') center center / 100% no-repeat;
          position: absolute;
          top: 12px;
          right: 16px;
        }
        .chat-ico {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          margin-right: 10px;
        }
        .chat-info {
          width: calc(100% - 90px);
          > h4 {
            width: 100%;
            font-size: 18px;
            line-height: 1.33;
            color: #272e35;
            font-weight: 600;
            overflow: hidden;
            display: -webkit-box;
            text-overflow: ellipsis;
            word-break: break-all;
            -webkit-box-orient: vertical;
            -webkit-line-clamp: 2;
            margin-bottom: 5px;
          }
          .connention {
            position: relative;
            display: flex;
            align-items: center;
            justify-content: space-between;
            > em {
              font-size: 14px;
              color: #808387;
              padding-left: 14px;
              &::after {
                content: '';
                width: 8px;
                height: 8px;
                border-radius: 50%;
                display: inline-block;
                background-color: #0b9c38;
                position: absolute;
                top: 50%;
                left: 0;
                transform: translateY(-50%);
              }
            }
            .chatting-end {
              width: auto;
              height: 24px;
              line-height: 24px;
              padding: 0 10px;
              border: 1px solid #d7d9f3;
              border-radius: 4px;
              color: #272e35;
              font-size: 13px;
            }
          }
        }
      }
      .chat-cont {
        width: 100%;
        background-size: 100% 100%;
        background-color: #f0f3f8;
        padding: 20px 16px;
        flex: 1;
        .bot-chat {
          width: 100%;
          display: flex;
          flex-direction: column;
          flex-wrap: wrap;
          align-content: flex-start;
          .profile {
            display: flex;
            align-items: center;
            margin-bottom: 6px;
            .icon {
              width: 34px;
              height: 34px;
              border-radius: 50%;
              overflow: hidden;
              margin-right: 6px;
            }
            > span {
              width: calc(100% - 40px);
              font-size: 17px;
              color: #272e35;
              font-weight: normal;
            }
          }
          > .txt-box {
            width: 82%;
            border-radius: 4px 14px 14px 14px;
            border: 1px solid #d7d9f3;
            background-color: #fff;
            font-size: 15px;
            line-height: 1.39;
            color: #272e35;
            padding: 12px;
            & + .txt-box,
            & + .btn-list {
              margin-top: 6px;
            }

            > strong {
              width: 100%;
              display: inline-block;
              font-size: 16px;
              font-weight: 600;
              margin-bottom: 10px;
            }
            > .button {
              width: 100%;
              padding:6px 0;
              border-radius: 4px;
              border: 1px solid #d7d9f3;
              background-color: #fff;
              font-size: 15px;
              margin-top: 10px;
              text-align: center;
            }
          }
          .btn-list {
            width: 100%;
            display: flex;
            background-color: transparent;
            padding: 0;
            > li {
              & + li {
                margin-left: 6px;
              }
              > .button {
                width: auto;
                border: 1px solid #d7d9f3;
                background-color: #fff;
                border-radius: 30px;
                padding: 6px 12px;
              }
            }
          }
          & + .bot-chat,
          & + .customer-chat {
            margin-top: 20px;
          }
        }
        .customer-chat {
          width: 100%;
          display: flex;
          justify-content: flex-end;
          > .txt-box {
            width: 82%;
            border-radius: 14px 4px 14px 14px;
            border: 1px solid #d7d9f3;
            background-color: #4e47d6;
            font-size: 15px;
            line-height: 1.39;
            color: #fff;
            padding: 12px;
            & + .txt-box {
              margin-top: 6px;
            }
          }
          & + .bot-chat,
          & + .customer-chat {
            margin-top: 20px;
          }
        }
      }
      .chat-input {
        border-top: 1px solid #d7d9f3;
        min-height: 80px;
        padding: 12px 16px;
        display: flex;
        align-items: center;
        > .button {
          width: 20px;
          height: 20px;
          background:url('/images/ico_chat_plus.svg') center center / 100% no-repeat;
          margin-right: 12px;
        }
        > textarea {
          width: 100%;
          height: 56px;
          line-height: 56px;
          border-radius: 14px;
          background-color: #f0f3f8;
          border: none;
          resize: none;
          padding: 0 10px;
          font-size: 18px;
          color: #808387;
          font-size: 15px;
          &:focus{
            outline: none;
          }
        }
      }
    }
    .ql-size-small{
      font-size:11px;
      line-height:18px;
      &.large{
        font-size:19px;
        line-height:26px;
      }
    }
    .ql-size-normal{
      font-size:13px;
      line-height:20px;
      &.large{
        font-size:21px;
        line-height:28px;
      }
    }
    .ql-size-large{
      font-size:15px;
      line-height:22px;
      &.large{
        font-size:23px;
        line-height:30px;
      }
    }
    .ql-size-huge{
      font-size:17px;
      line-height:24px;
      &.large{
        font-size:25px;
        line-height:32px;
      }
    }
    &.font-size-normal{
      .speech-bubble {
        word-break: break-all;
        font-size: 15px !important;
      }
      .chat-info {
        > h4 {
        font-size: 18px !important;
        } 
      }
      .connention{
        > em{
          font-size:14px !important;
        }
        .chatting-end{
          font-size:13px !important;
        }
      }
      .chat-box{
        height:562px;
      }
      .bot-chat{
        > .profile{
          > span{
            font-size:14px !important;
          }
        }
        > .txt-box{
          * {
            font-size: 15px !important;
          }
          > strong{
            font-size:16px !important;
          }
          > a {
            font-size:15px !important;
          }
          > .button {
            font-size:15px !important;
          }
        }
        .btn-list{
          > li{
            > .button{
              font-size:15px !important;
            }
          }
        }
      }
    }
    &.font-notosans{
      *{
        font-family:'Noto Sans KR' !important;;
      }
    }
    &.font-pretendard{
      *{
        font-family:'Pretendard' !important;;
      }
    }
    &.font-size-large{
      .speech-bubble {
        word-break: break-all;
        font-size: 18px !important;
      }
      .chat-info {
        > h4 {
        font-size: 22px !important;
        } 
      }
      .connention{
        > em{
          font-size:14px !important;
        }
        .chatting-end{
          font-size:13px !important;
        }
      }
      .chat-box{
        height:562px;
      }
      .customer-chat{
        > .txt-box{
          font-size:18px !important;
        }
      }
      .bot-chat{
        * {
          font-size: 18px !important;
        }
        > .profile{
          > span{
            font-size:17px !important;
          }
        }
        > .txt-box{
          > strong{
            font-size:19px !important;
          }
          > a {
            font-size:18px !important;
          }
          > .button {
            font-size:18px !important;
          }
        }
        .btn-list{
          > li{
            > .button{
              font-size:18px !important;
            }
          }
        }
      }
    &.font-notosans{
      *{
        font-family:'Noto Sans KR' !important;;
      }
    }
    &.font-pretendard{
      *{
        font-family:'Pretendard' !important;;
      }
    }
  }
`;

export const IpManagement = styled.div`
  ${tableTheadBg}
  ${S.GrayBox} {
    .text-filed-wrap {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    ${S.Button} {
      width: 100px;
    }
    & + ${S.Title} {
      margin-top: 24px;
    }
  }
  ${S.Checkbox} {
    .label {
      order: 0;
      margin-right: 8px;
    }
    .icon {
      order: 1;
    }
  }
`;

export const SystemManagement = styled.div`
  ${S.FormItem} {
    .form-label {
      width: 160px;
    }
    ${S.DatePickerInput} {
      width: 260px;
    }
  }

  .counter-wrap {
    display: flex;
    gap: 0 4px;
    align-items: flex-start;
    transform: translateY(6px);
    input {
      text-align: center;
    }
    .sub-text {
      padding: 14px 0 0 12px;
      font-size: 16px;
    }
  }
`;

export const PopupManageMenuAccess = styled.div`
  tr {
    td {
      font-weight: 600;
    }
    &.toggle > td {
      background: #f3f6f9;
    }
    .btn-toggle-triangle {
      width: 20px;
      height: 20px;
      background: ${_mx.svg(_svg.arrowHead('272e35'))} center no-repeat;
      transform: rotate(-90deg);
    }
    &.hide {
      display: none;
      td {
        font-weight: 400;
        background: ${_color.white};
      }
      & > td {
        padding: 0;
      }
    }
    &.active {
      .btn-toggle-triangle {
        transform: rotate(90deg);
      }
      & + .hide {
        display: table-row;
      }
    }
  }

  ${S.GrayBox} + ${S.Table} {
    margin-top: 44px;
  }
`;

