import * as S from '../../style/ElementsStyle';

/* vertical : 수직정렬, align : 좌우정렬. default : top left 정렬*/
const GrayBox = ({ vertical, align, direction, children, color,height }) => {
  return (
    <S.GrayBox vertical={vertical} direction={direction} align={align} color={color} height={height}>
      {children}
    </S.GrayBox>
  );
};
export default GrayBox;
