const groupDummy = [
  {id: '', title: '전체'},
  {id: 'group1', title: '조직1'},
  {id: 'group2', title: '조직2'},
  {id: 'group3', title: '조직3'},
]

const SearchBoxPopup = ({onClose, title}) => {
  const [showIs,setShowIs] = useState(false);
  const updatedTitle = title.slice(0,3);
  const lastLabel = updatedTitle === '평가자' ? '직원' : updatedTitle;
  const [group, setGroup] = useState({id: '', title: '전체'});
  const [user, setUser] = useState('');
  const [selectedId, setSelectedId] = useState(null);

  return(
    <>
      <GrayBox vertical="center">
        <FormGrid gap={12}>
          <FormItem label="조직">
            <Select
              title={group.title}
              type="simple"
              value={group.id}
              option={groupDummy}
              onChange={(value) => {
                setGroup(groupDummy.find(item => item["id"] === value));
              }}
              disabled={false}
              width={260}
            />
          </FormItem>
          <FormItem label={lastLabel}>
            <TextField
                placeholder={lastLabel+"명을 입력하세요"}
                value={user}
                width={260}
                readOnly={false}
                onChange={(value) => {
                  setUser(value)
                }}
            />
          </FormItem>
        </FormGrid>
      </GrayBox>
      <LayerInButtonWrap>
        <Button label="검색" className="primary wide" onClick={() => setShowIs(true)}/>
      </LayerInButtonWrap>

      {showIs &&  // 검색 버튼 클릭 후 노출될 테이블 영역
        <LayerPopupInHideBox>
          <Title
            title={updatedTitle+' 검색'}
            type="sub"
            subTitle={`<span className="count">조회 결과 <strong>${userListDummy.pagination.totalCount}</strong>개</span>`}
          />
          <Table fixedHeader height="308" interval={false}>
            <table>
              <caption>상담사/평가자, 소속에 관한 표</caption>
              <colgroup>
                <col width="60px" />
                <col width='204px'/>
                <col width="256px"/>
              </colgroup>
              <thead>
                <tr>
                  <th scope="col"></th>
                  <th className="t-left left-padding" scope="col">{updatedTitle + " (사번)"}</th>
                  <th scope="col" className="t-left">소속</th>
                </tr>
              </thead>
              <tbody>
                {userListDummy.users.length === 0 ? (
                  <tr className='thin'>
                    <td colSpan="6">
                      <NoData txt={`조회된 ${updatedTitle}가 없습니다.`} />
                    </td>
                  </tr>
                ) : (
                  userListDummy.users.map((item,index) => (
                    <tr key={index} className='thin'>
                      <td style={{paddingLeft:'22px'}}>
                        <Radio
                          key={item.userId}
                          name="id"
                          id={item.userId}
                          checked={selectedId === item.userId}
                          onChange={(id) => {setSelectedId(id)}}
                        />
                      </td>
                      <td className="t-left left-padding">{`${item.lastName}${item.firstName}`} &#40;{item.userNumber}&#41;</td>
                      <td className="t-left">{item.organizationName}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </Table>
          <Pagination
            pagingTotal={userListDummy.pagination.totalPages}
            currentPage={userListDummy.pagination.currentPage - 1}
            totalCount={userListDummy.pagination.totalCount}
            pageSize={userListDummy.pagination.pageSize}
            numberOfElements={userListDummy.users.length}
            displayed={5}
          />
          <S.LayerPopupBtns>
            <div className="right-area">
              <ButtonList buttonList={[
                // { label: '취소', className: 'secondary', onClick: ()=>{onClose()} },
                { label: '선택', className: 'primary', onClick: ()=>{}, disabled: false },
              ]} />
            </div>
          </S.LayerPopupBtns>
        </LayerPopupInHideBox>
      }

    </>
  );
}

export default SearchBoxPopup;