export const getDateTimeText = (datetime, containsDay = false) => {
  if (!datetime || datetime === '') {
    return '-';
  }
  const date = new Date(datetime);
  return dateTimeFormat(date, containsDay);
}

const day = ['일', '월', '화', '수', '목', '금', '토'];
/**
 * @description : Date 객체를 String 포맷으로 변환
 * @param {Date} date : Date
 * @param {boolean} containsDay : 요일 포함 여부
 * @returns {String} containsDay = true일 경우 `YYYY-MM-DD(E) hh-mm-ss`, containsDay = false일 경우 `YYYY-MM-DD hh-mm-ss`
 * @example dateTimeFormat(new Date(), true); // returns `2024-02-21(수) 17:46:10`
 */
export const dateTimeFormat = (date, containsDay) => {
  let formatter = `${date.getFullYear()}-${( (date.getMonth()+1) < 10 ? "0" + (date.getMonth()+1) : (date.getMonth()+1) )}-${( (date.getDate()) < 10 ? "0" + (date.getDate()) : (date.getDate()) )}`;
  if (containsDay) {
    formatter += `(${day[date.getDay()]})`;
  }
  formatter += ` ${date.getHours() < 10 ? "0" + date.getHours() : date.getHours()}:${date.getMinutes() < 10 ? "0" + date.getMinutes() : date.getMinutes()}:${date.getSeconds() < 10 ? "0" + date.getSeconds() : date.getSeconds()}`;
  return formatter;
}

