export const validateText = (str, minLength, maxLength, allowHangeulAndSpaces) => {
  if (str.length < minLength || str.length > maxLength) {
    return false;
  }
  // Check if it consists of valid characters
  const charRegex = allowHangeulAndSpaces ? /^[ㄱ-ㅎ가-힣a-zA-Z0-9_\-. ]+$/ : /^[a-zA-Z0-9_\-.]+$/;
  // Check for consecutive spaces and special characters
  const consecutiveRegex = allowHangeulAndSpaces ? /[_\-. ]{2}/ : /[_\-.]{2}/;
  // Check if spaces or special characters are at the start or end      
  const startEndRegex = allowHangeulAndSpaces ? /^[_\-. ]|[_\-. ]$/ : /^[_\-.]|[_\-.]$/;

  if (!charRegex.test(str) || consecutiveRegex.test(str) || startEndRegex.test(str)) {
    return false;
  }
  return true;
}


export const getSnapshotStatusText = (snapshotStatus, workflowActionRequest, workflowActionResult, errorHoverText = '') => {
  // workflowActionRequest: NONE, READY, CANCEL, RELEASE, LOCK, UNLOCK, ROLLBACK
  // workflowActionResult : NONE, SUCCESS_ON_REQUEST, SUCCESS_ON_RESPONSE, FAILURE_ON_RESPONSE, SUCCESS_ON_CALLBACK, FAILURE_ON_CALLBACK, TIMEOUT_ON_CALLBACK, ARCHIVED

  if (snapshotStatus === 'SERVICE') {
    if (workflowActionRequest === 'ARCHIVE') {
      if (workflowActionResult === 'FAILURE_ON_RESPONSE' || workflowActionResult === 'FAILURE_ON_CALLBACK' || workflowActionResult === 'TIMEOUT_ON_CALLBACK') {
        return <Flag type="line-red" padding={false} text="종료 실패" errorHover={errorHoverText}/>;
      } else if (workflowActionResult === 'SUCCESS_ON_REQUEST' || workflowActionResult === 'SUCCESS_ON_RESPONSE') {
        return <Flag type="line-yellow" padding={false} text="종료 중" />;
      }
    }
    return <Flag type="line-blue" text="서비스중" />;
  }

  if (workflowActionRequest === 'NONE' || workflowActionResult === 'NONE') {
    return '-';
  }

  switch (workflowActionRequest) {
    case 'READY':
      if (workflowActionResult === 'FAILURE_ON_RESPONSE' || workflowActionResult === 'FAILURE_ON_CALLBACK' || workflowActionResult === 'TIMEOUT_ON_CALLBACK') {
        return <Flag type="line-red" padding={false} text="업데이트 실패" errorHover={errorHoverText} />;
      } else if (workflowActionResult === 'SUCCESS_ON_REQUEST' || workflowActionResult === 'SUCCESS_ON_RESPONSE') {
        return <Flag type="line-yellow" padding={false} text="업데이트 중" />;
      } else if (workflowActionResult === 'SUCCESS_ON_CALLBACK') {
        return <Flag type="green" padding={false} text="업데이트 완료" />;
      } else {
        return snapshotStatus;
      }
    case 'RELEASE':
      if (workflowActionResult === 'FAILURE_ON_RESPONSE' || workflowActionResult === 'FAILURE_ON_CALLBACK' || workflowActionResult === 'TIMEOUT_ON_CALLBACK') {
        return <Flag type="line-red" padding={false} text="배포 실패" errorHover={errorHoverText} />;
      } else if (workflowActionResult === 'SUCCESS_ON_REQUEST' || workflowActionResult === 'SUCCESS_ON_RESPONSE') {
        return <Flag type="line-yellow" padding={false} text="배포 중" />;
      } else if (workflowActionResult === 'SUCCESS_ON_CALLBACK') {
        return <Flag type="green" padding={false} text="배포 완료" />;
      } else {
        return snapshotStatus;
      }
    case 'CANCEL':
      if (workflowActionResult === 'FAILURE_ON_RESPONSE' || workflowActionResult === 'FAILURE_ON_CALLBACK' || workflowActionResult === 'TIMEOUT_ON_CALLBACK') {
        return <Flag type="line-red" padding={false} width="150" text="업데이트 취소 실패" errorHover={errorHoverText} />;
      } else if (workflowActionResult === 'SUCCESS_ON_REQUEST' || workflowActionResult === 'SUCCESS_ON_RESPONSE') {
        return <Flag type="line-yellow" padding={false} width="150" text="업데이트 취소 중" />;
      } else if (workflowActionResult === 'SUCCESS_ON_CALLBACK') {
        return <Flag type="green" padding={false} text="업데이트 완료" />;
      } else {
        return snapshotStatus;
      }
    case 'ROLLBACK':
      if (snapshotStatus === 'ARCHIVED') {
        if (workflowActionResult === 'FAILURE_ON_RESPONSE' || workflowActionResult === 'FAILURE_ON_CALLBACK' || workflowActionResult === 'TIMEOUT_ON_CALLBACK') {
          return <Flag type="line-red" padding={false} text="업데이트 실패" errorHover={errorHoverText} />;
        } else if (workflowActionResult === 'SUCCESS_ON_REQUEST' || workflowActionResult === 'SUCCESS_ON_RESPONSE') {
          return <Flag type="line-yellow" padding={false} text="업데이트 중" />;
        } else {
          return snapshotStatus;
        }
      } else if (snapshotStatus === 'STAGING') {
        if (workflowActionResult === 'SUCCESS_ON_CALLBACK') {
          return <Flag type="green" padding={false} text="업데이트 완료"/>;
        } else {
          return snapshotStatus;
        }
      } else {
        return snapshotStatus;
      }
    default:
      return snapshotStatus;
  }
}

export const isFailedStatus = (workflowActionResult) => {
  return (
    workflowActionResult === 'FAILURE_ON_RESPONSE' ||
    workflowActionResult === 'FAILURE_ON_CALLBACK' ||
    workflowActionResult === 'TIMEOUT_ON_CALLBACK'
  );
};

export const getReleaseFailedBots = (botList) => {
  const isReleaseFailedSnapshot = (snapshot) => (
    snapshot.workflowActionRequest === 'RELEASE' && isFailedStatus(snapshot.workflowActionResult) && snapshot.botbuilderCancelResultCode !== 1
  );
  return botList.filter(bot => {
    return bot.snapshotList.some(snapshot => isReleaseFailedSnapshot(snapshot));
  }).map(bot => {
    const failedSnapshotId = bot.snapshotList.findLast(snapshot => isReleaseFailedSnapshot(snapshot)).snapshotId;
    return {
      botId: bot.botId,
      botName: bot.botName,
      snapshotId: failedSnapshotId,
    };
  });
}

const BB_UPDATE_ERROR_MSG_MAP = [
  { code: -1, message: "Fail: 봇 플랫폼 처리 실패" },
  { code: -2, message: "Unknown Error: NLU 처리 실패" },
  { code: -3, message: "Invalid Parameter: NLU 처리 요청의 파라미터 오류" },
  { code: -4, message: "Not Found: NLU에 모델 없음" },
  { code: -5, message: "Conflict: NLU에 모델 중복" },
  { code: -99, message: "봇 플랫폼 연동 실패" },
].reduce((map, errorObj) => {
  map.set(errorObj.code, errorObj.message);
  return map;
}, new Map());

export const getBotBuilderErrorMsg = (code) => {
  return BB_UPDATE_ERROR_MSG_MAP.get(code) ?? "콜백 타임아웃";
}

export const getBotBuilderErrorMsgGroupedByCode = (responses) => {
  const failedResponses = responses.filter(res => res.botBuilderResultCode < 0);
  if (responses.length === 1 && failedResponses.length === 1) {
    return getBotBuilderErrorMsg(failedResponses[0].botBuilderResultCode);
  }
  const failedResponsesByErrorCode = failedResponses.reduce((result, res) => {
    const { snapshotId, botBuilderResultCode } = res;
    result[botBuilderResultCode] ??= [];
    result[botBuilderResultCode].push(snapshotId);
    return result;
  }, {});

  const alertMsg = Object.entries(failedResponsesByErrorCode).reduce((msg, [code, snapshotIds]) => {
    return msg + [
      getBotBuilderErrorMsg(parseInt(code)), 
      ...snapshotIds, 
    ].join('\n') + '\n';
  }, "");

  return alertMsg;
}

export const formatMobile = (mobile) => {
  if(typeof(mobile) != "string") {
    return ""
  }

  if(mobile.length == 0) {
    return mobile
  }

  mobile = (mobile.replace(/[^0-9#]/g, ""))

  if(mobile.substring(0,1)=="#") {
    return mobile
  }

  var arrNum = new Array()
  var list = ",02,051,053,032,062,042,052,031,033,043,041,063,061,054,055,064,010,011,013,014,015,016,017,018,019,070,080,060"

  if(list.indexOf(","+mobile.substring(0,2)+",") >= 0) {
    arrNum[0] = mobile.substring(0,2)
    mobile = "0"+mobile
  } else {
    arrNum[0] = mobile.substring(0,3)
  }

  if(mobile.length >= 11) {
    arrNum[1] = mobile.substring(3,7)
    arrNum[2] = mobile.substring(7,20)
  } else {
    arrNum[1] = mobile.substring(3,6)
    arrNum[2] = mobile.substring(6,20)
  }

  var $return = ""
  $return = arrNum[0]
  if($return.length > 0 && arrNum[1].length > 0) {
    $return += "-"
  }

  $return += arrNum[1]
  if($return.length > 0 && arrNum[2].length > 0) {
    $return += "-"
  }

  $return += arrNum[2]
  if(mobile.length == 8 && mobile.substring(0,2) == "15") {
    $return = mobile.substring(0,4) + "-" + mobile.substring(4,8)
  }

  return $return
}

export const checkPWD = (pwd1, pwd2) => {
  // 8 ~ 16자 영문 소문자, 숫자, 특수문자 사용
  // 규칙
  const regex = /^(?=.*[a-z])(?=.*\d)(?=.*[@#$%^&+=!]).{8,16}$/

  if (pwd1 == '') {
    return {code: -1, msg: "비밀번호를 입력하세요"}
  }

  if (!regex.test(pwd1)) {
    return {code: -1, msg: "8 ~ 16자 영문 소문자, 숫자, 특수문자를 사용하세요"}
  }

  if (pwd2 == '') {
    return {code: -2, msg: "비밀번호 확인을 입력하세요"}
  }

  if (pwd1 != pwd2) {
    return {code: -2, msg: "비밀번호가 일치하지 않습니다"}
  }

  return {code: 0, msg: "성공"}
}

export const checkEmail = (email) => {
  var regExp = /[0-9a-zA-Z][_0-9a-zA-Z-]*@[_0-9a-zA-Z-]+(\.[_0-9a-zA-Z-]+){1,2}$/;

  //입력을 안했다면
  if(email.length == 0) {
    return {code: -1, msg: "이메일을 입력하세요."}
  }

  //데이터 형식이 맞지 않다면
  if (!email.match(regExp)) {
    return {code: -1, msg: "이메일 형식에 맞게 입력하세요."}
  } else {
    return {code: 0}
  }
}

export const checkMobile = (mobile) => {
  // 앞자리 규칙: 01 + [0, 1, 6, 7, 8, 9]
  // 중간자리규칙: 중간자리 중 앞에 2자리는 20~99 (59, 60, 61 제외)
  // ※ 전화번호 뒷자리는 0000도 가능
  var regExp1 = /^010-?([2-9]{1})([0-9]{2,3})-?([0-9]{4})$/

  // 입력을 안했다면
  if (mobile.length == 0) {
    return {code: -1, msg: "휴대폰 번호를 입력하세요."}
  }

  // 10자리보다 적을 때
  if (mobile.length < 13) {
    return {code: -1, msg: "휴대폰 번호 형식에 맞게 입력하세요."}
  }

  // 전화번호 형식으로 변환(ex. 010-2222-2222)
  mobile = formatMobile(mobile)

  // 제외 배열
  var exceptArr = ['59', '60', '61']

  // 중간자리 앞 두글자가 59, 60, 61인 경우
  if (exceptArr.includes(mobile.split('-')[1].substr(0, 2))) {
    return {code: -1, msg: "휴대폰 번호 형식에 맞게 입력하세요."}
  }

  // 데이터 형식이 맞지 않다면
  if (mobile.match(regExp1)) {
    return {code: 0}
  } else {
    return {code: -1, msg: "휴대폰 번호 형식에 맞게 입력하세요."}
  }
}

export const checkId = (id) => {
  // 영문, 숫자, 특수문자('-', '_') 정규식
  var idRegex = /^[a-zA-Z0-9_-]+$/

  //입력을 안했다면
  if (id.length == 0) {
    return {code: -1, msg: "아이디를 입력하세요."}
  }

  // 아이디 5~15자가 아닐 때
  if (id.length < 5 || id.length > 15 || !id.match(idRegex)) {
    return {code: -1, msg: "5~15자 소문자, 숫자, 특수기호(_),(-)만 사용 가능합니다."}
  }

  return {code: 0}
}

export const checkName = (name) => {
  // name 체크 정규식
  var ipRegex = /^([가-힣]{2,15})$/

  // 형식이 틀렸을 때
  if(!name.match(ipRegex)) {
    return {code: -1, msg: "이름은 2~15자의 한글만 입력 가능합니다."}
  }

  return {code: 0}
}