import styled from "@emotion/styled/macro";

import { Link } from "react-router-dom";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";

/* commmon style */
/* design scroll */
export const ScrollDefaultStyle = `
  &::-webkit-scrollbar-button:vertical:start:decrement,
  &::-webkit-scrollbar-button:vertical:start:increment {
    display: block;
    height: 0;
  }
  &::-webkit-scrollbar {
    width: 8px;
  }
  &::-webkit-scrollbar-thumb {
    background-color: #e9ecef;
    border-radius: 8px;
  }
`;

/* chk,rdo default style */
export const FormDefaultStyle = `
  display:inline-block;
  position: relative;
  vertical-align: top;
  .txt-label {
    display: flex;
    cursor: pointer;
    .icon {
      display: inline-block;
      position: relative;
      min-width: 16px;
      height: 16px;
      &:before {
        content: "";
        display: block;
        width: 16px;
        height: 16px;
        position: absolute;
        left: 0;
        box-sizing: border-box;
        border: 2px solid ${_color.gray6};
        background: ${_color.white};
      }
      &:after {
        content: "";
        display:none;
        width: 22px;
        height: 22px;
        position: absolute;
        left: -3px;
        top: 50%;
        transform: translateY(-50%);
        border: 2px solid ${_color.secondary2};
        box-sizing: border-box;
      }
    }
    .label {
      display: block;
      margin-left: 8px;
      font-size: 14px;
      line-height: 16px;
      color: ${_color.black2};
    }
  }
  label {
    &:hover {
      .icon:before {
        border-color: ${_color.secondary1};
      }
    }
    &:focus {
      .icon:after {
        display:block;
      }
    }
  }
  input {
    position: absolute;
    top: 0;
    left: 0;
    padding: 0;
    margin: 0;
    width: 16px;
    height: 16px;
    appearance: none;
    opacity: 0;
    &:focus {
      & + .txt-label {
        .icon:after {
          display:block;
        }
      }
    }
    &:disabled {
      & + .txt-label {
        .icon {
          color: ${_color.gray5};
          &:before {
            border-color: ${_color.gray7};
          }
        }
      }
    }
    &:checked {
      & + .txt-label {
        .icon:before {
          border: none;
          background-position:center center;
          background-repeat:no-repeat;
          background-color:${_color.secondary0};
        }
      }
      &:disabled {
        & + .txt-label {
          .icon:before {
            background-color: ${_color.secondary3};
          }
        }
      }
    }
  }

  /* alert */
  &.error {
    label {
      .icon:before {
        border-color: ${_color.error};
      }
    }
    input {
      &:checked {
        & + .txt-label {
          .icon:before {
            background-color: ${_color.error};
          }
        }
      }
    }

    .alert-text {
      padding-left: 20px;
      margin-top: 4px;
      font-size: 12px;
      color: ${_color.error};
      position: relative;
      &::before {
        content: "";
        width: 16px;
        height: 16px;
        position: absolute;
        left: 0;
        top: 50%;
        transform: translateY(-50%);
        background: ${_mx.svg(_svg.alertFill("C53434"))} center center no-repeat;
        background-size: contain;
      }
    }
  }
  /* alert-text */
  .alert-text {
    margin-left: 24px;
    margin-top: 6px;
    font-size: 12px;
    font-weight: 500;
    color: ${_color.gray3};
    &.disabled {
      color: ${_color.gray6};
    }
  }
  & + & {
    margin-left: 16px;
  }
`;

/* input default style */
export const InputDefaultStyle = `
  position: relative;
  width: 100%;
  .text-area {
    display: flex;
    align-items: center;
    overflow: hidden;
    background: ${_color.white};
    border: 1px solid #cfd6dd;
    border-radius: 6px;
    outline:none;
    &.focus:not(.disabled),
    &:hover:not(.disabled) {
      border-color: ${_color.secondary0};
      background: #fff;
    }
    &.disabled {
      input::placeholder,
      input, textarea {
        background-color:#E9EcEf;
        color:#9EA8B3;
      }
      textarea::placeholder {
        color: ${_color.gray5};
      }
    }
    &.error {
      border-color: ${_color.error};
    }
    input,
    textarea {
      width:100%;
      height: 100%;
      font-size: 14px;
      line-height: 24px;
      color: #272E35;
      box-sizing: border-box;
      border: 0;
      outline:none;
      background-color: transparent;
      &::-webkit-input-placeholder,
      &::placeholder {
        color: #555f6d;
      }
    }
  }
`;
/* 버튼/ 셀렉트 default style*/
export const MultiButtonDefaultStyle = `
  display:inline-block;
  position: relative;
  width: 248px;
  min-width: 0;
  > button {
    width: 100%;
    text-align: left;
    position: relative;
    border-radius: 6px;
    background: ${_color.white};
    border: 2px solid ${_color.white};
    box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
    color:#7E8B99;
    .title {
      color: ${_color.black2};
    }
    &::after {
      content: "";
      position: absolute;
      right: 14px;
      top: 50%;
      width: 20px;
      height: 20px;
      background-position:center center;
      background-repeat:no-repeat;
      background-size: contain;
    }
    &:hover {
      ${({ type }) => type === "multi"
    && "background-color: rgba(2, 47, 82, 0.06);border-color: transparent;"}
    }
    &:focus,
    &.open {
      background-color: ${_color.white};
      border-color: ${_color.secondary1};
    }
    &:disabled {
      background-color: #E9ECEF;
      border-color: #E9ECEF;
      .label,
      .title {
        color:#9EA8B3;
      }
      &:after {
        opacity : 0.5
      }
    }
    .label {
      ${_mx.ell}
      display: block;
      font-size: 14px;
      line-height: 21px;
      color: #7e8b99;
      font-weight: 400;
    }
    .title {
      ${_mx.ell}
      display: inline-block;
      width: 100%;
      font-weight: 500;
      color: ${_color.black2};
      line-height: 23px;
      vertical-align: middle;
    }
  }
`;

