import { useEffect, useRef, useState } from 'react';
import { usePopper } from 'react-popper';
import ReactDOM from 'react-dom';
import fp from 'lodash/fp';

import classnames from 'classnames';

import Checkbox from './Checkbox';

import * as S from '../../style/ElementsStyle';

/**
 * type : multi(2줄 default) | simple 한줄 (label 입력 x)
 * pagination : pagination 용 체크
 */
const Select = ({
  type = 'multi',
  title,
  pagination = false,
  label,
  multiple, // multiple 은 추후 작업 필요
  option,
  value = null,
  disabled,
  width,
  onChange = () => {},
}) => {
  const [selectValue, setSelectValue] = useState(value);
  const [isListOpen, setIsListOpen] = useState(false);
  const [selectedArray, setSelectedArray] = useState([]);
  const [selectedTitle, setSelectedTitle] = useState([]);

  const selectRef = useRef();
  const [referenceElement, setReferenceElement] = useState(null);
  const [popperElement, setPopperElement] = useState(null);
  const { styles, attributes } = usePopper(referenceElement, popperElement, {
    placement: 'bottom-end',
    modifiers: [
      {
        name: 'offset',
        options: {
          offset: [0, 2],
        },
      },
    ],
  });

  const listOpenHandler = () => {
    if (multiple) {
      if (isListOpen) {
        selectedTitle.length > 0
          ? setSelectValue(selectedTitle.join(', '))
          : setSelectValue('선택하세요.');
      }
    }
    setIsListOpen(!isListOpen);
  };

  const valueHandler = (id, title) => {
    setSelectValue(id);
    setIsListOpen(false);
    onChange(id, title);
  };

  const checkCall = (e) => {
    if (e.target.checked) {
      setSelectedArray([...selectedArray, e.currentTarget.dataset.id]);
      setSelectedTitle([...selectedTitle, e.currentTarget.labels[0].innerText]);
      onChange(
        [...selectedArray, e.currentTarget.dataset.id],
        [...selectedTitle, e.currentTarget.labels[0].innerText]
      );
    } else {
      setSelectedArray(selectedArray.filter((i) => i !== e.currentTarget.dataset.id));
      setSelectedTitle(selectedTitle.filter((i) => i !== e.currentTarget.labels[0].innerText));
      onChange(
        selectedArray.filter((i) => i !== e.currentTarget.dataset.id),
        selectedTitle.filter((i) => i !== e.currentTarget.labels[0].innerText)
      );
    }
  };

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (selectRef.current && !selectRef.current.contains(e.target)) {
        setIsListOpen(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  return (
    <S.Select type={type} disabled={disabled} ref={selectRef} pagination={pagination} width={width}>
      <button
        type="button"
        className={classnames({ open: isListOpen, selected: selectValue })}
        onClick={listOpenHandler}
        disabled={disabled}
        ref={setReferenceElement}
      >
        {label && <span className="label">{label}</span>}
        {/* <span className="title">
          {value && !fp.isEmpty(option) ? (
            <span className="title">{fp.find((item) => item.id === value, option)?.title} </span>
          ) : (
            <span className="title">{title} </span>
          )}
        </span> */}
        {(value || title) && (
          <span className="title">
            {value && !fp.isEmpty(option)
              ? fp.find((item) => item.id === value, option)?.title
              : title}
          </span>
        )}
      </button>
      {ReactDOM.createPortal(
        <>
          {isListOpen && (
            <S.SelectOption
              ref={setPopperElement}
              pagination={pagination}
              style={{ ...styles.popper, width: referenceElement.offsetWidth }}
              {...attributes.popper}
            >
              {option?.map((option, index) => {
                return multiple ? (
                  <li key={option.id}>
                    <Checkbox
                      id={option.id}
                      callback={checkCall}
                      defaultChecked={selectedArray.includes(option.id) ? true : false}
                    >
                      {option.title}
                    </Checkbox>
                  </li>
                ) : (
                  <li key={option.id}>
                    <button
                      type="button"
                      className={classnames({ on: option.id === value })}
                      onClick={() => {
                        valueHandler(option.id, option.title, index);
                      }}
                    >
                      {option.title}
                    </button>
                  </li>
                );
              })}
            </S.SelectOption>
          )}
        </>,
        document.getElementById('select-root')
      )}
    </S.Select>
  );
};

export default Select;
