import { useState } from 'react';
import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';
import TextCaution from '../common/TextCaution';

const Textarea = ({
  height,
  isDelete = false,
  valueError = false,
  valueSuccess = false,
  placeholder,
  id,
  disabled = false,
  readOnly,
  onChange,
  onRemove = () => {},
  errorMessage,
  successMessage,
  children,
  value,
  count,
  inputCount,
  maxLength = 100,
  width
}) => {
  const [isFocus, setIsFocus] = useState(false);
  const onFocus = () => {
    setIsFocus(true);
  };
  const onBlur = () => {
    setIsFocus(false);
  };
  return (
    <S.Textarea error={valueError} success={valueSuccess} height={height} width={width} isDelete={isDelete}>
      <div
        className={classnames('text-area', {
          error: valueError,
          success: valueSuccess,
          disabled: disabled,
          focus: isFocus,
        })}
      >
        <textarea
          placeholder={placeholder}
          id={id}
          disabled={disabled}
          readOnly={readOnly}
          onChange={onChange}
          onFocus={onFocus}
          onBlur={onBlur}
          value={value}
          maxLength={maxLength}
        >
          {children}
        </textarea>
        {isDelete && (
          <button type="button" className="btn-txt-delete" onClick={() => onRemove()}>
            <span className="hidden">삭제</span>
          </button>
        )}
      </div>
      {valueError && <TextCaution cautionType="error">{errorMessage}</TextCaution>}
      {valueSuccess && <TextCaution cautionType="success">{successMessage}</TextCaution>}
      {count && 
        <div className='right-area'>
          <span className="count" style={{fontSize: '14px', color: '#7e8b99'}}>{inputCount ? inputCount : '0'}/{maxLength}</span>
        </div>
      }
    </S.Textarea>
  );
};

export default Textarea;
