import { useState } from "react";
import GrayBox from "components/common/GrayBox";
import TextField from "components/elements/TextField";
import FormItem from "components/common/FormItem";
import Table from "components/common/Table";
import Select from "components/elements/Select";
import Textarea from "components/elements/Textarea";
import Button from "components/elements/Button";
import SimulationSearchPopup from "./SimulationSearchPopup";
import LayerPopup from 'components/common/LayerPopup';


const EvaluationSheetSimulation = () => {
  const [openPopup, setOpenPopup] = useState(false);
  return (
    <>
      {openPopup && //평가 항목 시뮬레이션 불러오기 팝업
        <LayerPopup
          size=""
          title={'상담사 검색'}
          customWidth={1200}
          open={openPopup}
          onClose={() => setOpenPopup(false)}
        >
          <SimulationSearchPopup />
        </LayerPopup>
      }
      <div className="custom-fix-layout">
        <p className="custom-sub-title">AI Agent 선택</p>
        <Select
          option={[]}
          type={'simple'}
          width={388}
          title={'선택'}
          onChange={() => { console.log('select!') }}
        />
      </div>

      {/* 항목정보 */}
      <div className="custom-fix-container">
        <GrayBox direction={"column"}>
          <FormItem label={"평가 항목 명"} marginB={8}>
            <TextField
              width={561}
              disabled={true}
            />
          </FormItem>
          <FormItem label={"평가 항목 설명"} marginB={8}>
            <TextField
              width={561}
              disabled={true}
            />
          </FormItem>
          <FormItem label={"항목 배점"}>
            <TextField
              width={223}
              disabled={true}
            />
          </FormItem>
        </GrayBox>

        {/* 세부항목 테이블 */}
        <div style={{ borderBottom: '1px solid #d7d9f3', marginTop: '24px' }}>
          <Table className="active" fixedHeader={true} height="260" hover={false} round={false} borderBottom={false}>
            <table className="hover">
              <caption>평가 세부 항목 정보</caption>
              <colgroup>
                <col width="716px" />
                <col width="190px" />
                <col width="190px" />
              </colgroup>
              <thead>
                <tr>
                  <th className="t-left left-padding">세부 항목</th>
                  <th className="t-left left-padding">세부 항목별 점수</th>
                  <th className="t-left left-padding">시뮬레이션 결과</th>
                </tr>
              </thead>
              <tbody>
                <tr height='54px'>
                  <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                    <TextField
                      width={680}
                      disabled={true}

                    />
                  </td>
                  <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                    <TextField
                      width={160}
                      disabled={true}
                    />
                  </td>
                  <td className="t-left left-padding" style={{ borderTop: '1px solid transparent' }}>
                    <TextField
                      width={160}
                    />
                  </td>
                </tr>
              </tbody>
            </table>
          </Table>
        </div>

        {/* 상담 스크립트 */}
        <div className="script-layout">
          <div className="titles">
            <p className="custom-sub-title">상담 스크립트</p>
            <Button label="불러오기" className="secondary wide" onClick={() => {setOpenPopup(true)}} />
          </div>
          <Textarea width={1096} height={136} />
        </div>  

      </div>
    </>
  )
};

export default EvaluationSheetSimulation;