import { useCallback, useEffect, useRef, useState } from 'react';
import ReactDOM from 'react-dom';

import { usePopper } from 'react-popper';
import DatePicker from 'react-datepicker';
import { ko } from 'date-fns/locale';
import classnames from 'classnames';

import ButtonList from './ButtonList';

import 'react-datepicker/dist/react-datepicker.css';
import '../../style/Calendar.css';

import * as S from '../../style/ElementsStyle';
import dayjs from 'dayjs';
// import weekday from 'dayjs/plugin/weekday';
import fp from 'lodash/fp';
import useOutsideClick from 'hooks/useOutsideClick';

// dayjs.extend(weekday);

const modifiers = [
  {
    name: 'flip',
    options: {
      allowedAutoPlacements: ['top', 'bottom'],
    },
  },
  {
    name: 'offset',
    options: {
      offset: [0, 1],
    },
  },
];

/**
 * type : multi(2줄 default) | simple 한줄 (label 입력 x)
 */
const DateRange = ({
  type = 'multi',
  disabled,
  startDate,
  endDate,
  label,
  rangeCal = false,
  multiCal = false,
  yearCal = false,
  isWeek = false,
  format = 'YYYY-MM-DD',
  utilMenu = false,
  headFixed = false,
  serviceCalendar = false,
  onChange,
  border,
  disableUnit = 'day', // 날짜 제한 단위 , day, week, month, year
  disableNum, // 날짜 제한 숫자
  ...rest
}) => {
  const [selectedStartDate, setSelectedStartDate] = useState(startDate);
  const [selectedEndDate, setSelectedEndDate] = useState(endDate);

  const [referenceElement, setReferenceElement] = useState(null);
  const [popperElement, setPopperElement] = useState(null);
  const { styles, attributes, update } = usePopper(referenceElement, popperElement, {
    placement: 'top-end',
    modifiers: [...modifiers],
  });

  const [isOpen, setIsOpen] = useState(false); //팝업 오픈
  const [isAlert, setIsAlert] = useState(false); // 경고 문구
  const [isDisableConfirm, setIsDisableConfirm] = useState(false); // 적용 버튼
  const [initStartDate, setInitStartDate] = useState(false); // 경고 문구
  const [initEndDate, setInitEndDate] = useState(false); // 경고 문구

  const wrapperRef = useRef(null);
  const excludedRef = useRef(null); // 제외할 영역의 ref
  const excludedRef2 = useRef(null); // 제외할 영역의 ref

  // 달력 바깥쪽 클릭
  const onOutsideClick = useCallback(() => {
    setSelectedStartDate(initStartDate);
    if (type === 'simple') {
      onChange(initStartDate);
    } else {
      onChange([initStartDate, initEndDate]);
      setSelectedEndDate(initEndDate);
    }
    setIsOpen(false);
  }, [initStartDate, initEndDate]);

  useOutsideClick(wrapperRef, onOutsideClick, excludedRef, excludedRef2);

  const calendarCtrlHandler = (i) => {
    utilMenuHandler(i);
  };

  // background click disabled 231115
  const backgroundDimmedAdd = function () {
    const div = document.querySelector('.calendar-dimmed');
    const area = document.querySelectorAll('.date-picker-area');
    area.forEach((item) => {
      item.style.zIndex = '5000';
    });
    div.style.display = 'block';
  };
  const backgroundDimmedRemove = function () {
    const div = document.querySelector('.calendar-dimmed');
    const area = document.querySelectorAll('.date-picker-area');
    area.forEach((item) => {
      item.style.zIndex = 'initial';
    });
    div.style.display = 'none';
  };

  const utilMenuHandler = (dates) => {
    const date = new Date();
    switch (dates) {
      case 0:
        handleChange([date, date]);
        break;
      case 1:
        const yesterDay = new Date(date.setDate(date.getDate() - 1));
        handleChange([yesterDay, yesterDay]);
        break;
      case 2:
        const monday = dayjs(date).startOf('week').$d;
        // const sunday = dayjs(date).endOf('week').add(1, 'day').$d;
        // const diffDate = dayjs(sunday).diff(date, 'day');
        handleChange([monday, date]);
        break;
      case 3:
        // handleChange([
        //   new Date(new Date().getFullYear(), new Date().getMonth(), 1),
        //   new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0),
        // ]);
        handleChange([new Date(new Date().getFullYear(), new Date().getMonth(), 1), date]);
        break;
      case 4:
        handleChange([new Date(new Date().setDate(new Date().getDate() - 6)), date]);
        break;
      default:
        handleChange([new Date(new Date().setDate(new Date().getDate() - 29)), date]);
        break;
    }

    setIsOpen(!isOpen);
  };
  const cancelHandler = (initStartDate, initEndDate) => {
    setSelectedStartDate(initStartDate);
    if (type === 'simple') {
      onChange(initStartDate);
    } else {
      onChange([initStartDate, initEndDate]);
      setSelectedEndDate(initEndDate);
    }

    setIsOpen(!isOpen);
  };

  const confirmHandler = (isMultiCal) => {
    if (isMultiCal) {
      onChange([selectedStartDate, selectedEndDate]);
    }
    setIsOpen(!isOpen);
  };
  const CalendarTobButtonList = [
    { title: '오늘' },
    { title: '어제' },
    { title: '이번 주' },
    { title: '이번 달' },
    { title: '최근 7일' },
    { title: '최근 30일' },
  ];

  const calendarButtons = [
    {
      label: '취소',
      className: 'secondary',
      onClick: () => cancelHandler(initStartDate, initEndDate),
    },
    {
      label: '적용',
      disabled: isDisableConfirm,
      className: 'primary',
      onClick: () => confirmHandler(multiCal),
    }, // 231103 텍스트 수정
  ];

  const dateFormat = (date, format) => {
    if (date === null || date === undefined) {
      return '';
    }
    const year = date?.getFullYear();
    const month = date?.getMonth() + 1;
    const day = date?.getDate();
    let dateText = '';
    if (format === 'YYYY-MM') {
      dateText = `${year}-${month >= 10 ? month : '0' + month}`;
    } else if (format === 'YYYY') {
      dateText = `${year}`;
    } else {
      dateText = `${year}-${month >= 10 ? month : '0' + month}-${day >= 10 ? day : '0' + day}`;
    }
    return dateText;
  };

  const renderMonthContent = (month) => {
    return <span>{`${(month + 1).toString().padStart(2, 0)}월`}</span>;
  };

  const handleChange = (dates, e) => {
    if (rangeCal) {
      const [start, end] = dates;

      // 주별 달력
      if (isWeek) {
        const monday = end ? start : dayjs(start).startOf('week').$d;
        const sunday = end ? dayjs(end).endOf('week').$d : end;

        setSelectedStartDate(monday);
        setSelectedEndDate(sunday);
        onChange([monday, sunday]);

        // 조회 기간 제한
        const diffDate = dayjs(sunday).diff(monday, disableUnit);
        setIsAlert(diffDate > disableNum - 1 ? true : false);
        setIsDisableConfirm(diffDate > disableNum - 1 || !sunday ? true : false);
        return;
      }

      setSelectedStartDate(start);
      setSelectedEndDate(end);
      onChange(dates);

      // 조회 기간 제한
      const diffDate = dayjs(end).diff(start, disableUnit);
      setIsAlert(diffDate > disableNum - 1 ? true : false);
      setIsDisableConfirm(diffDate > disableNum - 1 || !end ? true : false);
    } else if (multiCal) {
      if (e.target.closest('.start-calendar')) {
        setSelectedStartDate(dates);
      } else {
        const isBefore = dayjs(dates).isBefore(selectedStartDate);
        setSelectedEndDate(isBefore ? selectedStartDate : dates);
        if (isBefore) return;

        const diffDate = dayjs(dates).diff(selectedStartDate, disableUnit);
        setIsAlert(diffDate > disableNum - 1 ? true : false);
        setIsDisableConfirm(diffDate > disableNum - 1 || !dates ? true : false);
      }
    } else {
      setSelectedStartDate(dates);
      onChange(dates);
    }
  };
  //
  const calendarOpenHandler = (e) => {
    e.preventDefault();
    setIsOpen(!isOpen);
    update();
    if (!isOpen) return;
    setSelectedStartDate(initStartDate);
    if (type === 'simple') {
      onChange(initStartDate);
    } else {
      onChange([initStartDate, initEndDate]);
      setSelectedEndDate(initEndDate);
    }
  };

  const getAlertText = (disableUnit, disableNum) => {
    const cond = fp.cond([
      [fp.matches('day'), fp.constant('일')],
      [fp.matches('month'), fp.constant('개월')],
      [fp.matches('week'), fp.constant('주')],
      [fp.matches('year'), fp.constant('년')],
      [fp.T, fp.constant('일')],
    ]);

    return `조회 기간은 최대 ${disableNum}${cond(disableUnit)}까지만 가능합니다.`;
  };

  // const [hoveredDate, setHoveredDate] = useState(null);

  // const renderDayContents = (day, date) => {
  //   let isInRange = false;
  //   if (hoveredDate) {
  //     if (hoveredDate) {
  //       const nextDay = new Date(hoveredDate);
  //       nextDay.setDate(nextDay.getDate() + 2); // 이틀 후의 날짜로 설정
  //       const monday = dayjs(hoveredDate).startOf('week').$d;
  //       const sunday = dayjs(hoveredDate).endOf('week').$d;
  //       // const diffDate = dayjs(sunday).diff(date, 'day');
  //       isInRange = date >= monday && date <= sunday; // 호버된 날짜와 이틀 후 사이의 날짜인지 확인
  //     }

  //     // isInRange = date >= hoveredDate && date <= nextDay; // 호버된 날짜와 이틀 후 사이의 날짜인지 확인
  //   }

  //   return (
  //     <div
  //       onMouseEnter={() => setHoveredDate(date)}
  //       style={{ backgroundColor: isInRange ? 'lightblue' : 'transparent' }}
  //     >
  //       {day}
  //     </div>
  //   );
  // };

  // 월달력 첫번째 달력 년도 변경 콜백 함수
  const handleChangeFirstMonthDatePickerYear = (date, selectedDate) => {
    const datePickerYear = dayjs(date).year();
    const selectedDateYear = dayjs(selectedDate).year();
    const startCalendars = document.querySelectorAll('.start-calendar');

    if (datePickerYear === selectedDateYear) {
      // 보이는 년도와 시작 날짜 년도가 같으면 달력에 체크 표시
      [...startCalendars].map((c) => {
        const selectElement = c.querySelector('.react-datepicker__month-text--keyboard-selected');
        selectElement && selectElement.classList.remove('off');
      });
    } else {
      // 보이는 년도와 시작 날짜 년도가 다르면 달력에 체크 미표시
      [...startCalendars].map((c) => {
        const selectElement = c.querySelector('.react-datepicker__month-text--keyboard-selected');
        selectElement && selectElement.classList.add('off');
      });
    }
  };

  // 월달력 두번째 달력 년도 변경 콜백 함수
  const handleChangeSecondMonthDatePickerYear = (date, selectedDate) => {
    const datePickerYear = dayjs(date).year();
    const selectedDateYear = dayjs(selectedDate).year();
    const endCalendars = document.querySelectorAll('.end-calendar');

    if (datePickerYear === selectedDateYear) {
      // 보이는 년도와 종료 날짜 년도가 같으면 달력에 체크 표시
      [...endCalendars].map((c) => {
        const selectElement = c.querySelector('.react-datepicker__month-text--keyboard-selected');
        selectElement && selectElement.classList.remove('off');
      });
    } else {
      // 보이는 년도와 종료 날짜 년도가 다르면 달력에 체크 미표시
      [...endCalendars].map((c) => {
        const selectElement = c.querySelector('.react-datepicker__month-text--keyboard-selected');
        selectElement && selectElement.classList.add('off');
      });
    }
  };

  useEffect(() => {
    // isOpen ? backgroundDimmedAdd() : backgroundDimmedRemove();

    if (!isOpen) return;
    setInitStartDate(startDate);
    setInitEndDate(endDate);
  }, [isOpen]);

  useEffect(() => {
    if (isOpen) backgroundDimmedAdd();
    else backgroundDimmedRemove();
  }, [startDate, endDate, isOpen]);

  return (
    <S.DatePicker>
      <S.DatePickerInput type={type} className="date-picker-area" ref={excludedRef} border={border}>
        <button
          type="button"
          className={classnames({ open: isOpen })}
          onClick={calendarOpenHandler}
          disabled={disabled}
          ref={setReferenceElement}
        >
          {label && <span className="label">조회 기간</span>}
          <span className="title">
            {type === 'simple' || yearCal
              ? `${dateFormat(selectedStartDate, format)}`
              : `${dateFormat(selectedStartDate, format)} ~ ${dateFormat(selectedEndDate, format)}`}
          </span>
        </button>
      </S.DatePickerInput>

      {ReactDOM.createPortal(
        <S.DateRange
          isOpen={isOpen}
          ref={setPopperElement}
          style={styles.popper}
          {...attributes.popper}
          className={classnames(
            'date-picker-area',
            { 'head-fixed': headFixed },
            { 'service-calendar': serviceCalendar }
          )}
        >
          {isOpen ? (
            <S.CalendarArea ref={wrapperRef}>
              <S.CalendarInner>
                {multiCal ? (
                  <>
                    <DatePicker
                      {...rest}
                      selected={selectedStartDate}
                      calendarClassName="start-calendar"
                      // calendarStartDay={1}
                      shouldCloseOnSelect={false}
                      inline
                      onChange={handleChange}
                      renderMonthContent={renderMonthContent}
                      locale={ko}
                      onYearChange={(date) =>
                        handleChangeFirstMonthDatePickerYear(date, selectedStartDate)
                      }
                      showMonthYearPicker
                    />
                    <DatePicker
                      {...rest}
                      selected={selectedEndDate}
                      calendarClassName="end-calendar"
                      // calendarStartDay={1}
                      shouldCloseOnSelect={false}
                      inline
                      onChange={handleChange}
                      renderMonthContent={renderMonthContent}
                      locale={ko}
                      onYearChange={(date) =>
                        handleChangeSecondMonthDatePickerYear(date, selectedEndDate)
                      }
                      showMonthYearPicker
                    />
                  </>
                ) : (
                  <DatePicker
                    {...rest}
                    startDate={selectedStartDate}
                    endDate={selectedEndDate}
                    calendarClassName="start-calendar"
                    // calendarStartDay={1}
                    openToDate={
                      rest.selectsRange
                        ? dayjs(initEndDate).subtract(1, 'month').$d
                        : dayjs(initStartDate).$d
                    }
                    shouldCloseOnSelect={false}
                    inline
                    onChange={handleChange}
                    locale={ko}
                    // renderDayContents={renderDayContents}
                  />
                )}
              </S.CalendarInner>

              <div className="calendar-btm">
                {isAlert ? (
                  <div className="calendar-toast">
                    <p>{getAlertText(disableUnit, disableNum)}​</p>
                  </div>
                ) : null}
                <ButtonList buttonList={calendarButtons} ulClass="btn-area" />
              </div>
            </S.CalendarArea>
          ) : null}
          {utilMenu && (
            <S.CalendarUtilMenu className="calendar-util" ref={excludedRef2}>
              <ul>
                {CalendarTobButtonList.map((btn, index) => {
                  return (
                    <li key={`calendar-${index}`}>
                      <button
                        type="button"
                        onClick={() => calendarCtrlHandler(index)}
                        // className={termIndex === index ? 'active' : ''}
                      >
                        {btn.title}
                      </button>
                    </li>
                  );
                })}
              </ul>
            </S.CalendarUtilMenu>
          )}
        </S.DateRange>,
        document.getElementById('calendar-root')
      )}
    </S.DatePicker>
  );
};

export default DateRange;
