import { useState } from "react";
import Title from "components/common/Title";
import { SubTableTitle, CountingTitle } from "style/AutoQAStyle";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import Pagination from 'components/common/Pagination';
import LayerPopup from "components/common/LayerPopup";
import MenuManagementPopup from "./popups/MenuManagementPopup";
import NoData from "components/common/NoData";

const MenuManagementPage = () => {
	const [openPopup, setPopupOpen] = useState(false); // 사용자명 검색 팝업
	const [popupType, setPopupType] = useState(''); // 카테고리 타입

	const onHandlePopup = (type) => {
		setPopupOpen(true);
		setPopupType(type)
	};

	return (
		<>
			{openPopup && // 메뉴생성 , 상세 팝업 ()
				<LayerPopup
					title={`메뉴 ${popupType === 'add' ? '생성' : '상세'}`}
					customWidth={600}
					open={openPopup}
					onClose={() => setPopupOpen(false)}
				>
					<MenuManagementPopup type={popupType} />
				</LayerPopup>
			}
			<Title title="메뉴 목록" icon="settings" />
			<SubTableTitle>
				<CountingTitle/>
				<ButtonList buttonList={[
					{ label: '등록', className: 'primary left-plus', onClick: () => {onHandlePopup('add') } },
				]} />
			</SubTableTitle>
			<Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
				<table>
					<colgroup>
						<col width="240px" />
						<col width="260px" />
						<col width="260px" />
						<col width="180px" />
						<col width="420px" />
						<col width="220px" />
					</colgroup>
					<thead>
						<tr>
							<th>분류</th>
							<th>대분류 아이디</th>
							<th>메뉴명</th>
							<th>메뉴 순서</th>
							<th className="t-left left-padding">URL</th>
							<th>등록일시</th>
						</tr>
					</thead>
					<tbody>
						{/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={6}><NoData txt={'데이터가 없습니다'}/></td></tr> 
            */}
						{Array.from({ length: 10 }).map((_, index) => (
							<tr key={index} onClick={() => onHandlePopup('detail') }>
								<td>대분류</td>
								<td>management</td>
								<td>대시보드</td>
								<td>1</td>
								<td className="t-left left-padding">main/management/scorecard​</td>
								<td>2024-11-28 12:00​​​</td>
							</tr>
						))}
					</tbody>
				</table>
			</Table>
			<Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
		</>
	);
}

export default MenuManagementPage;