import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';

const Radio = ({
  id,
  type = 'radio',
  color,
  radioError,
  name,
  defaultChecked,
  checked,
  disabled,
  onChange = () => {},
  children,
  hiddenLabel = false,
  alert,
  helper,
  botIcon,
  icoIMG
}) => {
  return (
      <S.Radio className={classnames('box-radio', { error: radioError })} color={color} type={type}>
        <label>
          {botIcon && <span className='bot-ico'>{icoIMG}</span>}
          <input
              type="radio"
              id={id}
              name={name}
              checked={checked}
              disabled={disabled}
              defaultChecked={defaultChecked}
              onChange={(e) => {
                onChange(e.target.id);
              }}
          />
          <span className="txt-label">
          <i className="icon"></i>
          <em className={`label ${hiddenLabel ? 'hidden' : ''}`}>{children}</em>
        </span>
        </label>
        {helper && <div className="alert-text">{alert}</div>}
      </S.Radio>
  );
};

export default Radio;