import { useState } from 'react';
import { useLocation } from 'react-router-dom';
import * as S from '../../style/LayoutStyle';
import MenuFooter from '../common/MenuFooter';
import MenuList from '../common/MenuList';
import Heading from '../elements/Heading';
import LnbToggleButton from '../elements/LnbToggleButton';

const DashboardAside = ({ menuList }) => {
  const [isAsideExpand, setIsAsideExpand] = useState(true);
  const location = useLocation();

  function asideAreaHandler() {
    setIsAsideExpand(!isAsideExpand);
  }

  return (
    <S.DashbordAside className={isAsideExpand ? 'expand' : 'collapse'}>
      <S.DashbordInner>
        <S.DashbordScroll>
          <Heading className={isAsideExpand ? 'expand' : 'collapse'}></Heading>
          <MenuList
            currentPath={location.pathname}
            menuList={menuList}
            className={isAsideExpand ? 'expand' : 'collapse'}
          />
          {isAsideExpand && <MenuFooter />}
        </S.DashbordScroll>
        <LnbToggleButton
          btnClick={asideAreaHandler}
          className={isAsideExpand ? 'expand' : 'collapse'}
        ></LnbToggleButton>
      </S.DashbordInner>
    </S.DashbordAside>
  );
};

export default DashboardAside;
