import styled from "@emotion/styled/macro";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";
import * as S from "./ElementsStyle";

export const RetrainingFallback = styled.div`
  ${S.Table} {
    ${S.ButtonList} {
      justify-content: center;
    }
    ${S.Button} {
      display: inline-flex;
    }
  }
  ${S.Button} {
    &.play-new, 
    &.pauseNew {
      min-width:44px;
    }
    &.pauseNew {
      &::before {
        background: ${_mx.svg(_svg.pauseStop("272e35"))} center center no-repeat;
      }
    }
  }

  .in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 52px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}
	}
`;

const PopupFallbackStyle = `
  .search-wrap {
    display: flex;
    flex-direction: column;
    gap: 16px;
    .search-head,
    .search-list {
      border-radius: 6px;
      border: 1px solid #cfd6dd;
    }

    .search-head {
      position: relative;
      height: 40px;
      padding: 8px 16px 8px 40px;
      input[type=text] {
        border: 0 none;
        width: 100%;
        height: 100%;
      }
      .btn-search {
        position: absolute;
        top: 8px;
        left: 12px;
        width: 20px;
        height: 20px;
        background: ${_mx.svg(_svg.search("555F6D"))} center center no-repeat;
      }
    }
    
    .search-list {
      ${S.ScrollDefaultStyle};
      overflow-y: auto;
      height: 280px;
      li {
        height: 36px;
        & + li { border-top: 1px solid #cfd6dd; }

        .btn-list-item {
          width: 100%;
          height: 100%;
          padding: 0 20px;
          text-align: left;
          color: #272E35;
          font-size: 14px;
          font-weight: 400;
          line-height: 20px;

          &:hover,
          &:focus {
            background-color: rgba(215, 217, 243, 0.50);
          }
          .search-text {
            color: #272E35;
            font-size: 15px;
            font-weight: 600;
            line-height: 24px;
          }
        }
      }
    }
  }

  .line-chat {
    display:flex;
    position:relative;
    &:before {
      content:'';
      display:block;
      position:absolute;
      top:50%;
      left: 0;
      right: 0;
      width: 100%;
      height:1px;
      background-color: rgba(92, 95, 214, 0.20);
    }
    .line-inner {
      position:relative;
      padding:0 8px;
      background:#fff;
      margin:0 auto;
      span {
        display:block;
        min-width:88px;
        height:28px;
        padding:0 10px;
        border-radius:14px;
        color: #39288A;
        font-size: 14px;
        font-weight: 400;
        line-height: 28px;
        background-color: rgba(91.81, 95.29, 213.92, 0.10);;
        text-align:center;
      }
    }
    &.chat-end {
      margin-top:8px;
    }
  }

  ${S.LayerPopupBtns} {
    .left-area {
      button {min-width: auto}
    }
  }
`

export const PopupFallbackNewChoice = styled.div`
  ${PopupFallbackStyle}
`;

export const PopupFallbackProcessDetail = styled.div`

`;

export const PopupFallbackProcessDetailSecond = styled.div`
  ${PopupFallbackStyle}
`;

export const PopupFallbackView = styled.div`
  display: ${({open}) => open ? 'block' : 'none'};
  position: fixed;
  z-index: 4999;
  inset: 0px;
  .dim {
    position: fixed;
    z-index: 5000;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
  }
  .popup-fallback-view {
    display: flex;
    align-items: center;
    justify-content: right;
    height: 100%;
    margin-right:50px;
  }
  .pop-inner {
    overflow: hidden;
    position: relative;
    width:498px;
    border-radius: 8px;
    z-index: 6000;
    background: #fff;
    flex-shrink: 0;
    filter: drop-shadow(0px 1px 2px rgba(0,0,0, 0.1));
  }
  .fallback-header {
    display:flex;
    align-items:center;
    height:80px;
    padding:0 32px;
    background:${_color.white};
    h2 {
      display:flex;
      align-items:center;
      gap:0 12px;
      color: ${_color.black2};
      font-size: 20px;
      font-weight: 600;
      line-height: 32px;
      &:before {
        content:'';
        display:block;
        width:32px;
        height:32px;
        background:rgba(156, 163, 175, 0.1) ${_mx.svg(_svg.comment)} center no-repeat;
        border-radius:50%;
      }
    }
  }
  .fallback-content {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    height: 100%;
    max-height: calc(100vh - 160px);
    .fallback-inner {
      height:763px;
    }
  }
  .btn-fallback-close {
    display: block;
    position: absolute;
    right: 30px;
    top: 24px;
    width: 32px;
    height: 32px;
    background: ${_mx.svg(_svg.close)} center no-repeat;
  }
  ${S.ChatElementWrap} {
    border-top:0;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }
`
