import React, { useRef, useEffect, useState } from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import * as S from '../../style/ChartStyle';
import { BigDoughnutContainer } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(ArcElement, Tooltip, Legend);

const RatioDoughnutChartBig = ({
  title,
  rate,
  labels,
  datas,
  colors = ['#5C5FD6', '#9D9FE6', '#F47356'],
  width = 300,
  height = 300,
  boldTitle = '',
  twoline = false,
  legendShowIs = true,
  innerW,
  flexIs,
}) => {
  const chartRef = useRef(null); // Chart.js 인스턴스 참조
  const legendContainer = useRef(null); // Legend 컨테이너 참조
  const [legendItems, setLegendItems] = useState([]);
  const [, forceUpdate] = useState(0);

  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  useChartResolution(chartRef);

  const data = {
    labels,
    datasets: [
      {
        data: datas,
        backgroundColor: colors,
        borderColor: colors,
        hoverBackgroundColor: colors,
        hoverBorderColor: colors,
        borderWidth: 0,
        cutout: '60%',
      },
    ],
  };

  const options = {
    plugins: {
      datalabels: { display: false }, // 그래프 위 수치 표시 비활성화 
      legend: {
        display: false, // Chart.js 기본 legend 숨기기
      },
      tooltip: {
        callbacks: {
          afterLabel: (tooltipItem) => {
            const total = tooltipItem.dataset.data.reduce((sum, item) => sum + Number(item), 0);
            const percent = Math.round((tooltipItem.raw / total) * 100);
            return `(${percent}%)`;
          },
        },
      },
    },
  };

  // Chart.js 인스턴스에서 Legend 항목 가져오기
  useEffect(() => {
    if (chartRef.current) {
      const chart = chartRef.current;
      const items = chart.legend.legendItems || [];

      setLegendItems(items);
    }
  }, [datas, labels, colors]); // 데이터 변경 시에만 재생성

  const toggleVisibility = (index) => {
    if (chartRef.current) {
      const chart = chartRef.current;
      chart.toggleDataVisibility(index);
      chart.update();
      forceUpdate((prev) => prev + 1);
    }
  };

  const justifyContentValue =
  !boldTitle && title
    ? 'space-between'
    : boldTitle && !title
    ? ''
    : !boldTitle && !title
    ? 'end'
    : '';


  return (
    <BigDoughnutContainer flexIs={flexIs} style={{justifyContent:justifyContentValue}}>
      {boldTitle && <h5>{boldTitle}</h5>}
      {title && <p className="title">{title}</p>}
      <div className="inner" style={{ width: innerW ? innerW : 'auto' }}>
        <S.RatioDoughnutCanvas width={width} height={height}>
          {rate && <span className="rate">{rate}</span>}
          <Doughnut
            ref={chartRef} // Chart.js 인스턴스 참조
            data={data}
            options={options}
          />
        </S.RatioDoughnutCanvas>
        {legendShowIs && (
          <div ref={legendContainer} className={`legend ${twoline ? 'small' : ''}`}>
            <ul>
              {legendItems.map((item, index) => {
                const chart = chartRef.current;
                const isHidden = chart ? !chart.getDataVisibility(index) : false;

                return (
                  <li key={item.text} onClick={() => toggleVisibility(index)}>
                    <span
                      style={{
                        backgroundColor: item.fillStyle,
                        borderColor: item.strokeStyle,
                        borderWidth: item.lineWidth,
                      }}
                    />
                    <p
                      style={{
                        color: item.fontColor || '#000',
                        textDecoration:isHidden ? 'line-through' : 'none',
                    }}
                    >
                      {item.text}
                    </p>
                  </li>
                );

              })}
            </ul>
          </div>
        )}
      </div>
    </BigDoughnutContainer>
  );
};

export default RatioDoughnutChartBig;
