import classNames from 'classnames';

import * as S from '../../style/ElementsStyle';
/*
	type : 채팅타입, bot | tester | customer 

*/
const ChatElement = ({
  item,
  botClick = () => {},
  isNotPlay = true,
  setPlay = () => {},
  isPlay = false,
  isRealTime = false,
}) => {
  // const [play, setPlay] = useState(false);
  // const onClick = () => {
  //   setPlay(!play);
  // };
  const chatType = item.participant_type === 'counselor' ? '상담원' : item.participant_type === 'tester' ? '테스터' : '고객';
  return (
    <S.ChatElement
      type={item.participant_type}
      style={item.participant_type === 'counselor' && !isNotPlay ? { cursor: 'default' } : {}}
      onClick={item.participant_type === 'counselor' ? botClick : undefined}
    >
      {' '}
      {/* 231106 이벤트 영역 변경 */}
      <div className="thumb-chat">
        <em className="name">{chatType}</em>
      </div>
      <div className="bubble-chat">
        <div className="bubble-inner">
          <div
            className={classNames('bubble', {
              fallback: item.fallback,
              fallbackSelect: item.fallbackSelect,
              focus: item.focus,
              focus2: item.focus2,
            })}
          >
            {/* ********이상징후관리 > 대화상세 > 금칙어 검색 시 클래스명 : highlight 사용*/}
            <p className='label'>
              {item.content}
              <span className='highlight'>금칙어 하이라이트</span>
            </p>

          </div>
            <button
              type="button"
              className={classNames('btn-chat-play', { active: isPlay })}
              onClick={() => setPlay(item.rownum, item.id)}
            >
              <span className="hidden">{isPlay ? '정지' : '재생'}</span>
            </button>
        </div>
        <div className="date">{item.time_stamp}</div>
      </div>
    </S.ChatElement>
  );
};

export default ChatElement;
