import styled from "@emotion/styled";

const SearchBox = ({width,value,placeholder,label,onClick=()=>{}}) => {
  return(
    <SearchContainer onClick={onClick}>
      <span>
        <label htmlFor="">{label}</label>
        <input type="text" placeholder={placeholder} readOnly/>
      </span>
      <button/>
    </SearchContainer>

  );
};

export default SearchBox;

export const SearchContainer = styled.div`
  width:260px;
  height:64px;
  border-radius: 6px;
  background:#fff;
  padding:0 20px; 
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-sizing: border-box !important;
  border:2px solid transparent;
  box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
  &:focus , &:hover{
    border:2px solid #4E47D6;
  }

  span{
    width:200px;
    height:64px;
    padding:10px 0;
    display: flex;
    flex-direction: column;
    font-size:14px;
    font-weight:400;

    label{
      width:100%;
      color:#7E8B99;
      line-height: 21px;
    }
    input {
      width:100%;
      color:#555F6D;
      border:none;
      height:24px;
      line-height: 23px;
  }
  }

  button{
    width:20px;
    height:20px;
    background: url('/images/ico_searchBox.svg') no-repeat center center;
  }
`;
