import { useState } from 'react';
import Select from 'components/elements/Select';
import Table from 'components/common/Table';
import Button from 'components/elements/Button';
import TextField from 'components/elements/TextField';
import Pagination from 'components/common/Pagination';
import Checkbox from 'components/elements/Checkbox';
import { TwoLineFlexBox, FilterTwoLine, SubTableTitle, CountingTitle } from 'style/AutoQAStyle';
import ButtonList from 'components/common/ButtonList';
import Title from 'components/common/Title';
import LayerPopup from 'components/common/LayerPopup';
import DocumentsManagementAddPopup from './popups/DocumentsManagementAddPopup';
import DocumentsManagementPopup from './popups/DocumentsManagementPopup';
import NoData from 'components/common/NoData';

const DocumentsManagementPage = () => {
  const [openDetail, setDetailOpen] = useState(false); //문서 등록 팝업
  const [openPopup, setOpenPopup] = useState(false);
  const [popupType, setPopupType] = useState('상세'); //문서 상세, 수정 팝업

  return (
    <>
      {openDetail &&  //문서 등록 팝업
        <LayerPopup
          size="large"
          title={`문서 등록`}
          customWidth={900}
          open={openDetail}
          onClose={() => setDetailOpen(false)}
        >
          <DocumentsManagementAddPopup />
        </LayerPopup>
      }

      {openPopup &&  //문서 상세, 수정 팝업
        <LayerPopup
          size="large"
          title={`문서 ${popupType}`}
          customWidth={900}
          open={openPopup}
          onClose={() => setOpenPopup(false)}
        >
          <DocumentsManagementPopup setPopupType={setPopupType}/>
        </LayerPopup>
      }

      <Title title="문서 관리" icon="fileEdit" />
      <FilterTwoLine>
        <TwoLineFlexBox width={'810px'} >
          <Select
            option={[]}
            label="카테고리 1"
            value={null}
            disabled={false}
            title={'카테고리1 선택'}
            onChange={() => { console.log('select!') }}
          />
          <Select
            option={[]}
            label="카테고리 2"
            value={null}
            disabled={false}
            title={'카테고리2 선택'}
            onChange={() => { console.log('select!') }}
          />
          <Select
            option={[]}
            label="카테고리 3"
            value={null}
            disabled={false}
            title={'카테고리3 선택'}
            onChange={() => { console.log('select!') }}
          />
          <TextField
            placeholder="문서명을 입력해주세요"
            label="문서명 입력"
            multi
            onChange={(e) => { }}
          />
          <Select
            option={[]}
            label="상태 선택"
            value={null}
            title={'전체'}
            disabled={false}
            onChange={() => { console.log('select!') }}
          />
          <Select
            option={[]}
            label="사용 여부 선택"
            value={null}
            disabled={false}
            title={'전체'}
            onChange={() => { console.log('select!') }}
          />

        </TwoLineFlexBox>
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </FilterTwoLine>
      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          { label: '선택 삭제', className: 'secondary del2', onClick: () => { } },
          { label: '등록', className: 'primary left-plus', onClick: () => {setDetailOpen(true)} },
        ]} />
      </SubTableTitle>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="64px" />
            <col width="204px" />
            <col width="220px" />
            <col width="220px" />
            <col width="220px" />
            <col width="205px" />
            <col width="205px" />
            <col width="120px" />
            <col width="120px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th >문서명</th>
              <th >카테고리 1</th>
              <th >카테고리 2</th>
              <th >카테고리 3</th>
              <th >등록 일시</th>
              <th >수정 일시</th>
              <th>상태</th>
              <th>사용 여부</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={9}><NoData txt={'데이터가 없습니다'}/></td></tr> 
               */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index} onClick={(e) => {
                // 클릭한 요소가 체크박스가 포함된 td일 경우 행 클릭 이벤트 무시
                const excludedTd = e.currentTarget.querySelector('td.checkType');
                if (excludedTd && excludedTd.contains(e.target)) {
                  return;
                }
                setOpenPopup(true);
              }}>
                <td className='checkType'><Checkbox /></td>
                <td>5G 요금제</td>
                <td>카테고리 1</td>
                <td>카테고리 2</td>
                <td>카테고리 3</td>
                <td>2024-11-11 11:11:11</td>
                <td>2024-11-11 11:11:11</td>
                <td>진행중</td>
                <td>미사용</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  )
};

export default DocumentsManagementPage;