import * as S from '../../style/ElementsStyle';
import { useNavigate } from 'react-router-dom';

const Heading = ({ className }) => {
  const navigate = useNavigate();
  const goHome = () => {
    navigate('dashboard/serviceStatus');
  }
  return (
    <S.Heading className={className} onClick={goHome}>
      <strong style={{fontWeight:'bold'}}>SKT Auto QA</strong>
      {/* <strong style={{fontWeight:'bold'}}>AI KMS</strong> */}
    </S.Heading>
  );
};

export default Heading;
