import { useNavigate } from "react-router-dom";
import { useState } from "react";

import Title from "components/common/Title";
import Button from "components/elements/Button";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Select from "components/elements/Select";
import { DetailPageContainer, DetailContentsWrap, DetailTitles, BackBtnWrap , NoticeText } from 'style/AutoQAStyle';

const AIAModelDetail = () => {
  const navigate = useNavigate();
  const [showNotice, setShowNotice] = useState(false);

  return (
    <>
      <Title title="AI 모델 생성" icon="evaluation" />
      <DetailPageContainer>
        <DetailContentsWrap padding={true}>
          <DetailTitles>AI 모델 정보</DetailTitles>
          <GrayBox direction={'column'} >
            <FormItem label={'AI 모델명 *'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'AI 모델 명을 입력하세요.'} />
              {showNotice && <NoticeText margin={'8px 0 0 0'}>AI모델명을 입력해주시기 바랍니다.</NoticeText>}
            </FormItem>
            <FormItem label={'리소스명'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'리소스명을 입력하세요.'} />
            </FormItem>
            <FormItem label={'API Key'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'API Key를 입력하세요.'} />
            </FormItem>
            <FormItem label={'Endpoint *'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'버전 정보를 입력하세요'} />
              {showNotice && <NoticeText margin={'8px 0 0 0'}>Endpoint를 입력해주시기 바랍니다.</NoticeText>}
            </FormItem>
            <FormItem label={'Version *'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'버전 정보를 입력하세요'} />
              {showNotice && <NoticeText margin={'8px 0 0 0'}>Endpoint를 입력해주시기 바랍니다.</NoticeText>}
            </FormItem>
            <FormItem label={'사용 여부'}>
              <Select
                option={[]}
                type={'simple'}
                title={'선택'}
                onChange={() => { console.log('select!') }}
              />
            </FormItem>
          </GrayBox>
          <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
            <Button label="저장" className={'primary wide'} onClick={() => { }} />
          </div>
        </DetailContentsWrap>
        <BackBtnWrap>
          <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
        </BackBtnWrap>
      </DetailPageContainer>

    </>
  )
};

export default AIAModelDetail;