import { useState } from "react";
import GrayBox from "components/common/GrayBox";
import FormGrid from "components/common/FormGrid";
import TextField from 'components/elements/TextField';
import Select from 'components/elements/Select';
import { LayerInButtonWrap, PopupInSmallTitle ,NoticeText} from "style/AutoQAStyle";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import Button from "components/elements/Button";
import NoData from "components/common/NoData";

const UserSearchPopup = () => {
  const [noticeShowIs, setNoticeShowIs] = useState(false);
  
  return (
    <>
      <div style={{ marginBottom: '40px' }}>
        <GrayBox>
          <FormGrid>
            <div>
              <PopupInSmallTitle>아이디</PopupInSmallTitle>
              <div style={{ display: 'flex', gap: 16 }}>
                <TextField placeholder={"아이디를 입력하세요."} width={690} />
                <Button label="아이디 중복 검사" className={'primary'} onClick={() => { }} />
              </div>
              {noticeShowIs && <NoticeText>아이디 중복검사를 진행하세요.</NoticeText>}
            </div>

            <div>
              <PopupInSmallTitle>이름</PopupInSmallTitle>
              <div style={{ display: 'flex', gap: '16px' }}>
                <TextField placeholder={"성"} width={264} />
                <TextField placeholder={"이름"} width={560} />
              </div>
            </div>

            <div>
              <PopupInSmallTitle>사번</PopupInSmallTitle>
              <TextField placeholder={"사번을 입력하세요."} width={838} />
            </div>
            <div>
              <PopupInSmallTitle>이메일</PopupInSmallTitle>
              <TextField placeholder={"이메일을 입력하세요."} width={838} />
              {noticeShowIs && <NoticeText>올바른 이메일 형식을 입력하세요.</NoticeText>}
            </div>
          </FormGrid>
        </GrayBox>
      </div>
      <PopupInSmallTitle>사용자 권한 설정</PopupInSmallTitle>
      <Table >
        <table>
        <colgroup>
            <col width="232px" />
            <col width="232px" />
            <col width="232px" />
          </colgroup>
          <thead>
            <tr>
              <th>시스템 권한(역할)</th>
              <th>메뉴 접근 권한</th>
              <th>조직</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr className='thin'>
                  <td colSpan="4">
                    <NoData txt={`조회된 데이터가 없습니다.`} />
                  </td>
                </tr> */}
            <tr height="64px" >
              <td>
                <Select
                  option={[]}
                  label="권한을 선택하세요"
                  value={''}
                  type="simple"
                  width={267}
                />
              </td>
              <td>
                <Select
                  option={[]}
                  label="역할을 선택하세요"
                  value={''}
                  type="simple"
                  width={267}
                />
              </td>
              <td> <Select
                option={[]}
                label="조직을 선택하세요"
                value={''}
                type="simple"
                width={267}
              />
              </td>
            </tr>
          </tbody>
        </table>
      </Table>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '저장', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  );
};

export default UserSearchPopup;