import { useState } from 'react';
import { WideLayerGrid , RecentConversationHistoryList } from "style/AutoQAStyle";
import Button from 'components/elements/Button';
import CustomChatElementWrap from "components/common/CustomChatElementWrap";
import * as S from 'style/ElementsStyle';


const tempChatList = [
  {
    type:'tester',
    msg : '판교에 있는 티월드 매장 목록 보여줘.​',
    time_stamp:'2023.08.31 10:00:00',
  },
  {
    type:'counselor',
    msg : '경기도 성남시 분당구에는 총 23개의 매장이 있습니다.​ 각 매장의 상세 정보는 아래의 첨부 파일 또는 링크를 참고해주시기 바랍니다.​',
    file:[
      {
        type:'pdf',
        title:'성남시 분당구 매장.pdf​'
      },
      {
        type:'link',
        title:'전국 SK텔레콤 매장 안내.htm​l'
      }
    ],
    time_stamp:'2023.08.31 10:00:00',
  },
  {
    type:'tester',
    msg : '판교역에서 제일 가까운 매장은 어디야?​​',
    time_stamp:'2023.08.31 10:00:00',
  },
  {
    type:'counselor',
    msg : '판교 역에서 가장 가까운 매장은 ‘가능대리점 판교직영점’ 입니다.​ 해당 매장의 상세 정보는 아래의 첨부 파일 또는 링크를 참고해주시기 바랍니다.​',
    file:[],
    time_stamp:'2023.08.31 10:00:00',
  },
  {
    type:'tester',
    msg : '판교역에서 제일 가까운 매장은 어디야?​​',
    time_stamp:'2023.08.31 10:00:00',
  },
];


const ConversationTab = () => {
  const [loading, setLoading] = useState(false);

  const click = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
    }, 1000); 
  }

  return (
    <>
      {loading && (
        <S.Loading>
          <span className="loading" aria-label="로딩중"></span>
        </S.Loading>
      )}

       <WideLayerGrid>
        <div style={{ width: '294px' }}>
          <div className="sub-title-wrap">
            <div>
              <h5>최근 대화 이력</h5>
              <p>검색어는 최근 10개까지만 표시됩니다.</p>
            </div>
          </div>
          <div className="content-wrap round-contents" style={{padding:0, height:'642px'}}>
            <RecentConversationHistoryList>
            {Array.from({ length: 10 }).map((_, index) => (
              <li key={index}>
                <p>문구는 20byte 까지 입력 가능합니다</p>
                <Button className="secondary del2" btnType={'icon'} onClick={() => {}}/>
              </li>
            ))}
            </RecentConversationHistoryList>
          </div>
        </div>

        <div style={{ width: '1274px' }}>
          <div className="sub-title-wrap">
            <div>
              <h5>대화 내역</h5>
              <p>검색어를 클릭하면 해당 대화내용이 표시됩니다.</p>
            </div>
            <Button className="primary left-plus" label="새로 시작" onClick={() => {click()}}/>
          </div>
          <div className="content-wrap">
            <CustomChatElementWrap list={tempChatList} width={1274} height={642} searchInput={true}/>
          </div>
        </div>
      </WideLayerGrid>
    </>
  )
};

export default ConversationTab; 