import ReactDOM from 'react-dom';
import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';

const Dimmed = ({ onClose }) => {
  return <S.Dimmed onClick={onClose} />;
};

/**
 * size : mid (default : 800px) | small (500px)
 */
const Modal = ({
  size = 'mid',
  open,
  onClose,
  title,
  titleHeight = false,
  subTitle,
  customWidth,
  customClass,
  children,
}) => {
  //231107 titleHeight props추가
  return (
    <S.LayerPopupWrap open={open}>
      <Dimmed onClose={onClose} />
      <S.LayerPopup customWidth={customWidth} titleHeight={titleHeight}>
        {/* 231107 titleHeight 추가 */}
        <div className="layer-wrap">
          <div className={`layer-popup ${size}`}>
            {title && (
              <div className="layer-header">
                <h2>{title}</h2>
                {subTitle && <span className="sub-title">{subTitle}</span>}
                <button onClick={onClose}/>
              </div>
            )}
            <div className="layer-container">
              <div className={classnames('layer-inner', customClass)}>
                {children}
              </div>
            </div>
          </div>
        </div>
      </S.LayerPopup>
    </S.LayerPopupWrap>
  );
};
const LayerPopup = (props) => {
  return <>{ReactDOM.createPortal(<Modal {...props} />, document.getElementById('layer-root'))}</>;
};

export default LayerPopup;
