import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { useEffect, useState } from 'react';
import { getBotGroupsApi, getServicesApi } from '../../fallbackUtterance/apis';
import { getAutoTestHistoryApi, getBotsApi, getAutoTestDetailApi, getDownloadApi } from '../apis';
import { customSort, customBotSort } from 'libs/utiles';
import { CHANGING_RECORDS_SEARCH_PARAMS } from '../constants';
import {useServiceList} from "../../../libs/DataHook";
import {useSelector} from "react-redux";

const DEFAULT_SEARCH_AUTO_TEST_PARAMS = {
  startDate: dayjs().format('YYYY-MM-DD'),
  endDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 20,
  isAllSearch: true,
  // sort: { created_datetime: 'desc' },
};
const DEFAULT_SEARCH_AUTO_TEST_HISTORY_PARAMS = {
  startDate: dayjs().subtract(7, 'day').format('YYYY-MM-DD'),
  endDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 20,
  isAllSearch: true,
  // sort: { created_datetime: 'desc' },
};

const DEFAULT_AUTO_TEST_DETAIL_PARAMS = {
  pageNo: 0,
  pageSize: 20,
  callResult: 'Total'
  // sort: { created_datetime: 'desc' },
};

const useTest = () => {
  const [searchAutoTestParams, setSearchAutoTestParams] = useState(DEFAULT_SEARCH_AUTO_TEST_PARAMS);
  const [searchAutoTestHistoryParams, setSearchAutoTestHistoryParams] = useState(
    DEFAULT_SEARCH_AUTO_TEST_HISTORY_PARAMS
  );
  const [autoTestDetailParams, setAutoTestDetailParams] = useState(DEFAULT_AUTO_TEST_DETAIL_PARAMS);
  const [autoTestResultParams, setAutoTestResultParams] = useState(DEFAULT_AUTO_TEST_DETAIL_PARAMS);
  const [latestSearchAutoTestParams, setLatestSearchAutoTestParams] = useState({});
  const [latestSearchAutoTestHistoryParams, setLatestSearchAutoTestHistoryParams] = useState({});

  const serviceList = useServiceList()
  const {serviceId, serviceName} = useSelector((state) => state.service.value)
  const [botGroupList, setBotGroupList] = useState([]); // 자동 테스트 탭 봇 그룹 목록
  const [botList, setBotList] = useState([]); // 자동 테스트 탭 봇 목록
  const [historyServiceList, setHistoryServiceList] = useState([]); // 처리 이력 탭 서비스 목록
  const [historyBotGroupList, setHistoryBotGroupList] = useState([]); // 처리 이력 탭 봇 그룹 목록
  const [historyBotList, setHistoryBotList] = useState([]); // 처리 이력 탭 봇 그룹 목록
  const [autoTestRes, setAutoTestRes] = useState({}); // 폴백 신규 이력 목록
  const [autoTestHistoryRes, setAutoTestHistoryRes] = useState({}); // 자동 테스트 이력 조회 목록
  const [autoTestDetail, setAutoTestDetail] = useState({}); // 자동 테스트 상세
  const [autoTestDetailSum, setAutoTestDetailSum] = useState({}); // 자동 테스트 합계
  const [autoTestDetailList, setAutoTestDetailList] = useState({}); // 자동 테스트 발화 목록
  const [autoTestResult, setAutoTestResult] = useState({}); // 자동 테스트 결과 상세
  const [autoTestResultSum, setAutoTestResultSum] = useState({}); // 자동 테스트 결과 합계
  const [autoTestResultList, setAutoTestResultList] = useState({}); // 자동 테스트 결과 발화 목록
  const [imageKey, setImageKey] = useState(null); // 이미지 키

  // 조회 조건 변경
  const changeSearchAutoTestParams = (key, value) => {
    setSearchAutoTestParams(fp.set(key, value));
  };

  // 처리 이력 조회 조건 변경
  const changeSearchAutoTestHistoryParams = (key, value) => {
    if (key in CHANGING_RECORDS_SEARCH_PARAMS) {
      setSearchAutoTestHistoryParams((prev) => ({
        ...prev,
        ...CHANGING_RECORDS_SEARCH_PARAMS,
        [key]: value,
      }));
    } else {
      console.log('changeSearchAutoTestHistoryParams :::: ');
      setSearchAutoTestHistoryParams(fp.set(key, value));
    }
    // setSearchAutoTestHistoryParams(fp.set(key, value));
  };

  // 테스트 결과 조건 변경
  const changeAutoTestDetailParams = (key, value) => {
    setAutoTestDetailParams(fp.set(key, value));
  };

  // 자동 테스트 결과 조건 변경
  const changeAutoTestResultParams = (key, value) => {
    setAutoTestResultParams(fp.set(key, value));
  };

  // 서비스 목록 조회
  const getServices = async (type = 'new') => {
    try {
      const res = await getServicesApi();

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));

        const firstServiceId = fp.getOr('', 'data.data[0].serviceId', res);
        const serviceName = fp.pipe(
          fp.getOr([], 'data.data'),
          fp.find((obj) => obj.serviceId == firstServiceId),
          fp.getOr('', 'name')
        )(res);

      if (type === 'history') {
        setHistoryServiceList(fp.getOr([], 'data.data', res));
        changeSearchAutoTestHistoryParams('serviceId', firstServiceId);
        changeSearchAutoTestHistoryParams('serviceName', serviceName);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('서비스 목록 조회에 실패했습니다. 서비스 목록 조회가 가능한 상태인지 확인해주세요.');
      if (type === 'history') {
        setHistoryServiceList([]);
      }
    }
  };

  // 봇 그룹 목록 조회
  const getBotGroups = async (serviceId, type = 'new') => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
        let sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
        sortBotGroups.unshift({botGroupId:'ALL',botGroupName:'전체'});
      if (type === 'new') {
        setBotGroupList(sortBotGroups);
      } else {
        setHistoryBotGroupList(sortBotGroups);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('봇그룹 목록 조회에 실패했습니다. 봇그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      if (type === 'new') {
        setBotGroupList([]);
        setBotList([]);
      } else {
        setHistoryBotGroupList([]);
        setHistoryBotList([]);
      }
    }
  };

  // 봇 목록 조회
  const getBots = async (serviceId, botGroupId, type = 'new') => {
    try {
      const res = await getBotsApi({ serviceId, botGroupId, pageNo: 0, pageSize: 1000 });
      console.log('::::: ', fp.getOr([], 'data.data.content', res));
      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
        const sortBots = fp.sortBy(customBotSort, fp.getOr([], 'data.data.content', res));
      if (type === 'new') {
        setBotList(sortBots);
      } else {
        setHistoryBotList(sortBots);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 목록 조회에 실패했습니다. 봇그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      if (type === 'new') {
        setBotList([]);
      } else {
        setHistoryBotList([]);
      }
    }
  };

  // 자동 테스트 리스트 조회
  const getAutoTestHistory = async (searchParams) => {
    try {
      const res = await getAutoTestHistoryApi({ ...searchParams }, true);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setAutoTestHistoryRes(fp.getOr({}, 'data.data', res));
      setLatestSearchAutoTestHistoryParams(searchParams);
    } catch (error) {
      console.log('error', error?.message);
      alert('테스트 이력 목록 조회에 실패했습니다.');
      setAutoTestHistoryRes({});
    }
  };

  // 자동 테스트 상세 조회
  const getAutoTestDetail = async (searchParams, type = 'new') => {
    try {

      console.log('getAutoTestDetail type :::: ', type);
      const res = await getAutoTestDetailApi({ ...searchParams }, true);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
        if (type === 'new') {
          setAutoTestResult(fp.getOr({}, 'data.data.detail', res));
          setAutoTestResultSum(fp.getOr({}, 'data.data.sum', res));
          setAutoTestResultList(fp.getOr({}, 'data.data', res));
        }else{
          setAutoTestDetail(fp.getOr({}, 'data.data.detail', res));
          setAutoTestDetailSum(fp.getOr({}, 'data.data.sum', res));
          setAutoTestDetailList(fp.getOr({}, 'data.data', res));
        }
    } catch (error) {
      console.log('error', error?.message);
      alert('테스트 결과 조회에 실패했습니다.');
      if (type === 'new') {
        setAutoTestResult({});
        setAutoTestResultSum({});
        setAutoTestResultList({});
      }else{
        setAutoTestDetail({});
        setAutoTestDetailSum({});
        setAutoTestDetailList({});
      }
    }
  };

  const getDownload = async (autoTestHistoryId, fileType, fileName) => {
    try {
      console.log('file download :::: ');

      const res = await getDownloadApi({ autoTestHistoryId, fileType });
      console.log('res.data :::: ', res.data);
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', fileName);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      alert('다운로드에 실패했습니다.');
    }
  };
  
  // 이미지키 조회
  const getImageKey = async (searchParams) => {
    try {
      const res = await getAutoTestHistoryApi({ ...searchParams });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setImageKey(fp.getOr({}, 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
      setImageKey({});
    }
  };

  useEffect(() => {
    console.log('useEffect searchAutoTestParams ::: ', serviceId);
    if (!serviceId) return;
    getBotGroups(serviceId, 'new');
  }, [serviceId]);

  useEffect(() => {
    console.log(
      'useEffect searchAutoTestHistoryParams ::: ',
      searchAutoTestHistoryParams.serviceId
    );
    if (!searchAutoTestHistoryParams.serviceId) return;
    getBotGroups(searchAutoTestHistoryParams.serviceId, 'history');
  }, [searchAutoTestHistoryParams.serviceId]);

  useEffect(() => {
    console.log('useEffect searchAutoTestParams ::: ', searchAutoTestParams.botGroupId);
    if (!searchAutoTestParams.botGroupId) return;
    getBots(serviceId, searchAutoTestParams.botGroupId, 'new');
  }, [searchAutoTestParams.botGroupId]);

  useEffect(() => {
    console.log(
      'useEffect searchAutoTestHistoryParams ::: ',
      searchAutoTestHistoryParams.botGroupId
    );
    if (!searchAutoTestHistoryParams.botGroupId) return;
    getBots(
      searchAutoTestHistoryParams.serviceId,
      searchAutoTestHistoryParams.botGroupId,
      'history'
    );
  }, [searchAutoTestHistoryParams.botGroupId]);

  return {
    searchAutoTestParams,
    searchAutoTestHistoryParams,
    autoTestDetailParams,
    autoTestResultParams,
    serviceList,
    serviceId,
    serviceName,
    botGroupList,
    botList,
    historyServiceList,
    historyBotGroupList,
    historyBotList,
    autoTestRes,
    autoTestHistoryRes,
    autoTestDetail,
    autoTestDetailSum,
    autoTestDetailList,
    autoTestResult,
    autoTestResultSum,
    autoTestResultList,
    latestSearchAutoTestParams,
    latestSearchAutoTestHistoryParams,
    imageKey,
    changeSearchAutoTestParams,
    changeSearchAutoTestHistoryParams,
    changeAutoTestDetailParams,
    changeAutoTestResultParams,
    getServices,
    getBotGroups,
    getBots,
    getAutoTestHistory,
    getAutoTestDetail,
    getImageKey,
    getDownload,
  };
};

export default useTest;
