import {  useRef } from 'react'; // 231123
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import * as S from '../../style/ChartStyle';
import fp from 'lodash/fp';
import { getIncrementHighestDigit } from 'libs/utiles';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  ChartDataLabels
);

const MultipleLineChart = ({
  colors = ['#5C5FD6', '#9D9FE6'],
  legends,
  labels,
  datas = {},
  width,
  height,
}) => {
  // y 축 최대 값 계산
  // const getMax = (datas) => {
  //   const unionArr = fp.union(fp.getOr([], 'dataFirst', datas), fp.getOr([], 'dataSecond', datas));
  //   const max = fp.max(unionArr);
  //   return max > 10 ? getIncrementHighestDigit(max) : 10;
  // };
  const getMax = (datas) => {
    const max = fp.max(datas);
    return max > 10 ? getIncrementHighestDigit(max) : 10;
  };

  const options = {
    responsive: true,
    interaction: {
      mode: 'index',
      intersect: false,
    },
    plugins: {
      legend: {
        display: false,
      },
      datalabels: {
        display: false,
      },
    },
    maintainAspectRatio: false,
    scales: {
      x: {
        grid: {
          display: false,
        },
        ticks: {
          beginAtZero: true,
          color: 'rgba(71, 85, 105, 0.50)',
          fontSize: 12,
          maxRotation: 0, // 라벨을 수평으로 유지
          minRotation: 0, // 라벨 회전 제거
          align: 'center', // 라벨 중앙 정렬
        },
      },
      y: {
        type: 'linear',
        position: 'left',
        min: 0,
        max: getMax(datas.dataFirst),
        ticks: {
          beginAtZero: true,
          color: '#B3B3C5',
          fontSize: 12,
          
        },
      },
      y1: {
        type: 'linear',
        position: 'right',
        min: 0,
        max: getMax(datas.dataSecond),
        ticks: {
          display: true,
          beginAtZero: true,
        },
        grid: {
          drawBorder: false,
          display: false,
        },
      },
    },
  };

  const data = {
    labels,
    datasets: [
      {
        label: legends[0],
        data: datas.dataFirst,
        borderColor: colors[0],
        backgroundColor: colors[0],
        yAxisID: 'y',
      },
      {
        label: legends[1],
        data: datas.dataSecond,
        borderColor: colors[1],
        backgroundColor: colors[1],
        yAxisID: 'y1',
        ticks: {
          display: false,
        },
      },
    ],
  };

  const legendContainer = useRef(); // 231123 ref 추가

  // 231123 htmlLegendPlugin 추가
  const htmlLegendPlugin = {
    id: 'htmlLegend',
    afterUpdate(chart) {
      const legendBtns = legendContainer.current.children;
      [...legendBtns].map((btn, i) => {
        btn.onclick = (e) => {
          if (e.target.classList.contains('disabled')) { 
            e.target.classList.remove('disabled');
            chart.show(i);
            chart.update();
          } else {
            e.target.classList.add('disabled');
            chart.hide(i);
            chart.update();
          }
        }
      });
    }
  };
  
  return (
    <S.MultipleLineChart width={width} height={height}> 
      <div className="legend">
        <ul ref={legendContainer}> {/* 231123 ref 추가 */}
          {legends.map((legend, idx) => (
            <S.Legend key={`legend-${legend}`} color={colors[idx]}>
              {legend}
            </S.Legend>
          ))}
          {/* 231031 key 추가 */}
        </ul>
      </div>

      <div className="inner">
        <Line options={options} data={data} plugins={[htmlLegendPlugin]} /> {/* 231123 plugins 추가 */}
      </div>
    </S.MultipleLineChart>
  );
};

export default MultipleLineChart;
