import Filter from 'components/common/Filter';
import LayerPopup from 'components/common/LayerPopup';
import NoData from 'components/common/NoData';
import Pagination from 'components/common/Pagination';
import Table from 'components/common/Table';
import Title from 'components/common/Title';
import Button from 'components/elements/Button';
import Select from 'components/elements/Select';
import JobRegister from 'components/pages/callbotManager/JobRegister';
import JobRegisterCancel from 'components/pages/callbotManager/JobRegisterCancel.js';
import useLastPageUpdater from 'hooks/useLastPageUpdater';
import { BOT_TYPE_INBOUND, JOB_TYPES, JOB_TYPE_OUTBOUND, getJobTypeName } from 'libs/Constants';
import { useBotGroupList, useJobList, useServiceList } from 'libs/DataHook';
import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setService } from 'redux/service';

const MAX_JOB_COUNT = 200;
const PAGE_SIZE = 10;

const jobTypeOptions = [
  { id: 'ALL_JOBS', title: '전체 Job 유형' },
  ...JOB_TYPES.map((jt) => ({ id: jt.code, title: jt.name })),
];

export default function Job() {
  const dispatch = useDispatch();

  const serviceList = useServiceList();
  const service = useSelector((state) => state.service.value);
  const [serviceId, setServiceId] = useState(service.serviceId);
  const handleServiceChange = (event) => {
    setServiceId(event);
    setPageNo(0);
    setBotGroupList(event);
    setJobType('ALL_JOBS');
    setBotGroupId('ALL_BOT_GROUPS');
    serviceList.forEach((s) => {
      if (s.serviceId === event) {
        dispatch(setService({ serviceId: s.serviceId, serviceName: s.name }));
      }
    });
  };

  const [jobType, setJobType] = useState('ALL_JOBS');
  const handleJobTypeChange = (event) => {
    setJobType(event);
    setPageNo(0);
  };

  const [botGroupId, setBotGroupId] = useState('ALL_BOT_GROUPS');
  const [botGroupList, setBotGroupList] = useBotGroupList();

  useEffect(() => {
    if (!serviceList || serviceList.length === 0) {
      return;
    }
    const newServiceId = service.serviceId;
    setServiceId(newServiceId);
    setBotGroupList(newServiceId, BOT_TYPE_INBOUND.botType, '');
  }, [service, serviceList, setBotGroupList]);

  const handleBotGroupChange = (event) => {
    setBotGroupId(event);
    setPageNo(0);
  };

  const [pageNo, setPageNo] = useState(0);
  const { jobList, setJobList, jobTotalCount, jobTotalPages } = useJobList();
  useEffect(() => {
    setJobList(pageNo, PAGE_SIZE, serviceId, jobType, botGroupId);
  }, [pageNo, serviceId, jobType, botGroupId, setJobList]);

  useLastPageUpdater(jobList, jobTotalCount, setPageNo, PAGE_SIZE);

  function createRows(item) {
    const hasNoMappings = item.mapping.length === 0;
    const isOutbound = item.jobType === JOB_TYPE_OUTBOUND.code;
    return (
      <tr key={item.jobId}>
        <td className="t-left">{item.jobName}</td>
        <td>{getJobTypeName(item.jobType)}</td>
        <td>{item.channelCount}</td>
        <td>{isOutbound ? '-' : item.callpointStart}</td>
        <td>{isOutbound ? '-' : item.callpointEnd}</td>
        <td className="t-left">{hasNoMappings ? '-' : item.mapping[0].botGroupName}</td>
        <td>
          <Button
            label="등록 취소"
            className="secondary normal"
            disabled={!hasNoMappings}
            onClick={() => handleOpen('CANCEL_REGISTER', item)}
          />
        </td>
      </tr>
    );
  }

  const [isRegisterDialogOpen, setIsRegisterDialogOpen] = useState(false);
  const [isCancelDialogOpen, setIsCancelDialogOpen] = useState(false);

  const [jobToCancel, setJobToCancel] = useState(null);

  const handleClose = (event, doReload = false) => {
    setIsRegisterDialogOpen(false);
    setIsCancelDialogOpen(false);
    if (doReload) {
      setJobList(pageNo, PAGE_SIZE, serviceId, jobType, botGroupId);
    }
  };

  const handleOpen = (type, job) => {
    switch (type) {
      case 'REGISTER':
        if (jobList.length >= MAX_JOB_COUNT) {
          alert(
            `Job은 최대 ${MAX_JOB_COUNT}개까지 등록 가능합니다.\n\n기존에 등록된 Job을 등록 취소하신 후, 다시 시도해주세요.`
          );
          break;
        }
        setIsRegisterDialogOpen(true);
        break;
      case 'CANCEL_REGISTER':
        setIsCancelDialogOpen(true);
        setJobToCancel(job);
        break;
      default:
    }
  };

  return (
    <>
      <Title title="Job 관리" icon="callbot-manage" />
      <Filter>
        <div className="left-area">
          <Select
            option={serviceList.map((service) => ({ id: service.serviceId, title: service.name }))}
            value={serviceId}
            label="서비스 선택"
            onChange={handleServiceChange}
            disabled={serviceList.length === 0}
          />
          <Select
            option={jobTypeOptions}
            value={jobType}
            label="Job 유형 선택"
            onChange={handleJobTypeChange}
          />
          <Select
            option={[
              { id: 'ALL_BOT_GROUPS', title: '봇 그룹 선택' },
              ...botGroupList.map((botGroup) => ({
                id: botGroup.botGroupId,
                title: botGroup.botGroupName,
              })),
            ]}
            value={botGroupId}
            label="봇 그룹 선택"
            onChange={handleBotGroupChange}
            disabled={botGroupList?.length === 0}
          />
        </div>
        <div className="right-area">
          <Button
            className="primary left-plus"
            label="Job 등록"
            onClick={() => handleOpen('REGISTER')}
            disabled={!serviceId || serviceId === ''}
          />
        </div>
      </Filter>

      <div className="in-table-bg">
        <Table fixedHeader>
          <table>
            <caption>
              Job명, 유형, 채널수, Call Point 시작, Call Point 끝, 봇 그룹에 관한 표
            </caption>
            <colgroup>
              <col />
              <col />
              <col />
              <col />
              <col />
              <col />
              <col />
            </colgroup>
            <thead>
              <tr>
                <th scope="col" className="t-left">Job명</th>
                <th scope="col">유형</th>
                <th scope="col">채널수</th>
                <th scope="col">Call Point 시작</th>
                <th scope="col">Call Point 끝</th>
                <th scope="col" className="t-left">봇 그룹</th>
                <th scope="col"></th>
              </tr>
            </thead>
            <tbody>
              {serviceId === '' ? (
                <tr>
                  <td colSpan={7}>
                    <NoData txt="서비스를 선택해주세요." />
                  </td>
                </tr>
              ) : jobList.length === 0 ? (
                <tr>
                  <td colSpan={7}>
                    <NoData txt="등록된 Job이 없습니다." />
                  </td>
                </tr>
              ) : (
                jobList.map((row) => createRows(row))
              )}
            </tbody>
          </table>
        </Table>
      </div>

      <Pagination
        displayed={5}
        pagingTotal={jobTotalPages}
        currentPage={pageNo}
        totalCount={jobTotalCount}
        pageSize={PAGE_SIZE}
        numberOfElements={jobList.length}
        viewShowing
        hidePageSizeSelectOptions
        onPageChange={(pageNum) => {
          if (serviceId === '' || jobList.length === 0) {
            alert('조회 가능한 Job이 없습니다.');
            return;
          }
          setPageNo(pageNum);
        }}
      />

      {isRegisterDialogOpen ? (
        <LayerPopup title="Job 등록" open={isRegisterDialogOpen} onClose={handleClose}>
          <JobRegister
            serviceId={serviceId}
            currentJobCount={jobTotalCount}
            maxJobCount={MAX_JOB_COUNT}
            onClose={handleClose}
          />
        </LayerPopup>
      ) : null}

      {isCancelDialogOpen ? (
        <LayerPopup
          title="선택한 Job을 등록 취소하시겠습니까?"
          open={isCancelDialogOpen}
          onClose={handleClose}
        >
          <JobRegisterCancel onClose={handleClose} serviceId={serviceId} job={jobToCancel} />
        </LayerPopup>
      ) : null}
    </>
  );
}
