import * as S from '../../style/ElementsStyle';

/**
 * color : gray | white
 */
const Filter = ({ gap, color, tableFilter, children }) => {
  return (
    <S.Filter className={color} gap={gap} tableFilter={tableFilter}>
      {children}
    </S.Filter>
  ); //231116 tableFilter={tableFilter} 추가
};

export default Filter;
