import Textarea from "components/elements/Textarea";
import Button from "components/elements/Button";
import { BorderWithButton, TabInLabelBox } from "style/AutoQAStyle";
import FormItem from "components/common/FormItem";
import Radio from "components/elements/Radio";

const ObjectionTab = () => {
  return (
    <div>
      <div style={{marginBottom:'40px'}}>
        <TabInLabelBox>
          <p>신청 사유</p>
          <Textarea maxLength={100} height={164} value={'평가 결과와는 다르게 모든 사항에 대해 준수한 것으로 판단됩니다. 다시 한번 확인을 부탁드립니다.'} readOnly={true} count={true} />
          <div style={{ marginTop: '16px' }}>
            <FormItem label="처리 결과">
              <Radio id="result1" checked={true} onChange={() => { }} name="result">승인</Radio>
              <Radio id="result2" checked={false} onChange={() => { }} name="result">반려</Radio>
            </FormItem>
          </div>
        </TabInLabelBox>
        <TabInLabelBox>
          <p>관리자 Comment</p>
          <Textarea maxLength={200} height={164} placeholder={'녹취를 다시 확인한 결과 결과 평가에는 이상이 없는 것으로 판단됩니다. 다음에는 더 좋은 점수를 받을 수 있도록 노력을 부탁드립니다.'} count={true} />
        </TabInLabelBox>
      </div>
      <BorderWithButton>
        <Button label="저장" className="primary wide" onClick={() => { }} />
      </BorderWithButton>
    </div>
  );
};

export default ObjectionTab;