import { useEffect, useState } from 'react';
import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { getBotGroupsApi, getServicesApi } from 'pages/fallbackUtterance/apis';
import {
  getBotGroupPeriodStaticsExcelApi,
  getBotGroupStaticsDetailApi,
  getBotGroupWeekStaticsApi,
} from '../apis';
import { customSort } from 'libs/utiles';

const DEFAULT_BOTGROUP_WEEK_STATICS_SEARCH_PARAMS = {
  searchStartDate: dayjs().subtract(7, 'week').startOf('week').format('YYYY-MM-DD'),
  searchEndDate: dayjs().endOf('week').format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 10,
};

const useBotGroupWeekStatic = () => {
  const [botGroupWeekStaticsSearchParams, setBotGroupWeekStaticsSearchParams] = useState(
    DEFAULT_BOTGROUP_WEEK_STATICS_SEARCH_PARAMS
  ); // 조회 조건
  const [botGroupWeekStaticsRes, setBotGroupWeekStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [botGroupWeekTotalStaticsRes, setBotGroupWeekTotalStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [serviceListWeek, setserviceListWeek] = useState(null);
  const [botGroupListWeek, setBotGroupListWeek] = useState([]);
  const [isBotGroupWeekStaticsSearch, setIsBotGroupWeekStaticsSearch] = useState(false);
  const [latestBotGroupWeekSearchParams, setLatestBotGroupWeekSearchParams] = useState({});
  const [botGroupWeekDetailStaticsRes, setBotGroupWeekDetailStaticsRes] = useState({}); // 봇 그룹 통계 봇 그룹 데이터

  // 조회 조건 변경
  const changeBotGroupWeekStaticsSearchParams = (key, value) => {
    setBotGroupWeekStaticsSearchParams(fp.set(key, value));
  };

  // 봇별 조회
  const getBotGroupWeekStatics = async (searchParams) => {
    try {
      setIsBotGroupWeekStaticsSearch(true);
      const res = await getBotGroupWeekStaticsApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupWeekStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
      const botGroupName = fp.pipe(
        fp.find({ botGroupId: searchParams.botGroupId }),
        fp.getOr('', 'botGroupName')
      )(botGroupListWeek);

      setLatestBotGroupWeekSearchParams({ ...searchParams, botGroupName });
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 주별 조회에 실패했습니다.');
      setBotGroupWeekStaticsRes({});
    }
  };

  // 봇그룹 주별 전체 데이터 조회
  const getBotGroupWeekTotalStatics = async (searchParams) => {
    try {
      const res = await getBotGroupWeekStaticsApi({ ...searchParams, pageNo: 0, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupWeekTotalStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 봇별 조회에 실패했습니다.');
      setBotGroupWeekTotalStaticsRes({});
    }
  };

  // 봇 그룹 디테일 통계 조회
  const getBotGroupWeekStaticsDetail = async (searchParams) => {
    try {
      const res = await getBotGroupStaticsDetailApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupWeekDetailStaticsRes(fp.getOr({}, 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
    }
  };

  // 주별 리스트 엑셀 다운
  const getBotGroupWeekStaticsExcel = async (searchParams) => {
    try {
      // console.log('준비 중');
      const res = await getBotGroupPeriodStaticsExcelApi(searchParams, 'week');
      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_봇그룹통계_주별조회_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      alert('봇 그룹 통계 주별 엑셀 다운에 실패했습니다.');
    }
  };

  const getServicesWeek = async () => {
    try {
      const res = await getServicesApi();

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setserviceListWeek(fp.getOr([], 'data.data', res));

      const firstServiceId = fp.getOr('', 'data.data[0].serviceId', res);
      const serviceName = fp.pipe(
        fp.getOr([], 'data.data'),
        fp.find((obj) => obj.serviceId == firstServiceId),
        fp.getOr('', 'name')
      )(res);

      if (firstServiceId) {
        getBotGroupsWeek(firstServiceId);
        changeBotGroupWeekStaticsSearchParams('serviceId', firstServiceId);
        changeBotGroupWeekStaticsSearchParams('serviceName', serviceName);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('서비스 목록 조회에 실패했습니다. 서비스 목록 조회가 가능한 상태인지 확인해주세요.');
      setserviceListWeek([]);
    }
  };

  const getBotGroupsWeek = async (serviceId, jobType) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, jobType, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
      setBotGroupListWeek(sortBotGroups);
      const firstBotGroupId = fp.getOr('', '[0].botGroupId', sortBotGroups);
      changeBotGroupWeekStaticsSearchParams('botGroupId', firstBotGroupId);
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 목록 조회에 실패했습니다. 봇 그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupListWeek([]);
    }
  };

  useEffect(() => {
    if (!botGroupWeekStaticsSearchParams.serviceId) return;
    getBotGroupsWeek(botGroupWeekStaticsSearchParams.serviceId);
  }, [botGroupWeekStaticsSearchParams.serviceId]);

  return {
    botGroupWeekStaticsSearchParams, // 조회 조건
    latestBotGroupWeekSearchParams,
    botGroupWeekStaticsRes, // 봇그룹 봇별 통계 데이터
    botGroupWeekTotalStaticsRes,
    botGroupWeekDetailStaticsRes,
    serviceListWeek,
    botGroupListWeek,
    isBotGroupWeekStaticsSearch,
    changeBotGroupWeekStaticsSearchParams, // 조회 조건 변경
    getServicesWeek,
    getBotGroupsWeek,
    getBotGroupWeekStatics,
    getBotGroupWeekTotalStatics,
    getBotGroupWeekStaticsDetail,
    getBotGroupWeekStaticsExcel,
  };
};

export default useBotGroupWeekStatic;
