import { useEffect, useState } from 'react';
import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { getBotGroupsApi } from 'pages/fallbackUtterance/apis';
import {
  getBotGroupStaticsBotApi,
  getBotGroupStaticsBotExcelApi,
  getBotGroupStaticsDetailApi,
} from '../apis';
import { customSort } from 'libs/utiles';
import {useServiceList} from "../../../libs/DataHook";
import {useSelector} from "react-redux";

const DEFAULT_BOTGROUP_STATICS_BOT_SEARCH_PARAMS = {
  searchStartDate: dayjs().subtract(6, 'day').format('YYYY-MM-DD'),
  searchEndDate: dayjs().format('YYYY-MM-DD'),
  jobType: '',
  pageNo: 0,
  pageSize: 10,
};

const useBotGroupBotStatic = () => {
  const [botGroupBotStaticsSearchParams, setBotGroupBotStaticsSearchParams] = useState(
    DEFAULT_BOTGROUP_STATICS_BOT_SEARCH_PARAMS
  ); // 조회 조건
  const [botGroupBotStaticsRes, setBotGroupBotStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [botGroupDetailStaticsRes, setBotGroupDetailStaticsRes] = useState({}); // 봇 그룹 통계 봇 그룹 데이터
  const serviceList = useServiceList();
  const {serviceId, serviceName} = useSelector((state) => state.service.value);
  const [botGroupList, setBotGroupList] = useState([]);
  const [isBotGroupStaticsBotSearch, setIsBotGroupStaticsBotSearch] = useState(false);
  const [latestBotGroupSearchParams, setLatestBotGroupSearchParams] = useState(null);

  // 조회 조건 변경
  const changeBotGroupBotStaticsSearchParams = (key, value) => {
    setBotGroupBotStaticsSearchParams(fp.set(key, value));
  };

  // 봇별 조회
  const getBotGroupStaticsBot = async (searchParams) => {
    searchParams.serviceId = serviceId
    searchParams.serviceName = serviceName
    try {
      setIsBotGroupStaticsBotSearch(true);
      const res = await getBotGroupStaticsBotApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupBotStaticsRes(fp.getOr({}, 'data.data', res));
      setLatestBotGroupSearchParams({ ...searchParams });
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 봇별 조회에 실패했습니다.');
      setBotGroupBotStaticsRes({});
    }
  };

  // 봇 그룹 디테일 통계 조회
  const getBotGroupStaticsDetail = async (searchParams) => {
    searchParams.serviceId = serviceId
    searchParams.serviceName = serviceName
    try {
      setIsBotGroupStaticsBotSearch(true);
      const res = await getBotGroupStaticsDetailApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupDetailStaticsRes(fp.getOr({}, 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
    }
  };

  // 봇별 리스트 엑셀 다운
  const getBotGroupStaticsBotExcel = async (searchParams) => {
    searchParams.serviceId = serviceId
    searchParams.serviceName = serviceName
    try {
      const res = await getBotGroupStaticsBotExcelApi(searchParams);
      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_봇그룹통계_봇별조회_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      alert('봇 그룹 통계 봇별 엑셀 다운에 실패했습니다.');
    }
  };

  const getBotGroups = async (serviceId, botGroupId, jobType) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, jobType, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
      setBotGroupList(sortBotGroups);
      const firstBotGroupId = botGroupId || fp.getOr('', '[0].botGroupId', sortBotGroups);
      const botGroupName = fp.pipe(
        fp.getOr([], 'data.data.content'),
        fp.find((obj) => obj.botGroupId == firstBotGroupId),
        fp.getOr('', 'botGroupName')
      )(res);

      changeBotGroupBotStaticsSearchParams('botGroupName', botGroupName);
      changeBotGroupBotStaticsSearchParams('botGroupId', firstBotGroupId);
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 목록 조회에 실패했습니다. 봇 그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupList([]);
    }
  };

  useEffect(() => {
    if (!serviceId) return;
    getBotGroups(serviceId);
  }, [serviceId]);

  return {
    botGroupBotStaticsSearchParams, // 조회 조건
    latestBotGroupSearchParams,
    botGroupBotStaticsRes, // 봇그룹 봇별 통계 데이터
    botGroupDetailStaticsRes,
    serviceList,
    serviceId,
    serviceName,
    botGroupList,
    isBotGroupStaticsBotSearch,
    changeBotGroupBotStaticsSearchParams, // 조회 조건 변경
    getBotGroups,
    getBotGroupStaticsBot,
    getBotGroupStaticsBotExcel,
    getBotGroupStaticsDetail,
  };
};

export default useBotGroupBotStatic;
