import axios from 'axios';
import dayjs from 'dayjs';
import { AICC_PORTAL_API_URL } from 'libs/Constants';
import fp from 'lodash/fp';
import { useEffect, useState } from 'react';
import { CHANGING_RECORDS_SEARCH_PARAMS } from '../constants';
import { convertSortObjectToString, customSort } from 'libs/utiles';
import {
  getCallDialogsApi,
  getCallHistoryExcelDownloadApi,
  getFullVoiceDownApi,
  getUtteranceVoiceDownApi,
} from '../apis';
import {useSelector} from "react-redux";
import {useServiceList} from "../../../libs/DataHook";

const DEFAULT_RECORDS_SEARCH_PARAMS = {
  startDate: dayjs().format('YYYY-MM-DD'),
  endDate: dayjs().format('YYYY-MM-DD'),
  isAllSearch: true,
  pageNo: 0,
  pageSize: 10,
};

const useRecords = () => {
  const [recordsRes, setRecordsRes] = useState(null); // 콜 이력
  const [recordDetail, setRecordDetail] = useState(null); // 콜 이력 상세
  const [callDialogs, setCallDialogs] = useState([]); // 콜 이력 상세
  const [recordsSearchParams, setRecordsSearchParams] = useState(DEFAULT_RECORDS_SEARCH_PARAMS); // 조회 조건
  const [latestRecordsSearchParams, setLatestRecordsSearchParams] = useState(null);

  const serviceList = useServiceList();
  const {serviceId, serviceName} = useSelector((state) => state.service.value);
  const [botGroupList, setBotGroupList] = useState([]);
  const [isRecordSearch, setIsRecordSearch] = useState(false);

  useEffect(() => {
    if(serviceId && serviceName) {
      chageRecordsSearchParams('serviceId', serviceId)
      chageRecordsSearchParams('serviceName', serviceName)
    }
  }, [serviceId, serviceName])

  // 조회 조건 변경
  const chageRecordsSearchParams = (key, value) => {
    if (key in CHANGING_RECORDS_SEARCH_PARAMS) {
      setRecordsSearchParams((prev) => ({
        ...prev,
        ...CHANGING_RECORDS_SEARCH_PARAMS,
        [key]: value,
      }));
    } else {
      setRecordsSearchParams(fp.set(key, value));
    }
  };

  // 대화 이력 조회
  const getRecordsApi = async (searchParams, isSort = false) => {
    if (!searchParams.botGroupId) {
      alert('조회 가능한 봇 그룹이 없습니다.');
      return;
    }
    try {
      setIsRecordSearch(true);
      const res = await axios({
        url: AICC_PORTAL_API_URL + '/api/v1/records',
        method: 'GET',
        params: isSort
          ? {
              ...searchParams,
              sort: searchParams.sort
                ? convertSortObjectToString(searchParams.sort)
                : convertSortObjectToString({ start_datetime: 'desc' }),
            }
          : searchParams,
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setRecordsRes(fp.getOr({}, 'data.data', res));

      const botGroupName = fp.pipe(
        fp.find({ botGroupId: searchParams.botGroupId }),
        fp.getOr('', 'botGroupName')
      )(botGroupList);
      setLatestRecordsSearchParams({ ...searchParams, botGroupName });
    } catch (error) {
      console.log('error', error?.message);
      alert('대화 이력 목록 조회에 실패했습니다.');
      setRecordsRes({});
    }
  };

  // 콜 이력 엑셀
  const getCallHistoryExcelDownload = async (searchParams) => {
    try {
      const res = await getCallHistoryExcelDownloadApi(searchParams);

      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_콜이력조회_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.log('error', error?.message);
    }
  };

  // 대화 이력 상세 조회
  const getRecordDetailApi = async (callId) => {
    try {
      const res = await axios({
        url: AICC_PORTAL_API_URL + '/api/v1/records',
        method: 'GET',
        params: callId,
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setRecordDetail(fp.getOr({}, 'data.data.list.content[0]', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('대화 이력 목록 조회에 실패했습니다.');
      setRecordDetail({});
    }
  };

  // 콜 대화 이력 조회
  const getCallDialogs = async (callId) => {
    try {
      const res = await getCallDialogsApi(callId);
      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setCallDialogs(fp.getOr([], 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('대화 이력 조회에 실패했습니다.');
    }
  };

  const getBotGroupsApi = async (serviceId, botGroupId, jobType) => {
    try {
      const res = await axios({
        url: AICC_PORTAL_API_URL + `/api/v1/service/${serviceId}/bot-groups`,
        method: 'GET',
        params: {
          pageNo: 0,
          pageSize: 1000,
          jobType: jobType ? jobType : null,
        },
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
      setBotGroupList(sortBotGroups);
      const firstBotGroupId = botGroupId || fp.getOr('', '[0].botGroupId', sortBotGroups);
      chageRecordsSearchParams('botGroupId', firstBotGroupId);
    } catch (error) {
      console.log('error', error?.message);
      alert('서비스 목록 조회에 실패했습니다. 서비스 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupList([]);
    }
  };

  // 전체 녹취 다운로드
  const getFullVoiceDown = async (callId, createdDate) => {
    try {
      const res = await getFullVoiceDownApi(callId, createdDate);

      // Blob 객체로 변환
      const url = window.URL.createObjectURL(new Blob([res.data]));
      return url;
    } catch (error) {
      console.log('Download error:', error);
      return '';
    }
  };

  // 발화 녹취 다운로드
  const getUtteranceVoiceDown = async (callId, seq) => {
    try {
      const res = await getUtteranceVoiceDownApi(callId, seq);

      const pcmArrayBuffer = await res.data.arrayBuffer();

      return { callId, seq, pcm: pcmArrayBuffer };
    } catch (error) {
      console.log('Download error:', error);
      return {};
    }
  };

  useEffect(() => {
    if (!serviceId) return;
    getBotGroupsApi(serviceId);

    const serviceName = fp.pipe(
      fp.find((obj) => obj.serviceId === serviceId),
      fp.getOr('', 'name')
    )(serviceList);

    chageRecordsSearchParams('serviceName', serviceName);
  }, [serviceId]);

  return {
    recordsSearchParams,
    latestRecordsSearchParams,
    recordsRes,
    recordDetail,
    callDialogs,
    serviceList,
    serviceId,
    serviceName,
    botGroupList,
    isRecordSearch,
    chageRecordsSearchParams,
    getRecordsApi,
    getBotGroupsApi,
    getCallDialogs,
    getRecordDetailApi,
    getCallHistoryExcelDownload,
    getFullVoiceDown,
    getUtteranceVoiceDown,
  };
};

export default useRecords;
