import { useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Title from 'components/common/Title';
import Select from 'components/elements/Select';
import Pagination from 'components/common/Pagination';
import Table from 'components/common/Table';
import Button from 'components/elements/Button';
import dayjs from 'dayjs';
import DateRange from 'components/common/DateRange';
import Filter from 'components/common/Filter';
import { SubTableTitle, CountingTitle } from 'style/AutoQAStyle';
import ButtonList from 'components/common/ButtonList';
import LayerPopup from 'components/common/LayerPopup';
import SearchBoxPopup from '../consultationEvaluation/popups/SearchPopup';
import SearchBox from 'components/common/SearchBox';

const ConversationHistoryPage = () => {
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [openPopup, setPopupOpen] = useState(false); // 사용자 검색 팝업
  const navigate = useNavigate();
  return (
    <>
      {openPopup && // 사용자명 검색 팝업
        <LayerPopup
          title={'사용자 검색'}
          customWidth={800}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <SearchBoxPopup onClose={() => setPopupOpen(false)} title={'사용자 검색'} />
        </LayerPopup>
      }
      <Title title="대화 이력" icon="fileEdit" />
      <Filter>
        <SearchBox
          placeholder={'사용자명을 입력해주세요'}
          label="사용자명 검색"
          onClick={() => setPopupOpen(true)}
        />
        <Select
          option={[]}
          label="전체 선택"
          value={null}
          disabled={false}
          title={'전체'}
          onChange={() => { console.log('select!') }}
        />
        <DateRange
          rangeCal
          utilMenu
          label="조회 기간"
          monthsShown={2}
          selectsRange
          format="YYYY-MM-DD"
          startDate={dayjs(startDate).toDate()}
          endDate={dayjs(endDate).toDate()}
          selected={dayjs(startDate).toDate()}
          disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
          disableNum={3}
          maxDate={dayjs().toDate()}
          onChange={(value) => {
            setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
            setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
          }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>
      <SubTableTitle>
        <CountingTitle/>
        <ButtonList buttonList={[
          { label: '다운로드', className: 'secondary download', onClick: () => { } },
        ]} />
      </SubTableTitle>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="240px" />
            <col width="777px" />
            <col width="360px" />
            <col width="200px" />
          </colgroup>
          <thead>
            <tr>
              <th >사용자</th>
              <th >제목</th>
              <th >대화 일시</th>
              <th>상태</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr><td colSpan={5}><NoData txt={'데이터가 없습니다'}/></td></tr> 
               */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index} onClick={() => navigate('/conversationHistory/detail')}>
                <td>김상담</td>
                <td>시니어 요금 종류 알려줘.​</td>
                <td>2024-11-11 11:11:11</td>
                <td>진행 중</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  )
};

export default ConversationHistoryPage;