import React from "react";
import { Chart as ChartJS, BarElement, CategoryScale, LinearScale, Tooltip } from "chart.js";
import { StackBarContainer, StackBarLabels, StackBarLabelItem } from "style/AutoQAStyle";
import { Bar } from "react-chartjs-2";

ChartJS.register(BarElement, CategoryScale, LinearScale, Tooltip);

const HorizontalStackedBarChartRotate = ({ labels, colors, datas, width, height }) => {
  const data = {
    labels: ["점수 분포"], // 가로축에 단일 라벨 추가
    datasets: labels.map((label, index) => ({
      label: label,
      data: [datas[index]],
      backgroundColor: colors[index],
      borderWidth: 0,
      barThickness: 30,
    })),
  };

  const options = {
    indexAxis: "y", // 가로 방향 설정
    responsive: true,
    maintainAspectRatio: false, // 비율 유지 해제
    plugins: {
      datalabels: { display: false }, // 그래프 위 수치 표시 비활성화
      legend: { display: false }, // 범례 숨김
      tooltip: {
        enabled: true,
        position: "nearest",
        callbacks: {
          label: (tooltipItem) => `${tooltipItem.dataset.label} : ${tooltipItem.raw}%`,
        },
      },
    },
    scales: {
      x: {
        stacked: true,
        grid: { display: false, drawBorder: false }, // x축 그리드와 테두리 숨김
        beginAtZero: true,
        max: 100,
        ticks: { display: false, padding: 5 }, // x축 라벨 숨김
      },
      y: {
        stacked: true,
        grid: { display: false, drawBorder: true }, // y축 그리드와 테두리 숨김
        ticks: { display: false, padding: 5, }, // y축 라벨 숨김
      },
    },
    layout: {
      padding: {
        top: 0,    // 위쪽 여백
        bottom: 18, // 아래쪽 여백
        left: -8,   // 왼쪽 여백
        right: 0,  // 오른쪽 여백
      },
    },
  };


  // 누적 데이터를 계산하는 함수
  const getCumulativeData = () => {
    let cumulativeData = [];
    let cumulativeSum = 0;
    datas.forEach((dataPoint) => {
      cumulativeSum += dataPoint;
      cumulativeData.push(cumulativeSum);
    });
    return cumulativeData;
  };

  const cumulativeData = getCumulativeData();

  let filteredLabels = [];
  let filteredPositions = [];

  return (
    <StackBarContainer width={width} height={height}>
      <div style={{ width: width + 'px', height: '59px', position: 'relative', overflow: 'visible', paddingTop: '5px',zIndex:1 }}>
        <Bar data={data} options={options} />
      </div>

      <StackBarLabels rotate={'rotate'}>
      {datas.map((dataPoint, index) => {
          const cumulativePosition = (cumulativeData[index] - dataPoint) * (width / 100);// 각 데이터의 시작 위치 계산
          const prevCumulativePosition = index > 0 ? (cumulativeData[index - 1] - datas[index - 1]) * (width / 100) : 0;// 이전 아이템 위치 계산
          const condition = index > 0 && cumulativePosition - prevCumulativePosition < 60; //겹쳐질 수 있는 조건

          if (condition) { //겹쳐지는 조건이면 따로 처리해야함
            filteredLabels.push(labels[index]);
            filteredPositions.push(cumulativePosition);
            return null;
          }

          return ( //기본 라벨 그리기
            <StackBarLabelItem key={index} left={cumulativePosition} rotate={'rotate'}>
              <span>{labels[index]}</span>
              <p>{dataPoint}%</p>
            </StackBarLabelItem>
          );
        })}

        {filteredLabels.map((label, index) => { //겹치는 라벨 그리기
          let adjustedPosition = filteredPositions[index] + 50 * (index + 1);

          return (
            <StackBarLabelItem key={`filtered-${index}`} left={adjustedPosition} rotate={'rotate'}>
              <span>{label}</span>
              <p>{datas[labels.indexOf(label)]}%</p>
            </StackBarLabelItem>
          );
        })}
      </StackBarLabels>
    </StackBarContainer>
  );
};

export default HorizontalStackedBarChartRotate;
