import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import Table from "components/common/Table";
import React from "react";
import NoData from "components/common/NoData";
import { TotalScore } from "style/AutoQAStyle";

const _tempList_ = [
  {
    name: 'CS 자동 > 기본인사 > 첫 인사',
    desc: '고객에게 첫 인사를 했는가?',
    cnt: 40,
    details: ['첫인사 스크립트 준수', '상담사 이름 소개']
  },
  {
    name: 'CS 자동 > 기본인사 > 마무리 인사',
    desc: '고객에게 마무리 인사를 했는가?',
    cnt: 25,
    details: ['상담사 이름 소개','요금제 별 가격 안내']
  },
  {
    name: 'CS 자동 > 상품안내 > 요금안내',
    desc: '고객에게 정확한 요금을 했는가?',
    cnt: 35,
    details: ['테스트0000']
  }
];

const EvaluationSheetPreview = ({ text1, text2 }) => {
  return (
    <>
      <GrayBox direction={'column'}>
        <FormItem label={'평가표 명'} marginB={8}>
          <p>{text1}</p>
        </FormItem>
        <FormItem label={'상담 유형'}>
          <p>{text2}</p>
        </FormItem>
      </GrayBox>
      <div style={{ marginTop: '32px' }}>
        <Table className="active" fixedHeader={true} height="492" hover={false} interval={true} round={false}>
          <table className="hover">
            <caption>평가표 조회</caption>
            <colgroup>
              <col width="466px" />
              <col width="500px" />
              <col width="130px" />
            </colgroup>
            <thead>
              <tr>
                <th className="t-left left-padding">평가 항목</th>
                <th className="t-left left-padding">평가 항목 설명</th>
                <th>배점</th>
              </tr>
            </thead>
            <tbody>
              {_tempList_.length > 0 ?
                _tempList_.map((item, index) => {
                  return (
                    <React.Fragment key={index}>
                      <tr>
                        <td className="t-left left-padding gray">{item.name}</td>
                        <td className="t-left left-padding gray">{item.desc}</td>
                        <td className="gray">{item.cnt}</td>
                      </tr>
                      {item.details.length > 0 && (
                        <tr key={`${index}-details`}>
                          <td colSpan={3}>
                            <ul className="popup-table">
                              {item.details.map((detail, i) => (
                                <li key={`${index}-${i}`}>
                                  <div><span className="detail-tag">세부 항목</span>{detail}</div>
                                  <p className="score">{item.cnt / 2}</p>
                                </li>
                              ))}
                            </ul>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  )
                }) :
                <tr><td colSpan={5}><NoData txt={'내용이 없습니다'} /></td></tr>
              }
            </tbody>
          </table>
        </Table>
      </div>
      <TotalScore border={false} height={70}>000</TotalScore>
    </>
  );
}

export default EvaluationSheetPreview;