import { useState } from 'react';

import Button from 'components/elements/Button';

import * as PS from 'style/Dashboard';
import AutoRefreshSetPopup from './AutoRefreshSetPopup';

const AutoRefreshSet = ({
  refrashData,
  autoRefrashTimeOption,
  setAutoRefrashTimeOption,
  onSaveCallback = () => {},
}) => {
  const [refreshOpen, setRefreshOpen] = useState(false);

  const options = [
    { id: '0', title: '설정안함' },
    { id: '5000', title: '5초' },
    { id: '10000', title: '10초' },
    { id: '15000', title: '15초' },
    { id: '30000', title: '30초' },
    { id: '60000', title: '1분' },
    { id: '300000', title: '5분' },
  ];

  const popupOpenHandler = () => {
    setRefreshOpen(!refreshOpen);
  };

  return (
    <PS.AutoRefreshSet>
      <div className="refresh-item">
        <strong className="auto-title">자동 새로고침 설정</strong>
        <Button
          label={options.find((obj) => obj.id === autoRefrashTimeOption)?.title}
          className="secondary down-small"
          onClick={popupOpenHandler}
        />
      </div>
      <div className="refresh-item">
        <Button
          label="새로고침"
          className="secondary repeat"
          btnType="icon"
          onClick={() => {
            refrashData();
          }}
        />
      </div>

      {refreshOpen && (
        <AutoRefreshSetPopup
          autoRefrashTimeOption={autoRefrashTimeOption}
          setAutoRefrashTimeOption={setAutoRefrashTimeOption}
          setRefreshOpen={setRefreshOpen}
          onSaveCallback={onSaveCallback}
        />
      )}
    </PS.AutoRefreshSet>
  );
};

export default AutoRefreshSet;
