import classnames from 'classnames';
import * as S from '../../style/ElementsStyle';
import React from 'react';

/**
 * vertical : label 위치 정렬 기본 baseline |  center
 * oveflow : 팝업 안에 ellipsis 적용위해 form-cont에 overflow hidden 처리 시 사용. defualat false
 */
const FormItem = ({
  flex,
  col,
  vertical,
  overflowCont,
  label,
  isLabel = false,
  id,
  hiddenLabel,
  tooltip,
  children,
  marginB,
}) => {
  const renderLabel = (label) => {
    if (!label) return null;
    const parts = label.split('*');
    return parts.map((part, index) => (
      <React.Fragment key={index}>
        {part}
        {index < parts.length - 1 && <span style={{ color: '#4E47D6' }}>*</span>}
      </React.Fragment>
    ));
  };

  return (
    <S.FormItem col={col} vertical={vertical} overflowCont={overflowCont} flex={flex} marginB={marginB}>
      {isLabel ? (
        <label className={classnames('form-label', { hidden: hiddenLabel })} htmlFor={id}>
          <span className="label">{renderLabel(label)}</span>
          {tooltip && tooltip}
        </label>
      ) : (
        <strong className={classnames('form-label', { hidden: hiddenLabel })}>
          <span className="label">{renderLabel(label)}</span>
          {tooltip && tooltip}
        </strong>
      )}
      <div className="form-cont">{children}</div>
    </S.FormItem>
  );
};

export default FormItem;
