import { useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

import Title from "components/common/Title";
import Button from "components/elements/Button";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import TextField from "components/elements/TextField";
import Select from "components/elements/Select";
import LayerPopup from "components/common/LayerPopup";
import { DetailPageContainer, DetailContentsWrap, DetailTitles, BackBtnWrap } from 'style/AutoQAStyle';
import dayjs from 'dayjs';
import DateRange from 'components/common/DateRange';
import Radio from "components/elements/Radio";
import ExtractPopup from "../popups/QaaExtractPopup";
import TransferListPopup from "../popups/QaaTransferlistPopup";
import EvaluationSheetSelect from "../popups/EvaluationSheetSelect";

const QAAEvaluationTabDetail = () => {
  const navigate = useNavigate();
  const [openPopup, setOpenPopup] = useState(false); //추출결과 팝업
  const [openSettingPopup, setOpenSettingPopup] = useState(false); // 대상 상담원, 평가자 설정 팝업
  const [openSelectPopup, setSelectPopup] = useState(false); //평가표 불러오기 팝업
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜      
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [radioValue, setRadioValue] = useState('type1');
  const [settingType, setPoptype] = useState('a');

  return (
    <>
      {openPopup && // 추출결과 팝업
        <LayerPopup
          size="large"
          title={`평가 대상 추출 상세 결과 (${radioValue === 'type1' ? `조건 추출` : `자동 평가 추출`})`}
          customWidth={910}
          open={openPopup}
          onClose={() => setOpenPopup(false)}
        >
          <ExtractPopup type={radioValue} />
        </LayerPopup>
      }

      {openSettingPopup && // 대상 상담원,평가자 설정 팝업 
        <LayerPopup
          size="large"
          title={`${settingType === 'a' ? '평가 상담사' : '평가자'} 설정`}
          customWidth={1200}
          open={openSettingPopup}
          onClose={() => setOpenSettingPopup(false)}
        >
          <TransferListPopup type={settingType} />
        </LayerPopup>
      }

      {openSelectPopup && // 평가표 불러오기 팝업
        <EvaluationSheetSelect onClose={() => setSelectPopup(false)} openIs={openSelectPopup} />
      }

      <Title title="QAA 평가 계획 생성" icon="evaluation" />
      <DetailPageContainer>
        <DetailContentsWrap padding={true}>
          {/* 평가 기준 설정 */}
          <DetailTitles>평가 기준 설정</DetailTitles>
          <GrayBox direction={'column'}>
            <FormItem label={'평가 계획명'} marginB={8}>
              <TextField disabled={false} width={561} placeholder={'평가 계획명을 입력하세요.'} count={20} maxLength={20} />
            </FormItem>
            <FormItem label={'평가표'} marginB={8}>
              <div style={{ display: 'flex', gap: '0 16px' }}>
                <TextField disabled={false} width={248} value={'평가표 명'} readOnly={true} />
                <Button label="불러오기" className={'primary wide'} onClick={() => setSelectPopup(true)} />
              </div>
            </FormItem>
            <FormItem label={'업무 유형'} marginB={8}>
              <Select
                option={[]}
                type={'simple'}
                title={'업무 유형'}
                onChange={() => { console.log('select!') }}
              />
            </FormItem>
            <FormItem label={'상담 유형'} marginB={8}>
              <div className="wrapping-item">
                <Select
                  option={[]}
                  type={'simple'}
                  title={'상담유형 1'}
                  disabled={true}
                  onChange={() => { console.log('select!') }}
                />
                <Select
                  option={[]}
                  type={'simple'}
                  title={'상담유형 2'}
                  disabled={true}
                  onChange={() => { console.log('select!') }}
                />
                <Select
                  option={[]}
                  type={'simple'}
                  title={'상담유형 3'}
                  disabled={true}
                  onChange={() => { console.log('select!') }}
                />
              </div>
            </FormItem>
            <FormItem label={'평가 대상 기간'} marginB={8}>
              <DateRange
                rangeCal
                type="wide"
                utilMenu
                monthsShown={2}
                selectsRange
                format="YYYY-MM-DD"
                startDate={dayjs(startDate).toDate()}
                endDate={dayjs(endDate).toDate()}
                selected={dayjs(startDate).toDate()}
                disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
                disableNum={3}
                maxDate={dayjs().toDate()}
                onChange={() => { console.log('DateRange onChange') }}
                border={true}
              />
            </FormItem>
            <FormItem label={'평가 기간'} marginB={8}>
              <DateRange
                rangeCal
                type="wide"
                utilMenu
                monthsShown={2}
                selectsRange
                format="YYYY-MM-DD"
                startDate={dayjs(startDate).toDate()}
                endDate={dayjs(endDate).toDate()}
                selected={dayjs(startDate).toDate()}
                disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
                disableNum={3}
                maxDate={dayjs().toDate()}
                onChange={() => { console.log('DateRange onChange') }}
                border={true}
              />
            </FormItem>
            <FormItem label={'이의 신청 기간'}>
              <DateRange
                rangeCal
                type="wide"
                utilMenu
                monthsShown={2}
                selectsRange
                format="YYYY-MM-DD"
                startDate={dayjs(startDate).toDate()}
                endDate={dayjs(endDate).toDate()}
                selected={dayjs(startDate).toDate()}
                disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
                disableNum={3}
                maxDate={dayjs().toDate()}
                onChange={() => { console.log('DateRange onChange') }}
                border={true}
              />
            </FormItem>
          </GrayBox>

          {/* 평가 대상 설정 */}
          <DetailTitles>평가 대상 설정</DetailTitles>
          <GrayBox direction={'column'}>
            <FormItem label={'대상 상담원'} marginB={8}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <TextField disabled={false} width={248} />
                <span className="substr">명</span>
                <Button
                  label="설정"
                  className={'primary wide'}
                  onClick={() => {
                    setOpenSettingPopup(true);
                    setPoptype('a');
                  }}
                />
              </div>
            </FormItem>
            <FormItem label={'통화 길이'} marginB={8}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <TextField disabled={false} width={248} />
                <span className="substr">초 이상</span>
              </div>
              <span className="sub-gray-txt" style={{ marginTop: '8px', display: 'block' }}>* 최소 100초 이상 설정이 필요합니다.</span>
            </FormItem>
            <FormItem label={'콜 추출 방식'} marginB={8}>
              <div style={{ display: 'flex', gap: '0 24px', alignItems: 'center', height: '32px' }}>
                <Radio id="result1" checked={radioValue === 'type1'} onChange={() => setRadioValue('type1')} name="result">
                  조건 추출
                </Radio>
                <Radio id="result2" checked={radioValue === 'type2'} onChange={() => setRadioValue('type2')} name="result">
                  자동 평가 결과 참고 추출
                </Radio>
               
              </div>
              <span className="sub-gray-txt" style={{ marginTop: '8px', display: 'block',marginBottom:'13px' }}>
                * 조건 추출 : 대상 상담원, 통화 길이 기준이 추출됩니다. <br/>
                * 자동평가 결과 참고 추출 : 대상 상담원, 통화 길이, AI 평가 결과 기준이 추출됩니다.
              </span>
            </FormItem>
            {radioValue === 'type2' &&
              <FormItem label={'추출 비율'} marginB={8}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0 16px', }}>
                  <span className="substr withInput">상위　<TextField disabled={false} width={248} /></span>
                  <span className="substr withInput">중위　<TextField disabled={false} width={248} /></span>
                  <span className="substr withInput">하위　<TextField disabled={false} width={248} /></span>
                </div>
                <span className="sub-gray-txt" style={{ marginTop: '8px', display: 'block',marginBottom:'10px' }}>* 기재한 각 비율의 합은 반드시 100% 가 되어야 합니다.
              </span>
              </FormItem>
            }
            <FormItem label={'평가 최소 콜 수'} marginB={8}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <TextField disabled={false} width={248} />
                <span className="substr">건</span>
                <Button label="추출" className={'primary wide'} onClick={() => { }} />
              </div>
            </FormItem>
            <FormItem label={'추출 결과'}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <p className="substr btnstr" onClick={() => setOpenPopup(true)}>
                  총 820건 중
                  <span className="blue-point"> 188</span>건 추출 완료
                </p>
                <Button label="취소" className={'secondary'} onClick={() => { }} />
              </div>
              <span className="sub-gray-txt" style={{ marginTop: '8px', display: 'block'}}>
                * 상담원별 최소 8건, 최대 10건이 추출됩니다. 
              </span>
            </FormItem>
          </GrayBox>

          {/* 평가자 배정 설정 */}
          <DetailTitles>평가자 배정 설정</DetailTitles>
          <GrayBox direction={'column'}>
            <FormItem label={'평가자 설정'} marginB={8}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <TextField disabled={false} width={248} />
                <span className="substr">명</span>
                <Button
                  label="설정"
                  className={'primary wide'}
                  onClick={() => {
                    setOpenSettingPopup(true);
                    setPoptype('b');
                  }}
                />
              </div>
            </FormItem>
            <FormItem label={'배정 결과'}>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <div className="slice-item">
                  <p className="substr">김박사 <span className="blue-point">40</span>건</p>
                  <p className="substr">김박사 <span className="blue-point">40</span>건</p>
                  <p className="substr">김박사 <span className="blue-point">40</span>건</p>
                </div>
                <Button label="취소" className={'secondary'} onClick={() => { }} />
              </div>
            </FormItem>
          </GrayBox>

          <div style={{ marginTop: '26px', display: 'flex', 'justifyContent': 'end' }}>
            <Button label="저장" className={'primary wide'} onClick={() => { }} />
          </div>
        </DetailContentsWrap>
        <BackBtnWrap>
          <Button label="목록" className={'primary arrow-left-large'} onClick={() => navigate(-1)} />
        </BackBtnWrap>
      </DetailPageContainer>
    </>
  );
}

export default QAAEvaluationTabDetail;