import Title from "components/common/Title";
import Tab from "components/common/Tab";
import AbnolmalCallConsultationTypeTab from "./tabs/AbnolmalCallConsultationTypeTab";
import AbnolmalCallOrganizationTypeTab from "./tabs/AbnolmalCallOrganizationTypeTab";
import AbnolmalCallPeriodTypeTab from "./tabs/AbnolmalCallPeriodTypeTab";

const evaluationTabList = [
  {
    title: '기간별', //Period type 
    tabContent: <AbnolmalCallPeriodTypeTab/>
  },
  {
    title: '조직별', //organization type
    tabContent: <AbnolmalCallOrganizationTypeTab/>
  },
  {
    title: '상담 유형별', //consultation type
    tabContent: <AbnolmalCallConsultationTypeTab/>
  },
];
 
const AbnormalCallPage = () => {
  return (
    <>
      <Title title="이상 징후 통계" icon="graph" />
      <Tab tabList={evaluationTabList} />
    </>
  )
};

export default AbnormalCallPage;