import { useState } from 'react';

import FormItem from 'components/common/FormItem';
import GrayBox from 'components/common/GrayBox';
import FormGrid from 'components/common/FormGrid';
import TextField from 'components/elements/TextField';
import Button from 'components/elements/Button';
import Title from 'components/common/Title';
import Table from 'components/common/Table';
import ButtonList from 'components/common/ButtonList';
import * as S from '../../../../../style/ElementsStyle';
import Pagination from 'components/common/Pagination';
import Tooltip from 'components/common/Tooltip';
import NoData from 'components/common/NoData';
import { LayerPopupInHideBox, LayerInButtonWrap } from 'style/AutoQAStyle';

const SearchBoxPopupForGroup = ({ onClose, disabled }) => {
  const [showIs, setShowIs] = useState(false);
  const [user, setUser] = useState('');

  return (
    <>
      <GrayBox vertical="center">
        <FormGrid gap={12}>
          <FormItem label={'조직명'}>
            <TextField
              placeholder={"고객만족본부"}
              width={260}
              onChange={(value) => {
                setUser(value)
              }}
              disabled={disabled}
            />
          </FormItem>
        </FormGrid>
      </GrayBox>
      <LayerInButtonWrap>
        <Button label="조회" className="primary wide" onClick={() => setShowIs(true)} />
      </LayerInButtonWrap>

      {showIs &&  // 검색 버튼 클릭 후 노출될 테이블 영역
        <LayerPopupInHideBox>
          <Title
            title={'구성원'}
            type="sub"
            subTitle={`<span className="count">총 <strong>0</strong>명</span>`}
            tooltip={<Tooltip color={'white'}>구성원 변경은 사용자 관리 메뉴에서 가능하며 해당 페이지에서는 조회만 가능합니다.</Tooltip>}
          />
          <Table fixedHeader height="308" interval={false}>
            <table>
              <colgroup>
                <col width="168px" />
                <col width='180px' />
                <col width="220px" />
                <col width="128px" />
              </colgroup>
              <thead>
                <tr>
                  <th scope="col">사용자명</th>
                  <th>메뉴 접근 권한</th>
                  <th className="t-left left-padding">이메일</th>
                  <th>계정 상태</th>
                </tr>
              </thead>
              <tbody>
                {/***********************
                  데이터 없는 경우
              ***********************
               <tr className='thin'>
                  <td colSpan="4">
                    <NoData txt={`조회된 데이터가 없습니다.`} />
                  </td>
                </tr> */}
                {Array.from({ length: 5 }).map((_, index) => (
                  <tr key={index} className='thin'>
                    <td>김상담님</td>
                    <td>상담사</td>
                    <td className="t-left left-padding">test@test.com</td>
                    <td>정상</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Table>
          <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
          {!disabled &&
            <S.LayerPopupBtns>
              <div className="right-area">
                <ButtonList buttonList={[
                  { label: '취소', className: 'secondary', onClick: () => { onClose() } },
                  { label: '선택', className: 'primary', onClick: () => { }, disabled: false },
                ]} />
              </div>
            </S.LayerPopupBtns>}

        </LayerPopupInHideBox>
      }

    </>
  );
}

export default SearchBoxPopupForGroup;