import { useRef,useEffect } from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import * as S from '../../style/ChartStyle';
import { GraphTitleItem } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(ArcElement, Tooltip, Legend);

// 컬러표 : 파랑 : '#5C5FD6' 보라 : '#9D9FE6' 빨강 :'#F47356' ['#5C5FD6', '#9D9FE6', '#F47356' ]
const RatioDougnutChart = ({
  title,
  rate,
  labels,
  datas,
  colors = ['#5C5FD6', '#9D9FE6'],
  width,
  height,
  boldTitle,
}) => {
  
  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const data = {
    labels: labels,
    datasets: [
      {
        data: datas,
        backgroundColor: [...colors],
        borderColor: [...colors],
        hoverBackgroundColor: [...colors],
        hoverBorderColor: [...colors],
        borderWidth: 0,
        cutout: '60%',
      },
    ],
  };

  const legendContainer = useRef();

  const getOrCreateLegendList = () => {
    let listContainer = legendContainer.current.querySelector('ul');

    if (!listContainer) {
      listContainer = document.createElement('ul');
      legendContainer.current.appendChild(listContainer);
    }

    return listContainer;
  };

  const htmlLegendPlugin = {
    id: 'htmlLegend',
    afterUpdate(chart) {
      const ul = getOrCreateLegendList(chart);

      while (ul.firstChild) {
        ul.firstChild.remove();
      }

      const items = chart.options.plugins.legend.labels.generateLabels(chart);

      items.forEach((item) => {
        const li = document.createElement('li');
        li.onclick = () => {
          chart.toggleDataVisibility(item.index);
          chart.update();
        };

        // Color box
        const boxSpan = document.createElement('span');
        boxSpan.style.background = item.fillStyle;
        boxSpan.style.borderColor = item.strokeStyle;
        boxSpan.style.borderWidth = item.lineWidth + 'px';

        // Text
        const textContainer = document.createElement('p');
        textContainer.style.color = item.fontColor;
        textContainer.style.textDecoration = item.hidden ? 'line-through' : '';

        const text = document.createTextNode(item.text);
        textContainer.appendChild(text);

        li.appendChild(boxSpan);
        li.appendChild(textContainer);
        ul.appendChild(li);
      });
    },
  };

  const options = {
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        callbacks: {
          afterLabel: function (tooltipItem) {
            let total = 0;
            tooltipItem.dataset.data.forEach((item) => (total += Number(item)));
            const percent = Math.round((tooltipItem.formattedValue / total) * 100);
            return `(${percent}%)`;
          },
        },
      },
      datalabels: {
        display: false,
      },
    },
  };

  return (
    <S.RatioDoughnut>
      <div style={{marginBottom:'20px'}}>
        <GraphTitleItem>{boldTitle}</GraphTitleItem>
      </div>
      {title && (
        <div className="chart-title">
          <div className="title-area">
            <strong className="title">{title}</strong>
          </div>
        </div>
      )}
      <div className="inner">
        <S.RatioDoughnutCanvas width={width} height={height}>
          {rate && <span className="rate">{rate}</span>}
          <Doughnut data={data} options={options} plugins={[htmlLegendPlugin]} />
        </S.RatioDoughnutCanvas>
        <div ref={legendContainer} className="legend"></div>
      </div>
    </S.RatioDoughnut>
  );
};

export default RatioDougnutChart;
