import { useState } from 'react';
import { CustomChatElementWrapContainer, ChatInputWrap } from "style/AutoQAStyle";
import LikeButton from "components/elements/LikeButton";
import PdfViewerWithPopup from "components/common/PdfViewerWithPopup";

/**
 * 
 * list           : 채팅 리스트
 * width          : 컨테이너 너비
 * height         : 컨테이너 높이
 * searchInput    : 하단 검색영역 노출여부
 */

const CustomChatElementWrap = ({ list, width, height, searchInput }) => {
  const [selectedPdfUrl, setSelectedPdfUrl] = useState(null);
  const openPdfViewer = (url) => {
    setSelectedPdfUrl(url);
  };

  const closePdfViewer = () => {
    setSelectedPdfUrl(null);
  };

  return (
    <CustomChatElementWrapContainer as="div" width={width} height={height}>
      <div className="chat-list">
        {list.map((item, index) => {
          return (
            item.type === 'tester' ?
              <div className="customer-chat" key={index}>
                <div className="bubble">
                  <p className="chat-text">{item.msg}​</p>
                </div>
                <span className="date">{item.time_stamp}</span>
              </div>
              :
              <div className="counselor-chat" key={index}>
                <div className="bubble">
                  <p className="chat-text">{item.msg}
                  </p>
                  {item.file.length > 0 &&
                    <ul className="file-list">
                      {item.file.map((fileItem, idx) => {
                        return <li key={idx} onClick={() => openPdfViewer()}>{fileItem.title}</li>
                      })}
                    </ul>
                  }
                </div>
                <div className="like-wrap">
                  <span className="date">{item.time_stamp}</span>
                  <LikeButton name={`likeRadio-${index}`} />
                </div>
              </div>
          );
        })}
      </div>
      {searchInput &&
        <ChatInputWrap>
          <textarea name="" id="" placeholder={'검색어를 입력하세요'}></textarea>
          <button/>
        </ChatInputWrap>
      }
      {(selectedPdfUrl !== null )&& (
        <PdfViewerWithPopup
          selectedPdfUrl={selectedPdfUrl}
          closePdfViewer={closePdfViewer}
        />
      )}
    </CustomChatElementWrapContainer>
  )
};

export default CustomChatElementWrap;


