import * as S from '../../style/ElementsStyle';

/**
 * icon : warning-fill(노란 삼각! default) |  ...
 * simple : table밖으로 위아래 라인있는 타입
 */
const NoData = ({ icon = 'warning-fill', txt, height, simple }) => {
  return (
    <S.NoData height={height} simple={simple}>
      {icon !== '' && <i className={`icon ${icon}`}></i>}
      <p className="txt">{txt}</p>
    </S.NoData>
  );
};

export default NoData;
