import DashboardAside from 'components/layouts/DashboardAside';
import DashboardHeader from 'components/layouts/DashboardHeader';
import * as S from '../../../style/LayoutStyle';
import { Outlet } from 'react-router-dom';

import { tempMenuList } from './MenuList';

const TempLayouts = () => {
  
  const user = '테스트';

  return (
    <S.DashboardLayout>
      <DashboardAside menuList={tempMenuList} />
      <S.Contents>
        <DashboardHeader user={user} />
        <S.SubContents>
          <Outlet />
        </S.SubContents>
      </S.Contents>
    </S.DashboardLayout>
  );
}

export default TempLayouts;