import { useState } from "react";
import { WideLayerGrid } from "style/AutoQAStyle";
import IconTab from "components/common/IconTab";
import ChatElementWrap from "components/common/ChatElementWrap";
import AutoCheckTab from "../tabs/AutoCheckTab";
import ManualCheckTab from "../tabs/ManualCheckTab";
import ItemGraph from "components/common/ItemGraph";
import { GraphBox, GraphWraps, DashboardContainer,DashbordInScoreWrap } from "style/AutoQAStyle";
import RadarChart from "components/chart/RadarChart";

const tabLists = [
  {
    icon: 'noteIcon',
    title: '자동 평가',
    tabContent: <AutoCheckTab />
  },
  {
    icon: 'writeIcon',
    title: '수동 평가',
    tabContent: <ManualCheckTab />
  }
];

const ExcellentCallManagementPopup = () => {
  const [activeTabIndex, setActiveTabIndex] = useState(0); // 현재 선택된 탭 인덱스 관리
  const graphData = activeTabIndex === 0 ? [100, 90, 90, 90, 80] : [90, 90, 50, 30, 80];
  
  return (
    <>
      <WideLayerGrid>
        <div style={{ width: '652px' }}>
          <h5 className="icon-title">
            <img src={process.env.PUBLIC_URL+'/images/ico-tab-title.svg'} alt='icon' />
            평가 결과
          </h5>
          <div className="content-wrap">
            <DashboardContainer>
              <GraphWraps>
                <GraphBox width={260} height={207} >
                  <DashbordInScoreWrap>
                    <h5>평가 점수</h5>
                    <p>{activeTabIndex === 0 ? '100' : '111'}</p>
                  </DashbordInScoreWrap>
                </GraphBox>
                <GraphBox width={387} height={207} flexIs={'center'}>
                  <ItemGraph
                    gapIs={false}
                    graph={[
                      {
                        graph: (
                          <RadarChart
                            title={'평가 항목'}
                            legends={[]}
                            colors={['#5C5FD6']}
                            width={206}
                            height={140}
                            labels={["가입상담", "품질상담", "요금상담", "혜택상담", "해지상담"]}
                            datas={[graphData]}
                          />
                        ),
                      },
                    ]}
                  />
                </GraphBox>
              </GraphWraps>
            </DashboardContainer>
            <IconTab tabList={tabLists} height={'auto'} tabClickCallback={(index) => setActiveTabIndex(index)} />
          </div>
        </div>
        <div style={{ width: '691px' }}>
          <h5 className="icon-title">
            <img src={process.env.PUBLIC_URL+'/images/ico-tab-title2.svg'} alt='icon' />
            상담 내역
          </h5>
          <div className="content-wrap">
            <ChatElementWrap waveIs={true} isChatInput={false} />
          </div>
        </div>
      </WideLayerGrid>
    </>
  )
};

export default ExcellentCallManagementPopup;

