import { Link } from 'react-router-dom';
import * as S from 'style/LayoutStyle';
import SktEnterprise from '../elements/SktEnterprise';

const menuItems = [{ url: '/main/openSource', name: '오픈소스 라이선스' }];

const MenuFooter = () => {
  return (
    <S.AsideFooter>
      {menuItems.map((item, index) => (
        <li key={index}>
          <Link to={item.url}>
            <span>{item.name}</span>
          </Link>
        </li>
      ))}
      <SktEnterprise />
    </S.AsideFooter>
  );
};

export default MenuFooter;
