import axios from 'axios';
import ButtonList from 'components/common/ButtonList';
import FormGrid from 'components/common/FormGrid';
import FormItem from 'components/common/FormItem';
import GrayBox from 'components/common/GrayBox';
import NoData from 'components/common/NoData';
import Pagination from 'components/common/Pagination';
import Table from 'components/common/Table';
import Title from 'components/common/Title';
import Checkbox from 'components/elements/Checkbox';
import Select from 'components/elements/Select';
import TextField from 'components/elements/TextField';
import {
  AICC_PORTAL_API_URL,
  JOB_TYPE_INBOUND,
  JOB_TYPE_OUTBOUND,
  getJobTypeName,
} from 'libs/Constants';
import { useJobEngineJobList } from 'libs/DataHook';
import { useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';
import { showToastNotice } from 'redux/toast';
import * as PS from 'style/Configuration';
import * as S from 'style/ElementsStyle';

const PAGE_SIZE = 10;

const jobOptions = [
  { id: JOB_TYPE_INBOUND.code, title: JOB_TYPE_INBOUND.name },
  { id: JOB_TYPE_OUTBOUND.code, title: JOB_TYPE_OUTBOUND.name },
];

const ErrorCode = {
  // TODO: 임시 error 객체, 추후 리팩토링 필요
  5002: { // JOB_ALREADY_EXIST
    message: '요청하신 사항을 처리할 수 없습니다. 다시 확인해 주세요.',
    messagePostfix: '',
  },
  6003: { // BOT_GROUP_JOB_MAPPING_INVALID_CALLPOINT_RANGE
    message: '입력하신 Call Point의 범위에 오류가 있습니다.',
    messagePostfix: '',
  },
  6006: { // BOT_GROUP_JOB_MAPPING_INVALID_CALLPOINT_LENGTH
    message: '입력하신 Call Point의 길이에 오류가 있습니다.',
    messagePostfix: '',
  },
  6007: { // BOT_GROUP_JOB_MAPPING_DUPLICATE_CALLPOINT_EXISTS
    message: '이미 사용 중인 Call Point가 입력된 Job이 있습니다.',
    messagePostfix: '입력하신 Call Point 정보를 확인해주세요.',
  },
  6008: { // BOT_GROUP_JOB_MAPPING_CALLPOINT_END_LESSER_THAN_CALLPOINT_START
    message:
      "'Call Point 시작'보다 'Call Point 끝'이 커야 합니다. (Call Point가 한 개일 경우에는 'Call Point 시작'과 'Call Point 끝'을 동일하게 입력해야 합니다.)",
    messagePostfix: '',
  },
  UNKNOWN_ERROR: {
    message: '알 수 없는 오류로 실패한 Job이 있습니다.',
    messagePostfix: '',
  },
};

const isNumeric = (str) => /^[0-9]*$/.test(str);

const JobRegister = ({ serviceId, currentJobCount, maxJobCount, onClose }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);
  const [step, setStep] = useState(1);
  const [pageNo, setPageNo] = useState(0);
  const [jobType, setJobType] = useState('');
  const [fullJobList, setFullJobList, getDataAtPage, totalCount, totalPages] = useJobEngineJobList();
  const [jobList, setJobList] = useState([]);

  const [jobListMap, setJobListMap] = useState(new Map());
  const [selectedJobs, setSelectedJobs] = useState(new Map());

  useEffect(() => {
    if (jobType === '') {
      return;
    }
    setFullJobList(serviceId, jobType, PAGE_SIZE);
  }, [jobType, serviceId, PAGE_SIZE]);

  useEffect(() => {
    setJobList(getDataAtPage(pageNo, PAGE_SIZE));
  }, [fullJobList, pageNo, PAGE_SIZE]);

  useEffect(() => {
    setSelectedJobs(new Map());
    setPageNo(0);
  }, [jobType]);

  useEffect(() => {
    setJobListMap(fullJobList.reduce((map, obj) => {
      map.set(obj.jobId, obj);
      return map;
    }, new Map()));
  }, [fullJobList]);

  const buildJobObject = (jobId) => {
    const job = jobListMap.get(jobId);
    return {
      serviceId: serviceId,
      jobId: job.jobId,
      jobName: job.name,
      jobType: job.jobType,
      callpointStart: '',
      callpointEnd: '',
    };
  };

  const nextStep = () => {
    if (step === 1 && !isOverMaxJobCount()) {
      setStep(2);
    }
  };
  const backStep = () => {
    if (step === 2) {
      setStep(1);
    }
  };

  const handleJobRowClick = (event) => {
    const jobId = event.currentTarget.getAttribute('data-job-id');
    // Checkbox 클릭으로 인한 중복 event 무시
    if (event.target.tagName === 'INPUT') {
      return;
    }

    // 이미 선택된 Job일 경우, 선택 항목에서 제거
    const newSelectedJobs = new Map(selectedJobs);
    newSelectedJobs.delete(jobId);

    // 기존에 선택되지 않은 Job일 경우, 선택 항목에 추가
    if (newSelectedJobs.size === selectedJobs.size) {
      newSelectedJobs.set(jobId, buildJobObject(jobId));
    }

    setSelectedJobs(newSelectedJobs);
  };

  const isAllSelected = () => {
    if (jobList.length === 0) {
      return false;
    }
    return jobList.every((job) => selectedJobs.has(job.jobId));
  };

  const handleSelectAll = (event) => {
    const { checked } = event.target;
    const newSelectedJobs = new Map(selectedJobs);

    if (checked) {
      jobList.forEach((job) => newSelectedJobs.set(job.jobId, buildJobObject(job.jobId)));
    } else {
      jobList.forEach((job) => newSelectedJobs.delete(job.jobId));
    }
    setSelectedJobs(newSelectedJobs);
  };

  const _inputChanged = (event, jobId, type) => {
    const newSelectedJobs = new Map(selectedJobs);
    const job = newSelectedJobs.get(jobId);
    if (type === 'start') {
      job.callpointStart = event.target.value;
    } else {
      job.callpointEnd = event.target.value;
    }
    setSelectedJobs(newSelectedJobs);
  };

  const isOverMaxJobCount = () => {
    if (selectedJobs.size + currentJobCount > maxJobCount) {
      alert(
        `Job은 최대 ${maxJobCount}개까지 등록 가능합니다.\n\n기존에 등록된 Job을 등록 취소하신 후, 다시 시도해주세요.`
      );
      return true;
    }
    return false;
  };

  const areCallpointsEntered = () => {
    return Array.from(selectedJobs.values()).every(
      (job) => job.callpointStart.trim() !== '' && job.callpointEnd.trim() !== ''
    );
  };

  const getJobsWithInvalidCallpoints = () => {
    return Array.from(selectedJobs.values()).filter((job) => {
      const start = job.callpointStart.trim();
      const end = job.callpointEnd.trim();

      const areNotEmpty = start !== '' && end !== '';
      const areNumeric = isNumeric(start) && isNumeric(end);
      const isEndGreaterOrEqual = Number.parseInt(start) <= Number.parseInt(end);
      const areLengthsEqual = start.length === end.length;

      return !(areNotEmpty && areNumeric && isEndGreaterOrEqual && areLengthsEqual);
    });
  };

  const registerJobs = async (event) => {
    if (isLoading) {
      return;
    }
    if (isOverMaxJobCount()) {
      return;
    }

    if (jobType === JOB_TYPE_INBOUND.code) {
      const invalidJobList = getJobsWithInvalidCallpoints();
      if (invalidJobList.length > 0) {
        alert(
          '유효하지 않은 Call Point가 입력된 Job이 있습니다. 다음을 확인해주세요.\n\n' +
            ' * Call Point에는 숫자만 입력 가능합니다.\n' +
            " * 'Call Point 시작'보다 'Call Point 끝'이 커야 합니다. (Call Point가 한 개일 경우에는 'Call Point 시작'과 'Call Point 끝'을 동일하게 입력해야 합니다.)\n" +
            " * 'Call Point 시작'과 'Call Point 끝'의 자릿수가 동일해야 합니다.\n" +
            invalidJobList.map((job) => job.jobName).join('\n')
        );
        return;
      }
    }

    setIsLoading(true);
    const requestURL = AICC_PORTAL_API_URL + `/api/v1/service/${serviceId}/jobs`;
    const failedJobsByErrorCode = {};

    const requestArr = Array.from(selectedJobs.values()).map((job) =>
      axios
        .post(requestURL, job)
        .then((response) => {
          console.log(response);
        })
        .catch((error) => {
          console.log(error);
          const { errorCode } = error.response.data;
          if (!!errorCode && Object.prototype.hasOwnProperty.call(ErrorCode, errorCode)) {
            failedJobsByErrorCode[errorCode] ??= [];
            failedJobsByErrorCode[errorCode].push(job);
          } else {
            failedJobsByErrorCode['UNKNOWN_ERROR'] ??= [];
            failedJobsByErrorCode['UNKNOWN_ERROR'].push(job);
          }
        })
    );

    await Promise.all(requestArr);
    console.log(failedJobsByErrorCode);
    const failedJobsByErrorCodeList = Object.entries(failedJobsByErrorCode);

    if (failedJobsByErrorCodeList.length === 0) {
      dispatch(showToastNotice({ toastType: 'INFO', toastMsg: 'Job 등록이 완료되었습니다.' }));
    } else {
      const alertMsg = failedJobsByErrorCodeList.reduce((currentMsg, [errorCode, jobs]) => {
        return (
          currentMsg +
          [
            ErrorCode[errorCode].message,
            ...jobs.map((job) => job.jobName),
            ErrorCode[errorCode].messagePostfix,
          ].join('\n') +
          '\n'
        );
      }, '');
      alert(alertMsg);
    }
    onClose(event, true);
    setIsLoading(false);
  };

  return (
    <PS.PopupJobRegister>
      {/* STEP 1 */}
      <div style={{ display: step === 1 ? 'block' : 'none' }}>
        <GrayBox>
          <FormGrid>
            <FormItem label="Job 유형 선택">
              <Select
                type="simple"
                title="Job 유형 선택"
                option={jobOptions}
                value={jobType}
                onChange={(event) => setJobType(event)}
              />
            </FormItem>
          </FormGrid>
        </GrayBox>

        <Title
          subTitle={`<span className="count">선택 <strong>${selectedJobs.size}</strong>개</span>`}
          subNoLine
        />

        <Table scroll hover={jobList.length > 0} height={400} fixedHeader>
          <table>
            <caption>Job명, 유형, 채널수에 관한 표</caption>
            <colgroup>
              <col width="50px" />
              <col />
              <col width="200px" />
              <col width="140px" />
            </colgroup>
            <thead>
              <tr>
                <th scope="col">
                  <Checkbox
                    checked={isAllSelected()}
                    callback={handleSelectAll}
                    disabled={jobList.length === 0}
                    indeterminate={jobList.some((job) => selectedJobs.has(job.jobId))}
                    hiddenLabel
                  >
                    등록 선택
                  </Checkbox>
                </th>
                <th scope="col" className="t-left">
                  Job명
                </th>
                <th scope="col">유형</th>
                <th scope="col">채널수</th>
              </tr>
            </thead>
            <tbody>
              {jobList.length > 0 ? (
                jobList.map((job) => (
                  <tr
                    key={job.jobId}
                    data-job-id={job.jobId}
                    className={job.registered ? 'job-row__disabled' : undefined}
                    onClick={job.registered ? undefined : handleJobRowClick}
                  >
                    <td>
                      <Checkbox
                        checked={selectedJobs.has(job.jobId)}
                        disabled={job.registered}
                        hiddenLabel
                      />
                    </td>
                    <td className="t-left title">{job.name}</td>
                    <td>{getJobTypeName(job.jobType)}</td>
                    <td>{job.channels}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4}>
                    <NoData
                      txt={jobType === '' ? 'Job 유형을 선택해 주세요.' : '조회된 Job이 없습니다.'}
                    />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </Table>

        <Pagination
          displayed={5}
          pagingTotal={totalPages}
          currentPage={pageNo}
          totalCount={totalCount}
          pageSize={PAGE_SIZE}
          numberOfElements={jobList.length}
          viewShowing
          hidePageSizeSelectOptions
          onPageChange={(pageNum) => {
            if (serviceId === '' || jobList.length === 0) {
              alert('조회 가능한 Job이 없습니다.');
              return;
            }
            setPageNo(pageNum);
          }}
        />

        <S.LayerPopupBtns>
          <div className="right-area">
            <ButtonList
              buttonList={[
                { label: '취소', className: 'secondary', onClick: onClose },
                {
                  label: jobType === JOB_TYPE_OUTBOUND.code ? '등록' : '다음',
                  className: 'primary',
                  onClick: jobType === JOB_TYPE_OUTBOUND.code ? registerJobs : nextStep,
                  disabled: selectedJobs.size === 0 || isLoading,
                },
              ]}
            />
          </div>
        </S.LayerPopupBtns>
      </div>

      {/* STEP 2 */}
      <div style={{ display: step === 2 ? 'block' : 'none' }}>
        <S.BulletList>
          <li>Job에서 사용할 Call Point를 입력해주세요.</li>
        </S.BulletList>

        <Table height={400} scroll fixedHeader>
          <table>
            <caption>Job명, Call Point 시작, Call Point 끝에 관한 표</caption>
            <colgroup>
              <col />
              <col width="150px" />
              <col width="50px" />
              <col width="150px" />
            </colgroup>
            <thead>
              <tr>
                <th scope="col" className="t-left">
                  Job명
                </th>
                <th scope="col">Call Point 시작</th>
                <th scope="col"></th>
                <th scope="col">Call Point 끝</th>
              </tr>
            </thead>
            <tbody>
              {Array.from(selectedJobs.values()).map((job) => (
                <tr key={job.jobId}>
                  <td className="t-left">{job.jobName}</td>
                  <td>
                    <TextField
                      valueError={job.callpointStart === ''}
                      placeholder="Call Point 시작"
                      onChange={(e) => _inputChanged(e, job.jobId, 'start')}
                    />
                  </td>
                  <td>~</td>
                  <td>
                    <TextField
                      valueError={job.callpointEnd === ''}
                      placeholder="Call Point 끝"
                      onChange={(e) => _inputChanged(e, job.jobId, 'end')}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </Table>

        <S.LayerPopupBtns>
          <div className="right-area">
            <ButtonList
              buttonList={[
                { label: '이전', className: 'secondary', onClick: backStep },
                {
                  label: '등록',
                  className: 'primary',
                  onClick: registerJobs,
                  disabled: !areCallpointsEntered() || isLoading,
                },
              ]}
            />
          </div>
        </S.LayerPopupBtns>
      </div>
    </PS.PopupJobRegister>
  );
};

export default JobRegister;
