import { useState } from 'react';
import * as PS from '../../../style/Test';

/**
 * type : error
 */
const FileUpload = ({ error, success, uploading }) => {
  return (
    <PS.FileUpload error={error} success={success}>
      <input type="file" id="file-upload" />
      <label className="file-inner" htmlFor="file-upload">
        {error ? (
          <>
            <strong>업로드 실패 / 잘못된 파일 형식</strong>
            <p>다시 시도해주세요!</p>
            <span className="btn-file">파일 선택</span>
          </>
        ) : (
          <>
            <span className="btn-file">파일 선택</span>
            <strong>여기에 파일을 놓아주세요.</strong>
            <p>xls 또는 xlsx 형식 파일만 가능합니다.</p>
          </>
        )}
      </label>
      {uploading && (
        <div className="file-upload">
          <div className="file-info">
            <strong>파일 업로드 진행중</strong>
            <div className="file-detail">
              <span>1.2MB</span>
              <span>7 Seconds Left</span>
            </div>
          </div>
          <div className="progress-bar">
            <span style={{ width: '10%' }}></span>
          </div>
          <button type="button" className="btn-close">
            <span className="hidden">닫기</span>
          </button>
        </div>
      )}
      {success && (
        <div className="file-upload">
          <div className="file-info">
            <strong>업로드 완료!</strong>
            <div className="file-detail">
              <span>테스트_230808_result.xlsx​</span>
              <span>42,223kB</span>
            </div>
          </div>
          <button type="button" className="btn-close">
            <span className="hidden">닫기</span>
          </button>
        </div>
      )}
    </PS.FileUpload>
  );
};

export default FileUpload;
