const  QaaEvaluationTab = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [deletePopup, setDeletePopup] = useState(false); // 삭제 클릭 팝업
  const _btnListIs = [
    {
      label : '취소',
      type:'secondary',
      evt : () => {console.log('1')}
    },
    {
      label : '확인',
      type:'primary',
      evt : () => {console.log('2')}
    },
  ];
  
  return (
    <>
      {deletePopup && // 선택삭제 팝업
        <Alert onClose={() => setDeletePopup(false)} text={'삭제가 완료되었습니다.'} />  // **** 기본 텍스트 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'<div class="icon"></div><span class="red">현재 진행 중</span>인 평가 계획은 삭제가 불가합니다.'}/>  // **** 아이콘 + 경고(빨간 텍스트) 포함 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'선택하신 평가 계획을 삭제 하시겠습니까?​'} btnList={_btnListIs}/>  // **** 기본 텍스트 타입
      }
      <FilterTwoLine>
        <TwoLineFlexBox width={'1080px'} >
          <article>
            <TextField
              placeholder="평가계획명를 입력해주세요"
              label="평가 계획명"
              multi
              onChange={(e) => { }}
            />
            <TextField
              placeholder="평가표명를 입력해주세요"
              label="평가표명"
              multi
              onChange={(e) => { }}
            />
            <Select
              option={[]}
              label="업무 유형 선택"
              value={null}
              disabled={false}
              title={'업무 유형'}
              onChange={() => { console.log('select!') }}
            />
          </article>
          <article>
            <Select
              option={[]}
              label="상담 유형 1 선택"
              value={null}
              title={'상담유형 1'}
              disabled={false}
              onChange={() => { console.log('select!') }}
            />
            <Select
              option={[]}
              label="상담 유형 2 선택"
              value={null}
              disabled={false}
              title={'상담유형 2'}
              onChange={() => { console.log('select!') }}
            />
            <Select
              option={[]}
              label="상담 유형 3 선택"
              value={null}
              disabled={false}
              title={'상담유형 3'}
              onChange={() => { console.log('select!') }}
            />
            <DateRange
              rangeCal
              utilMenu
              label="상담 일시"
              monthsShown={2}
              selectsRange
              format="YYYY-MM-DD"
              startDate={dayjs(startDate).toDate()}
              endDate={dayjs(endDate).toDate()}
              selected={dayjs(startDate).toDate()}
              disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
              disableNum={3}
              maxDate={dayjs().toDate()}
              onChange={() => { console.log('DateRange onChange') }}
            />
          </article>
        </TwoLineFlexBox>
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </FilterTwoLine>

      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          { label: '선택 삭제', className: 'secondary del2', onClick: () => setDeletePopup(true) },
          { label: '생성', className: 'primary left-plus', onClick: () => navigate('/evaluationPlans/qaa/detail') },
        ]} />
      </SubTableTitle>
      <Table className="active" fixedHeader={true} height="692" hover={false} interval={true} round={false}>
        <table>
          <caption>평가표 조회</caption>
          <colgroup>
            <col width="64px" />
            <col width="140px" />
            <col width="120px" />
            <col width="120px" />
            <col width="170px" />
            <col width="170px" />
            <col width="170px" />
            <col width="120px" />
            <col width="120px" />
            <col width="120px" />
            <col width="184px" />
            <col width="80px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th >평가 계획명</th>
              <th >평가표명</th>
              <th >업무유형</th>
              <th >상담유형1</th>
              <th >상담유형2</th>
              <th >상담유형3</th>
              <th>평가 년월</th>
              <th>평가 대상</th>
              <th>평가자</th>
              <th>평가 기간</th>
              <th>상태</th>
            </tr>
          </thead>
          <tbody>
            {_tempList_.map((item, index) => {
              return <tr key={index}>
                <td><Checkbox /></td>
                <td>{item.name}</td>
                <td>{item.tablename}</td>
                <td height={52}>{item.type0}</td>
                <td >{item.type1}</td>
                <td >{item.type2}</td>
                <td>{item.type3}</td>
                <td>{item.group1}</td>
                <td>{item.model}</td>
                <td>{item.cycle}</td>
                <td>{item.time}</td>
                <td>{item.status}</td>
              </tr>
            })}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}

