import React, { useRef } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import * as S from '../../style/ChartStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const DecimalSingleBarChart = ({ title, datas }) => {

  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const backgroundBar = {
    id: 'backgroundBar',
    beforeDatasetsDraw(chart, args, pluginOptions) {
      const {
        ctx,
        chartArea: { top, width, height },
      } = chart;
      if (datas) {
        ctx.save();
        ctx.fillStyle = pluginOptions.barColor;
        ctx.fillRect(width / 2 + 20, top, 21, height);
      }
    },
  };
  const options = {
    responsive: true,
    plugins: {
      legend: {
        display: false,
      },
      datalabels: {
        display: false,
      },
      backgroundBar: {
        barColor: '#9D9FE6',
      },
    },
    scales: {
      x: {
        display: false,
        grid: {
          display: false,
        },
      },
      y: {
        min: 0,
        max: 1,
        setpSize: 0.1,
      },
    },
    maintainAspectRatio: false,
  };

  const labels = [title];

  const data = {
    labels,
    datasets: [
      {
        label: '',
        barThickness: 20,
        maxBarThickness: 20,
        data: [datas],
        backgroundColor: '#5c5fd6',
        hoverBackgroundColor: '#5c5fd6',
        borderRadius: 0,
      },
    ],
  };

  return (
    <S.DecimalSingleBar>
      {title && (
        <div className="chart-title">
          <strong className="title">{title}</strong>
          <span className="num">{datas === undefined ? '-' : datas}</span>

          <div className="legend">
            <ul>
              <li>
                <span></span>
                <p>최고점-평균</p>
              </li>
              <li>
                <span></span>
                <p>평균앙상블값</p>
              </li>
            </ul>
          </div>
        </div>
      )}
      <div className="inner">
        <Bar options={options} data={data} plugins={[backgroundBar]} />
      </div>
    </S.DecimalSingleBar>
  );
};

export default DecimalSingleBarChart;
