import ButtonList from '../../common/ButtonList';
import GrayBox from '../../common/GrayBox';

import * as S from '../../../style/ElementsStyle';
import * as PS from '../../../style/Configuration';

const PopupRegistrationOver = ({ onClose, maxCount }) => {
  const popupBts = [{ label: '확인', className: 'primary', onClick: onClose }];

  return (
    <>
      <PS.PopupGrayBox>
        <GrayBox vertical="center" align="center">
          <p className="info">
            콜봇/챗봇 각각 <strong className="col-blue">{maxCount}개</strong>까지 등록 가능합니다.<br />
            ​기존에 등록된 봇을 등록 취소하신 후, 다시 시도해주세요.
          </p>
        </GrayBox>
      </PS.PopupGrayBox>
      <S.LayerPopupBtns>
        <div className="right-area">
          <ButtonList buttonList={popupBts} />
        </div>
      </S.LayerPopupBtns>
    </>
  );
};

export default PopupRegistrationOver;
