import styled from "@emotion/styled/macro";
import _mx from "./Style";
import _svg from "./SvgList";
import { _color } from "./Variable";

import * as S from "./ElementsStyle";

export const PopupGrayBox = styled.div`
  color: ${_color.black2};
  ${S.GrayBox} {
    min-height:120px;
  }
  p {
    color: #272E35;
    font-size: 14px;
    font-weight: 400;
    text-align:left;
    line-height: 22px;
    strong {
      font-weight: 500;
    }
    &.left {
      text-align:left;
    }
    &.info {
      font-size: 15px;
      font-weight: 500;
      strong {
        font-weight: 600;
      }
    }
    &.bot-name {
      color: #555f6d;
      text-align: center;
      strong {
        color: #272e35;
      }
    }
  }

  dl.info {
    display:flex;
    color: #272e35;
    font-size: 14px;
    dt {
      font-weight: 500;
      flex-shrink: 0;
    }
    dd {
      margin-left: 4px;
      font-weight: 400;
    }
  }
  .col-red {
    color: #c53434;
  }
  .col-blue {
    color: ${_color.secondary0};
  }
`;
export const BoxGridWhite = styled.div`
  border-radius: 6px;
  background-color: ${_color.white};
  .grid-header {
    display: flex;
    align-items: center;
    gap: 24px;
    justify-content: space-between;
    height: 80px;
    padding: 0 52px;
    .title {
      display: flex;
      align-items: center;
      gap: 16px;
      font-size: 18px;
      font-weight: 700;
      line-height: 32px;
      color: #555f6d;
      strong {
        font-size: 20px;
        font-weight: 700;
        color: ${_color.black2};
      }
      .col-blue {
        color: ${_color.secondary0};
        font-size: 18px;
      }
    }
    button {
      min-width: 88px;
    }
    &.sub {
      height:60px;
      .title {
        font-size:20px;
        font-weight: 700;
        color: #272E35;
      }
    }
  }
  .grid-cont {
    padding: 0px 52px 24px;
    .btn-area {
      display:flex;
      justify-content:right;
      margin-top: 23px;
      ${S.Button} {
        width:100px;
      }
    }
    &.borderNone {
      border-top: 0 !important;
    }
  }

  ${S.Table} + ${S.Title} {
    margin-top: 24px;
  }
`;

export const Bot = styled.div`
  ${S.Table} {
    ${S.ButtonList} {
      justify-content: center;
    }
    ${S.Button} {
      min-width:102px !important;
      &:first-of-type {
        min-width: 72px !important;
      }
    }
  }
`;

