export const PopupBotGroupCreate = styled.div`
  ${S.GrayBox} {
    .form-cont{
      font-size: 14px;
    }
    ${S.TextField} {
      width: 400px;
    }
  }
  .box-bot-select {
    display: flex;
  }
  .bot-select-item {
    overflow: hidden;
    border-radius: 4px;
    border: 1px solid #d7d9f3;
    .select-header {
      display: flex;
      align-items: center;
      height: 52px;
      padding: 0 20px;
      background: #ecf0fe;
      border-bottom: 1px solid #d7d9f3;
      ${S.Checkbox} {
        .label {
          color: #272e35;
          font-size: 15px;
          font-weight: 500;
        }
        strong {
          color: ${_color.primary2};
          font-weight: 500;
        }
      }
    }
    .select-cont {
      ${S.Table} {
        border-bottom: 0;
      }
      ${S.Button} {
        width: 92px;
      }
      
    }
    .select-info {
      display: flex;
      align-items: center;
      height: 50px;
      padding: 0 38px;
      strong {
        padding-left: 10px;
        color: #5c5fd6;
        font-size: 15px;
        font-weight: 500;
        &.error {
          color: #D38A41;
        }
      }
      p {
        display: block;
        width: 100%;
        color: #7e8b99;
        font-size: 14px;
        font-weight: 400;
        line-height: 20px;
      }
    }
  }
  .box-move-btns {
    display: flex;
    align-items: center;
    flex-direction: column;
    flex-wrap: wrap;
    justify-content: center;
    gap: 24px 0px;
    min-width: 100px;
    button {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
      overflow: hidden;
      position: relative;
      width: 48px;
      height: 48px;
      padding: 0;
      box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
      border-radius: 6px;
      border: 1px solid #cfd6dd;
      background-color: ${_color.white};
      &:before {
        content: "";
        display: block;
        width: 20px;
        height: 20px;
        background: ${_mx.svg(_svg.chevron("1f2937"))} center center no-repeat;
        background-size: contain;
      }
      &.btn-right:before {
        rotate: 180deg;
      }
      &:disabled {
        pointer-events: none;
        box-shadow: none;
        background-color: #E9ECEF;
        &::before {
          background: ${_mx.svg(_svg.chevron("9EA8B3"))} center center no-repeat;
        }
      }
    }   
  }
`;

export const BotGroupInformationStyle = `
  > ${S.Title}:first-of-type {
    margin-bottom: 10px;
  }
  ${S.Title} {
    strong.title {
      font-size: 20px;
    }
    .sub-title {
      font-size: 20px;
      color: #5c5fd6;
      font-weight: 600;
    }
  }
  ${S.Table} {
    .btn-area {
      justify-content:center;
      &.type02 {
        ${S.Button} {
          min-width: 64px;
          width: 64px;
        }
      }
    }
  }
  ${BoxGridWhite} {
    & ~ ${BoxGridWhite} {
      background-color:rgba(255, 255, 255,0.7);
    }
    & + ${BoxGridWhite} {
      margin-top: 20px;
    }
    .grid-header {
      .title {
        flex-grow: 1;
        strong {
          font-weight:600;
        }
      }
      ${S.Button} {
        min-width: 50px;
      }
      & + .grid-cont {
        border-top:1px solid #E3E7EA;
      }
    }
    .grid-cont {
      ${S.Title} {
        // margin-top: 30px;
        &:first-of-type {
          margin-top: 0;
        }
        .title {
          font-size: 15px;
          font-weight: 500;
          color:${_color.black2};
        }
      }
      .box-td {
        display: flex;
        align-items: center;
        gap: 0 50px;
        ${S.Flag} {
          margin: 0;
        }
      }
      .td-deploy-status {
        display: flex;

        .flex-1 {
          display: flex;
          flex: 1;
        }
      }
      ${S.Table} {
        ${S.ButtonList} {
          justify-content: center;
        }
      }
    }
  }
  .lock-information {
    display: flex;
    align-items: center;
    .locked {
      display: flex;
      align-items: center;
      min-height: 20px;
      padding-left: 26px;
      background: ${_mx.svg(_svg.lock)} left center no-repeat;
      font-size: 14px;
      font-weight: 400;
      strong {
        font-weight: 600;
      }
    }
    .unlocked {
      content: ${_mx.svg(_svg.unlock)};
    }
  }
  .deploy-information {
    display: flex;
    align-items: center;
    gap: 0 24px;
    margin-left: auto;
    /* padding-right:70px; */
    color: #7e8b99;
    font-size: 15px;
    font-weight: 400;
    li {
      display: flex;
      align-items: center;
      gap: 0 16px;
      /* min-width:200px; */
    }
    strong {
      /* min-width: 160px; */
      color: ${_color.black2};
      font-weight: 500;
    }
  }
  .grid-item {
    &.header-only {
      .grid-header {
        height:68px;
        padding:0 20px;
      }
    }
  }
  .box-bot-btns {
    margin:34px 0 0;
    text-align:right;
    ${S.Button} {
      width:100px;
    }
  }
`;

