export const ToggleBox = styled.div`
  p:nth-of-type(n + 3) {
    display: none;
  }
  ${S.Button} {
    justify-content: space-between;
    width: 144px;
    margin-top: 10px;
    span {
      width:100%;
    }
  }
  &.open {
    p {
      display: block;
    }
    ${S.Button} {
      &:after {
        transform:rotate(90deg);
      }
    }
  }
`;
