export const PopupAddTarget = styled.div`
  p {
    margin-bottom: 20px;
    color: #555f6d;
    font-size: 14px;
    font-weight: 500;
  }
  ${S.BulletList} + ${S.GrayBox} {
    margin-top: 24px;
  }
  .box-target {
    ${S.ScrollDefaultStyle};
    overflow-y: auto;
    height: 146px;
    border: 1px solid #d7d9f3;
    border-radius: 8px;
    background: ${_color.gray7};
    li {
      display: flex;
      justify-content: space-between;
      gap: 10px;
      align-items: center;
      height: 48px;
      padding: 0 23px;
      color: ${_color.black2};
      background: ${_color.white};
      font-size: 15px;
      font-weight: 400;
      border-top: 1px solid #d7d9f3;
      &:first-of-type {
        border-top: 0;
      }
    }
    .title {
      overflow: hidden;
      width: 100%;
      text-overflow: ellipsis;
    }
    .btn-delete {
      display: block;
      width: 40px;
      height: 32px;
      border-radius: 6px;
      border: 1px solid #cfd6dd;
      background: ${_mx.svg(_svg.delete("4A545E"))} center center no-repeat;
    }
  }
  .box-input {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
    height: 48px;
    margin: 8px 15px;
    border-bottom: 1px solid #d7d9f3;
    input {
      background: transparent;
      border: 0;
      outline: 0;
      color: ${_color.black2};
      font-size: 15px;
      font-weight: 400;
    }
  }
  .deploy-time-area {
    display: flex;
    align-items: center;
    gap: 0 10px;
    & > div {
      width: 100%;
    }
    button {
      padding: 0 20px 0 20px;
    }
  }
`;

