const ExcellentCallPage = () => {
  const [openPopup, setPopupOpen] = useState(false); // 상담사, 평가자 검색 팝업
  const [titleIs, setTitleIs] = useState('');
  const [openDetail, setDetailOpen] = useState(false); //테이블 리스트 클릭 시 팝업

  const togglePopup = (title) => {
    setPopupOpen(!openPopup);
    setTitleIs(title)
  };

  return (
    <>
      {openPopup && //상담사 검색 팝업
        <LayerPopup
          size=""
          title={titleIs}
          customWidth={800}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <SearchBoxPopup title={titleIs} />
        </LayerPopup>
      }

      {openDetail && //상세 팝업
        <LayerPopup
          size=""
          title={'　'}
          customWidth={1500}
          open={openDetail}
          onClose={() => setDetailOpen(false)}
          customClass={'padding-custom'}
        >
          <ExcellentCallManagementPopup />
        </LayerPopup>
      }

      <Title title="우수 콜 조회" icon="counsel" />
      <Filter>
        <SearchBox
          placeholder={'상담사명을 입력해주세요'}
          value={''}
          label="상담사명 검색"
          onClick={() => togglePopup('상담사 검색')}
        />
        <Select
          option={[]}
          label="상담 유형 대 선택"
          value={null}
          title={'상담유형 대'}
          disabled={false}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="상담 유형 중 선택"
          value={null}
          disabled={false}
          title={'상담유형 중'}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="상담 유형 소 선택"
          value={null}
          disabled={false}
          title={'상담유형 소'}
          onChange={() => { console.log('select!') }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>
      <Table className="active" fixedHeader={true} height="692" hover={false} interval={true} round={false}>
        <table>
          <caption>우수 콜 조회</caption>
          <colgroup>
            <col width="270px" />
            <col width="253px" />
            <col width="253px" />
            <col width="253px" />
            <col width="320px" />
            <col width="228px" />
          </colgroup>
          <thead>
            <tr>
              <th className="t-left left-padding">상담사명</th>
              <th className="t-left left-padding">상담유형1</th>
              <th className="t-left left-padding">상담유형2</th>
              <th className="t-left left-padding">상담유형3</th>
              <th>상담 일시</th>
              <th>상담 내역</th>
            </tr>
          </thead>
          <tbody>
            {_personList.map((item, index) => {
              return <tr key={index}>
                <td className="t-left left-padding" height={52}>{item.name} &#40;{item.id}&#41;</td>
                <td className="t-left left-padding">{item.type1}</td>
                <td className="t-left left-padding">{item.type2}</td>
                <td className="t-left left-padding">{item.type3}</td>
                <td>{item.time}</td>
                <td className='center'>
                  <TableInTxtBtn onClick={() => { setDetailOpen(true) }}>보기</TableInTxtBtn>
                </td>
              </tr>
            })}
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
};

export default ExcellentCallPage;