import Title from "components/common/Title";
import Tab from "components/common/Tab";
import AiEvaluationTab from "./tabs/AiEvaluationTab";
import QaaEvaluationTab from "./tabs/QaaEvaluationTab";

const EvaluationPlansPage = () => {
  const evaluationTabList = [
    {
      title: 'AI평가',
      tabContent: <AiEvaluationTab />
    },
    {
      title: 'QAA평가',
      tabContent: <QaaEvaluationTab />
    }
  ]
  return (
    <>
      <Title title="평가 계획 조회" icon="evaluation" />
      <Tab tabList={evaluationTabList} />
    </>
  )
};

export default EvaluationPlansPage;