import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import Button from "components/elements/Button";
import { LayerInButtonWrap, FormFileList } from "style/AutoQAStyle";
import Select from "components/elements/Select";
import TextField from "components/elements/TextField";
import ButtonList from 'components/common/ButtonList';
import { useEffect, useState } from "react";
import FileUpload from 'components/pages/Test/FileUpload';

const DocumentsManagementPopup = ({ setPopupType }) => {
  const [btnTxt, setBtnTxt] = useState('수정');
  const [typeIs, setTypeIs] = useState('');
  const [inputDisabled, setInputDisabled] = useState(true);

  useEffect(() => {
    if (typeIs === 'edit') {
      setBtnTxt('저장');
      setPopupType('수정'); // 부모 컴포넌트 타이틀 적용
      setInputDisabled(false);
    }
  }, [typeIs, setPopupType]);

  

  return (
    <>
      <GrayBox direction={"column"}>
        <FormItem label={'문서명'} marginB={8}>
          <TextField width={575} disabled={inputDisabled} readOnly={true} value={'테스트'} />
        </FormItem>
        <FormItem label={'카테고리'} marginB={8}>
          <div style={{ display: 'flex', gap: 8 }}>
            <TextField width={typeIs === 'edit' ? 508 : 575} disabled={inputDisabled} value={'카테고리1​'} readOnly={true}/>
            {typeIs === 'edit' && <Button label="변경" className="secondary" onClick={() => { }} />}
          </div>
        </FormItem>
        <FormItem label={'상태'} marginB={8}>
          {inputDisabled ?
            <TextField width={260} disabled={inputDisabled} value={'사용'} readOnly={true}/>
            : <Select option={[]} type={'simple'} title={'사용'} onChange={() => { }} disabled={inputDisabled}/>
          }
          
        </FormItem>
        <FormItem label={'파일'} marginB={8}>
          {typeIs === 'edit' ?
            <>
              <FormFileList height='40px'>
                <li>선택약정 할인 제도.pdf<button /></li>
              </FormFileList>
              <div style={{ marginTop: '8px', width: '575px' }}>
                <FileUpload />
              </div>
            </>
            :
            <p>선택 약정 할인제도.pdf</p>}
        </FormItem>
        <FormItem label={'작성자'} marginB={8}>
          <TextField width={260} disabled={inputDisabled} readOnly={true} value={'관리자'} />
        </FormItem>
        {typeIs !== 'edit' && 
          <FormItem label={'등록일시'}>
            <TextField width={260} disabled={inputDisabled} value={'2024-08-22 09:13:24​'} readOnly={true}/>
          </FormItem>
        }
      </GrayBox>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: btnTxt, className: 'primary', onClick: () => { setTypeIs('edit') } },
        ]} />
      </LayerInButtonWrap>
    </>
  )
};

export default DocumentsManagementPopup;