import * as S from '../../style/ElementsStyle';
import Button from '../elements/Button';

const ButtonList = ({ ulClass, col, alignCenter, alignRight, buttonList,marginT}) => {
  return (
      <S.ButtonList className={ulClass} col={col} alignCenter={alignCenter} alignRight={alignRight} marginT={marginT}>
        {buttonList?.map((btn) => {
          return (
              <Button
                  key={btn.label}
                  label={btn.label}
                  as={btn.as}
                  to={btn.to}
                  className={btn.className}
                  onClick={btn.onClick}
                  target={btn.target}
                  disabled={btn.disabled}
                  btnType={btn.btnType}
              ></Button>
          );
        })}
      </S.ButtonList>
  );
};

export default ButtonList;
