import { useState } from "react";
import Title from "components/common/Title";
import { SubTableTitle, CountingTitle } from "style/AutoQAStyle";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import Pagination from 'components/common/Pagination';
import LayerPopup from "components/common/LayerPopup";
import Tooltip from "components/common/Tooltip";
import SystemAuthorityPopup from "./popups/SystemAuthorityPopup";
import NoData from "components/common/NoData";

const SystemAuthorityManagement = () => {
	const [openPopup, setPopupOpen] = useState(false); // 사용자명 검색 팝업
	const [popupType, setPopupType] = useState(''); // 카테고리 타입

	const onHandlePopup = (type) => {
		setPopupOpen(true);
		setPopupType(type)
	};

	return (
		<>
			{openPopup && // 메뉴생성 , 상세 팝업 ()
				<LayerPopup
					title={`시스템 권한 ${popupType === 'add' ? '등록' : '상세'}`}
					customWidth={900}
					open={openPopup}
					onClose={() => setPopupOpen(false)}
				>
					<SystemAuthorityPopup type={popupType} />
				</LayerPopup>
			}
			<Title title="시스템 권한 관리" icon="settings"  tooltip={<Tooltip color={'white'}>{'각 별개의 시스템에서의 권한을 ​등록/설정할 수 있는 메뉴입니다.​'}</Tooltip>}/>
			<SubTableTitle>
				<CountingTitle/>
				<ButtonList buttonList={[
					{ label: '권한 등록', className: 'primary left-plus', onClick: () => {onHandlePopup('add') } },
				]} />
			</SubTableTitle>
			<Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
				<table>
					<colgroup>
						<col width="395px" />
						<col width="395px" />
						<col width="395px" />
						<col width="395px" />
					</colgroup>
					<thead>
						<tr>
							<th>권한명</th>
							<th>AutoQA</th>
							<th>AI KMS</th>
							<th>AICC 포털</th>
						</tr>
					</thead>
					<tbody>
						{/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={4}><NoData txt={'데이터가 없습니다'}/></td></tr> 
            */}
						{Array.from({ length: 4 }).map((_, index) => (
							<tr key={index} onClick={() => onHandlePopup('detail') }>
								<td>운영자(<span className="blue">4</span>)</td>
								<td>ROLE_MANGER​</td>
								<td>ROLE_MANGER​</td>
								<td>ROLE_MANGER​</td>
							</tr>
						))}
					</tbody>
				</table>
			</Table>
			<Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
		</>
	);
}

export default SystemAuthorityManagement;