import React, { useState } from 'react';
import Title from 'components/common/Title';
import { SubTableTitle, CountingTitle } from 'style/AutoQAStyle';
import Table from 'components/common/Table';
import Pagination from 'components/common/Pagination';
import ButtonList from 'components/common/ButtonList';
import NoData from 'components/common/NoData';
import LayerPopup from 'components/common/LayerPopup';
import AuthorityPopup from './popups/AuthorityPopup';


const AuthorityManagementPage = () => {
  const [layerPopup, setLayerPopup] = useState(false);  // 레이어 팝업 상태
  const [type,setType] = useState('');
  
  return (
    <>
    {layerPopup &&
      <LayerPopup
        title={`메뉴접근 권한 ${type === 'a' ? '등록' : '상세'}`}
        customWidth={1000}
        open={layerPopup}
        onClose={() => setLayerPopup(false)}
      >
        <AuthorityPopup  type={type}/>
      </LayerPopup>
    }
      <Title title="메뉴 접근 권한 목록" icon="settings" />
      <SubTableTitle>
				<CountingTitle/>
				<ButtonList buttonList={[
					{ label: '권한 등록', className: 'primary left-plus', onClick: () => {
            setLayerPopup(true)
            setType('a')
          } },
				]} />
			</SubTableTitle>
      <div style={{marginTop:'24px'}}>
      <Table className="active" fixedHeader={true} height="692" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="526px" />
            <col width="526px" />
            <col width="526px" />
          </colgroup>
          <thead>
            <tr>
              <th>메뉴 접근 권한</th>
              <th>접근 가능 메뉴 갯수</th>
              <th>다운로드 권한</th>          
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={3}><NoData txt={'데이터가 없습니다'}/></td></tr> 
            */}
            {Array.from({ length: 10 }).map((_, index) => (
              <tr key={index} onClick={() => {
                setLayerPopup(true)
                setType('b')
              }}>
                <td>운영자(<span className="blue">4</span>)</td>
                <td>40</td>
                <td>보유</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>
      </div>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  );
}
export default AuthorityManagementPage;