import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';

const Table = ({
  interval = true,
  scroll = false,
  hover = false,
  fixedHeader = false,
  height = 200,
  children,
  round=false,  
  borderBottom=true,
  xScroll=false
}) => {
  return (
    <S.Table
      className={classnames({ scroll: scroll, hover: hover,round:round,xScroll:xScroll })}
      fixedHeader={fixedHeader}
      interval={interval}
      height={height}
      borderBottom={borderBottom}
    >
      {children}
    </S.Table>
  );
};

export default Table;
