import { useEffect, useState } from 'react';
import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { getBotGroupsApi } from 'pages/fallbackUtterance/apis';
import {
  getBotGroupDayStaticsApi,
  getBotGroupPeriodStaticsExcelApi,
  getBotGroupStaticsDetailApi,
} from '../apis';
import { customSort } from 'libs/utiles';
import {useServiceList} from "../../../libs/DataHook";
import {useSelector} from "react-redux";

const DEFAULT_BOTGROUP_DAY_STATICS_SEARCH_PARAMS = {
  searchStartDate: dayjs().subtract(6, 'day').format('YYYY-MM-DD'),
  searchEndDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 10,
};

const useBotGroupDayStatic = () => {
  const [botGroupDayStaticsSearchParams, setBotGroupDayStaticsSearchParams] = useState(
    DEFAULT_BOTGROUP_DAY_STATICS_SEARCH_PARAMS
  ); // 조회 조건
  const [botGroupDayStaticsRes, setBotGroupDayStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [botGroupDayTotalStaticsRes, setBotGroupDayTotalStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const serviceListDay = useServiceList();
  const {serviceId, serviceName} = useSelector((state) => state.service.value)
  const [botGroupListDay, setBotGroupListDay] = useState([]);
  const [isBotGroupDayStaticsSearch, setIsBotGroupDayStaticsSearch] = useState(false);
  const [latestBotGroupDaySearchParams, setLatestBotGroupDaySearchParams] = useState({});
  const [botGroupDetailStaticsRes, setBotGroupDetailStaticsRes] = useState({}); // 봇 그룹 통계 봇 그룹 데이터

  // 조회 조건 변경
  const changeBotGroupDayStaticsSearchParams = (key, value) => {
    setBotGroupDayStaticsSearchParams(fp.set(key, value));
  };

  // 봇그룹 일별 조회
  const getBotGroupDayStatics = async (searchParams) => {
    try {
      searchParams.serviceId = serviceId
      searchParams.serviceName = serviceName
      setIsBotGroupDayStaticsSearch(true);
      const res = await getBotGroupDayStaticsApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupDayStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
      const botGroupName = fp.pipe(
        fp.find({ botGroupId: searchParams.botGroupId }),
        fp.getOr('', 'botGroupName')
      )(botGroupListDay);
      setLatestBotGroupDaySearchParams({ ...searchParams, botGroupName });
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 봇별 조회에 실패했습니다.');
      setBotGroupDayStaticsRes({});
    }
  };

  // 봇그룹 일별 전체 데이터 조회
  const getBotGroupDayTotalStatics = async (searchParams) => {
    try {
      searchParams.serviceId = serviceId
      searchParams.serviceName = serviceName
      const res = await getBotGroupDayStaticsApi({ ...searchParams, pageNo: 0, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupDayTotalStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 봇별 조회에 실패했습니다.');
      setBotGroupDayTotalStaticsRes({});
    }
  };

  // 봇 그룹 디테일 통계 조회
  const getBotGroupStaticsDetail = async (searchParams) => {
    try {
      searchParams.serviceId = serviceId
      searchParams.serviceName = serviceName
      const res = await getBotGroupStaticsDetailApi(searchParams);

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupDetailStaticsRes(fp.getOr({}, 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
    }
  };

  // 봇그룹 일별 리스트 엑셀 다운
  const getBotGroupDayStaticsExcel = async (searchParams) => {
    try {
      searchParams.serviceId = serviceId
      searchParams.serviceName = serviceName

      const res = await getBotGroupPeriodStaticsExcelApi(searchParams, 'day');
      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_봇그룹통계_일별조회_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      alert('봇 그룹 통계 일별 엑셀 다운에 실패했습니다.');
    }
  };

  const getBotGroupsDay = async (serviceId, jobType) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, jobType, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));

      setBotGroupListDay(sortBotGroups);
      const firstBotGroupId = fp.getOr('', '[0].botGroupId', sortBotGroups);
      changeBotGroupDayStaticsSearchParams('botGroupId', firstBotGroupId);
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 목록 조회에 실패했습니다. 봇 그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupListDay([]);
    }
  };

  useEffect(() => {
    if (!serviceId) return;
    getBotGroupsDay(serviceId);
  }, [serviceId]);

  return {
    botGroupDayStaticsSearchParams, // 조회 조건
    latestBotGroupDaySearchParams,
    botGroupDayStaticsRes, // 봇그룹 봇별 통계 데이터
    botGroupDayTotalStaticsRes,
    botGroupDetailStaticsRes, // 봇 그룹 상세 통계 데이터
    serviceListDay,
    serviceId,
    serviceName,
    botGroupListDay,
    isBotGroupDayStaticsSearch,
    changeBotGroupDayStaticsSearchParams, // 조회 조건 변경
    getBotGroupsDay,
    getBotGroupDayStatics,
    getBotGroupDayTotalStatics,
    getBotGroupStaticsDetail,
    getBotGroupDayStaticsExcel,
  };
};

export default useBotGroupDayStatic;
