/* 파일 업로드 */
export const FileUpload = styled.div`
  position:relative;
  overflow:hidden;
  height:160px;
  border-radius: 6px;
  background:${({error}) => error ? '#FFEBEB' : `${_color.white}` };  
  box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
  border:1px dashed #CFD6DD;
  text-align:center;
  box-sizing:border-box;
  .btn-file {
    display:inline-block;
    height:40px;
    ${({error}) => error && 'margin-top:12px;'}
    padding:0 16px 0 44px;
    border-radius:6px;
    background:${_color.white} ${_mx.svg(_svg.upload("555F6D"))} left 16px center no-repeat;
    border:1px solid #CFD6DD;
    color:#4A545E;
    font-size: 14px;
    line-height:40px;
    box-shadow: 0px 1px 2px rgba(27, 36, 44, 0.12);
    & + strong {
      margin-top:14px;
    }
  }
  .file-inner {
    display:block;
    width:100%;
    height:100%;
    padding: 32px 0 24px;
    p {
      color: #7E8B99;
      font-size: 14px;
      font-weight: 400;
      line-height: 24px;
    }
    strong {
      display:flex;
      align-items:center;
      justify-content:center;
      gap:0 4px;
      margin-bottom: 4px;
      color: ${({error}) => error ? '#C53434' : `${_color.black2}`};
      font-size: 15px;
      font-weight: 500;
      line-height: 22px; 
      &:before {
        content:'';
        display:${({error}) => error ? 'block' : 'none'};
        width:16px;
        height:16px;
        background:${_mx.svg(_svg.alertFill("C53434"))} left center no-repeat; background-size:16px 16px;
      }
    }
  }
  input {
    position:absolute;
    left:-3000px;
    top:0;
    opacity: 0;
  }
  .file-upload {
    display:flex;
    flex-direction:column;
    justify-content:center;
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:160px;
    padding:24px 40px;
    text-align:left;
    background:${({ success }) => success ? '#EDF2FF' : '#F0F3F5'};
    ${({success}) => success && 'align-items: center;'};
    .file-info {
      padding-left:${({ success }) => success ? '0' : '48'}px;
      color: ${_color.black2};
      font-size: 15px;
      font-weight: 500;
      line-height: 22px;
      background:${_mx.svg(_svg.spreadSheetFile)} left center no-repeat;
      ${({success}) => success && `text-align:center;background:none;strong {padding-left:28px;font-size:16px;font-weight:500;background:${_mx.svg(_svg.checkCircle('43B03A'))} left center no-repeat;};`};
      .file-detail {
        display:flex;
        gap:0 8px;
        margin-top:${({success}) => success ? '12' : '2'}px;
        color: #555F6D;
        font-size: ${({success}) => success ? '14' : '12'}px;
        font-weight: 400;
        line-height: 20px;
        span + span {
          position:relative;
          padding-left:8px;
          &:before {
            content : '';
            display:block;
            position:absolute;
            left:0;
            top: 8px;
            width: 4px;
            height: 4px;
            background:${_mx.svg(_svg.dot('555F6D'))} left center no-repeat;
            background-size: contain;
          }
        }
      }
    }
    .progress-bar {
      display:block;
      overflow:hidden;
      width:100%;
      height:4px;
      margin-top:16px;
      border-radius : 6px;
      background:${_color.white};
      span {
        display:block;
        height:100%;
        border-radius:6px;
        background:${_color.primary0};
      }
    }
    .btn-close {
      display:block;
      position:absolute;
      right: 40px;
      top: 47px;
      width:20px;
      height:20px;
      background:${_mx.svg(_svg.close('4A545E'))} center center no-repeat;
    }
  }
`

/* 자동 테스트 */
export const Automatic = styled.div`
  ${FileUpload} {
    margin-bottom:20px;
  }
  .box-chart-wrap {
    display:flex;
    gap:0 6px;
    height:248px;
    margin:6px 0 48px;
    .test-info {
      width:100%;
      li {
        display:flex;
        align-items:baseline;
        position:relative;
        & + li {
          margin-top:14px;
        }
      }
    }
    .chart-item {
      display:flex;
      justify-content:center;
      align-items: center;
      overflow:hidden;
      padding: 0 20px;
      background:${_color.white};
      .chart-inner {
        width:100%;
      }
      &:first-of-type {
        width:20%;
      }
      &:nth-of-type(2) {
        width:36%
      }
      &:nth-of-type(3) {
        width:20%
      }
      &:last-of-type {
        width:24%;
        ul {
          width:100%;
        }
        li {
          flex-direction: column;
          & + li {
            margin-top: 32px;
          }
        }
        .cont {
          margin-top:8px;
          text-align:left;
        }
        .txt {
          overflow: hidden;
          width: calc(100% - 50px);
          display: block;
          white-space: nowrap;
          text-overflow: ellipsis;
        }
      }
      .subject {
        display:block;
        min-width:120px;
        color: #555F6D;
        font-size: 15px;
        font-weight: 500;
        line-height: 22px;
      }
      .cont {
        width:100%;
        text-align:right;
        word-break: keep-all;
        .txt {       
          font-size: 16px;
          font-weight: 400;
          line-height: 24px;
          color:${_color.black2};
        }
        strong.txt {
          font-size: 18px;
          font-weight: 600;
          line-height: 32px;
        }
      }
      ${S.Button} {
        position:absolute;
        right:0;
        top:50%;
        margin-top:-20px;
      }
    }
  }
  .chart-box {
    display:flex;
    align-items:center;
    justify-content:space-between;
    ${CS.RatioDoughnut} {
      min-width:50%;
    }
  }

  .in-table-bg {
		position: relative;
		width: calc( 100% - 8px );
		&::before {
			display: block;
			content: '';
			width: 8px;
			height: 52px;
			background: #e9edfb;
			border-top: 1px solid #d7d9f3;
			border-bottom: 1px solid #d7d9f3;
			position: absolute;
			top: 0;
			right: -8px;
		}

    &.thin {
      &::before {
        height: 42px;
      }
    }
	}
`
