import fp from 'lodash/fp';
import * as S from '../../style/ElementsStyle';

const SortingButton = ({ text, status, onSortClick = () => {} }) => {
  // const [sortStatus, setSortStatus] = useState('normal');

  const getSortStatus = (status) => {
    switch (status) {
      case 'asc':
        return 'up';
      case 'desc':
        return 'down';
      default:
        return 'nomal';
    }
  };

  const handleSortClick = (status) => {
    const cond = fp.cond([
      [fp.isEqual('desc'), fp.constant('asc')],
      [fp.isEqual('asc'), fp.constant('')],
      [fp.T, fp.constant('desc')],
    ]);

    onSortClick(cond(status));
  };

  return (
    <S.Sorting
      dangerouslySetInnerHTML={{ __html: text }}
      onClick={() => handleSortClick(status)}
      className={getSortStatus(status)}
    ></S.Sorting>
  );
};

export default SortingButton;
