import Title from "components/common/Title";
import Tab from "components/common/Tab";
import EvaluationList from "./tabs/EvaluationList";
import TestSet from "./tabs/TestSet";

const tabList = [
  {
    title: '평가 목록',
    tabContent: <EvaluationList/>
  },
  {
    title: '테스트셋',
    tabContent: <TestSet/>
  },
];

const AgentPerformanceEvaluationPage = () => {
  return(
    <>
      <Title title="Agent 성능 평가​" icon="settings" />
      <Tab tabList={tabList} />
    </>
  )
};

export default AgentPerformanceEvaluationPage;