import { useEffect, useState } from 'react';
import dayjs from 'dayjs';
import fp from 'lodash/fp';
import { getBotGroupsApi, getServicesApi } from 'pages/fallbackUtterance/apis';
import {
  getBotGroupMonthStaticsApi,
  getBotGroupPeriodStaticsExcelApi,
  getBotGroupStaticsDetailApi,
} from '../apis';
import { customSort } from 'libs/utiles';

const DEFAULT_BOTGROUP_MONTH_STATICS_SEARCH_PARAMS = {
  searchStartDate: dayjs().subtract(5, 'month').format('YYYY-MM-DD'),
  searchEndDate: dayjs().format('YYYY-MM-DD'),
  pageNo: 0,
  pageSize: 10,
};

const useBotGroupMonthStatic = () => {
  const [botGroupMonthStaticsSearchParams, setBotGroupMonthStaticsSearchParams] = useState(
    DEFAULT_BOTGROUP_MONTH_STATICS_SEARCH_PARAMS
  ); // 조회 조건
  const [botGroupMonthTotalStaticsRes, setBotGroupMonthTotalStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [botGroupMonthStaticsRes, setBotGroupMonthStaticsRes] = useState(null); // 봇 그룹 통계 봇별 데이터
  const [serviceListMonth, setserviceListMonth] = useState(null);
  const [botGroupListMonth, setBotGroupListMonth] = useState([]);
  const [isBotGroupMonthStaticsSearch, setIsBotGroupMonthStaticsSearch] = useState(false);
  const [latestBotGroupMonthSearchParams, setLatestBotGroupMonthSearchParams] = useState({});
  const [botGroupMonthDetailStaticsRes, setBotGroupMonthDetailStaticsRes] = useState({}); // 봇 그룹 통계 봇 그룹 데이터

  // 조회 조건 변경
  const changeBotGroupMonthStaticsSearchParams = (key, value) => {
    setBotGroupMonthStaticsSearchParams(fp.set(key, value));
  };

  // 봇 월별 조회
  const getBotGroupMonthStatics = async (searchParams) => {
    try {
      setIsBotGroupMonthStaticsSearch(true);
      const res = await getBotGroupMonthStaticsApi({
        ...searchParams,
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupMonthStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
      const botGroupName = fp.pipe(
        fp.find({ botGroupId: searchParams.botGroupId }),
        fp.getOr('', 'botGroupName')
      )(botGroupListMonth);

      setLatestBotGroupMonthSearchParams({ ...searchParams, botGroupName });
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 월별 조회에 실패했습니다.');
      setBotGroupMonthStaticsRes({});
    }
  };

  // 봇그룹 월별 전체 데이터 조회
  const getBotGroupMonthTotalStatics = async (searchParams) => {
    try {
      const res = await getBotGroupMonthStaticsApi({
        ...searchParams,
        pageNo: 0,
        pageSize: 1000,
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupMonthTotalStaticsRes(fp.getOr({}, 'data.data.statsBotGroupList', res));
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 통계 봇별 조회에 실패했습니다.');
      setBotGroupMonthTotalStaticsRes({});
    }
  };

  // 봇 그룹 디테일 월 통계 조회
  const getBotGroupMonthStaticsDetail = async (searchParams) => {
    const _searchStartDate = dayjs(searchParams.searchStartDate)
      .startOf('month')
      .format('YYYY-MM-DD');
    const _searchEndDate = dayjs(searchParams.searchEndDate).endOf('month').format('YYYY-MM-DD');
    try {
      const res = await getBotGroupStaticsDetailApi({
        ...searchParams,
        searchStartDate: _searchStartDate,
        searchEndDate: _searchEndDate,
      });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setBotGroupMonthDetailStaticsRes(fp.getOr({}, 'data.data', res));
    } catch (error) {
      console.log('error', error?.message);
    }
  };

  // 월별 리스트 엑셀 다운
  const getBotGroupMonthStaticsExcel = async (searchParams) => {
    try {
      const res = await getBotGroupPeriodStaticsExcelApi(searchParams, 'day');
      // Blob 객체 생성
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `${searchParams.serviceName}_봇그룹통계_월별조회_${dayjs().format('YYMMDD_HHmmss')}.xlsx`
      ); // 파일명 지정
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      alert('봇 그룹 통계 월별 엑셀 다운에 실패했습니다.');
    }
  };

  const getServicesMonth = async () => {
    try {
      const res = await getServicesApi();

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      setserviceListMonth(fp.getOr([], 'data.data', res));

      const firstServiceId = fp.getOr('', 'data.data[0].serviceId', res);
      const serviceName = fp.pipe(
        fp.getOr([], 'data.data'),
        fp.find((obj) => obj.serviceId == firstServiceId),
        fp.getOr('', 'name')
      )(res);
      if (firstServiceId) {
        getBotGroupsMonth(firstServiceId);
        changeBotGroupMonthStaticsSearchParams('serviceId', firstServiceId);
        changeBotGroupMonthStaticsSearchParams('serviceName', serviceName);
      }
    } catch (error) {
      console.log('error', error?.message);
      alert('서비스 목록 조회에 실패했습니다. 서비스 목록 조회가 가능한 상태인지 확인해주세요.');
      setserviceListMonth([]);
    }
  };

  const getBotGroupsMonth = async (serviceId, jobType) => {
    try {
      const res = await getBotGroupsApi({ serviceId, pageNo: 0, jobType, pageSize: 1000 });

      if (fp.getOr(0, 'data.header.resultCode', res) !== 0)
        throw new Error(fp.getOr('', 'data.header.resultMessage', res));
      const sortBotGroups = fp.sortBy(customSort, fp.getOr([], 'data.data.content', res));
      setBotGroupListMonth(sortBotGroups);
      const firstBotGroupId = fp.getOr('', '[0].botGroupId', sortBotGroups);
      changeBotGroupMonthStaticsSearchParams('botGroupId', firstBotGroupId);
    } catch (error) {
      console.log('error', error?.message);
      alert('봇 그룹 목록 조회에 실패했습니다. 봇 그룹 목록 조회가 가능한 상태인지 확인해주세요.');
      setBotGroupListMonth([]);
    }
  };

  useEffect(() => {
    if (!botGroupMonthStaticsSearchParams.serviceId) return;
    getBotGroupsMonth(botGroupMonthStaticsSearchParams.serviceId);
  }, [botGroupMonthStaticsSearchParams.serviceId]);

  return {
    botGroupMonthStaticsSearchParams, // 조회 조건
    latestBotGroupMonthSearchParams,
    botGroupMonthStaticsRes, // 봇그룹 봇별 통계 데이터
    botGroupMonthTotalStaticsRes,
    botGroupMonthDetailStaticsRes,
    serviceListMonth,
    botGroupListMonth,
    isBotGroupMonthStaticsSearch,
    changeBotGroupMonthStaticsSearchParams, // 조회 조건 변경
    getServicesMonth,
    getBotGroupsMonth,
    getBotGroupMonthStatics,
    getBotGroupMonthTotalStatics,
    getBotGroupMonthStaticsDetail,
    getBotGroupMonthStaticsExcel,
  };
};

export default useBotGroupMonthStatic;
