import { useEffect } from 'react';

function useOutsideClick(ref, callback, excludedRef, excludedRef2) {
  useEffect(() => {
    function handleClickOutside(event) {
      if (
        ref.current &&
        !ref.current.contains(event.target) &&
        !(excludedRef && excludedRef.current && excludedRef.current.contains(event.target)) &&
        !(excludedRef2 && excludedRef2.current && excludedRef2.current.contains(event.target))
      ) {
        callback();
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [ref, callback, excludedRef, excludedRef2]);
}

export default useOutsideClick;
