import { useEffect, useRef, useState } from 'react';
import { usePopper } from 'react-popper';
import * as S from '../../style/ElementsStyle';

/**
 * isCustom : false(default 물음표 버튼 표시, 작동 시 content에 children 노출) | true(children 표시, 작동 시 content에 title 노출)
 * title : isCustom=true일 때 content에 표시할 string
 */

const Tooltip = ({ color, children, hover = false, isCustom = false, title }) => {
  const [openTooltip, setOpenTooltip] = useState(false);
  const tooltipRef = useRef();

  const [referenceElement, setReferenceElement] = useState(null);
  const [popperElement, setPopperElement] = useState(null);
  const [arrowElement, setArrowElement] = useState(null);
  const { styles, attributes } = usePopper(referenceElement, popperElement, {
    placement: 'bottom-end',
    modifiers: [
      {
        name: 'arrow',
        options: {
          element: arrowElement,
        },
      },
      {
        name: 'offset',
        options: {
          offset: [0, 11],
        },
      },
    ],
  });

  const tooltipToggle = () => {
    setOpenTooltip(!openTooltip);
  };

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (tooltipRef.current && !tooltipRef.current.contains(e.target)) {
        setOpenTooltip(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const handleMouseEnter = () => {
    if (hover) {
      setOpenTooltip(true);
    }
  };

  const handleMouseLeave = () => {
    if (hover) {
      setOpenTooltip(false);
    }
  };

  return (
    <S.Tooltip color={color} ref={tooltipRef}>
      {isCustom ? (
        <div
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          onClick={(e) => tooltipToggle(e)}
          ref={setReferenceElement}
        >
          {children}
        </div>
      ) : (
        <button
          type="button"
          className="btn-tooltip"
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          onClick={(e) => tooltipToggle(e)}
          ref={setReferenceElement}
        >
          <span className="hidden">툴팁</span>
        </button>
      )}
      {openTooltip && (
        <div
          className="tooltip-content"
          ref={setPopperElement}
          style={styles.popper}
          {...attributes.popper}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          <div className="tooltip-inner"dangerouslySetInnerHTML={{ __html: children }}/>
          <div className="tooltip-arrow" ref={setArrowElement} style={styles.arrow} />
        </div>
      )}
    </S.Tooltip>
  );
};

export default Tooltip;
