import InputTable from "components/common/InputTable";
import { ScrollBox } from "style/AutoQAStyle";

const _exList = ['CS자동', '기본인사', '첫 인사'];
const __tableList = [
  { description: "고객에게 첫 인사를 건넸는가?", maxScore: 50, score: 48, isSubItem: false, isEditable: false },
  { description: "첫인사 스크립트 준수", maxScore: 25, score: 25, isSubItem: true, isEditable: false },
  { description: "상담사 이름 소개", maxScore: 25, score: 25, isSubItem: true, isEditable: true },
];

const ManualCheckTab = () => {

  return (<>
    <div style={{ height: '470px' }}>
      <ScrollBox height={465}>
        <InputTable
          tableInfo={_exList}
          modifyIs={false}
          commentStr={'첫인사를 잘 했으나 상담사 이름을 소개하지 않았습니다.​​'}
          tableList={__tableList}
        />
      </ScrollBox>
    </div>
  </>
  );
}

export default ManualCheckTab;