import React from "react";
import { useState } from "react";
import ButtonList from "components/common/ButtonList";
import { LayerInButtonWrap } from "style/AutoQAStyle";
import FormGrid from "components/common/FormGrid";
import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import Checkbox from "components/elements/Checkbox";
import Table from "components/common/Table";
import TextField from "components/elements/TextField";
import Button from "components/elements/Button";
import NoData from "components/common/NoData";
import Alert from "components/common/Alert";

const __tempData = [
  {
    item: 'dashboard',
    subItems: ['전화 상담 및 이상 징후 발생 현황', '상담 평가 결과']
  },
  {
    item: 'system',
    subItems: ['조직관리', '사용자 관리']
  },
];

const _btnListIs = [
  {
    label: '취소',
    type: 'secondary',
    evt: () => { }
  },
  {
    label: '확인',
    type: 'primary',
    evt: () => { }
  },
];


const AuthorityPopup = ({ type }) => {
  const [openAlert, setOpenAlert] = useState(false); //저장버튼 alert 노출 여부

  const tableToggleHandler = (e) => {
    e.target.closest('tr').classList.toggle('active');
  };

  const [checkboxState, setCheckboxState] = useState(
    __tempData.map((item) => ({
      item: item.item,
      checked: false,
      subItems: item.subItems.map(() => false),
    }))
  );

  const handleParentCheckboxChange = (index) => {
    setCheckboxState((prevState) => {
      const newState = [...prevState];
      const parentChecked = !newState[index].checked;
      newState[index].checked = parentChecked;
      newState[index].subItems = newState[index].subItems.map(() => parentChecked);
      return newState;
    });
  };

  const handleChildCheckboxChange = (parentIndex, childIndex) => {
    setCheckboxState((prevState) => {
      const newState = [...prevState];
      newState[parentIndex].subItems[childIndex] = !newState[parentIndex].subItems[childIndex];
      newState[parentIndex].checked = newState[parentIndex].subItems.every(Boolean);
      return newState;
    });
  };

  return (
    <>
    {openAlert && // 선택삭제 팝업
        <Alert onClose={() => setOpenAlert(false)} text={'선택하신 시스템 권한을 삭제 하시겠습니까?​​'} btnList={_btnListIs} /> 
      }
      <GrayBox vertical="center">
        <FormGrid gap={12}>
          <FormItem label={'메뉴 접근 권한명'}>
            {type === 'a' ?
              <TextField placeholder={'메뉴 접근 권한명을 입력하세요.'} count={10} maxLength={10} width={400} />
              :
              <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                <p> 관리자</p>
                <Button label="권한 삭제" className="secondary" onClick={() => {setOpenAlert(true)}} />
              </div>
            }
          </FormItem>
          <FormItem label={'역할 코드'}>
            <Checkbox
              type="switch"
            />
          </FormItem>
          <FormItem label={'접근 가능 메뉴'}>
            <p>30</p>
          </FormItem>
          <FormItem label={'최종 변경 일자'}>
            <p>2024-11-28 12:00</p>
          </FormItem>
          <FormItem label={'변경인'}>
            <p>권한 저장시 표시됩니다.</p>
          </FormItem>
        </FormGrid>
      </GrayBox>
      <div style={{ marginTop: '32px' }}>

        <Table fixedHeader height="265" interval={false} scroll hover={false}>
          <table className="small-line">
            <colgroup>
              <col width="140px" />
              <col width='256px' />
              <col width="500px" />
            </colgroup>
            <thead>
              <tr>
                <th className="t-left left-padding">메뉴명</th>
                <th className="t-left left-padding">　</th>
                <th>메뉴 접근 권한</th>
              </tr>
            </thead>
            <tbody>
              {/***********************
                  데이터 없는 경우
              ***********************
               <tr className='thin'>
                  <td colSpan="3">
                    <NoData txt={`조회된 데이터가 없습니다.`} />
                  </td>
                </tr> */}

              {__tempData.map((item, index) => {
                return (
                  <React.Fragment key={index}>
                    <tr className="toggle active">
                      <td className="t-left left-padding" style={{fontWeight:'bold'}}>{item.item}</td>
                      <td className="t-left left-padding">
                        <button
                          type="button"
                          className="btn-toggle-triangle"
                          onClick={(e) => tableToggleHandler(e)}
                        >
                          <span className="hidden">펼침</span>
                        </button>
                      </td>
                      <td>
                        <Checkbox
                          checked={checkboxState[index].checked}
                          callback={() => handleParentCheckboxChange(index)}
                        />
                      </td>
                    </tr>
                    {item.subItems.length > 0 &&
                      <tr className="hide">
                        <td colSpan={3}>
                          <table>
                            <colgroup>
                              <col width="140px" />
                              <col width='256px' />
                              <col width="500px" />
                            </colgroup>
                            <tbody>
                              {item.subItems.map((subItem, subIndex) => {
                                return (
                                  <tr className="toggle active" key={subIndex}>
                                    <td className="t-left left-padding"></td>
                                    <td className="t-left left-padding">{subItem}</td>
                                    <td>
                                      <Checkbox
                                        checked={checkboxState[index].subItems[subIndex]}
                                        callback={() =>
                                          handleChildCheckboxChange(index, subIndex)
                                        }
                                      />
                                    </td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                        </td>
                      </tr>
                    }
                  </React.Fragment>

                );
              })}

            </tbody>
          </table>
        </Table>
      </div>

      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '수정', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  );
}

export default AuthorityPopup;