import { useState } from "react";
import InputTable from "components/common/InputTable";
import { ScrollBox, TotalScore, BorderWithButton } from "style/AutoQAStyle";
import Button from "components/elements/Button";
import LayerPopup from 'components/common/LayerPopup';
import FormItem from 'components/common/FormItem';
import Table from 'components/common/Table';
import GrayBox from 'components/common/GrayBox';
import Textarea from "components/elements/Textarea";
import * as S from '../../../../../style/ElementsStyle';
import ButtonList from 'components/common/ButtonList';

const _exList = ['CS자동', '기본인사', '첫 인사'];
const __tableList = [
  { description: "고객에게 첫 인사를 건넸는가?", maxScore: 50, score: 48, isSubItem: false, isEditable: false },
  { description: "첫인사 스크립트 준수", maxScore: 25, score: 25, isSubItem: true, isEditable: false },
  { description: "상담사 이름 소개", maxScore: 25, score: 25, isSubItem: true, isEditable: true },
];

export const InnerContents = () => {
  return (
    <>
      <Table>
        <table>
          <caption>이의 신청 표</caption>
          <colgroup>
            <col width="182px" />
            <col width='266px' />
            <col width="180px" />
            <col width="169px" />
          </colgroup>
          <thead>
            <tr>
              <th scope="col">상담사명</th>
              <th scope="col">상담일시</th>
              <th scope="col">평가방식</th>
              <th scope="col">평가자</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>김상담&#40;202020&#41;</td>
              <td>2024-01-05 13:15:45</td>
              <td>수동</td>
              <td>김박사</td>
            </tr>
          </tbody>
        </table>
      </Table>
      <div style={{ margin: '32px 0' }}>
        <GrayBox height={248}>
          <FormItem label={'신청 사유'}>
            <Textarea width={556} height={200} maxLength={100} count={true} placeholder={'코멘트 입력 (공백 포함 최대 100자)'} />
          </FormItem>
        </GrayBox>
      </div>
      <S.LayerPopupBtns>
        <div className="right-area">
          <ButtonList buttonList={[
            // { label: '취소', className: 'secondary', onClick: () => { } },
            { label: '저장', className: 'primary', onClick: () => { }, disabled: false },
          ]} />
        </div>
      </S.LayerPopupBtns>
    </>
  );
};

const ManualCheckTab = ({commentIs=true , btnText='저장'}) => {
  const [scoreIs, setScoreIs] = useState(0);
  const [showIs, setShowIs] = useState(false);

  return (<>
    {showIs &&
      <LayerPopup
        size=""
        title={'이의 신청'}
        customWidth={900}
        open={showIs}
        onClose={() => setShowIs(false)}
      >
        <InnerContents />
      </LayerPopup>
    }
    <div style={{ paddingTop: '8px' }}>
      <TotalScore border={true}>{scoreIs}</TotalScore>
      <ScrollBox height={545}>
        <InputTable
          tableInfo={_exList}
          commentStr={'첫인사를 잘 했으나 상담사 이름을 소개하지 않았습니다.​​'}
          tableList={__tableList}
          commentIs={commentIs} // 코멘트 텍스트필드 입력
        />
      </ScrollBox>
      <BorderWithButton>
        <Button label={btnText} className="primary wide" onClick={() => { btnText !== '저장' && setShowIs(true) }} />
      </BorderWithButton>
    </div>
  </>
  );
}

export default ManualCheckTab;