import { useState } from "react";
import Title from "components/common/Title";
import Pagination from 'components/common/Pagination';
import Table from 'components/common/Table';
import Filter from 'components/common/Filter';
import ButtonList from 'components/common/ButtonList';
import { SubTableTitle, CountingTitle ,RadioContainer} from 'style/AutoQAStyle';
import Select from 'components/elements/Select';
import Button from 'components/elements/Button';
import TextField from 'components/elements/TextField';
import Radio from "components/elements/Radio";
import Alert from "components/common/Alert";
import Checkbox from "components/elements/Checkbox";
import LayerPopup from "components/common/LayerPopup";
import ForbiddenWordPopup from "./popups/ForbiddenWordPopup";

const __tempList = ['cvc번호', '금칙어', '대통령', '엘지유플러스', '요금폭탄', '케이티', '묵음처리', '그만하자', '끊겠습니다', '그만하자'];


const ForbiddenWordManagePage = () => {
  const [deletePopup, setDeletePopup] = useState(false); // 삭제 클릭 팝업
  const [openPopup, setOpenPopup] = useState(false); // 금칙어 등록, 상세 팝업
  const [title, setTitle] = useState(''); // 평가항목 팝업 타이틀

  const onChangedPopup = (type) => {
    setOpenPopup(true)
    setTitle(type);
  };

  const _btnListIs = [
    {
      label: '취소',
      type: 'secondary',
      evt: () => { console.log('1') }
    },
    {
      label: '확인',
      type: 'primary',
      evt: () => { console.log('2') }
    },
  ];

  return (
    <>
      {deletePopup && // 선택삭제 팝업
        <Alert onClose={() => setDeletePopup(false)} text={'삭제가 완료되었습니다.'} />  // **** 기본 텍스트 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'<div class="icon"></div><span class="red">현재 진행 중</span>인 평가 계획은 삭제가 불가합니다.'}/>  // **** 아이콘 + 경고(빨간 텍스트) 포함 타입
        // <Alert onClose={() => setDeletePopup(false)} text={'선택하신 평가 계획을 삭제 하시겠습니까?​'} btnList={_btnListIs}/>  // **** 기본 텍스트 타입
      }
      {openPopup && // 금칙어 등록, 상세 팝업
        <LayerPopup
          size="large"
          title={`금칙어 ${title}`}
          customWidth={1200}
          open={openPopup}
          onClose={() => setOpenPopup(false)}
        >
          <ForbiddenWordPopup />
        </LayerPopup>
      }
      <Title title="금칙어 관리" icon="notice" />
      <Filter>
        <Select
          option={[]}
          label="카테고리 1 선택"
          value={null}
          title={'카테고리 1'}
          disabled={false}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="카테고리 2 선택"
          value={null}
          disabled={false}
          title={'카테고리 2'}
          onChange={() => { console.log('select!') }}
        />
        <Select
          option={[]}
          label="카테고리 3 선택"
          value={null}
          disabled={false}
          title={'카테고리 3'}
          onChange={() => { console.log('select!') }}
        />
        <RadioContainer>
          <p>사용 여부</p>
          <div className="radio-wrap">
            <Radio
              name="test1"
              onChange={() => { }}
            >
              사용
            </Radio>
            <Radio
              name="test1"
              onChange={() => { }}
            >
              미사용
            </Radio>
          </div>
        </RadioContainer>
        <TextField
          placeholder="금칙어를 입력해주세요"
          label="금칙어 입력"
          multi
          onChange={(e) => { }}
        />
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </Filter>

      <SubTableTitle>
        <CountingTitle>선택 <span>0</span>개</CountingTitle>
        <ButtonList buttonList={[
          { label: '선택 삭제', className: 'secondary del2', onClick: () => setDeletePopup(true) },
          { label: '생성', className: 'primary left-plus', onClick: () => onChangedPopup('등록') },
        ]} />
      </SubTableTitle>

      <Table className="active" fixedHeader={true} height="572" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="64px" />
            <col width="280px" />
            <col width="280px" />
            <col width="280px" />
            <col width="314ox" />
            <col width="180px" />
            <col width="180px" />
          </colgroup>
          <thead>
            <tr>
              <th>
                <Checkbox />
              </th>
              <th className="t-left left-padding">카테고리 1</th>
              <th className="t-left left-padding">카테고리 2</th>
              <th className="t-left left-padding">카테고리 3</th>
              <th>금칙어</th>
              <th>사용 여부</th>
              <th>검출 횟수</th>
            </tr>
          </thead>
          <tbody>
            {__tempList.map((item, index) => {
              return (
                <tr key={index} onClick={(e) => {
                  // 클릭한 요소가 체크박스가 포함된 td일 경우 행 클릭 이벤트 무시
                  const excludedTd = e.currentTarget.querySelector('td.checkType');
                  if (excludedTd && excludedTd.contains(e.target)) {
                    return;
                  }
                  onChangedPopup('상세')
                }}
                >
                  <td className='checkType'>
                    <Checkbox />
                  </td>
                  <td className="t-left left-padding">상담유형 대</td>
                  <td className="t-left left-padding">상담유형 중</td>
                  <td className="t-left left-padding">상담유형 소</td>
                  <td>{item}</td>
                  <td>사용 여부</td>
                  <td>검출 횟수</td>
                </tr>
              );

            })}

          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />

    </>
  )
};

export default ForbiddenWordManagePage;