import { useState } from "react";
import TextField from "components/elements/TextField";
import Select from 'components/elements/Select';
import { LayerInButtonWrap, PopupInSmallTitle } from "style/AutoQAStyle";
import Button from "components/elements/Button";
import ButtonList from "components/common/ButtonList";
import Table from "components/common/Table";
import Alert from "components/common/Alert";
import NoData from "components/common/NoData";

const alertBtnList = [
  {
    label:'취소',
    type:'secondary',
    evt : () => {}
  },
  {
    label:'저장',
    type:'primary',
    evt : () => {}
  }
];

const SystemAuthorityPopup = ({type}) => {
  const [openPopup, setOpenPopup] = useState(false);

  return (
    <>
      {openPopup && // 선택삭제 팝업
        <Alert onClose={() => setOpenPopup(false)} text={'선택하신 시스템 권한을 삭제 하시겠습니까?​'} btnList={alertBtnList}/>
      }
      <div style={{ marginBottom: '40px' }}>
        <PopupInSmallTitle>
          시스템 권한명
        </PopupInSmallTitle>
        <div style={{display:'flex',gap:8}}>
          <TextField placeholder={'시스템 권한명을 입력하세요.'} count={10} maxLength={10} defaultValue={type === 'detail' ? '관리자' : ''}/>
          {type === 'detail' && <Button label="권한 삭제" className="secondary wide" onClick={() => {setOpenPopup(true)}} />}
        </div>
        
      </div>
      <PopupInSmallTitle>사용자 설정</PopupInSmallTitle>
      <Table >
        <table>
          <colgroup>
            <col width="232px" />
            <col width="232px" />
            <col width="232px" />
          </colgroup>
          <thead>
            <tr>
              <th>Auto QA</th>
              <th>AI KMS</th>
              <th>AICC 포털</th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
               <tr className='thin'>
                  <td colSpan="3">
                    <NoData txt={`조회된 데이터가 없습니다.`} />
                  </td>
                </tr> */}
            <tr height="64px" >
              <td>
                <Select
                  option={[]}
                  label="권한을 선택하세요"
                  value={''}
                  type="simple"
                  width={234}
                />
              </td>
              <td>
                <Select
                  option={[]}
                  label="권한을 선택하세요"
                  value={''}
                  type="simple"
                  width={234}
                />
              </td>
              <td>
                <Select
                  option={[]}
                  label="권한을 선택하세요"
                  value={''}
                  type="simple"
                  width={234}
                />
              </td>
            </tr>
          </tbody>
        </table>
      </Table>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '저장', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  );
};

export default SystemAuthorityPopup;