import { useState } from "react";
import { useSearchParams } from 'react-router-dom';
import { StatisticsDashboardContainer, StatisticsDashboardTitle, CustomFilter, GraphWraps, GraphBox } from "style/AutoQAStyle";
import Filter from "components/common/Filter";
import Radio from "components/elements/Radio";
import DateRange from 'components/common/DateRange';
import dayjs from 'dayjs';
import Button from "components/elements/Button";
import RatioDougnutChart from "components/chart/RatioDougnutChart";
import MultiBarLineChart from "components/chart/MultiBarLineChart";
import Table from "components/common/Table";
import Pagination from "components/common/Pagination";
import SortingButton from "components/elements/SortingButton";
import Title from "components/common/Title";
import DownloadDropdown from "components/common/DropDownButton";
import NoData from "components/common/NoData";

const SearchUsagePage = () => {
  const [date, setDate] = useState('2023-01-20 ~ 2023-01-22'); //기간
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜

  const handleExport = async () => {
    const charts = document.querySelectorAll("canvas, svg");

    for (let chart of charts) {
      if (chart.tagName === "CANVAS") {
        // Canvas → Image 변환
        const img = document.createElement("img");
        img.src = chart.toDataURL("image/png",1.0);
        img.style = chart.style.cssText;
        chart.replaceWith(img); // Canvas 대신 이미지 삽입

      } else if (chart.tagName === "SVG") {
        // SVG → Image 변환
        const serializer = new XMLSerializer();
        const svgString = serializer.serializeToString(chart);
        const svgBlob = new Blob([svgString], { type: "image/svg+xml" });
        const url = URL.createObjectURL(svgBlob);

        const img = document.createElement("img");
        img.src = url;
        img.style = chart.style.cssText;
        chart.replaceWith(img); // SVG 대신 이미지 삽입
      }
    }
  };

  return(
    <>
    <Title title="검색 이용 통계" icon="graph" />
     <StatisticsDashboardContainer>
        <Filter>
          <CustomFilter>
            <div className="radio-wrap">
              <Radio onChange={() => { }} name="result">일별</Radio>
              <Radio onChange={() => { }} name="result">주별</Radio>
              <Radio onChange={() => { }} name="result">월별</Radio>
            </div>
            <DateRange
              rangeCal
              utilMenu
              label="상담 일시"
              monthsShown={2}
              selectsRange
              format="YYYY-MM-DD"
              startDate={dayjs(startDate).toDate()}
              endDate={dayjs(endDate).toDate()}
              selected={dayjs(startDate).toDate()}
              disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
              disableNum={3}
              maxDate={dayjs().toDate()}
              onChange={(value) => {
                setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
                setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
              }}
            />
          </CustomFilter>
          <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
        </Filter>
        <StatisticsDashboardTitle>
          <div>
            <h5 className="title">기간별 평가</h5>
            <span className="date">{date}</span>
          </div>
          <DownloadDropdown btnLabel='다운로드' btnClass={'secondary download down-small'} dropdownList={['EXCEL','HTML']} onClickHtml={() => handleExport()}/>
        </StatisticsDashboardTitle>

        {/* 대시보드 */}
        <GraphWraps>
          <GraphBox width={287} height={248} padding={'42px 12px 10px 40px'}>
            <RatioDougnutChart
              labels={['긍정', '부정']}
              datas={['20', '80']}
              colors={['#5C5FD6', '#F47356']}
              boldTitle={'검색 만족도'}
            />
          </GraphBox>

          <GraphBox width={247} height={248}>
            <ul className="graph-list">
              <li className="title">
                <p>총 대화 건수</p>
                <span>0,000</span>
              </li>
              <li>
                <p>총 검색 건수</p>
                <span>0,000</span>
              </li>
              <li>
                <p>긍정 평가 건수</p>
                <span>0,000</span>
              </li>
              <li>
                <p>부정 평가 건수</p>
                <span>0,000</span>
              </li>
            </ul>
          </GraphBox>

          <GraphBox width={1031} height={248} padding={'42px 32px'}>
            <MultiBarLineChart
              legendPadding={20}
              labels={["MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD",
                "MM-DD", "MM-DD", "MM-DD", "MM-DD", "MM-DD"]}
              legends={['검색 건수', '긍정', '부정']}
              colors={['#9D9FE6','#5C5FD6','#F47356' ]}
              datas={[
                [600, 500, 650, 400, 550, 500, 450, 520, 600, 700],
                [10, 25, 30, 15, 35, 30, 25, 20, 25, 30],
                [5, 10, 15, 10, 20, 15, 10, 5, 10, 15],
              ]}
              graphTypes={['line', 'bar', 'bar']}
              title="일자별 이용 건수"
              width={790}
              height={172}
              useRightYAxis={false}
            />
          </GraphBox>
        </GraphWraps>
        </StatisticsDashboardContainer>

        <Table className="active" fixedHeader={true} height="532" hover={true} interval={true} round={false}>
        <table>
          <colgroup>
            <col width="337px" />
            <col width="310px" />
            <col width="310px" />
            <col width="310px" />
            <col width="310px" />
          </colgroup>
          <thead>
            <tr>
              <th><SortingButton text={'일자'} /></th>
              <th><SortingButton text={'부정'} /></th>
              <th><SortingButton text={'대화형 검색 건수'} /></th>
              <th><SortingButton text={'검색 문서 건수'} /></th>
              <th><SortingButton text={'긍정'} /></th>
            </tr>
          </thead>
          <tbody>
            {/***********************
                  데이터 없는 경우
              ***********************
              <tr><td colSpan={5}><NoData txt={'데이터가 없습니다'}/></td></tr> 
              */}
            {Array.from({ length: 1 }).map((_, index) => (
              <tr key={index}>
                <td>yyyy-mm-dd</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
                <td>00</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Table>

      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />
    </>
  )
};

export default SearchUsagePage;