import Title from "components/common/Title";
import Tab from "components/common/Tab";
import AImodelTypeTab from "./tabs/AiModelTypeTab";
import EvaluationConsultationTypeTab from "./tabs/EvaluationConsultationTypeTab";
import EvaluationPeriodTypeTab from "./tabs/EvaluationPeriodTypeTab";
import EvaluationOrganizationTypeTab from "./tabs/EvaluationOrganizationTypeTab";

const EvaluationsPage = () => {
  const evaluationTabList = [
    {
      title: '기간별', //Period type 
      tabContent: <EvaluationPeriodTypeTab />
    },
    {
      title: '조직별', //organization type
      tabContent: <EvaluationOrganizationTypeTab />
    },
    {
      title: '상담 유형별', //consultation type
      tabContent: <EvaluationConsultationTypeTab />
    },
    {
      title: 'AI 모델별', //aimodeltype
      tabContent: <AImodelTypeTab />
    }
  ]

  return (
    <>
      <Title title="평가 현황 통계" icon="graph" />
      <Tab tabList={evaluationTabList} />
    </>
  )
};

export default EvaluationsPage;