import GrayBox from "components/common/GrayBox";
import FormItem from "components/common/FormItem";
import FormGrid from "components/common/FormGrid";
import { LayerInButtonWrap } from "style/AutoQAStyle";
import ButtonList from "components/common/ButtonList";
import TextField from "components/elements/TextField";
import Textarea from "components/elements/Textarea";

const ChunkManagementPopup = () => {
  return (
    <>
      <GrayBox vertical="center">
        <FormGrid gap={10}>
          <FormItem label="Chunk ID​​">
            <TextField width={575} defaultValue={'UUID'} disabled={true}/>
          </FormItem>
          <FormItem label="등록 일시​​​">
            <TextField width={575} defaultValue={'2024-01-01 01:01:01​'} disabled={true}/>
          </FormItem>
          <FormItem label="원본 문서​​​">
            <TextField width={575} defaultValue={'선택 약정 할인 제도'} disabled={true}/>
          </FormItem>
          <FormItem label="컨텍스트​​​" >
            <Textarea width={575}/>
          </FormItem>
          <FormItem label="메타데이터1​">
            <TextField width={575} defaultValue={'3G 요금상품​'} />
          </FormItem>
          <FormItem label="메타데이터2​">
            <TextField width={575} defaultValue={'지원금 수혜​​'} />
          </FormItem>
          <FormItem label="메타데이터3​">
            <TextField width={575} defaultValue={'선택약정 할인​'} />
          </FormItem>
        </FormGrid>
      </GrayBox>
      <LayerInButtonWrap>
        <ButtonList buttonList={[
          { label: '실행', className: 'primary', onClick: () => { } },
        ]} />
      </LayerInButtonWrap>
    </>
  )
};

export default ChunkManagementPopup;