import { DashboardGridBoxs } from 'style/AutoQAStyle'
import Title from 'components/common/Title';
import * as S from "../../../../../style/ElementsStyle";
import Filter from 'components/common/Filter';
import AutoRefreshSet from 'components/common/AutoRefreshSet';

const CounselorType = () => {

  return (
    <>
      <Filter>
        <div className="left-area">
          <Title
            type="sub"
            title="상담 평가 현황"
            leftArea={<S.TxtInfo>　</S.TxtInfo>}
          />
        </div>
        <div className="right-area">
          <AutoRefreshSet
            refrashData={15000}
            autoRefrashTimeOption={15000}
            setAutoRefrashTimeOption={15000}
            onSaveCallback={() => { }} />
        </div>
      </Filter>

      <DashboardGridBoxs>
        <div className="left">
          <div className='container'>
            <div className="titles">
              <p>AI 자동 평가</p>
              <span className="date">최근 업데이트 시간 HH:MM:SS</span>
            </div>
            <ul>
              <li data-title="평가 대상 건수" className='bold'>0,000</li>
              <li data-title="평가 완료 건수">0,000</li>
              <li data-title="진행중 건수">0,000</li>
              <li data-title="평균 점수">0,000</li>
            </ul>
            <div className='list-type'>
              <p data-title='최고 점수'>000</p>
              <p data-title='최저 점수'>000</p>
            </div>
          </div>
          <div className='container'>
            <div className="titles">
              <p>QAA 평가</p>
              <span className="date">최근 업데이트 시간 HH:MM:SS</span>
            </div>
            <ul>
              <li data-title="평가 대상 건수" className='bold'>0,000</li>
              <li data-title="평가 완료 건수">0,000</li>
              <li data-title="진행중 건수">0,000</li>
              <li data-title="평균 점수">0,000</li>
            </ul>
            <div className='list-type'>
            <p data-title='최고 점수'>000</p>
            <p data-title='최저 점수'>000</p>
          </div>
          </div>
        </div>
        <div className="right">
          <div className="titles">
            <p>이의 신청</p>
            <span className="date">최근 업데이트 시간 HH:MM:SS</span>
          </div>
          <ul>
            <li className='big' data-title="누적 신청 건수">0,000</li>
            <li data-title="AI 평가 대상">0,000</li>
            <li data-title="QAA 평가 대상">0,000</li>
            <li data-title="검토 중">0,000</li>
            <li data-title="승인">0,000</li>
            <li data-title="반려">0,000</li>
          </ul>
        </div>
      </DashboardGridBoxs>
    </>
  );
}

export default CounselorType;