import { useState } from 'react';
import Title from 'components/common/Title';
import { WideLayerGrid, CategoryListContainer } from 'style/AutoQAStyle';
import CategoryDetails from './components/CategoryDetails';
import ButtonList from 'components/common/ButtonList';
import Alert from "components/common/Alert";
import { SortableTree } from './TreeItems/SortableTree';

const _initialItems = [
  {
    id: "Category 0",
    name: "Category 0",
    children: [
      {
        id: "Module",
        name: "Module",
        children: [
          {
            id: "Lesson",
            name: "Lesson",
            children: [
              {
                id: "Learning Object",
                name: "Learning Object",
                children: [],
              },
            ],
          },
        ],
      },
    ],
  },
  {
    id: "Category 1",
    name: "Category 1",
    children: [
      {
        id: "Module 1",
        name: "Module 1",
        children: [
          {
            id: "Lesson 1",
            name: "Lesson 1",
            children: [
              {
                id: "Learning Object 1",
                name: "Learning Object 1",
                children: [],
              },
            ],
          },
        ],
      },
    ],
  },
  {
    id: "Category 2",
    name: "Category 2",
    children: [
      {
        id: "Module 2",
        name: "Module 2",
        children: [
          {
            id: "Lesson 2",
            name: "Lesson 2",
            children: [
              {
                id: "Learning Object 2",
                name: "Learning Object 2",
                children: [],
              },
            ],
          },
        ],
      },
    ],
  },
];

const _btnListIs = [
  {
    label: '취소',
    type: 'secondary',
    evt: () => { }
  },
  {
    label: '삭제',
    type: 'primary',
    evt: () => { }
  },
];

const CategoryManagementPage = () => {
  const [openAlert, setOpenAlert] = useState(false); //저장버튼 alert 노출 여부
  const [contentsType, setContentsType] = useState('');
  const [selectedId, setSelectedId] = useState(null);
  const modeIs = contentsType === 'add' || contentsType === '';

  return (
    <>
      {openAlert && // 선택삭제 팝업
        <Alert onClose={() => setOpenAlert(false)} text={'<div class="icon"></div>해당 카테고리를 삭제하시겠습니까?​'} btnList={_btnListIs} />  // **** 아이콘 + 텍스트 타입
      }
      <Title title="카테고리 관리" icon="fileEdit" />
      <WideLayerGrid>
        {/* 좌측: 카테고리 목록 */}
        <div style={{ width: '772px' }}>
          <div className="sub-title-wrap">
            <div>
              <h5>카테고리</h5>
              <p>모든 카테고리는 삭제 및 편집이 가능합니다.</p>
            </div>
            <ButtonList buttonList={[
              {
                label: '카테고리 추가', className: 'primary left-plus', onClick: () => { setContentsType('add') },
              },
              { label: '', className: 'secondary del2', onClick: () => { setOpenAlert(true) }, btnType: 'icon', }
            ]} />
          </div>
          <div className="content-wrap" style={{ height: '584px', }}>
            <CategoryListContainer style={{ height: '584px', width: '772px' }}>
              <SortableTree
                defaultItems={_initialItems}
                collapsible
                indicator

                selectedId={selectedId}
                onSelectCategory={(id) => {
                  setSelectedId(id);
                  setContentsType('edit');
                }}

              />
            </CategoryListContainer>
          </div>
        </div>

        {/* 우측: 카테고리 생성 영역 */}
        <div style={{ width: '772px' }}>
          <div className="sub-title-wrap">
            <div>
              <h5>카테고리 {modeIs ? '생성' : '수정'}</h5>
              <p>{modeIs ?
                '생성할 수 있는 카테고리 수에는 제한이 없습니다.'
                : '카테고리명 수정 후 저장 버튼을 클릭하세요.'}
              </p>
            </div>
          </div>
          <div className="content-wrap round-contents" style={{ height: '584px', marginBottom: 0, }}>
            {contentsType !== '' && <CategoryDetails viewType={contentsType} />}
          </div>
        </div>

      </WideLayerGrid>
      <div style={{ display: 'flex', justifyContent: 'end', alignItems: 'center', margin: '24px 0', width: '1576px' }}>
        <ButtonList buttonList={[
          { label: '취소', className: 'secondary', onClick: () => { } },
          { label: '저장', className: 'primary', onClick: () => { } },
        ]} />
      </div>
    </>
  );
};

export default CategoryManagementPage;
