import React, { useRef } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { GraphLabelWrap, GraphLayout, GraphTitleItem, GraphWrapBox } from 'style/AutoQAStyle';

import usePreventZoom from "./chartHooks/usePreventZoom";
import useChartResolution from "./chartHooks/useChartResolution";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

/**
 * 
 * labels : 그래프 라벨 값
 * colors : 그레프 컬러 (보여주려는 순서대로 작성)
 * datas : 그래프 데이터
 * width : 그래프 너비
 * height : 그래프 높이
 * legends : 그래프별 항목 값
 * title : 그래프 타이틀
 * isHorizontal = false : 기본값 수직 스택
 * 
 */

const StackBarChart = ({ labels, colors, datas, width, height, legends, title, isHorizontal = false , legendPadding }) => {
  const isStacked = datas.length > 1; // datas 길이에 따라 스택 여부 결정
  const hasValidLegends = legends.some(legend => legend.trim() !== ""); // 유효한 legend가 있는지 확인

  
  usePreventZoom(); //브라우저 확대방지
  // 그래프 해상도 맞춰 그려주기
  const chartRef = useRef(null);
  useChartResolution(chartRef);

  const data = {
    labels,
    datasets: legends.map((legend, index) => ({
      label: legend,
      data: datas[index],
      backgroundColor: colors[index],
      borderWidth: 0,
      barThickness: 40,
      ...(isStacked && { stack: "stack1" }), // 스택 그룹 설정 (모든 데이터셋을 동일한 스택으로 그룹화)
    })),
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    indexAxis: isHorizontal ? "y" : "x", // 수평/수직 스택 설정

    plugins: {
      legend: { display: false },// 범례 숨김
      title: { display: false },
      tooltip: { enabled: true },
      datalabels: { display: false }, // 그래프 위 수치 표시 비활성화 
    },
    scales: {
      x: {
        stacked: isStacked, // x축 스택 여부 설정
        grid: { display: false, drawBorder: false },
        ticks: {
          color: "rgba(71, 85, 105, 0.5)",
          font: { size: 11 },
          maxRotation: 0,
          minRotation: 0,
          // callback: isHorizontal ? (value) => `${labels[value]}` : undefined, // 수평일 때 라벨 표시
        },
      },
      y: {
        stacked: isStacked, // y축 스택 여부 설정
        grid: { drawBorder: false },
        border: { display: false },
        ticks: {
          display: true,
          stepSize: 1000,
          padding: 5,
          color: "#B3B3C5",
          font: { size: 12 },
          // callback: !isHorizontal ? (value) => `${value}%` : undefined, // 세로형일 때 % 표시
        },
      },
    },
  };

  return (
    <GraphLayout>
      <div className="left-wrap">
        <GraphTitleItem>{title}</GraphTitleItem>
        {hasValidLegends && // 유효한 legends가 있을 때만 렌더링
          <CustomLegend legends={legends} colors={colors} paddingL={legendPadding} />
        }
      </div>
      <GraphWrapBox width={width} height={height}>
        <Bar data={data} options={options} />
      </GraphWrapBox>
    </GraphLayout>
  );
};

const CustomLegend = ({ legends, colors ,paddingL}) => (
  <GraphLabelWrap paddingL={paddingL}>
    {legends.map((item, index) => (
      <p key={index}>
        <span style={{ backgroundColor: colors[index] }} />
        {item}
      </p>
    ))}
  </GraphLabelWrap>
);

export default StackBarChart;
