const GenerationStatusPage = () => {
  const [searchParams] = useSearchParams(); //date-range
  const startDateIs = searchParams.get('startDate'); //date-range
  const endDateIs = searchParams.get('endDate'); //date-range
  const [startDate, setStartDate] = useState(startDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [endDate, setEndDate] = useState(endDateIs || dayjs().format('YYYY-MM-DD')); // 달력 날짜
  const [openPopup, setPopupOpen] = useState(false); // 상담사, 평가자 검색 팝업
  const [openDetail, setDetailOpen] = useState(false); //테이블 리스트 클릭 시 팝업
  return (
    <>
      {openPopup && // 상담사 검색 팝업
        <LayerPopup
          title={'상담사 검색'}
          customWidth={800}
          open={openPopup}
          onClose={() => setPopupOpen(false)}
        >
          <SearchBoxPopup onClose={() => setPopupOpen(false)} title={'상담사 검색'} />
        </LayerPopup>
      }

      {openDetail && // 대화상세내역 팝업
        <LayerPopup
          size="large"
          title="대화 상세"
          customWidth={800}
          customClass="none-padding"
          open={openDetail}
          onClose={() => setDetailOpen(false)}
        >
          <ExcellentCallPopup list={chatList} iconType={'forbidden'}/>
        </LayerPopup>
      }
      <Title title="이상 징후 발생 현황" icon="notice" />
      <FilterTwoLine>
        <TwoLineFlexBox width={'810px'}>
          <TextField
            placeholder="조직명을 입력해주세요"
            label="조직명 입력"
            multi
            onChange={(e) => { }}
          />
          <SearchBox
            placeholder={'상담사명을 입력해주세요'}
            label="상담사 검색"
            onClick={() => setPopupOpen(true)}
          />
          <DateRange
            rangeCal
            utilMenu
            label="조회 기간"
            monthsShown={2}
            selectsRange
            format="YYYY-MM-DD"
            startDate={dayjs(startDate).toDate()}
            endDate={dayjs(endDate).toDate()}
            selected={dayjs(startDate).toDate()}
            disableUnit={'month'} // 날짜 제한 단위 , day, week, month, year
            disableNum={3}
            maxDate={dayjs().toDate()}
            onChange={(value) => {
              setStartDate(dayjs(value[0]).format('YYYY-MM-DD'))
              setEndDate(dayjs(value[1]).format('YYYY-MM-DD'))
            }}
          />
          <Select
            option={[]}
            label="상담 유형 소 선택"
            value={''}
            title={'상담유형1'}
          />
          <Select
            option={[]}
            label="상담 유형 중 선택"
            value={''}
            title={'상담유형1'}
          />
          <Select
            option={[]}
            label="상담 유형 대 선택"
            value={''}
            title={'상담유형1'}
          />
        </TwoLineFlexBox>
        <Button label="조회" className="primary wide" onClick={() => { alert('조회중') }} />
      </FilterTwoLine>
      <Table className="active" fixedHeader={true} height="572" hover={false} interval={true} round={false}>
        <table>
          <caption>발생현황 조회 </caption>
          <colgroup>
            <col width="194px" />
            <col width="120px" />
            <col width="320px" />
            <col width="180px" />
            <col width="460px" />
            <col width="120px" />
            <col width="120px" />
          </colgroup>
          <thead>
            <tr>
              <th className="t-left left-padding">조직</th>
              <th className="t-left left-padding">상담사</th>
              <th className="t-left left-padding">상담유형</th>
              <th>상담 일시</th>
              <th className="t-left left-padding">사용 금칙어(<span className="blue">사용횟수</span>)</th>
              <th>합계</th>
              <th>대화 내역</th>
            </tr>
          </thead>
          <tbody>
            {__tempList.map((item, index) => {
              return <tr key={index}>
                <td className="t-left left-padding" height={52}>{item.group}</td>
                <td className="t-left left-padding">{item.name}</td>
                <td className="t-left left-padding">{item.type}</td>
                <td>{item.date}</td>
                <td className="t-left left-padding">{item.word}(<span className='blue'>{item.cnt}</span>)</td>
                <td>{item.total}</td>
                <td className='center'>
                  <TableInTxtBtn onClick={() => setDetailOpen(true)}>보기</TableInTxtBtn>
                </td>
              </tr>
            })

            }
          </tbody>
        </table>
      </Table>
      <Pagination pagingTotal={27} displayed={5} viewShowing as={'a'} />

    </>
  )
};

export default GenerationStatusPage;