import {useState} from 'react';
import classnames from 'classnames';

import * as S from '../../style/ElementsStyle';
import TextCaution from '../common/TextCaution';
import Button from '../elements/Button';

/**
 * size : 인풋 높이값 설정 기본 40px | small 32px
 */
const TextField = ({
  size,
  maxLength = 100,
  type = 'text',
  multi = false,
  label,
  title,
  valueError = false,
  valueSuccess = false,
  placeholder,
  id,
  width,
  disabled = false,
  readOnly = false,
  value,
  defaultValue,
  onChange,
  count,
  inputCount,
  info,
  infoTxt,
  onKeyDown,
  onKeyUp,
  errorMessage,
  successMessage,
  onBlur,
  btnDelete = false,
  onClickDeleteBtnListener,
  btnOrigin,
  setFileName,
  setHtml,
  setIsModified,
  center
}) => {
  const [isFocus, setIsFocus] = useState(false);

  const onFocusFn = () => {
    setIsFocus(true);

  };
  const onBlurFn = () => {
    setIsFocus(false);
    if (onBlur) {
      onBlur()
    }
  };
  const handleDeleteButtonClick = () => {
    if(btnDelete) {
      onClickDeleteBtnListener()
    }
    if (setFileName) {
      setFileName(btnOrigin);
      setIsModified(false);
      setHtml('');
    }
  };
  return (
      <S.TextField size={size} width={width} multi={multi}>
        <div
            className={classnames('text-area', {
              error: valueError,
              success: valueSuccess,
              disabled: disabled,
              focus: isFocus,
              center:center
            })}
        >
          {label && (
              <label className="label" id={id}>
                {label}
              </label>
          )}
          <input
              className={btnDelete ? 'with-button' : null}
              type={type}
              placeholder={placeholder}
              maxLength={maxLength}
              id={id}
              title={title}
              disabled={disabled}
              readOnly={readOnly}
              value={value}
              defaultValue={defaultValue}
              onChange={onChange}
              onFocus={onFocusFn}
              onBlur={onBlurFn}
              onKeyDown={onKeyDown}
              onKeyUp={onKeyUp}
              autoComplete='off'
              style={
                count || btnDelete ? {
                  padding: "0px 60px 0px 16px"
                } : {
                  padding: "0px 16px"
                }
              }
          />
          {count && <span className="count">{inputCount ? inputCount
              : '0'}/{maxLength}</span>}
          {btnDelete && <Button className="delete"
                                onClick={handleDeleteButtonClick}/>}
        </div>
        {info && <span className="info">{infoTxt}</span>}
        {(valueError && errorMessage) && <TextCaution
            cautionType="error">{errorMessage}</TextCaution>}
        {(valueSuccess && successMessage) && <TextCaution
            cautionType="success">{successMessage}</TextCaution>}
      </S.TextField>
  );
};

export default TextField;
